window.SKIM_PAPERS = window.SKIM_PAPERS || {};
window.SKIM_PAPERS["gpt-1"] = {"concepts": [{"id": "labeled-data-scarcity", "name": "Scarcity of Labelled Data", "tier": "major", "parent": null, "summary": "The problem the paper starts from: raw text is abundant, but human-annotated data for any one task is small and expensive.", "explanation": "Deep models for language tasks are normally fitted on manually annotated examples. Producing those annotations costs people, time and money, so the datasets stay small relative to what a large model could absorb.\n\nRaw text costs nothing by comparison. It exists in enormous quantity and needs no annotator at all.\n\nThe abstract states the gap plainly: large unlabeled corpora are plentiful while labelled data for specific tasks is scarce, which makes it hard for discriminatively trained models to perform adequately.\n\nThe paper's whole design follows from trying to spend the abundant resource to relieve the scarce one. It adds a second motivation as well: even where supervision is plentiful, learning representations without labels can still give a boost.", "prerequisites": [], "sectionIds": ["abstract", "1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "generative-vs-discriminative-training", "name": "Generative vs Discriminative Training", "tier": "minor", "parent": "labeled-data-scarcity", "summary": "Two ways of framing what a model predicts: the data itself, or a label given the data.", "explanation": "A generative objective asks the model to put probability on the data. For text that means predicting the next token from the tokens before it, which needs no labels.\n\nA discriminative objective asks for $P(y \\mid x)$: a label given an input. Every training step then consumes one annotated example.\n\nThe paper's title stacks the two in order — [[generative-pretraining|generative pre-training]], then discriminative fine-tuning. That ordering is what lets it spend unlabelled text first and small labelled sets second.\n\nWhen the paper says prior systems were discriminatively trained, it means the second kind of signal was all they had.", "prerequisites": ["labeled-data-scarcity"], "sectionIds": ["abstract", "1", "3", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "natural-language-understanding", "name": "Natural Language Understanding", "tier": "minor", "parent": null, "summary": "The umbrella label the paper uses for a set of diverse supervised text tasks, each with its own dataset and its own notion of a correct answer.", "explanation": "The paper opens by saying natural language understanding is not one task but a collection of them. It names textual entailment, question answering, [[semantic-similarity]] assessment and document classification.\n\nEach comes with its own labelled dataset, its own input format and its own scoring metric.\n\nThat diversity is what makes the central claim interesting: one model, pre-trained once, is asked to handle all of them. In the experiments the collection is twelve datasets grouped into four task types.\n\nTreating them as one family is a framing choice rather than a fact about language. The paper earns it by showing a single set of pre-trained weights transfers across the group.", "prerequisites": [], "sectionIds": ["abstract", "1", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "semi-supervised-learning-for-nlp", "name": "Semi-Supervised Learning for NLP", "tier": "major", "parent": null, "summary": "The family of methods that combine a large unlabelled corpus with a small labelled dataset, which the paper places itself inside.", "explanation": "Semi-supervised learning uses both labelled and unlabelled data for the same end task. The related-work section says this is the category the paper broadly falls under.\n\nIt then sorts prior work into a rough chronology. The earliest methods computed word- and phrase-level statistics from unlabelled text and fed them into a supervised model as extra features.\n\nLater work replaced those hand-built counts with learned word embeddings, and more recent work moved beyond single words to phrase and sentence representations.\n\nThe paper's own contribution sits at the far end of that progression. It transfers an entire pre-trained network rather than a table of vectors or a fixed feature channel.", "prerequisites": ["labeled-data-scarcity"], "sectionIds": ["1", "2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "word-embedding-transfer", "name": "Pre-Trained Word Embedding Transfer", "tier": "minor", "parent": "semi-supervised-learning-for-nlp", "summary": "Training one vector per word on unlabelled text, then reusing that table inside a supervised model for a different task.", "explanation": "A word embedding table is fitted on a large corpus with a co-occurrence-style objective and no task labels. The resulting vectors are then dropped into a supervised model as its input layer.\n\nThe introduction calls this the most compelling evidence so far that unsupervised learning helps, pointing at a range of tasks it has improved.\n\nThe paper's criticism is narrow and specific. This transfers word-level information only: one vector per word type says nothing about how that word behaves in a particular sentence, and nothing about phrase or sentence meaning.\n\nThe paper says it aims instead at higher-level semantics, which is why it transfers a whole network rather than a lookup table.", "prerequisites": ["semi-supervised-learning-for-nlp"], "sectionIds": ["1", "2"], "floor": false, "citedFrom": {"citationKey": "[39, 42]", "refText": "T. Mikolov et al. Distributed representations of words and phrases and their compositionality. NIPS, 2013. / J. Pennington, R. Socher, and C. Manning. Glove: Global vectors for word representation. EMNLP, 2014.", "whyNeeded": "The objectives that produce these vectors live in those papers; this one cites them as prior evidence."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "phrase-and-sentence-embeddings", "name": "Phrase- and Sentence-Level Embeddings", "tier": "minor", "parent": "semi-supervised-learning-for-nlp", "summary": "Methods that learn one vector for a whole phrase or sentence from unlabelled text, then use it as a feature for the target task.", "explanation": "These methods answer the word-level limitation by encoding a longer span into a single fixed vector. The encoder is trained on unlabelled text with some self-supervised signal, then frozen and used as a feature extractor.\n\nThe related-work section cites a cluster of such approaches, including skip-thought vectors and paragraph-level representations, as the closest predecessors in spirit.\n\nThe difference is where the representation stops. A sentence vector is a bottleneck: everything the target task can use must survive compression into that one vector.\n\nThis paper instead keeps a hidden state per position and continues training the encoder itself on the target task.", "prerequisites": ["semi-supervised-learning-for-nlp", "word-embedding-transfer"], "sectionIds": ["2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "unsupervised-pretraining", "name": "Unsupervised Pre-Training as a Category", "tier": "minor", "parent": "semi-supervised-learning-for-nlp", "summary": "The branch of semi-supervised learning where unlabelled data chooses a starting point for the weights instead of changing the supervised objective.", "explanation": "The related-work section draws a line here. In some semi-supervised methods the unlabelled data enters through an extra term in the loss during supervised training.\n\nIn unsupervised pre-training it enters earlier and differently. It is used to find a good initialization, and supervised training then proceeds normally from those weights.\n\nThe paper's own wording is that the goal is to find a good initialization point instead of modifying the supervised learning objective. This is the category it places its two-stage recipe in.\n\nThe technique predates its use in NLP: the section traces it to layer-by-layer training of deep networks on image classification and regression.", "prerequisites": ["semi-supervised-learning-for-nlp", "generative-vs-discriminative-training"], "sectionIds": ["2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "pretraining-as-regularization", "name": "Pre-Training as a Regularization Scheme", "tier": "minor", "parent": "unsupervised-pretraining", "summary": "The cited finding that pre-training helps not only by easing optimization but by landing the network somewhere that generalizes better.", "explanation": "One reading of pre-training is that it just gives supervised optimization an easier start. A later study argued for a different reading.\n\nIt found that pre-training acts as a regularization scheme, enabling better generalization in deep networks. On that account the unlabelled data constrains where supervised training may begin, and the constraint itself limits overfitting on a small labelled set.\n\nThe paper cites this framing directly and does not re-derive it.\n\nIt matters for the story here because several of the twelve target datasets are small, so an initialization that generalizes is worth more than one that merely converges fast.", "prerequisites": ["unsupervised-pretraining"], "sectionIds": ["2"], "floor": false, "citedFrom": {"citationKey": "[15]", "refText": "D. Erhan, Y. Bengio, A. Courville, P.-A. Manzagol, P. Vincent, and S. Bengio. Why does unsupervised pre-training help deep learning? JMLR, 2010.", "whyNeeded": "The regularization claim is an empirical result established there and asserted here in one sentence."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "auxiliary-training-objectives", "name": "Auxiliary Training Objectives", "tier": "minor", "parent": "semi-supervised-learning-for-nlp", "summary": "The other branch: add a second unsupervised loss term alongside the supervised loss, so the model keeps learning from raw text while it learns the task.", "explanation": "Instead of using unlabelled data first and then setting it aside, the extra objective runs at the same time as supervised training. The total loss becomes a sum of the task loss and the auxiliary loss.\n\nThe related-work section presents this as a separate line with its own history, going back to training one shared network on several NLP tasks at once.\n\nThe paper's position is slightly two-sided. Its own fine-tuning does use an auxiliary objective.\n\nBut it also reports that pre-training already learns several linguistic aspects relevant to the target tasks, which implies the auxiliary term is doing less work here than it did for methods with no pre-training.", "prerequisites": ["semi-supervised-learning-for-nlp"], "sectionIds": ["2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "feature-based-transfer", "name": "Feature-Based Transfer", "tier": "minor", "parent": "unsupervised-pretraining", "summary": "The competing transfer style: freeze a pre-trained language or translation model and feed its hidden states into a separate task model as extra input features.", "explanation": "Here the pre-trained network is a fixed producer of vectors. A new task-specific model is built on top and trained from scratch on the labelled data, taking those vectors as additional inputs alongside ordinary word embeddings.\n\nThe related-work section describes it as using hidden representations from a pre-trained language or machine translation model as auxiliary features while training a supervised model on the target task.\n\nThe paper's objection is about cost. Each target task needs its own new model, so the approach involves a substantial amount of new parameters per task.\n\nThe comparison as stated is about parameter cost and architectural effort. The accuracy comparison is left to the experiments.", "prerequisites": ["unsupervised-pretraining", "supervised-fine-tuning"], "sectionIds": ["1", "2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "elmo-deep-contextualized-word-representations", "name": "Deep Contextualized Word Representations (ELMo)", "tier": "minor", "parent": "feature-based-transfer", "summary": "The best-known feature-based approach: hidden states from a pre-trained bidirectional language model, added as features to a task model.", "explanation": "A language model is trained on unlabelled text and then frozen. Its internal states give each token a vector that depends on the surrounding sentence, unlike a static word embedding.\n\nThose vectors feed a task-specific network that is trained separately.\n\nThe paper cites this line repeatedly. It is the feature-based contrast to fine-tuning, the source of the 1B Word Benchmark corpus comparison, and the contextual features inside the BiLSTM + ELMo + Attn baselines the results tables measure against.\n\nThe difference from this paper's setup is that the pre-trained weights are never updated by the task.", "prerequisites": ["feature-based-transfer", "word-embedding-transfer"], "sectionIds": ["1", "2", "4.1", "4.2"], "floor": false, "citedFrom": {"citationKey": "[44]", "refText": "M. E. Peters, M. Neumann, M. Iyyer, M. Gardner, C. Clark, K. Lee, and L. Zettlemoyer. Deep contextualized word representations. NAACL, 2018.", "whyNeeded": "The bidirectional language model and the layer-mixing scheme that produce the features are defined there; this paper summarizes it in a clause."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "per-task-parameter-cost", "name": "Per-Task Parameter Cost", "tier": "minor", "parent": "feature-based-transfer", "summary": "The quantity the paper uses to separate its approach from feature-based transfer: how many freshly initialized parameters each new task needs.", "explanation": "Every parameter that is new for a task must be fitted from that task's labelled data, which is the scarce resource.\n\n[[feature-based-transfer|Feature-based transfer]] needs a whole task model on top of the frozen encoder, so the count is large.\n\nFine-tuning starts every parameter from a pre-trained value and adds only a thin task-specific layer, so the count is small.\n\nThe related-work section frames the difference exactly this way, contrasting a substantial amount of new parameters for each separate target task with minimal changes to the model architecture during transfer. It states the contrast qualitatively and gives no parameter counts.", "prerequisites": ["feature-based-transfer", "minimal-extra-parameters", "labeled-data-scarcity"], "sectionIds": ["2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "lm-pretraining-then-finetuning-predecessors", "name": "Language-Model Pre-Training Then Fine-Tuning", "tier": "minor", "parent": "unsupervised-pretraining", "summary": "The line of work the paper calls closest to its own: pre-train with a language modelling objective, then fine-tune the whole network on a supervised task.", "explanation": "The related-work section identifies two prior systems with exactly this shape, both applied to [[text-classification]].\n\nThe paper accepts the shape and changes two things. The first is the network: those systems used LSTMs, while this one uses a transformer, which the paper argues captures longer-range structure.\n\nThe second is the range of tasks. This paper adds [[natural-language-inference]], paraphrase detection and story completion to classification.\n\nSo the claimed contribution is not the recipe but what it is built from and how far it stretches.", "prerequisites": ["unsupervised-pretraining", "language-modeling-objective"], "sectionIds": ["2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "semi-supervised-sequence-learning", "name": "Semi-Supervised Sequence Learning", "tier": "minor", "parent": "lm-pretraining-then-finetuning-predecessors", "summary": "Earlier work that pre-trained a recurrent network with a language modelling or autoencoding objective and fine-tuned it for text classification.", "explanation": "This is one of the two systems the related-work section names as closest in method.\n\nIt established that a recurrent sequence model pre-trained on unlabelled text could be fine-tuned to improve classification accuracy.\n\nThe paper's stated difference is the model class and the breadth of tasks, not the training procedure. It is cited in a single sentence, so the objective and schedule are not reproduced here.", "prerequisites": ["lm-pretraining-then-finetuning-predecessors"], "sectionIds": ["2"], "floor": false, "citedFrom": {"citationKey": "[13]", "refText": "A. M. Dai and Q. V. Le. Semi-supervised sequence learning. NIPS, 2015.", "whyNeeded": "The pre-training objectives and fine-tuning procedure are defined there; this paper names the result only."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "ulmfit", "name": "Universal Language Model Fine-Tuning", "tier": "minor", "parent": "lm-pretraining-then-finetuning-predecessors", "summary": "A contemporaneous method that fine-tunes a pre-trained LSTM language model for text classification using a carefully staged schedule.", "explanation": "This system shares the paper's two-stage shape but puts considerable design effort into how fine-tuning is run.\n\nThe introduction refers to that kind of effort as intricate learning schemes, and lists it among the open questions about how best to transfer representations.\n\nThe related-work section then names the same work as one of the two closest predecessors. The contrast drawn is again the LSTM backbone and the restriction to [[text-classification]].", "prerequisites": ["lm-pretraining-then-finetuning-predecessors", "lstm-short-range-limitation"], "sectionIds": ["1", "2"], "floor": false, "citedFrom": {"citationKey": "[21]", "refText": "J. Howard and S. Ruder. Universal language model fine-tuning for text classification. ACL, 2018.", "whyNeeded": "The staged fine-tuning schedule this paper calls intricate is specified there, not here."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "lstm-short-range-limitation", "name": "Short-Range Limitation of LSTM Pre-Training", "tier": "minor", "parent": "lm-pretraining-then-finetuning-predecessors", "summary": "The paper's argument that recurrent pre-trained models keep their predictions local, capping how much structure they transfer.", "explanation": "The related-work section says that although pre-training helps those systems capture some linguistic information, their use of LSTMs restricts prediction ability to a short range.\n\nThe reasoning is about how information travels in a recurrent network. Everything from the past has to pass through a single state vector, one step at a time.\n\nThe paper contrasts this with attention, which reaches any earlier position directly, and says its choice allows longer-range linguistic structure to be captured.\n\nThe support offered is an architectural argument plus downstream results, not a direct measurement of dependency length.", "prerequisites": ["lm-pretraining-then-finetuning-predecessors", "long-range-dependencies-gpt1"], "sectionIds": ["2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "choice-of-pretraining-objective", "name": "Which Pre-Training Objective to Use", "tier": "minor", "parent": null, "summary": "The first open question the introduction identifies: nobody knows which unsupervised objective yields text representations that transfer best.", "explanation": "Several objectives had been tried for learning transferable representations. The introduction lists language modelling, machine translation and discourse coherence.\n\nIts observation is that none dominates: each method outperforms the others on different tasks, with a footnote pointing at the GLUE leaderboard as evidence.\n\nThat is a stated uncertainty rather than a rhetorical setup.\n\nThe paper resolves it by picking language modelling and showing results, not by arguing the choice through in advance.", "prerequisites": ["unsupervised-pretraining"], "sectionIds": ["1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "how-to-transfer-representations", "name": "How to Transfer Learned Representations", "tier": "minor", "parent": null, "summary": "The second open question: given a pre-trained representation, there was no consensus on how best to move it into a target task.", "explanation": "The introduction lists three transfer techniques then in use. One makes task-specific changes to the model architecture. Another uses intricate learning schemes during fine-tuning. A third adds auxiliary learning objectives to the supervised loss.\n\nThe paper's summary is that these uncertainties, together with the objective question, had made it difficult to develop effective semi-supervised approaches for language processing.\n\nIts own answer is to change the input rather than the architecture, keeping the transfer machinery simple.", "prerequisites": ["unsupervised-pretraining", "supervised-fine-tuning"], "sectionIds": ["1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "two-stage-training-procedure", "name": "Two-Stage Training Procedure", "tier": "major", "parent": null, "summary": "The paper's recipe: learn the network's initial parameters with a language modelling objective on unlabelled text, then adapt those same parameters to each target task with its supervised objective.", "explanation": "Stage one trains a high-capacity language model on a large corpus of plain text. No labels are involved, and the product the paper cares about is a set of weights rather than any prediction.\n\nStage two takes those weights as the starting point and continues training on a labelled dataset using that task's loss.\n\nBoth stages train the same model. The second begins from the first's parameters rather than from scratch, which is what makes this transfer rather than feature extraction.\n\nThe architecture stays essentially fixed across the two stages and across target tasks. That is what lets one pre-trained model serve twelve evaluations with only a small per-task addition.\n\nThe paper states the goal as learning a universal representation that transfers with little adaptation, and adds an assumption that keeps the recipe cheap: the target tasks need not come from the same domain as the unlabelled corpus.", "prerequisites": ["unsupervised-pretraining", "generative-vs-discriminative-training"], "sectionIds": ["abstract", "1", "3", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "transfer-learning", "name": "Transfer Learning Here", "tier": "minor", "parent": "two-stage-training-procedure", "summary": "Reusing parameters learned on one task as the starting point for another. Here the pre-trained language model's weights initialize every target task.", "explanation": "In this setup everything below the classifier is transferred: the embeddings and all twelve transformer blocks start from their pre-trained values.\n\nSection 3.3 uses the term to make a criticism. If a method adds new task-specific architecture on top of transferred representations, those new components start from random weights and get no benefit from transfer.\n\nSection 5 measures what the transfer buys. Removing pre-training entirely and training the same transformer directly on the supervised tasks costs 14.8%.", "prerequisites": ["two-stage-training-procedure"], "sectionIds": ["3", "3.3", "5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "domain-mismatch-tolerance", "name": "No Domain Match Required", "tier": "minor", "parent": "two-stage-training-procedure", "summary": "The stated assumption that the unlabelled pre-training corpus need not come from the same domain as the target tasks.", "explanation": "Some transfer setups require the source data to resemble the destination data. The introduction says plainly that this one does not.\n\nThat is what makes a single pre-training run reusable across twelve datasets of different kinds.\n\nIt also means the pre-training corpus can be chosen for its own properties, such as long contiguous passages, rather than to match any particular benchmark.", "prerequisites": ["two-stage-training-procedure", "labeled-dataset-c"], "sectionIds": ["1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "generative-pretraining", "name": "Generative Pre-Training (Stage One)", "tier": "major", "parent": "two-stage-training-procedure", "summary": "Train a multi-layer transformer decoder to predict each next token on a large unlabelled corpus, and keep the weights rather than the outputs.", "explanation": "The paper is handed a corpus of tokens $U = \\{u_1,\\dots,u_n\\}$ with no labels attached. Training maximizes the likelihood the model assigns to each token given the tokens before it.\n\nNothing about the target tasks enters at this stage. The only thing being fit is the text.\n\nThe paper calls this generative because the objective models the data itself rather than a label conditioned on the data. Every position in the corpus supplies a training signal for free.\n\nCapacity matters here, because stage two only pays off if stage one stored something worth transferring. The concrete model is twelve layers of 768-dimensional states, trained for 100 epochs.\n\nThe objective itself is described as standard. What the paper claims is the scale of the corpus and the choice of architecture.\n\nThe conclusion adds a claim about what the model picks up along the way: [[world-knowledge]], and an ability to process long-range dependencies.", "prerequisites": ["two-stage-training-procedure", "language-modeling-objective", "multi-layer-transformer-decoder"], "sectionIds": ["abstract", "1", "3", "3.1", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "language-modeling-objective", "name": "Language Modelling Objective $L_1$", "tier": "major", "parent": "generative-pretraining", "summary": "The pre-training loss $L_1(U)=\\sum_i \\log P(u_i \\mid u_{i-k},\\dots,u_{i-1};\\Theta)$: maximize the log-probability the model gives each token given the tokens before it.", "explanation": "Take a position $i$ in the corpus. The model reads the $k$ tokens before it and produces a distribution over the vocabulary for position $i$.\n\nThe objective picks out the log-probability that distribution assigned to the token that actually appeared.\n\nThose log-probabilities are summed over every position in the corpus, and the sum is maximized by stochastic gradient descent over the parameters $\\Theta$.\n\nOnly preceding tokens condition each prediction. The objective is strictly left-to-right, which is what makes [[masked-self-attention|masked self-attention]] necessary in the architecture.\n\nBecause no annotation is needed to build an example, every token of the corpus is a training case.\n\nThe paper labels this term $L_1$ and reuses the label in Section 3.2, where it returns as an auxiliary term during fine-tuning.", "prerequisites": ["context-window-512-tokens", "maximum-likelihood-training"], "sectionIds": ["1", "2", "3", "3.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "maximum-likelihood-training", "name": "Maximum-Likelihood Training", "tier": "minor", "parent": "language-modeling-objective", "summary": "Fitting parameters by maximizing the log-probability the model assigns to the observed data. Assumed known.", "explanation": "Both $L_1$ and $L_2$ in this paper are written as sums of log-probabilities to be maximized, which in practice is minimizing cross-entropy by gradient descent.\n\nThe paper assumes this and does not comment further.", "prerequisites": [], "sectionIds": ["3.1", "3.2"], "floor": true, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "world-knowledge", "name": "World Knowledge from Pre-Training", "tier": "minor", "parent": "generative-pretraining", "summary": "The conclusion's claim that predicting text over a large corpus leaves the model with facts and expectations about the world.", "explanation": "The conclusion states that the model acquires significant world knowledge during pre-training, and that this knowledge transfers to the discriminative tasks.\n\nThe implied mechanism is indirect. To predict text well a model has to encode regularities about what tends to be true and what tends to happen next.\n\nThe Story Cloze result is the strongest supporting number, since choosing a story ending rewards exactly that kind of expectation.\n\nThe claim is made at summary level. The paper does not isolate world knowledge from other things pre-training might supply.", "prerequisites": ["generative-pretraining", "question-answering-and-commonsense-reasoning"], "sectionIds": ["6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "multi-layer-transformer-decoder", "name": "Multi-Layer Transformer Decoder", "tier": "major", "parent": "generative-pretraining", "summary": "The language model is a stack of transformer blocks used as a decoder only: masked multi-head self-attention over the context, then position-wise feedforward layers.", "explanation": "The paper takes the transformer and keeps only the decoder side of it, following the variant used for generating Wikipedia from long input sequences.\n\nEach layer applies multi-headed self-attention over the input context tokens, then a position-wise feedforward network. Stacking gives $h_l = \\mathrm{transformer\\_block}(h_{l-1})$ for $l \\in [1,n]$, with $n = 12$ in the trained model.\n\nLayer zero is the token embeddings plus the position embeddings. The top layer's states are projected back to the vocabulary to give the output distribution.\n\nThe paper's argument for this stack over a recurrent one is that its attentional memory handles long-range dependencies better.\n\nSection 5 puts a number on that argument. Swapping in a single-layer 2048-unit LSTM under the same framework costs 5.6 average score.", "prerequisites": ["transformer-gpt1"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": {"citationKey": "[34]", "refText": "P. J. Liu, M. Saleh, E. Pot, B. Goodrich, R. Sepassi, L. Kaiser, and N. Shazeer. Generating wikipedia by summarizing long sequences. ICLR, 2018.", "whyNeeded": "The decoder-only transformer variant the paper adopts is defined there; the paper cites it in place of describing the variant."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "transformer-gpt1", "name": "Transformer Architecture", "tier": "minor", "parent": null, "summary": "The stacked self-attention and feed-forward architecture this paper builds on. Assumed known.", "explanation": "A stack of identical blocks, each combining multi-head self-attention over all positions with a position-wise feed-forward network, plus residual connections and layer normalization.\n\nThe paper adopts it rather than introducing it, citing its results on machine translation, document generation and syntactic parsing.\n\nWhat this paper changes — a [[decoder-only-stack|decoder-only stack]], [[masked-self-attention|masked self-attention]], [[learned-position-embeddings]] — is covered separately.", "prerequisites": [], "sectionIds": ["1", "3.1", "4.1", "6"], "floor": true, "citedFrom": {"citationKey": "[62]", "refText": "A. Vaswani, N. Shazeer, N. Parmar, J. Uszkoreit, L. Jones, A. N. Gomez, Ł. Kaiser, and I. Polosukhin. Attention is all you need. NIPS, 2017.", "whyNeeded": "The architecture is defined there and adopted wholesale here."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "decoder-only-stack", "name": "Decoder-Only Stack", "tier": "major", "parent": "multi-layer-transformer-decoder", "summary": "The model drops the encoder half of the original encoder-decoder transformer and keeps one stack that attends only to its own past tokens.", "explanation": "The original transformer has two stacks. An encoder reads a source sequence with unrestricted self-attention, so every source position sees every other.\n\nThe decoder generates a target sequence. It attends to its own previous outputs through [[masked-self-attention|masked self-attention]], and separately to the encoder's states through a cross-attention sublayer.\n\nLanguage modelling has no source sequence. There is nothing to encode and nothing to cross-attend to.\n\nSo the paper keeps one stack and removes the cross-attention sublayer. Each block is left with masked self-attention followed by a feedforward network, and Section 4.1 states the result directly: a 12-layer decoder-only transformer with masked self-attention heads.\n\nThe consequence carries into stage two. Every input the model ever sees, for any task, has to arrive as a single ordered sequence read left to right — which is what the input transformations then have to arrange.", "prerequisites": ["transformer-gpt1", "masked-self-attention"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": {"citationKey": "[62]", "refText": "A. Vaswani, N. Shazeer, N. Parmar, J. Uszkoreit, L. Jones, A. N. Gomez, Ł. Kaiser, and I. Polosukhin. Attention is all you need. NIPS, 2017.", "whyNeeded": "The encoder-decoder design this stack is a trimmed version of, including the cross-attention sublayer that gets removed, is defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "masked-self-attention", "name": "Masked Self-Attention", "tier": "major", "parent": "multi-layer-transformer-decoder", "summary": "Self-attention restricted so each position attends only to itself and earlier positions, never to later ones.", "explanation": "Plain self-attention lets every position attend to every other, including positions to its right. In a language model that would be fatal: the model would see token $u_i$ while being asked to predict $u_i$, and $L_1$ would be trivial to maximize.\n\nThe fix is a mask. Before the attention softmax, the scores for all positions to the right of the current one are driven to $-\\infty$, so after normalization their weights are zero.\n\nEach position then summarizes only $u_{i-k},\\dots,u_i$, which is exactly the conditioning set written down in $L_1$.\n\nThe practical payoff is throughput. One forward pass over a 512-token sequence yields a valid next-token prediction at every position at once, rather than one prediction per pass.\n\nAll [[twelve-attention-heads]] at all twelve layers are masked this way.\n\nThe mask stays in place during fine-tuning too. That is why a classification input must be one ordered sequence, and why the label is read off the final token rather than pooled across positions.", "prerequisites": ["language-modeling-objective", "transformer-gpt1"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "input-representation-h0", "name": "Input Representation $h_0$", "tier": "minor", "parent": "multi-layer-transformer-decoder", "summary": "The layer-zero input is the token embeddings of the context plus the position embeddings: $h_0 = UW_e + W_p$.", "explanation": "$U = (u_{-k},\\dots,u_{-1})$ is the context vector of tokens. Multiplying by the [[token-embedding-matrix]] $W_e$ replaces each token id with that token's embedding row.\n\nAdding $W_p$ then adds a second vector that depends on which slot the token occupies, not on which token it is.\n\nNote that this is a sum, not a concatenation. Both matrices produce vectors of the same width, 768 in this model, and they are added element-wise.\n\nThat sum is what the first transformer block reads. Position has to be injected here because self-attention on its own treats its inputs as an unordered set.", "prerequisites": ["token-embedding-matrix", "learned-position-embeddings"], "sectionIds": ["3.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "token-embedding-matrix", "name": "Token Embedding Matrix $W_e$", "tier": "minor", "parent": "multi-layer-transformer-decoder", "summary": "$W_e$ maps each vocabulary token to a dense vector, and its transpose is reused at the output to score candidate next tokens.", "explanation": "Each row of $W_e$ is the vector for one vocabulary entry. Context tokens are looked up in it to build the layer-zero input.\n\nThe same matrix appears again at the top of the model, as $W_e^T$, when the final hidden states are turned into a distribution over tokens.\n\nThe vocabulary is not words. It is a byte-pair encoding vocabulary built with 40,000 merges, so rows correspond to subword units.\n\nReusing one matrix at both ends keeps the parameter count down and ties a token's input and output representations together.", "prerequisites": [], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "learned-position-embeddings", "name": "Learned Position Embeddings", "tier": "minor", "parent": "multi-layer-transformer-decoder", "summary": "Position information comes from a trained matrix $W_p$, one vector per slot, rather than from the fixed sinusoids of the original transformer.", "explanation": "Self-attention computes a weighted sum over positions, and nothing in that computation depends on order. Permute the inputs and the same vectors come back permuted.\n\nThe original transformer solves this by adding fixed sinusoidal functions of the position index. Those values are computed, not learned.\n\nThis paper instead makes $W_p$ a parameter matrix: one trainable 768-dimensional vector for each of the 512 slots in the context window, added to the token embedding at that slot and updated by the same gradients as everything else.\n\nOne consequence is that the table has a fixed height. There is no vector for position 513, so a learned scheme does not extrapolate past the trained window the way a sinusoid formally can.\n\nThe paper reports no ablation isolating this choice, so it reads as a design preference rather than a demonstrated gain.", "prerequisites": ["transformer-gpt1", "context-window-512-tokens"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": {"citationKey": "[62]", "refText": "A. Vaswani, N. Shazeer, N. Parmar, J. Uszkoreit, L. Jones, A. N. Gomez, Ł. Kaiser, and I. Polosukhin. Attention is all you need. NIPS, 2017.", "whyNeeded": "The sinusoidal scheme being replaced is defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "output-softmax-tied-embeddings", "name": "Output Distribution $P(u) = \\mathrm{softmax}(h_n W_e^T)$", "tier": "minor", "parent": "multi-layer-transformer-decoder", "summary": "The top block's states are multiplied by the transpose of the token embedding matrix and softmaxed to give a distribution over the vocabulary.", "explanation": "Equation 2 ends with $P(u) = \\mathrm{softmax}(h_n W_e^T)$, where $h_n$ holds the states leaving the top transformer block.\n\nMultiplying a 768-dimensional state by $W_e^T$ gives one score per vocabulary entry. Each score is the dot product between the state and that token's embedding row, so a token scores highly when the state points the same way its embedding does.\n\nThe softmax turns those scores into a distribution.\n\nBecause the output projection is the transpose of the input embedding matrix, no separate output matrix is trained. This is the distribution $L_1$ scores during pre-training, and the same one the auxiliary objective scores again during fine-tuning.", "prerequisites": ["token-embedding-matrix"], "sectionIds": ["3.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "long-range-dependencies-gpt1", "name": "Long-Range Dependencies in Text", "tier": "minor", "parent": null, "summary": "Relationships spanning many tokens, such as a pronoun and an antecedent several sentences back, or an exam question and the passage detail that answers it.", "explanation": "Some of the information a model needs is nearby, and some is far away. A model that reaches back only a few tokens handles the first kind and not the second.\n\nThe paper makes the second kind load-bearing. The introduction says the transformer gives a more structured memory for handling long-term dependencies than alternatives such as recurrent networks, because attention keeps every earlier position addressable instead of compressing the past into one state vector.\n\nThe related-work section reuses the same argument against LSTM-based pre-training, and the conclusion names text with long-range dependencies as the kind of data the approach works best with.\n\nThe support offered is transfer performance across tasks rather than a dedicated probe of dependency length.", "prerequisites": ["transformer-gpt1"], "sectionIds": ["1", "2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "supervised-fine-tuning", "name": "Supervised Fine-Tuning (Stage Two)", "tier": "major", "parent": "two-stage-training-procedure", "summary": "Run labelled inputs through the pre-trained model, take the final block's activation at the last token, and train a linear layer on it to predict the label.", "explanation": "The labelled dataset $C$ holds instances made of a token sequence $x_1,\\dots,x_m$ and a label $y$. The whole sequence is passed through the pre-trained transformer.\n\nThe activation of the final transformer block at the last token, written $h_l^m$, is taken as the representation of the instance.\n\nA linear layer with parameters $W_y$ maps that vector to one score per class, and a softmax turns the scores into $P(y \\mid x_1,\\dots,x_m)$.\n\nTraining maximizes $L_2(C)$, the summed log-probability of the correct labels, with gradients flowing back through the entire pre-trained stack. The pre-trained representations are adjusted by the task, not merely consulted by it.\n\nThe word discriminative marks the change of objective: the model now predicts a label given an input rather than predicting the input itself.\n\nThis stage is short. The paper reports a learning rate of 6.25e-5, batches of 32, and three epochs sufficient for most tasks.", "prerequisites": ["generative-pretraining", "final-token-activation", "generative-vs-discriminative-training"], "sectionIds": ["abstract", "1", "3", "3.2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "labeled-dataset-c", "name": "Labelled Dataset $C$", "tier": "minor", "parent": "supervised-fine-tuning", "summary": "$C$ denotes a target task's labelled data: input token sequences each paired with one label.", "explanation": "Each instance in $C$ is a sequence $x_1,\\dots,x_m$ together with a label $y$, and the length $m$ varies from instance to instance.\n\nNone of $C$ is used during pre-training. It enters only in stage two, and each of the twelve target tasks gets its own fine-tuning run from the same pre-trained weights.\n\nTasks whose raw inputs are not a single sequence — a premise and a hypothesis, or a document with a question and several answers — must first be converted into one.\n\nAfter that conversion every target task looks the same to the model: one sequence in, one label out.", "prerequisites": ["supervised-fine-tuning"], "sectionIds": ["1", "3.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "final-token-activation", "name": "Final Block Activation $h_l^m$", "tier": "minor", "parent": "supervised-fine-tuning", "summary": "The representation fed to the classifier is the final transformer block's output at the last input token.", "explanation": "The notation $h_l^m$ in Equation 3 picks position $m$, the last token, from the final block $l$.\n\nThat position is special because attention is masked. Every other position has seen only a prefix of the input; the last position is the only one that has attended to the whole sequence.\n\nSo everything the classifier learns about an instance has to be summarized in that single vector. There is no pooling over positions.\n\nThis is also why every transformed input ends with an end token. It gives the model a dedicated final slot to summarize into, which Figure 1 labels Extract.", "prerequisites": ["masked-self-attention"], "sectionIds": ["3.2", "3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "linear-output-layer-wy", "name": "Added Linear Output Layer $W_y$", "tier": "minor", "parent": "supervised-fine-tuning", "summary": "The one parameter matrix added on top of the pre-trained model, mapping the final activation to label scores.", "explanation": "Equation 3 is $P(y \\mid x_1,\\dots,x_m) = \\mathrm{softmax}(h_l^m W_y)$.\n\n$W_y$ is small. With 768-dimensional states and a handful of classes it is 768 by the number of labels, a few thousand parameters against a stack of twelve blocks.\n\nIt is initialized fresh for each target task, because the label sets differ. Everything beneath it is inherited from pre-training.\n\nA dropout at rate 0.1 is applied to this classifier during fine-tuning.", "prerequisites": ["final-token-activation"], "sectionIds": ["3.2", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "supervised-objective-l2", "name": "Supervised Objective $L_2$", "tier": "minor", "parent": "supervised-fine-tuning", "summary": "$L_2(C) = \\sum_{(x,y)} \\log P(y \\mid x_1,\\dots,x_m)$: the summed log-probability of the correct labels over the labelled data.", "explanation": "For each instance, take the probability the model assigned to the true label and add its logarithm to the total. Maximizing that total is ordinary classification training.\n\nGradients do not stop at $W_y$. They flow back through the whole pre-trained stack, so fine-tuning adjusts every transformer weight.\n\nOn its own $L_2$ would be the objective for a plain fine-tune. The paper adds a second term to it in Equation 5.", "prerequisites": ["linear-output-layer-wy", "maximum-likelihood-training"], "sectionIds": ["3.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "auxiliary-lm-objective", "name": "Auxiliary Language Modelling Objective", "tier": "major", "parent": "supervised-fine-tuning", "summary": "During fine-tuning the paper keeps optimizing the language modelling loss alongside the task loss: $L_3(C) = L_2(C) + \\lambda\\, L_1(C)$.", "explanation": "The next-token loss does not disappear when stage two begins. It is recomputed on the fine-tuning data $C$ — the same task inputs, scored simply as text — and added to the classification loss with weight $\\lambda$.\n\nThe paper reports two effects from including it: better generalization of the supervised model, and faster convergence.\n\nBoth are stated as empirical findings. No mechanism is offered, and the paper notes prior work observed similar gains from adding a language modelling term to a supervised objective.\n\nSection 5 puts a limit on the claim. Ablating the term shows it helps on the [[natural-language-inference]] tasks and on [[qqp]], while smaller datasets do not benefit.\n\nSo the reported trend is that larger fine-tuning sets gain from it and smaller ones do not.", "prerequisites": ["language-modeling-objective", "supervised-objective-l2", "auxiliary-training-objectives"], "sectionIds": ["2", "3.2", "5"], "floor": false, "citedFrom": {"citationKey": "[50]", "refText": "M. Rei. Semi-supervised multitask learning for sequence labeling. ACL, 2017.", "whyNeeded": "The construction this paper adopts, and its measured effect on sequence labeling, come from there; this paper cites it in one sentence."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "auxiliary-objective-weight", "name": "Auxiliary Objective Weight $\\lambda = 0.5$", "tier": "minor", "parent": "auxiliary-lm-objective", "summary": "$\\lambda$ scales the auxiliary language modelling term against the classification term. The paper sets it to 0.5.", "explanation": "In $L_3 = L_2 + \\lambda L_1$, setting $\\lambda = 0$ recovers plain fine-tuning. Making $\\lambda$ large would push the model to care more about predicting text than about getting the label right.\n\nSection 4.1 gives the value used throughout: $\\lambda$ was set to 0.5, so the language modelling term carries half the weight of the classification term in every reported result.\n\nThe paper reports no sweep over $\\lambda$, so it is best read as a chosen value rather than a tuned optimum.\n\nThis single number is what the first ablation removes: setting it to zero is what without the [[auxiliary-lm-objective]] means in Table 5.", "prerequisites": ["auxiliary-lm-objective"], "sectionIds": ["3.2", "4.1", "5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "minimal-extra-parameters", "name": "Minimal Extra Fine-Tuning Parameters", "tier": "minor", "parent": "supervised-fine-tuning", "summary": "Adapting to a new task adds only the linear layer $W_y$ and embeddings for the delimiter tokens.", "explanation": "Section 3.2 states this at the end: the only extra parameters required during fine-tuning are $W_y$ and embeddings for the delimiter tokens.\n\nNo new layers, no task-specific encoder, no attention module stacked on top.\n\nThe delimiter embeddings are new because those symbols never appeared in the pre-training corpus, so their rows start randomly initialized. Everything else is a pre-trained weight being adjusted.\n\nThe abstract, introduction and related-work section all repeat the point in different words, and it is the basis of the paper's comparison against methods that add a substantial amount of new parameters per task.", "prerequisites": ["linear-output-layer-wy", "delimiter-token"], "sectionIds": ["abstract", "1", "2", "3.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "task-specific-input-transformations", "name": "Task-Specific Input Transformations", "tier": "major", "parent": "two-stage-training-procedure", "summary": "Structured task inputs are rewritten as one ordered token sequence, so the pre-trained model can read them without architectural change.", "explanation": "Pre-training saw contiguous runs of text, one sequence at a time. Many target tasks do not arrive that way.\n\nEntailment gives an ordered sentence pair. Question answering gives a document, a question and a set of candidate answers. [[text-classification]], by contrast, already is a single sequence and can be fine-tuned directly.\n\nRather than build a module per task to combine those pieces, the paper concatenates them into one sequence using special tokens. Every transformation wraps the result in randomly initialized [[start-and-end-tokens]], $\\langle s\\rangle$ and $\\langle e\\rangle$.\n\nThe architecture then stays fixed and only the input formatting varies. Figure 1 draws the four cases side by side.\n\nThe abstract presents this as the difference from previous approaches: the transformations achieve effective transfer while requiring minimal changes to the model architecture. The work of handling structure moves out of the network and into the data format.", "prerequisites": ["supervised-fine-tuning", "decoder-only-stack"], "sectionIds": ["abstract", "1", "3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "structured-inputs", "name": "Structured Inputs", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "Task inputs made of several distinct parts — ordered sentence pairs, or document/question/answer triplets — rather than one run of text.", "explanation": "Section 3.3 names two shapes. Ordered sentence pairs cover entailment and similarity. Triplets of document, question and answers cover [[question-answering-and-commonsense-reasoning]].\n\nThe difficulty is that the pre-trained model has no notion of a part. It was trained on contiguous sequences, so it has no slot for the second sentence or for candidate answer three.\n\nThe transformations exist to bridge that gap. They flatten structure into order and mark the seams with a delimiter.", "prerequisites": ["task-specific-input-transformations"], "sectionIds": ["3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "traversal-style-approach", "name": "Traversal-Style Approach", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "The strategy of walking the parts of a structured input into one ordered sequence, instead of building an architecture that mirrors the structure.", "explanation": "The paper borrows the term from earlier work on entailment with neural attention, and says its task-specific input adaptations are derived from it.\n\nThe name comes from traversing a structure in a fixed order to flatten it. Applied here, a premise-hypothesis pair or a document-question-answer triple becomes one ordered stream.\n\nThe alternative the paper rejects is learning [[task-specific-architectures|task-specific architectures]] on top of transferred representations.\n\nThe cost of traversal is that the model must recover from the format whatever structure the format only implies. The delimiter is a marker, not a described relationship.\n\nThe benefit claimed is that nothing new has to be designed or learned per task, so the transformations let the paper avoid extensive changes to the architecture across tasks.", "prerequisites": ["task-specific-input-transformations"], "sectionIds": ["1", "3.3"], "floor": false, "citedFrom": {"citationKey": "[52]", "refText": "T. Rocktäschel, E. Grefenstette, K. M. Hermann, T. Kočiský, and P. Blunsom. Reasoning about entailment with neural attention. arXiv:1509.06664, 2015.", "whyNeeded": "The paper names this as the source of the traversal-style approach it adopts without describing what that approach is."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "start-and-end-tokens", "name": "Start and End Tokens $\\langle s\\rangle$, $\\langle e\\rangle$", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "Every transformed input is bracketed by a randomly initialized start token and end token.", "explanation": "Section 3.3 says all transformations include adding randomly initialized start and end tokens.\n\nNeither symbol occurs in the pre-training corpus, so neither has a pre-trained embedding. Their rows begin random and are learned during fine-tuning, alongside the delimiter embeddings.\n\nThe two are not equally important. The start token simply opens the sequence.\n\nThe end token is the final position, and it is the one whose activation the classifier reads. Figure 1 labels that slot Extract, because it is where the model must summarize the whole input.", "prerequisites": ["final-token-activation"], "sectionIds": ["3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "delimiter-token", "name": "Delimiter Token ($)", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "A special `$` symbol inserted between the parts of a transformed input to mark where one part ends and the next begins.", "explanation": "When a premise and a hypothesis are concatenated, nothing in the raw text says where the boundary falls. The delimiter is placed there.\n\nIt is one more symbol with a learned embedding, added at fine-tuning time. Section 3.2 counts these delimiter embeddings, together with $W_y$, as the only extra parameters fine-tuning requires.\n\nEvery structured transformation uses it: entailment, similarity, and the document-question-answer format.\n\nThe symbol carried no meaning during pre-training. Whatever the boundary means for a given task has to be learned from that task's labelled data.", "prerequisites": ["task-specific-input-transformations"], "sectionIds": ["3.2", "3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "entailment-input-transformation", "name": "Entailment Input Transformation", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "The premise and hypothesis token sequences are concatenated with a delimiter between them.", "explanation": "The resulting sequence is $\\langle s\\rangle$, the premise tokens, `$`, the hypothesis tokens, $\\langle e\\rangle$.\n\nOne forward pass produces the final-block activation at $\\langle e\\rangle$, and $W_y$ maps that to the entailment labels.\n\nThere are no separate encoders and no cross-attention between two towers. The single masked stack reads the hypothesis tokens with the premise already sitting in their context.\n\nBecause entailment has an inherent direction — whether $p$ entails $h$ is a different question from whether $h$ entails $p$ — one fixed ordering encodes the problem faithfully.", "prerequisites": ["natural-language-inference", "delimiter-token", "final-token-activation"], "sectionIds": ["3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "similarity-input-transformation", "name": "Similarity Input Transformation", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "Both sentence orderings are built and processed separately, and their two final activations are added element-wise before the linear output layer.", "explanation": "A single concatenation would break the task's symmetry. The stack reads left to right under a mask, so in \"A $ B\" the tokens of B see A, while the tokens of A never see B.\n\nSo the paper builds two sequences, one for each ordering, each with a delimiter between the sentences.\n\nEach is processed independently and produces its own final-block activation $h_l^m$.\n\nThe two vectors are then added element-wise. Addition commutes, so swapping which sentence was called first leaves the sum unchanged, and the representation is symmetric by construction.\n\nThat single sum is what $W_y$ reads. The cost is two forward passes per example instead of one.", "prerequisites": ["semantic-similarity", "delimiter-token", "final-token-activation"], "sectionIds": ["3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "qa-and-commonsense-input-transformation", "name": "Question Answering and Commonsense Transformation", "tier": "minor", "parent": "task-specific-input-transformations", "summary": "Each candidate answer is concatenated onto the document and question to form its own sequence, and the resulting scores are normalized across candidates.", "explanation": "The input is a context document $z$, a question $q$, and a set of possible answers $\\{a_k\\}$.\n\nFor each candidate $k$ the paper forms the sequence $[z; q; \\$; a_k]$: the document and question run together, then a delimiter, then that one candidate.\n\nEach sequence is processed independently by the same model, so a four-choice question costs four forward passes.\n\nEach pass yields one scalar score, read from the final token through the output layer. A softmax over the $k$ scores turns them into a distribution across the candidate set, and the highest-probability candidate is the prediction.\n\nScoring is therefore comparative. A candidate is not judged good or bad in isolation; it has to beat the others for the same question. The number of output classes is set by how many candidates the question happens to have, not by $W_y$.", "prerequisites": ["delimiter-token", "final-token-activation"], "sectionIds": ["3.3"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "task-agnostic-model", "name": "Task-Agnostic Model", "tier": "major", "parent": null, "summary": "A single architecture, pre-trained once, applied to every task without being redesigned for any of them.", "explanation": "The abstract's central claim is comparative: the general task-agnostic model outperforms discriminatively trained models that use architectures specifically crafted for each task.\n\nTask-agnostic here means the network's structure carries no assumptions about entailment, or multiple-choice answers, or sentence pairs. Those assumptions live in the input format and in a small output layer instead.\n\nThe introduction frames the goal as learning a universal representation that transfers with little adaptation to a wide range of tasks. Universal does two jobs in that sentence: one representation rather than one per task, and a low adaptation cost.\n\nThe evidence offered is breadth. Four task types, twelve datasets, one pre-training run, with improvement on the previous best result for nine of the twelve.", "prerequisites": ["two-stage-training-procedure", "task-specific-input-transformations"], "sectionIds": ["abstract", "1", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "task-specific-architectures", "name": "Task-Specific Architectures", "tier": "minor", "parent": "task-agnostic-model", "summary": "The prevailing alternative: networks designed by hand around one task's structure, often stacked on top of transferred representations.", "explanation": "For each task type, researchers had built architectures matched to it — cross-sentence attention for entailment, answer-scoring modules for reading comprehension — and trained them discriminatively on that task's labelled data.\n\nWhere transferred representations were used at all, they sat at the bottom. Everything above was designed and trained per task, starting from random weights each time.\n\nThe paper's complaint has two parts. It re-introduces a significant amount of task-specific customization, and [[transfer-learning]] does no work for the added components.\n\nThe introduction also lists making task-specific changes to the architecture among the open questions that had held semi-supervised NLP back.\n\nThe counter-proposal is to move the per-task work out of the architecture and into the input format.", "prerequisites": ["task-agnostic-model", "transfer-learning"], "sectionIds": ["abstract", "1", "3.3"], "floor": false, "citedFrom": {"citationKey": "[44]", "refText": "M. E. Peters, M. Neumann, M. Iyyer, M. Gardner, C. Clark, K. Lee, and L. Zettlemoyer. Deep contextualized word representations. NAACL, 2018.", "whyNeeded": "This is the concrete prior approach Section 3.3 contrasts against; the contrast needs its transfer scheme and what it builds on top."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "bookscorpus", "name": "BooksCorpus", "tier": "major", "parent": "generative-pretraining", "summary": "The pre-training corpus: over 7,000 unpublished books across genres. Its selling point in this paper is long stretches of contiguous text.", "explanation": "BooksCorpus is the unlabelled text the language model is trained on. It contains over 7,000 unique unpublished books spanning genres such as Adventure, Fantasy and Romance.\n\nThe property the paper cares about is not the genre mix but the shape of the text. A book arrives as a long unbroken run of sentences in their original order.\n\nThat matters because the objective asks the model to predict the next token from the tokens before it. If the preceding tokens reach back across paragraphs, the model has an incentive to condition on long-range information rather than on the last few words.\n\nThe paper calls this out as its reason for preferring BooksCorpus to a similarly sized but sentence-shuffled alternative.\n\nIt reports a token-level perplexity of 18.4 on this corpus as a sanity figure for the pre-training run, and does not tie that number to any downstream claim.", "prerequisites": ["generative-pretraining", "language-modeling-objective"], "sectionIds": ["4.1"], "floor": false, "citedFrom": {"citationKey": "[71]", "refText": "Y. Zhu, R. Kiros, R. Zemel, R. Salakhutdinov, R. Urtasun, A. Torralba, and S. Fidler. Aligning books and movies: towards story-like visual explanations by watching movies and reading books. ICCV, 2015.", "whyNeeded": "The corpus is defined and collected there; its size, genre composition and collection method are not restated here."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "long-range-contiguous-text", "name": "Long-Range Contiguous Text", "tier": "minor", "parent": "bookscorpus", "summary": "Text kept in its original order across sentences and paragraphs, so a context window can span far more than one sentence.", "explanation": "Contiguous means the corpus preserves the order in which sentences were written, rather than storing sentences as independent items.\n\nWhen a 512-token example is cut from such a corpus, the tokens at the end of the window depend on tokens hundreds of positions earlier: a character named in one paragraph, a fact established in another.\n\nThe paper's argument is that this dependency structure is what lets a generative model learn to condition on long-range information. If the corpus never contains such dependencies, the objective never rewards learning them.\n\nThe conclusion turns the observation into advice, naming text with long-range dependencies as the kind of data the approach works best with. The evidence is the transfer results as a whole, not a controlled comparison against a shuffled corpus.", "prerequisites": ["bookscorpus", "long-range-dependencies-gpt1"], "sectionIds": ["4.1", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "one-billion-word-benchmark", "name": "1B Word Benchmark", "tier": "minor", "parent": "bookscorpus", "summary": "An alternative pre-training corpus of roughly the same size as BooksCorpus, but shuffled at the sentence level. The paper names it as the corpus ELMo uses.", "explanation": "This is the comparison the paper draws to justify its corpus choice. The benchmark is approximately the same size as BooksCorpus, so the contrast is not about how much text is available.\n\nThe difference is ordering. The benchmark is shuffled at a sentence level, which the paper says destroys long-range structure.\n\nAfter shuffling, the sentence before the current one is an unrelated sentence from elsewhere in the collection. A model trained on it can still learn within-sentence statistics, but there is no coherent discourse reaching backwards for it to exploit.\n\nThe paper notes that ELMo, which it treats as a similar approach, trains on this corpus.", "prerequisites": ["bookscorpus", "long-range-contiguous-text", "elmo-deep-contextualized-word-representations"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "token-level-perplexity", "name": "Token-Level Perplexity of 18.4", "tier": "minor", "parent": "bookscorpus", "summary": "The paper reports its language model reaching a token-level perplexity of 18.4 on BooksCorpus, offered as evidence pre-training fit the corpus.", "explanation": "Perplexity summarizes how surprised a model is by the text it scores. It is the exponential of the average negative log-probability per token, so 18.4 means the model is on average about as uncertain as if choosing uniformly among 18.4 options at each token.\n\nThe qualifier token-level matters. Because the paper works in byte-pair units rather than whole words, the average is taken over subword tokens.\n\nThat makes the number not directly comparable to word-level perplexities quoted elsewhere.\n\nThe paper offers it as a single sanity figure and draws no downstream conclusion from it.", "prerequisites": ["bookscorpus", "language-modeling-objective", "byte-pair-encoding-gpt1"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "model-specification", "name": "Model Specification", "tier": "major", "parent": "multi-layer-transformer-decoder", "summary": "The exact architecture trained: a 12-layer decoder-only transformer with 768-dimensional states, 12 attention heads and 3072-dimensional inner feed-forward states.", "explanation": "This is the concrete configuration behind every number in the results. The paper says it largely follows the original transformer work, then lists where it fixes the free parameters.\n\nThe stack is 12 layers deep. Each layer carries a 768-dimensional hidden state per position, splits attention into 12 heads, and expands to 3072 dimensions inside its position-wise feed-forward sublayer.\n\nTwo choices depart from the original. The stack is decoder-only with [[masked-self-attention|masked self-attention]] rather than an encoder-decoder pair, and positions are represented by learned embeddings rather than fixed sinusoids.\n\nLayer normalization is used extensively throughout the model, and the paper reports that a simple $\\mathcal{N}(0, 0.02)$ [[weight-initialization]] was sufficient because of it.\n\nEverything downstream — the fine-tuning results, the layer-transfer curve, the ablations — is this one model, so the spec is the fixed point the experiments vary around.", "prerequisites": ["multi-layer-transformer-decoder", "decoder-only-stack"], "sectionIds": ["4.1"], "floor": false, "citedFrom": {"citationKey": "[62]", "refText": "A. Vaswani, N. Shazeer, N. Parmar, J. Uszkoreit, L. Jones, A. N. Gomez, Ł. Kaiser, and I. Polosukhin. Attention is all you need. NIPS, 2017.", "whyNeeded": "The architecture the spec largely follows is defined there; this section records only the deltas and the hyperparameter values."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "twelve-layer-depth", "name": "12 Layers", "tier": "minor", "parent": "model-specification", "summary": "The stack is twelve decoder blocks deep, and the analysis section treats that depth as a dial the transfer experiments turn.", "explanation": "Depth here is the number of identical decoder blocks stacked between the embeddings and the output.\n\nTwelve is the paper's choice for pre-training.\n\nIt is also the quantity the layer-transfer experiment sweeps. Transferring zero layers means keeping only the embeddings; full transfer means carrying all twelve into the fine-tuned model.\n\nSo the number is more than a size setting. It sets the resolution of the analysis curve, which reports performance for each count of layers carried over.", "prerequisites": ["model-specification"], "sectionIds": ["4.1", "5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "hidden-state-dimension-768", "name": "768-Dimensional States", "tier": "minor", "parent": "model-specification", "summary": "Each token is represented by a 768-dimensional vector at every layer of the stack.", "explanation": "The model width is 768. Every token embedding, every layer output and every residual stream vector has that many components.\n\nWidth is what the residual connections force to stay constant: because each sublayer adds its output back onto its input, the two must have the same size all the way up.\n\nIt also interacts with the head count. Splitting 768 across 12 attention heads gives each head $768/12 = 64$ dimensions to work in.", "prerequisites": ["model-specification"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "twelve-attention-heads", "name": "12 Attention Heads", "tier": "minor", "parent": "model-specification", "summary": "Each layer's self-attention is split into twelve parallel heads, each attending in a 64-dimensional subspace.", "explanation": "Multi-head attention runs several attention operations side by side instead of one wide one. Each head projects the 768-dimensional state into a smaller subspace, attends there, and the outputs are concatenated back.\n\nWith 12 heads over 768 dimensions, each head works in $768/12 = 64$ dimensions, and twelve 64-dimensional outputs restore the full width.\n\nEvery one of these heads is masked, so all twelve see only the current position and earlier ones.", "prerequisites": ["model-specification", "masked-self-attention", "hidden-state-dimension-768"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "position-wise-feedforward-3072", "name": "3072-Dimensional Inner Feed-Forward States", "tier": "minor", "parent": "model-specification", "summary": "The feed-forward sublayer in each block expands from 768 to 3072 dimensions and projects back down.", "explanation": "After attention, each block passes every position independently through a small two-layer network. Position-wise means the same network is applied to each token's vector separately, with no mixing across positions.\n\nThe paper sets the inner width to 3072. So the sublayer projects $768 \\rightarrow 3072$, applies its nonlinearity, then projects $3072 \\rightarrow 768$ to restore the residual width.\n\nThat is a factor of four expansion in the middle.\n\nThe nonlinearity applied at the 3072-dimensional point is [[gelu]].", "prerequisites": ["model-specification", "hidden-state-dimension-768", "gelu"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "gelu", "name": "Gaussian Error Linear Unit (GELU)", "tier": "minor", "parent": "model-specification", "summary": "The activation function used in place of ReLU. It gates each input by the probability that a standard normal draw falls below it.", "explanation": "A ReLU makes a hard decision: keep the input if it is positive, otherwise output zero. GELU makes the same decision smoothly.\n\nIt multiplies the input by the standard normal cumulative distribution function evaluated at that input, $\\mathrm{GELU}(x) = x\\,\\Phi(x)$.\n\nA large positive input passes through almost unchanged, because $\\Phi(x)$ is near 1. A large negative input is suppressed, because $\\Phi(x)$ is near 0. Inputs near zero are scaled by something in between rather than snapped to one side.\n\nThe paper adopts it without argument, as one line in the specification. It appears at the 3072-dimensional point inside every position-wise feed-forward sublayer.", "prerequisites": ["model-specification"], "sectionIds": ["4.1"], "floor": false, "citedFrom": {"citationKey": "[18]", "refText": "D. Hendrycks and K. Gimpel. Bridging nonlinearities and stochastic regularizers with gaussian error linear units. arXiv:1606.08415, 2016.", "whyNeeded": "The activation is defined and motivated there; this paper only names it."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "layer-normalization-gpt1", "name": "Layer Normalization", "tier": "minor", "parent": "model-specification", "summary": "Per-position normalization of activations to zero mean and unit variance, with learned gain and bias. Used throughout the stack.", "explanation": "Layer normalization rescales each position's activation vector using statistics computed over that vector's own components, then applies a learned gain and bias.\n\nThe paper treats it as standard equipment and notes only how heavily it is used.\n\nThe consequence that matters in the setup section is that layernorm sits between the layers everywhere, which is the reason the paper gives for its simple [[weight-initialization]].", "prerequisites": ["transformer-gpt1"], "sectionIds": ["4.1"], "floor": true, "citedFrom": {"citationKey": "[2]", "refText": "J. L. Ba, J. R. Kiros, and G. E. Hinton. Layer normalization. arXiv:1607.06450, 2016.", "whyNeeded": "Definition of the normalization scheme the setup relies on."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "weight-initialization", "name": "$\\mathcal{N}(0, 0.02)$ Weight Initialization", "tier": "minor", "parent": "model-specification", "summary": "All weights are drawn from a normal distribution with standard deviation 0.02, which the paper says was sufficient because layernorm is used throughout.", "explanation": "Deep stacks are usually sensitive to initialization scale, because activations can grow or shrink multiplicatively as they pass through many layers.\n\nThe paper reports it did not need a scale-aware scheme. Weights are sampled from $\\mathcal{N}(0, 0.02)$.\n\nIts stated reason is layer normalization: because activations are renormalized at every layer, the scale drift that initialization schemes are designed to prevent is corrected as it arises.\n\nThis is reported as an observation about what worked, not as an analysis.", "prerequisites": ["model-specification", "layer-normalization-gpt1"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "pre-training-optimization", "name": "Pre-Training Optimization Setup", "tier": "major", "parent": "generative-pretraining", "summary": "How the language model was actually trained: Adam, a warmup-then-cosine schedule peaking at 2.5e-4, and 100 epochs of 64-sequence minibatches.", "explanation": "The setup section fixes the optimizer and its schedule as tightly as it fixes the architecture.\n\nUpdates use Adam. The learning rate does not start at its maximum: it rises linearly from zero over the first 2000 updates, peaks at 2.5e-4, then decays to zero along a cosine curve for the rest of training.\n\nTraining runs for 100 epochs over BooksCorpus. Each minibatch holds 64 sequences, and each sequence is a contiguous 512-token span sampled at random from the corpus.\n\nThese are the numbers a reader would need to reproduce the pre-trained model that everything else in the paper starts from.", "prerequisites": ["bookscorpus", "language-modeling-objective"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "adam-optimizer-gpt1", "name": "Adam Optimizer", "tier": "minor", "parent": "pre-training-optimization", "summary": "The adaptive gradient method used for pre-training, with a maximum learning rate of 2.5e-4.", "explanation": "Adam keeps running averages of both the gradient and its square for each parameter, and divides the step by the square root of the second average.\n\nThe practical effect is a per-parameter step size. Parameters with consistently large gradients take proportionally smaller steps, so one global learning rate can serve very differently scaled parameters.\n\nThis paper sets that global rate's ceiling at 2.5e-4 for pre-training. It is a ceiling rather than a constant because the schedule warms up to it and then anneals away from it.\n\nAdam also matters for the weight decay choice, since the [[decoupled-weight-decay|modified L2 regularization]] the paper adopts is a fix specific to how decay interacts with Adam's adaptive denominator.", "prerequisites": ["pre-training-optimization"], "sectionIds": ["4.1"], "floor": false, "citedFrom": {"citationKey": "[27]", "refText": "D. P. Kingma and J. Ba. Adam: a method for stochastic optimization. arXiv:1412.6980, 2014.", "whyNeeded": "The update rule, its moment estimates and default betas are defined there and are needed to reproduce the schedule."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "linear-warmup", "name": "Linear Warmup Over 2000 Updates", "tier": "minor", "parent": "pre-training-optimization", "summary": "The learning rate is raised linearly from zero to 2.5e-4 across the first 2000 updates instead of starting at full size.", "explanation": "At the very start of training the parameters are random and Adam's running estimates of gradient scale rest on almost no data.\n\nTaking full-size steps in that regime can push the model somewhere it takes a long time to recover from. Warmup avoids the question by making the early steps small.\n\nThe schedule is linear in the update count: update 1 uses a rate near zero, update 2000 uses the full 2.5e-4, and the rate rises in equal increments in between.\n\nOnly after those 2000 updates does the annealing phase begin.", "prerequisites": ["pre-training-optimization", "adam-optimizer-gpt1"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "cosine-annealing", "name": "Cosine Learning Rate Annealing", "tier": "minor", "parent": "pre-training-optimization", "summary": "After warmup, the learning rate follows a cosine curve from 2.5e-4 down to zero over the remainder of training.", "explanation": "Once warmup ends the rate is decayed rather than held fixed. The paper anneals it to 0 on a cosine schedule.\n\nThe shape of that curve is the point. A cosine falling from peak to trough is nearly flat at first, steepest in the middle, and nearly flat again at the end.\n\nSo the model spends a long stretch training near the maximum rate, then gets a long gentle tail of very small steps.\n\nTraining ends with the learning rate at zero, meaning the final parameters are settled rather than still moving.", "prerequisites": ["pre-training-optimization", "linear-warmup"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "pretraining-schedule", "name": "100 Epochs of 64-Sequence Minibatches", "tier": "minor", "parent": "pre-training-optimization", "summary": "Pre-training makes 100 passes over BooksCorpus with minibatches of 64 randomly sampled contiguous sequences.", "explanation": "An epoch is one pass over the corpus, and the paper takes 100 of them.\n\nEach gradient step uses 64 sequences at once. The sequences are sampled at random from the corpus, but each is contiguous internally — a real 512-token span of a real book, not a bag of unrelated sentences.\n\nMultiplying out, a single minibatch supplies $64 \\times 512 = 32{,}768$ tokens. Because [[masked-self-attention|masked self-attention]] lets every position be a prediction target, essentially all of them contribute a next-token loss term in one forward pass.\n\nThe schedule also anchors the warmup figure: 2000 updates is a small slice of a 100-epoch run.", "prerequisites": ["pre-training-optimization", "context-window-512-tokens", "masked-self-attention"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "context-window-512-tokens", "name": "512-Token Context Window", "tier": "minor", "parent": "language-modeling-objective", "summary": "The window $k$ of preceding tokens a prediction may condition on, fixed at 512 contiguous tokens in the trained model.", "explanation": "In $L_1$ the conditioning set is written out as $u_{i-k},\\dots,u_{i-1}$, so $k$ fixes how far back the model may look when predicting token $i$.\n\nA larger $k$ lets the model condition on longer-range structure. It also costs more computation, since self-attention compares every position in the window against every other.\n\nSection 4.1 trains on contiguous spans of 512 tokens, so that is the window the model actually sees. Nothing outside it is visible to attention.\n\nBecause the span is contiguous, those 512 slots hold several paragraphs of one book. A shuffled corpus would fill the same slots with unrelated sentences.\n\nThe number also fixes the height of the learned position embedding table, since there must be one trained vector per slot. And it caps what any downstream task can present, because fine-tuning reuses the same window for its transformed inputs.", "prerequisites": ["language-modeling-objective", "long-range-contiguous-text"], "sectionIds": ["3.1", "4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "regularization-setup", "name": "Regularization Setup", "tier": "minor", "parent": "pre-training-optimization", "summary": "Three regularizers during pre-training: dropout at 0.1 in three places, a modified L2 weight decay at $w = 0.01$, and no decay on biases or gains.", "explanation": "The paper trains a 12-layer model for 100 epochs on a fixed corpus, so it states its defences against overfitting explicitly.\n\nDropout is applied at rate 0.1 in three distinct places: on the residual connections, on the embeddings, and inside attention.\n\nSeparately, a modified version of L2 regularization pulls weights towards zero with coefficient $w = 0.01$, applied to all weights except biases and gains.\n\nThe exemption is deliberate. Biases and layernorm gains are few in number and set operating points rather than input-output mappings, so shrinking them regularizes little and distorts normalization.", "prerequisites": ["dropout-gpt1", "model-specification"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "dropout-gpt1", "name": "Dropout", "tier": "minor", "parent": "regularization-setup", "summary": "Randomly zeroing activations during training to discourage co-adaptation. Assumed known.", "explanation": "During training a fraction of units is set to zero at random on each forward pass, so no unit can rely on any particular other unit being present.\n\nThis paper assumes the idea and specifies only rates and placement.", "prerequisites": [], "sectionIds": ["4.1"], "floor": true, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "residual-embedding-attention-dropout", "name": "Residual, Embedding and Attention Dropout at 0.1", "tier": "minor", "parent": "regularization-setup", "summary": "Dropout with rate 0.1 applied at three points: residual branches, the embedding layer, and attention.", "explanation": "The paper does not apply one blanket dropout; it names three sites.\n\nResidual dropout drops activations on a sublayer's output before it is added back onto the residual stream. Embedding dropout drops components of the summed token and position embeddings at the bottom of the stack. Attention dropout drops entries of the attention distribution itself, so a head cannot depend on one specific source position.\n\nAll three use the same rate of 0.1, meaning one value in ten is zeroed on each training pass.\n\nThe same rate is reused for a fresh dropout on the classifier during fine-tuning.", "prerequisites": ["dropout-gpt1", "regularization-setup", "masked-self-attention"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "decoupled-weight-decay", "name": "Modified L2 Regularization (Decoupled Weight Decay)", "tier": "minor", "parent": "regularization-setup", "summary": "A variant of L2 regularization designed for Adam, applied with $w = 0.01$ to all non-bias and non-gain weights.", "explanation": "Classical L2 regularization adds a penalty term to the loss, so its gradient flows through the optimizer like any other gradient.\n\nWith Adam that has a side effect. Adam divides every gradient component by its own running root-mean-square, so the penalty on a parameter with large gradients is scaled down while the penalty on a quiet parameter is scaled up.\n\nThe intended uniform pull towards zero therefore becomes uneven.\n\nThe modified version the paper adopts decouples the two. The decay is applied directly to the weights as a separate shrinkage step, outside Adam's adaptive rescaling, so the strength $w = 0.01$ means the same thing for every parameter it touches.", "prerequisites": ["regularization-setup", "adam-optimizer-gpt1"], "sectionIds": ["4.1"], "floor": false, "citedFrom": {"citationKey": "[37]", "refText": "I. Loshchilov and F. Hutter. Fixing weight decay regularization in adam. arXiv:1711.05101, 2017.", "whyNeeded": "The exact modified update rule, and why L2 and weight decay differ under Adam, live there; this section only names it and gives w."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "text-preprocessing-pipeline", "name": "Text Preprocessing Pipeline", "tier": "minor", "parent": "bookscorpus", "summary": "Raw BooksCorpus text is cleaned with ftfy, tokenized with spaCy, then converted to subword units by byte-pair encoding with 40,000 merges.", "explanation": "Between the raw books and the model sits a three-stage pipeline, and the paper names each stage.\n\nFirst ftfy repairs mangled text and standardizes some punctuation and whitespace. Then the [[spacy-tokenizer]] splits the cleaned text into word-level tokens.\n\nFinally byte-pair encoding maps those tokens into a subword vocabulary built with 40,000 merges. That is the unit the model actually sees, and the unit the reported perplexity of 18.4 is averaged over.\n\nThe order matters. BPE learns its merges from whatever the earlier stages produce, so encoding noise and inconsistent whitespace would otherwise be baked into the vocabulary.", "prerequisites": ["bookscorpus"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "ftfy", "name": "ftfy", "tier": "minor", "parent": "text-preprocessing-pipeline", "summary": "A library used to clean the raw BooksCorpus text and standardize some punctuation and whitespace.", "explanation": "Text scraped from the wild carries encoding damage: characters decoded under the wrong codec, stray control characters, curly and straight quotes used interchangeably.\n\nThe paper runs ftfy over raw BooksCorpus to repair this.\n\nThe reason to bother is downstream. Every distinct surface form is a separate thing for the tokenizer and for BPE to learn, so leaving three spellings of a quotation mark in the corpus spends vocabulary on an artefact of encoding.", "prerequisites": ["text-preprocessing-pipeline"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "spacy-tokenizer", "name": "spaCy Tokenizer", "tier": "minor", "parent": "text-preprocessing-pipeline", "summary": "The word-level tokenizer applied to the cleaned text before byte-pair encoding.", "explanation": "Tokenization here is the step that decides where one word ends and the next begins, including how to treat punctuation, contractions and hyphens.\n\nThe paper uses spaCy's tokenizer for this, and its output is a stream of word-level tokens.\n\nThose tokens are not what the model consumes. They are the input to byte-pair encoding, which then breaks rare ones into subword pieces.", "prerequisites": ["text-preprocessing-pipeline"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "byte-pair-encoding-gpt1", "name": "Byte-Pair Encoding (BPE)", "tier": "minor", "parent": "text-preprocessing-pipeline", "summary": "A subword vocabulary built by repeatedly merging the most frequent adjacent symbol pair, so common words stay whole and rare words split into pieces.", "explanation": "BPE starts from a vocabulary of individual characters, so at the outset every word is spelled out one character at a time.\n\nIt then counts adjacent symbol pairs across the corpus and merges the most frequent pair into a single new symbol. Repeating this grows the vocabulary by one entry per merge.\n\nBecause merges follow frequency, common sequences fuse early. A word like the becomes a single symbol quickly, while a rare proper noun is left as several pieces.\n\nThe payoff is that there is no out-of-vocabulary token. Any string can be spelled from pieces already in the vocabulary, down to single characters in the worst case.\n\nThe cost is that a rare word occupies several positions in the 512-token window rather than one.", "prerequisites": ["text-preprocessing-pipeline", "spacy-tokenizer"], "sectionIds": ["4.1"], "floor": false, "citedFrom": {"citationKey": "[53]", "refText": "R. Sennrich, B. Haddow, and A. Birch. Neural machine translation of rare words with subword units. arXiv:1508.07909, 2015.", "whyNeeded": "The merge algorithm and its training procedure are defined there; this paper gives only the merge count."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "bpe-merges-40000", "name": "40,000 Merges", "tier": "minor", "parent": "byte-pair-encoding-gpt1", "summary": "The number of merge operations used to build the vocabulary, the single knob controlling how coarse the subword units are.", "explanation": "Each merge adds one symbol, so 40,000 merges gives a vocabulary of roughly that size on top of the initial character set.\n\nThe count trades off two costs. Too few merges and common words stay fragmented, so the 512-token window holds less text and the model must reassemble words at every layer.\n\nToo many and the vocabulary grows large, inflating the embedding table and the output softmax while the extra entries cover ever rarer strings.\n\nAt 40,000 merges the frequent English vocabulary of BooksCorpus is largely whole-word and the tail is handled by pieces.\n\nThis is also why the reported 18.4 is a token-level perplexity: the averaging unit is one of these subword symbols, not a word.", "prerequisites": ["byte-pair-encoding-gpt1", "token-level-perplexity"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "fine-tuning-hyperparameters", "name": "Fine-Tuning Hyperparameters", "tier": "major", "parent": "supervised-fine-tuning", "summary": "Fine-tuning reuses the pre-training settings except for a learning rate of 6.25e-5, batch size 32, three epochs, classifier dropout 0.1, and a short warmup.", "explanation": "The paper's stated default is inheritance: unless it says otherwise, the fine-tuning run keeps the pre-training hyperparameters.\n\nThe exceptions are small. A fresh dropout at rate 0.1 is added to the classifier head. Most tasks use a learning rate of 6.25e-5, roughly a quarter of the pre-training maximum, with a batch size of 32.\n\nTraining is short. The paper reports that the model finetunes quickly and that 3 epochs sufficed for most cases.\n\nThe schedule is linear decay with warmup over 0.2% of training, and the [[auxiliary-lm-objective|auxiliary language modelling objective]] is weighted at $\\lambda = 0.5$.\n\nThe short, low-rate schedule is part of the paper's claim that adapting a pre-trained model to a task is cheap compared with training one. Note the hedge: most cases, not all.", "prerequisites": ["supervised-fine-tuning", "pre-training-optimization"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "classifier-dropout", "name": "Classifier Dropout", "tier": "minor", "parent": "fine-tuning-hyperparameters", "summary": "An extra dropout at rate 0.1 applied to the task-specific classifier head added during fine-tuning.", "explanation": "Fine-tuning attaches a small linear output layer on top of the transformer for each task.\n\nThat head is freshly initialized and trained on a labelled dataset that may hold only a few thousand examples, which makes it the most overfitting-prone part of the model.\n\nSo the paper adds dropout to it at rate 0.1, matching the rate used inside the pre-trained stack.", "prerequisites": ["fine-tuning-hyperparameters", "dropout-gpt1", "linear-output-layer-wy"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "fine-tuning-lr-and-batch", "name": "Learning Rate 6.25e-5, Batch Size 32", "tier": "minor", "parent": "fine-tuning-hyperparameters", "summary": "The optimization settings used for most fine-tuning runs, notably a learning rate about four times smaller than pre-training's peak.", "explanation": "Fine-tuning starts from parameters that already encode a working language model, so the goal is adjustment rather than learning from scratch.\n\nThe paper reflects this in the rate. Where pre-training peaked at 2.5e-4, most fine-tuning runs use 6.25e-5, a quarter of that.\n\nA smaller rate means smaller steps, so the pre-trained solution is nudged rather than overwritten. The batch is also halved, from 64 sequences to 32.\n\nThe hedge in the paper is worth keeping: it says most tasks, so some datasets used other values.", "prerequisites": ["fine-tuning-hyperparameters", "adam-optimizer-gpt1"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "three-epochs-fine-tuning", "name": "Three Epochs of Fine-Tuning", "tier": "minor", "parent": "fine-tuning-hyperparameters", "summary": "The paper reports that three passes over a task's training set were enough for most datasets.", "explanation": "Pre-training runs for 100 epochs; fine-tuning runs for 3.\n\nThe paper offers this as an observation about speed — the model finetunes quickly, and 3 epochs was sufficient for most cases.\n\nRead alongside the pre-training figure, it is the cheapness argument in numbers. One expensive unsupervised run is amortized across twelve datasets, each costing three short passes.\n\nAgain the claim is hedged with most cases rather than stated for all tasks.", "prerequisites": ["fine-tuning-hyperparameters"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "fine-tuning-lr-schedule", "name": "Linear Decay with 0.2% Warmup", "tier": "minor", "parent": "fine-tuning-hyperparameters", "summary": "During fine-tuning the learning rate warms up over the first 0.2% of updates, then decays linearly to zero.", "explanation": "Fine-tuning uses a different schedule shape from pre-training's cosine.\n\nThere is still a warmup, but a very short one: 0.2% of total updates, which over a three-epoch run is a handful of steps.\n\nAfter that the rate falls linearly to zero across the remaining updates.\n\nThe brief warmup does the same job as before, letting the freshly initialized classifier head take small steps before full-size updates start propagating into the pre-trained weights below it.", "prerequisites": ["fine-tuning-hyperparameters", "linear-warmup"], "sectionIds": ["4.1"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "evaluation-task-families", "name": "Four Task Families, Twelve Datasets", "tier": "major", "parent": null, "summary": "The paper evaluates on natural language inference, question answering and commonsense reasoning, semantic similarity, and text classification, across twelve datasets.", "explanation": "Rather than tuning one benchmark, the paper spreads evaluation across four families of supervised task.\n\nTwelve datasets sit under them, some drawn from the GLUE multi-task benchmark.\n\nThe spread is the argument. A single model with one architecture and one pre-training run is fine-tuned on each, with only the input transformation and the output head changing.\n\nThe headline is new state-of-the-art results on 9 of the 12 datasets, in many cases beating ensembles.\n\nThe paper also notes the datasets span sizes from roughly 5.7k training examples on STS-B up to roughly 550k on SNLI, and uses that range to claim the method is not just a large-data technique.", "prerequisites": ["supervised-fine-tuning", "task-specific-input-transformations", "natural-language-understanding"], "sectionIds": ["4.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "absolute-improvement", "name": "Absolute Improvement", "tier": "minor", "parent": "evaluation-task-families", "summary": "The paper reports its gains as differences in percentage points against the previous best, not as relative reductions in error.", "explanation": "There are two ways to report an improvement. A relative figure divides the gain by the previous score or the previous error. An absolute figure just subtracts.\n\nThe paper is explicit that its headline numbers are absolute: 8.9% on Story Cloze, 5.7% on RACE, 1.5% on MultiNLI and 5.5% on GLUE.\n\nSo an 8.9% absolute gain means accuracy moved by 8.9 points, which on a task already scoring high is a large shift.\n\nThe reporting style matters when comparing these numbers against figures quoted elsewhere.", "prerequisites": ["evaluation-task-families"], "sectionIds": ["abstract", "1", "4.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "state-of-the-art-9-of-12", "name": "9 of 12 Datasets", "tier": "minor", "parent": "evaluation-task-families", "summary": "The paper's headline count: new best published results on nine of the twelve datasets, in many cases beating ensembles.", "explanation": "Rather than a single benchmark number, the summary statistic is a count across the evaluation suite.\n\nThe paper reports new state-of-the-art results on 9 out of the 12 datasets, outperforming ensembles in many cases.\n\nThe three it does not claim are visible in the section text: RTE, where it trails a multi-task biLSTM, SST-2, where it calls its result competitive rather than best, and one of the three [[semantic-similarity]] datasets.\n\nRead carefully, the count also concedes that three specialised systems were not beaten.", "prerequisites": ["evaluation-task-families", "task-agnostic-model", "absolute-improvement"], "sectionIds": ["abstract", "1", "4.2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "glue-benchmark", "name": "GLUE Benchmark", "tier": "minor", "parent": "evaluation-task-families", "summary": "A recently released multi-task benchmark bundling several language understanding datasets, from which the paper draws some tasks and reports an overall score of 72.8.", "explanation": "GLUE collects existing language understanding datasets under one evaluation harness, so a single model can be scored across all of them and summarized by one aggregate number.\n\nThe paper says some of its tasks are available as part of this benchmark.\n\nIt reports an overall GLUE score of 72.8 against a previous best of 68.9, a 5.5% [[absolute-improvement]]. Because the aggregate mixes tasks with different metrics and sizes, it is a summary of breadth rather than a measurement of any one capability.\n\nThe introduction also points at the GLUE leaderboard in a footnote, as evidence that different pre-training objectives win on different tasks.", "prerequisites": ["evaluation-task-families"], "sectionIds": ["1", "4.2"], "floor": false, "citedFrom": {"citationKey": "[64]", "refText": "A. Wang, A. Singh, J. Michael, F. Hill, O. Levy, and S. R. Bowman. Glue: a multi-task benchmark and analysis platform for natural language understanding. arXiv:1804.07461, 2018.", "whyNeeded": "Which datasets GLUE contains and how the aggregate score is computed are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "baseline-comparisons", "name": "Baselines and Ensembles", "tier": "minor", "parent": "evaluation-task-families", "summary": "The prior systems measured against: mostly task-specific biLSTM architectures, sometimes with ELMo features, attention, or ensembling.", "explanation": "The comparison points in these tables are the previous best result on each dataset, which at this point are mostly bidirectional LSTM models designed for one task.\n\nTwo are named directly. A multi-task biLSTM model holds the RTE result of 61.7% the paper does not beat. A Single-task BiLSTM + ELMo + Attn model is the [[qqp]] baseline it improves on by 4.2%.\n\nSome baselines are ensembles — several models whose predictions are combined, which usually costs several times the compute of a single model.\n\nThe paper notes that its single fine-tuned model outperforms ensembles in many cases, which is part of its argument that one pre-trained model plus light adaptation can replace bespoke architectures.", "prerequisites": ["evaluation-task-families", "lstm-gpt1"], "sectionIds": ["4.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "lstm-gpt1", "name": "LSTM", "tier": "minor", "parent": "baseline-comparisons", "summary": "A recurrent architecture that processes tokens in sequence through a gated hidden state. Assumed known; used here as the comparison architecture.", "explanation": "An LSTM reads a sequence one position at a time, carrying a hidden state forward and using gates to control what is kept and what is overwritten.\n\nThe paper assumes this and uses LSTMs in two roles: as the backbone of most prior state-of-the-art baselines, and as the substitute architecture in its own ablation and zero-shot comparisons.", "prerequisites": [], "sectionIds": ["4.2", "5"], "floor": true, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "natural-language-inference", "name": "Natural Language Inference (Textual Entailment)", "tier": "minor", "parent": "evaluation-task-families", "summary": "Given a premise and a hypothesis, decide whether the premise entails the hypothesis, contradicts it, or leaves it open.", "explanation": "An NLI example is a pair of texts. The first is the premise and the second the hypothesis, and the label describes the relation from premise to hypothesis.\n\nEntailment means a reader accepting the premise would accept the hypothesis. Contradiction means accepting the premise rules the hypothesis out. Neutral means the premise leaves the question open.\n\nThe ordering is part of the problem, which is why the entailment transformation can concatenate the two in a fixed order and stop there.\n\nThe paper notes the task has attracted recent interest but remains challenging, because a decision can require lexical entailment — one word naming a subtype of another — plus coreference resolution and the resolution of lexical and syntactic ambiguity.\n\nIt evaluates on five NLI datasets deliberately drawn from different sources: image captions, transcribed speech, fiction, government reports, Wikipedia, science exams and news. Success is therefore not a property of one text domain.", "prerequisites": ["evaluation-task-families"], "sectionIds": ["abstract", "1", "2", "3.3", "4.2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "coreference", "name": "Coreference", "tier": "minor", "parent": "natural-language-inference", "summary": "Two expressions in a text referring to the same entity, for instance a pronoun and the name it stands for.", "explanation": "Coreference is the link between a mention and what it refers to. A pronoun, a definite description like the doctor, and a proper name can all point at one entity.\n\nAn NLI system has to resolve these links before it can compare premise with hypothesis, because the two sentences may name the same entity in different ways.\n\nThe paper lists coreference among the phenomena that make NLI difficult. It returns in the analysis section, where the DPRD zero-shot heuristic is a coreference problem in its own right.", "prerequisites": ["natural-language-inference"], "sectionIds": ["4.2", "5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "snli", "name": "SNLI", "tier": "minor", "parent": "natural-language-inference", "summary": "A large NLI dataset built from image captions; the biggest in the evaluation at roughly 550k training examples.", "explanation": "SNLI draws its premises from image captions, so the sentences describe concrete visual scenes.\n\nAt roughly 550,000 training examples it is the largest of the twelve datasets.\n\nThe paper reports an [[absolute-improvement]] of 0.6% over the previous best here — the smallest of its NLI gains, on the dataset where prior supervised methods already had the most labelled data.\n\nSNLI is also one end of the size argument, used against STS-B to claim the approach works across dataset sizes.", "prerequisites": ["natural-language-inference"], "sectionIds": ["4.2"], "floor": false, "citedFrom": {"citationKey": "[5]", "refText": "S. R. Bowman, G. Angeli, C. Potts, and C. D. Manning. A large annotated corpus for learning natural language inference. EMNLP, 2015.", "whyNeeded": "The dataset's construction, label scheme and split sizes are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "multinli", "name": "MultiNLI (MNLI)", "tier": "minor", "parent": "natural-language-inference", "summary": "A multi-genre NLI dataset covering transcribed speech, popular fiction and government reports, used as a benchmark and in the layer-transfer analysis.", "explanation": "MultiNLI keeps SNLI's three-way label scheme but widens the source material across genres.\n\nThe genre spread is the point. A model cannot succeed by learning the register of one text source.\n\nThe paper reports an [[absolute-improvement]] of up to 1.5% over the previous best, one of the three headline numbers quoted in the abstract.\n\nMultiNLI does double duty. It is also one of the two tasks plotted in the layer-transfer analysis, where transferring all twelve layers is worth up to 9% over transferring embeddings alone.", "prerequisites": ["natural-language-inference"], "sectionIds": ["abstract", "1", "4.2", "5"], "floor": false, "citedFrom": {"citationKey": "[66]", "refText": "A. Williams, N. Nangia, and S. R. Bowman. A broad-coverage challenge corpus for sentence understanding through inference. NAACL, 2018.", "whyNeeded": "The genre composition and matched/mismatched split structure are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "qnli", "name": "QNLI", "tier": "minor", "parent": "natural-language-inference", "summary": "An NLI dataset built over Wikipedia articles, where the paper reports its largest NLI gain at 5.8%.", "explanation": "QNLI presents the entailment task over text drawn from Wikipedia articles.\n\nIt is handled like the other four NLI datasets, through the sentence-pair input transformation and a classifier head.\n\nThe paper reports an [[absolute-improvement]] of 5.8% over the previous best result, the largest of its five NLI margins.\n\nQNLI is one of the datasets taken from the [[glue-benchmark]].", "prerequisites": ["natural-language-inference", "glue-benchmark"], "sectionIds": ["4.2"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "scitail", "name": "SciTail", "tier": "minor", "parent": "natural-language-inference", "summary": "An entailment dataset built from science exam questions, on which the paper reports a 5% absolute improvement.", "explanation": "SciTail poses the entailment task over material from science exams, so premises and hypotheses carry technical content rather than everyday description.\n\nIt is one of the five NLI datasets, chosen as part of the deliberate spread of text sources.\n\nThe paper reports an [[absolute-improvement]] of 5% over the previous best result.", "prerequisites": ["natural-language-inference"], "sectionIds": ["4.2"], "floor": false, "citedFrom": {"citationKey": "[25]", "refText": "T. Khot, A. Sabharwal, and P. Clark. Scitail: a textual entailment dataset from science question answering. AAAI, 2018.", "whyNeeded": "How entailment pairs were derived from science questions is defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "rte", "name": "RTE", "tier": "minor", "parent": "natural-language-inference", "summary": "A small NLI dataset over news articles, with 2490 training examples, and the one NLI dataset where the paper does not beat the previous best.", "explanation": "RTE is the smallest NLI dataset in the evaluation, with 2490 training examples drawn from news articles.\n\nHere the model reaches 56% accuracy, below the 61.7% reported by a multi-task biLSTM model. The paper states this plainly rather than working around it.\n\nIts explanation is size plus training regime. Given strong performance on the larger NLI datasets, it says it is likely the model would benefit from multi-task training as well.\n\nThat last clause is worth keeping as written, together with the admission that it has not explored this. The multi-task explanation is a conjecture the paper offers, not something it tests.", "prerequisites": ["natural-language-inference", "baseline-comparisons"], "sectionIds": ["4.2"], "floor": false, "citedFrom": {"citationKey": "[4]", "refText": "L. Bentivogli, P. Clark, I. Dagan, and D. Giampiccolo. The fifth pascal recognizing textual entailment challenge. TAC, 2009.", "whyNeeded": "The RTE challenge data and its label conventions are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "question-answering-and-commonsense-reasoning", "name": "Question Answering and Commonsense Reasoning", "tier": "minor", "parent": "evaluation-task-families", "summary": "Tasks requiring single- and multi-sentence reasoning over a passage: the paper evaluates on RACE and the Story Cloze Test.", "explanation": "This family asks the model to read a passage and select an answer, which needs reasoning that spans sentences rather than matching one.\n\nCommonsense reasoning is the harder end of it. Those problems cannot be settled by matching text against text; they need expectations about ordinary events — what usually follows what, what people typically want.\n\nBoth datasets are handled through the multiple-choice input transformation. The passage and question are concatenated with each candidate answer in turn, and the candidates are scored against each other.\n\nThe paper reports gains of up to 8.9% on Story Cloze and 5.7% overall on RACE, and reads these as evidence the model handles long-range contexts effectively.", "prerequisites": ["evaluation-task-families", "qa-and-commonsense-input-transformation"], "sectionIds": ["abstract", "1", "2", "4.2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "race-dataset", "name": "RACE", "tier": "minor", "parent": "question-answering-and-commonsense-reasoning", "summary": "A reading comprehension dataset of English exam passages and questions, chosen because it contains more reasoning-type questions than the alternatives.", "explanation": "RACE collects passages and multiple-choice questions from middle-school and high-school English examinations.\n\nThe paper's reason for choosing it is the question mix. It states that the corpus has been shown to contain more reasoning-type questions than datasets like CNN or SQuAD, which makes it a test of inference rather than of span matching.\n\nSince exam passages are long and the answer is often not local, the paper calls it a good fit for a model trained to handle long-range contexts, and reports a 5.7% overall improvement.\n\nRACE returns twice more. It is one of the two curves in the layer-transfer plot, and one of the four zero-shot heuristics is built for it.", "prerequisites": ["question-answering-and-commonsense-reasoning"], "sectionIds": ["abstract", "1", "4.2", "5"], "floor": false, "citedFrom": {"citationKey": "[30]", "refText": "G. Lai, Q. Xie, H. Liu, Y. Yang, and E. Hovy. Race: large-scale reading comprehension dataset from examinations. EMNLP, 2017.", "whyNeeded": "Passage length, question types, and the analysis showing it is more reasoning-heavy than CNN or SQuAD are established there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "cnn-and-squad-contrast", "name": "CNN and SQuAD as Contrast Datasets", "tier": "minor", "parent": "race-dataset", "summary": "Two earlier reading comprehension datasets named only to argue that RACE demands more reasoning than they do.", "explanation": "The paper does not evaluate on CNN or SQuAD. It mentions them to position RACE.\n\nBoth are established reading comprehension datasets in which answers are typically found in the passage, often as a span to be located rather than a conclusion to be drawn.\n\nThe claim is that RACE has been shown to contain more reasoning-type questions than these.\n\nNote the hedge in the phrasing. The paper cites this as an established finding about RACE rather than demonstrating it here.", "prerequisites": ["race-dataset"], "sectionIds": ["4.2"], "floor": false, "citedFrom": {"citationKey": "[19, 47]", "refText": "[19] K. M. Hermann et al. Teaching machines to read and comprehend. NIPS 2015. [47] P. Rajpurkar, J. Zhang, K. Lopyrev, and P. Liang. Squad: 100,000+ questions for machine comprehension of text. EMNLP, 2016.", "whyNeeded": "The comparison rests on what these datasets' questions look like, which is only established in those papers."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "story-cloze-test", "name": "Story Cloze Test", "tier": "minor", "parent": "question-answering-and-commonsense-reasoning", "summary": "A commonsense task: given a multi-sentence story, choose the correct ending from two options.", "explanation": "Each item gives a short everyday narrative followed by two candidate final sentences, exactly one of which is the real ending.\n\nBoth endings are written to be locally plausible, so word overlap alone does not settle it. Choosing correctly usually needs expectations about how situations resolve.\n\nThe paper reports an improvement of up to 8.9% over the previous best, its single largest margin and the number most often quoted from the abstract.\n\nThe two-option format maps directly onto the multiple-choice transformation: build one sequence per ending and compare their scores. This result is also the strongest support offered for the claim that pre-training on contiguous prose supplies [[world-knowledge]].", "prerequisites": ["question-answering-and-commonsense-reasoning", "qa-and-commonsense-input-transformation"], "sectionIds": ["abstract", "1", "4.2"], "floor": false, "citedFrom": {"citationKey": "[40]", "refText": "N. Mostafazadeh, M. Roth, A. Louis, N. Chambers, and J. Allen. Lsdsem 2017 shared task: the story cloze test. 2017.", "whyNeeded": "The shared-task setup, how the wrong endings were written, and the evaluation split are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "semantic-similarity", "name": "Semantic Similarity", "tier": "minor", "parent": "evaluation-task-families", "summary": "Deciding whether two sentences mean the same thing, also called paraphrase detection. Evaluated on MRPC, QQP and STS-B.", "explanation": "Semantic similarity asks whether two sentences are semantically equivalent, however differently they are worded. Some datasets want a binary answer, others a graded score.\n\nThe paper lists three difficulties: recognizing rephrasing of concepts, understanding negation, and handling syntactic ambiguity. Negation is the sharp one, since inserting a single not can flip meaning while leaving almost every word intact.\n\nThe relation is symmetric: if A paraphrases B then B paraphrases A. Section 3.3 makes the same point by saying there is no inherent ordering of the two sentences.\n\nThat symmetry is what the [[similarity-input-transformation]] is built to satisfy.\n\nThe paper reports state-of-the-art results on two of the three datasets: a 1 point absolute gain on STS-B and a 4.2% [[absolute-improvement]] on [[qqp]].", "prerequisites": ["evaluation-task-families", "similarity-input-transformation"], "sectionIds": ["abstract", "1", "3.3", "4.2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "mrpc", "name": "Microsoft Paraphrase Corpus (MRPC)", "tier": "minor", "parent": "semantic-similarity", "summary": "A paraphrase detection dataset collected from news sources; the one dataset where the LSTM ablation beats the transformer.", "explanation": "MRPC pairs sentences collected from news sources and labels whether each pair is a paraphrase.\n\nIt is one of three [[semantic-similarity]] datasets, and one of the two in this family on which the paper does not report a new state of the art.\n\nMRPC shows up again in the ablations. When the transformer is swapped for a single-layer 2048-unit LSTM, MRPC is the only dataset where the LSTM comes out ahead.\n\nThe paper records that exception without explaining it.", "prerequisites": ["semantic-similarity"], "sectionIds": ["4.2", "5"], "floor": false, "citedFrom": {"citationKey": "[14]", "refText": "W. B. Dolan and C. Brockett. Automatically constructing a corpus of sentential paraphrases. IWP2005.", "whyNeeded": "The corpus construction and its paraphrase labelling criteria are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "qqp", "name": "Quora Question Pairs (QQP)", "tier": "minor", "parent": "semantic-similarity", "summary": "A dataset of question pairs labelled for whether they ask the same thing, where the paper reports a 4.2% absolute improvement.", "explanation": "QQP consists of pairs of questions posted to Quora, labelled according to whether the two ask the same thing.\n\nThe paper calls its margin here significant: a 4.2% [[absolute-improvement]] over a Single-task BiLSTM + ELMo + Attn baseline.\n\nQQP also appears in the first ablation. It is one of the datasets, alongside the NLI tasks, where dropping the [[auxiliary-lm-objective|auxiliary language modelling objective]] hurts.\n\nThat is consistent with the paper's reading that larger datasets benefit from that objective.", "prerequisites": ["semantic-similarity", "baseline-comparisons"], "sectionIds": ["4.2", "5"], "floor": false, "citedFrom": {"citationKey": "[9]", "refText": "Z. Chen, H. Zhang, X. Zhang, and L. Zhao. Quora question pairs. 2018.", "whyNeeded": "The dataset release, size and labelling are defined there, and the size is needed for the 'larger datasets benefit' claim."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "sts-b", "name": "Semantic Textual Similarity Benchmark (STS-B)", "tier": "minor", "parent": "semantic-similarity", "summary": "A semantic similarity dataset of roughly 5.7k training examples, the smallest in the evaluation, where the paper reports a 1 point absolute gain.", "explanation": "STS-B scores how semantically close two sentences are, on a graded scale rather than a binary label.\n\nThe paper reports a 1 point absolute gain over the previous best.\n\nIts other role is as the small end of the size range. With roughly 5,700 training examples it anchors the claim that the approach works across datasets of different sizes, against SNLI's roughly 550,000 at the other end.\n\nThat range spans about two orders of magnitude, which is the basis for the paper's claim of robustness to dataset size.", "prerequisites": ["semantic-similarity"], "sectionIds": ["4.2"], "floor": false, "citedFrom": {"citationKey": "[6]", "refText": "D. Cer, M. Diab, E. Agirre, I. Lopez-Gazpio, and L. Specia. Semeval-2017 task 1: semantic textual similarity. arXiv:1708.00055, 2017.", "whyNeeded": "The similarity rating scale and correlation metric a '1 point absolute gain' is measured on are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "text-classification", "name": "Text Classification", "tier": "minor", "parent": "evaluation-task-families", "summary": "Single-sentence labelling tasks: CoLA for grammatical acceptability and SST-2 for binary sentiment.", "explanation": "This family takes one input sequence and returns one label, with no second sentence to compare against.\n\nIt is the simplest of the four types, because the input needs no restructuring beyond the [[start-and-end-tokens]] to be fed to a language model.\n\nThat simplicity is why earlier pre-training work stopped there: both closest predecessors demonstrated language-model pre-training on classification alone.\n\nThe results here split. CoLA jumps to 45.4 from a previous best of 35.0, which the paper reads as evidence of learned linguistic bias, while SST-2 reaches 91.3% accuracy, which it calls competitive with the state of the art rather than better.", "prerequisites": ["evaluation-task-families"], "sectionIds": ["abstract", "1", "2", "4.2", "6"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "cola", "name": "Corpus of Linguistic Acceptability (CoLA)", "tier": "minor", "parent": "text-classification", "summary": "Expert judgements on whether a sentence is grammatical. The paper reports a score of 45.4 against a previous best of 35.0.", "explanation": "CoLA contains sentences labelled by experts as grammatical or not, so the task probes syntax rather than content.\n\nThe paper describes it as testing the innate linguistic bias of trained models — whether a model has internalized what well-formed English looks like.\n\nIt reports 45.4, calls this an especially big jump over the previous best of 35.0, and reads the jump as showcasing linguistic bias learned during pre-training.\n\nThat reading is an interpretation offered on top of one number, not a controlled test of it.\n\nCoLA also reappears as one of the four zero-shot heuristics in the analysis.", "prerequisites": ["text-classification"], "sectionIds": ["4.2", "5"], "floor": false, "citedFrom": {"citationKey": "[65]", "refText": "A. Warstadt, A. Singh, and S. R. Bowman. Corpus of linguistic acceptability. 2018.", "whyNeeded": "The acceptability judgements and the correlation metric the 45.4 is measured in are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "sst-2", "name": "Stanford Sentiment Treebank (SST-2)", "tier": "minor", "parent": "text-classification", "summary": "A binary sentiment classification task, on which the paper reports 91.3% accuracy, competitive with but not beating the state of the art.", "explanation": "SST-2 labels sentences as positive or negative in sentiment, which the paper calls a standard binary classification task.\n\nThe model reaches 91.3% accuracy.\n\nThe paper describes this as competitive with the state-of-the-art results rather than as a new best, making it one of the three datasets out of twelve where it does not claim the top result.\n\nSST-2 also supplies one of the zero-shot heuristics, where sentiment is read off the language model directly.", "prerequisites": ["text-classification"], "sectionIds": ["4.2", "5"], "floor": false, "citedFrom": {"citationKey": "[54]", "refText": "R. Socher, A. Perelygin, J. Wu, J. Chuang, C. D. Manning, A. Ng, and C. Potts. Recursive deep models for semantic compositionality over a sentiment treebank. EMNLP, 2013.", "whyNeeded": "The treebank and its binary sentence-level split define what 91.3% accuracy is measured on, and the label vocabulary underpins the zero-shot heuristic."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "layers-transferred", "name": "Impact of Number of Layers Transferred", "tier": "major", "parent": null, "summary": "An analysis varying how many pre-trained layers are carried into fine-tuning, showing each transformer layer adds performance, up to 9% on MultiNLI for full transfer.", "explanation": "After pre-training, the paper can choose how much of the model to carry into the supervised task. Transfer zero layers and only the embeddings come across; transfer all twelve and the whole stack does.\n\nThe analysis sweeps that count on MultiNLI and RACE and plots performance against it.\n\nTwo things come out. Transferring embeddings helps, which the paper calls the standard result and which matches years of word-vector practice.\n\nBeyond that, each additional transformer layer keeps adding, up to 9% for full transfer on MultiNLI.\n\nThe paper's reading is that each layer of the pre-trained model contains useful functionality for solving target tasks, not just the bottom embedding layer. That is the argument against treating pre-training as a source of word vectors only.", "prerequisites": ["twelve-layer-depth", "supervised-fine-tuning", "multinli", "race-dataset"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "zero-shot-behaviors", "name": "Zero-Shot Behaviours", "tier": "major", "parent": null, "summary": "Heuristics that make the pre-trained generative model perform the evaluation tasks with no supervised fine-tuning at all, tracked across pre-training.", "explanation": "The paper wants to know why language model pre-training of transformers works, and puts forward a hypothesis: the generative model learns to perform many of the evaluation tasks in the course of improving its language modelling.\n\nTo test this it strips out the supervised part entirely. It designs one heuristic per task that reads an answer directly off the generative model, with no fine-tuning and no trained classifier head.\n\nIt then runs those heuristics at checkpoints across pre-training and plots how they do as a function of updates.\n\nThe reported pattern is that performance is stable and steadily increases, which the paper takes as evidence that pre-training builds task-relevant functionality rather than fine-tuning acquiring it.\n\nThe same heuristics are also run against an LSTM, which the paper reports shows higher variance in zero-shot performance.\n\nThese are heuristics the authors designed, so the absolute numbers say as much about the heuristic as about the model. The trend across updates is what the paper actually leans on.", "prerequisites": ["generative-pretraining", "language-modeling-objective", "labeled-dataset-c"], "sectionIds": ["1", "5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "average-token-log-probability-scoring", "name": "Average Token Log-Probability Scoring", "tier": "minor", "parent": "zero-shot-behaviors", "summary": "The common device behind three of the four heuristics: score a candidate string by the mean log-probability the language model assigns its tokens.", "explanation": "A language model returns a probability for each token given the tokens before it. Summing the logs of those probabilities gives a score for a whole string.\n\nDividing by the number of tokens gives the average.\n\nThat normalization matters when candidates differ in length, because a longer string accumulates more negative log-probability simply by being longer and would otherwise always lose.\n\nWith this in hand, choosing between candidates becomes a comparison of numbers. CoLA thresholds a single score; RACE and DPRD compare scores across candidates.\n\nNo training is involved. The score is read straight from the pre-trained model.", "prerequisites": ["zero-shot-behaviors", "language-modeling-objective"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "cola-zero-shot-heuristic", "name": "CoLA Zero-Shot Heuristic", "tier": "minor", "parent": "zero-shot-behaviors", "summary": "Score each sentence by the generative model's average token log-probability and predict acceptability by thresholding that score.", "explanation": "CoLA asks whether a sentence is grammatical, and the heuristic answers with fluency.\n\nEach example is scored as the average token log-probability the generative model assigns it. An ungrammatical sentence should contain at least one token the model finds unlikely in its context, dragging the average down.\n\nA threshold on that single number produces the binary prediction.\n\nThis is the simplest of the four heuristics: no substitution, no candidate comparison, just one score and a cut point.", "prerequisites": ["zero-shot-behaviors", "average-token-log-probability-scoring", "cola"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "sst2-zero-shot-heuristic", "name": "SST-2 Zero-Shot Heuristic", "tier": "minor", "parent": "zero-shot-behaviors", "summary": "Append the token 'very' to the example, restrict the output distribution to 'positive' and 'negative', and take whichever scores higher.", "explanation": "This heuristic turns sentiment classification into a next-token prediction.\n\nThe token very is appended to the example, setting up a continuation where an intensifier is naturally followed by an evaluative adjective.\n\nThe model's output distribution over the full vocabulary is then restricted to just two words, positive and negative. Every other token is ignored.\n\nThe prediction is whichever of the two the model assigns higher probability. Nothing is trained; the label is read out of the language model's own next-token distribution.", "prerequisites": ["zero-shot-behaviors", "sst-2", "output-softmax-tied-embeddings"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "race-zero-shot-heuristic", "name": "RACE Zero-Shot Heuristic", "tier": "minor", "parent": "zero-shot-behaviors", "summary": "Condition the generative model on the document and question, then pick the answer with the highest average token log-probability.", "explanation": "For RACE the heuristic uses the multiple-choice structure directly.\n\nThe document and the question are fed in as context. Each candidate answer is then scored by the average token log-probability the model assigns it, conditioned on that context.\n\nThe prediction is the candidate scoring highest.\n\nIn effect the question becomes: which of these continuations does the language model find least surprising after reading the passage? Averaging rather than summing keeps answers of different lengths comparable.", "prerequisites": ["zero-shot-behaviors", "average-token-log-probability-scoring", "race-dataset"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "dprd-winograd-heuristic", "name": "DPRD Winograd-Schema Zero-Shot Heuristic", "tier": "minor", "parent": "zero-shot-behaviors", "summary": "Substitute each possible referent for the definite pronoun and choose the resolution under which the rest of the sentence scores higher.", "explanation": "A Winograd-schema item is a sentence with an ambiguous definite pronoun whose correct referent turns on [[world-knowledge]] rather than grammar.\n\nThe heuristic makes the ambiguity explicit. The pronoun is replaced by each of the two possible referents in turn, producing two full sentences with nothing left to resolve.\n\nThe model then scores the rest of the sequence after the substitution, by average token log-probability, and the higher-scoring version wins.\n\nThe idea is that the wrong substitution makes the continuation less coherent, and a good language model registers that as lower probability.\n\nThis is the only one of the four heuristics that edits the input before scoring it.", "prerequisites": ["zero-shot-behaviors", "average-token-log-probability-scoring", "coreference"], "sectionIds": ["5"], "floor": false, "citedFrom": {"citationKey": "[46]", "refText": "A. Rahman and V. Ng. Resolving complex cases of definite pronouns: the winograd schema challenge. EMNLP-CoNLL, 2012.", "whyNeeded": "The DPRD dataset and the definite-pronoun-resolution format the heuristic operates on are defined there."}, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "transformer-inductive-bias", "name": "Structured Attentional Memory and Inductive Bias", "tier": "minor", "parent": "zero-shot-behaviors", "summary": "The paper's hypothesis that the transformer's attention gives it a more structured memory than an LSTM, which helps transfer.", "explanation": "An LSTM compresses everything it has read into a fixed-size recurrent state, so information from far back competes for the same vector.\n\nAttention keeps every earlier position addressable and retrieves from them on demand. The paper calls this a more structured attentional memory and hypothesizes that it assists in transfer compared with LSTMs.\n\nThe evidence offered is indirect. The LSTM shows higher variance in zero-shot performance across pre-training, while the transformer's heuristic scores are stable and rise steadily.\n\nThe paper's own wording is suggesting rather than showing. Stability differences on hand-designed heuristics are thin support for a claim about architectural bias, and the paper does not push it further.", "prerequisites": ["zero-shot-behaviors", "lstm-gpt1", "masked-self-attention", "long-range-dependencies-gpt1"], "sectionIds": ["1", "5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "ablation-studies", "name": "Ablation Studies", "tier": "major", "parent": null, "summary": "Three controlled removals reported in Table 5: dropping the auxiliary LM objective, replacing the transformer with an LSTM, and skipping pre-training entirely.", "explanation": "The results tables show that the full system wins. The ablations ask which of its parts are doing the work.\n\nEach removes one piece and holds the rest fixed. First the [[auxiliary-lm-objective|auxiliary language modelling objective]] is switched off during fine-tuning. Second the transformer is replaced by a single-layer 2048-unit LSTM in the same framework. Third the transformer is trained directly on the supervised tasks with no pre-training at all.\n\nThe sizes of the three effects are not equal, and that ordering is the finding.\n\nRemoving pre-training costs 14.8%, swapping the architecture costs 5.6 average score points, and the auxiliary objective helps only on some datasets.\n\nSo the ablations put pre-training first, the architecture second, and the auxiliary objective a distant and dataset-dependent third.", "prerequisites": ["supervised-fine-tuning", "generative-pretraining"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "ablation-no-auxiliary-objective", "name": "Ablation: No Auxiliary LM Objective", "tier": "minor", "parent": "ablation-studies", "summary": "Fine-tuning without the language modelling loss helps on some datasets and hurts on others, with larger datasets benefiting from keeping it.", "explanation": "This ablation sets the auxiliary term to zero during fine-tuning, so only the supervised loss is optimized.\n\nThe result is not uniform. The paper reports that the auxiliary objective helps on the NLI tasks and on [[qqp]], and that the overall trend suggests larger datasets benefit from it while smaller ones do not.\n\nOne reading is that the extra objective acts as a regularizer whose value depends on how much supervised signal there is. With plenty of labelled data the extra pull is affordable and useful; with little, it competes with the task.\n\nThe paper labels this a trend rather than a rule, and does not test the size explanation directly.", "prerequisites": ["ablation-studies", "auxiliary-lm-objective", "auxiliary-objective-weight"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "ablation-lstm-substitution", "name": "Ablation: LSTM Instead of Transformer", "tier": "minor", "parent": "ablation-studies", "summary": "Replacing the transformer with a single-layer 2048-unit LSTM in the same framework costs 5.6 average score points.", "explanation": "This ablation keeps the framework — the same pre-training, the same input transformations, the same fine-tuning procedure — and changes only the architecture.\n\nThe substitute is a single-layer LSTM with 2048 units. The paper reports a 5.6 average score drop relative to the transformer.\n\nOne exception is recorded: [[mrpc]] is the only dataset where the LSTM comes out ahead.\n\nThis is the ablation that isolates architecture from method, and it is the quantitative counterpart to the inductive-bias hypothesis in the zero-shot analysis. The paper reports the drop without attributing it to any particular property of the LSTM.", "prerequisites": ["ablation-studies", "lstm-gpt1", "decoder-only-stack", "mrpc"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}, {"id": "ablation-no-pretraining", "name": "Ablation: No Pre-Training", "tier": "minor", "parent": "ablation-studies", "summary": "Training the same transformer directly on the supervised tasks, with no pre-training, costs 14.8% across the board.", "explanation": "Here the architecture is unchanged and the [[generative-pretraining|generative pre-training]] stage is deleted. The transformer is trained on each supervised target task from scratch.\n\nThe paper reports that the lack of pre-training hurts performance across all the tasks, producing a 14.8% decrease compared with the full model.\n\nTwo details give this weight. The drop is uniform — across all the tasks, not concentrated in the small datasets where one would most expect it.\n\nAnd it is roughly three times the cost of swapping the architecture.\n\nThis is the ablation that carries the paper's central claim. Whatever the transformer contributes, the unsupervised pre-training stage contributes more.", "prerequisites": ["ablation-studies", "generative-pretraining", "supervised-fine-tuning", "transfer-learning"], "sectionIds": ["5"], "floor": false, "citedFrom": null, "sources": {"paperId": "gpt-1", "note": "", "sections": [], "pages": []}}], "items": [{"id": "fig-1", "kind": "figure", "number": 1, "caption": "Figure 1: (left) Transformer architecture and training objectives used in this work. (right) Input transformations for fine-tuning on different tasks. We convert all structured inputs into token sequences to be processed by our pre-trained model, followed by a linear+softmax layer.", "page": 4, "asset": "assets/fig-1.png", "title": "One Stack, Four Input Shapes", "takeaway": "The figure shows that a single decoder-only transformer, pre-trained once, serves every task in the paper: the left panel draws the block that is repeated twelve times and the two heads that sit on it, and the right panel shows that adapting to a new task means rewriting its input as one token sequence rather than redesigning the network. The only task-specific machinery is the added linear layer and the special tokens marking where the parts of an input begin and end.", "walkthrough": "Two diagrams sit side by side. The left one is the network and its training objectives. The right one is how four different kinds of task input are rewritten so that same network can read them.\n\n### Reading the left panel\n\nStart at the bottom. **Text & Position Embed** is the layer-zero input [[input-representation-h0]]: each token's embedding added to a vector for its slot in the sequence, where those slot vectors are trained rather than fixed sinusoids [[learned-position-embeddings]].\n\nThe arrow goes up into the blue box. Inside, **Masked Multi Self Attention** [[masked-self-attention]] lets each position attend to itself and earlier positions only, never later ones. The circled plus is the residual add, and **Layer Norm** [[layer-normalization-gpt1]] follows it. Then **Feed Forward** [[position-wise-feedforward-3072]], another add, another norm.\n\nThe **12x** bracket on the far left says this whole block is stacked twelve times [[twelve-layer-depth]], one feeding the next. That stack is the [[multi-layer-transformer-decoder]] — a [[decoder-only-stack]], with no encoder half.\n\nTwo arrows leave the top into two heads. **Text Prediction** is the next-token objective used for pre-training [[language-modeling-objective]] and kept during fine-tuning as an auxiliary term [[auxiliary-lm-objective]]. **Task Classifier** is the added output layer [[linear-output-layer-wy]]. Both draw on the same stack.\n\n### Reading the right panel\n\nEach row is one task family. The coloured boxes left of the bracket are a token sequence built by walking a structured input into one ordered line [[traversal-style-approach]]. **Start** and **Extract** are the randomly initialized bracketing tokens [[start-and-end-tokens]]; **Delim** is a `$` marking where one part ends [[delimiter-token]]. Extract is named for its job: its final-layer activation is what the classifier reads [[final-token-activation]].\n\nClassification is one span. Entailment concatenates premise and hypothesis [[entailment-input-transformation]].\n\nSimilarity draws **two** rows because the pair has no natural order [[similarity-input-transformation]]. Both orderings are run separately, and the circled plus adds the two representations element-wise before one **Linear** layer sees them.\n\nMultiple Choice builds one row per candidate answer [[qa-and-commonsense-input-transformation]]. Each row gets its own Linear head producing one score, and the small bar box on the right is the softmax over those scores.\n\nNothing in the blue stack changes across rows — that is the claim of a [[task-agnostic-model]].", "latex": null, "terms": [{"term": "Text & Position Embed", "definition": "The orange box at the bottom of the left panel: the input to layer zero, formed by adding each token's embedding to a learned vector for its position in the sequence. The paper writes this as $h_0 = UW_e + W_p$.", "conceptId": "input-representation-h0"}, {"term": "Masked Multi Self Attention", "definition": "The pink box: multi-head self-attention restricted so each position may attend only to itself and to earlier positions. The mask is what makes the stack usable as a left-to-right language model.", "conceptId": "masked-self-attention"}, {"term": "⊕ (circled plus, inside the block)", "definition": "The residual add: the sublayer's output is summed with the input that entered it, before normalization. Two appear per block, one after attention and one after the feed-forward.", "conceptId": null}, {"term": "Layer Norm", "definition": "The purple boxes: per-position normalization of activations to zero mean and unit variance with a learned gain and bias. It appears twice per block, after each residual add.", "conceptId": "layer-normalization-gpt1"}, {"term": "Feed Forward", "definition": "The yellow box: the position-wise feed-forward sublayer, applied to each position independently. In the trained model it expands 768 dimensions to 3072 and projects back down, with GELU in between.", "conceptId": "position-wise-feedforward-3072"}, {"term": "12x", "definition": "The bracket label on the far left of the blue box: the whole block drawn inside it is repeated twelve times, each layer's output feeding the next. It is not twelve parallel copies.", "conceptId": "twelve-layer-depth"}, {"term": "Blue box (the transformer block)", "definition": "The repeated unit of the stack: masked self-attention, residual add, layer norm, feed-forward, residual add, layer norm. Drawn once and multiplied by the 12x bracket.", "conceptId": "multi-layer-transformer-decoder"}, {"term": "Text Prediction", "definition": "The green head on the left: the next-token language modelling objective $L_1$. It is the only objective during pre-training, and stays on as a weighted auxiliary term during fine-tuning.", "conceptId": "language-modeling-objective"}, {"term": "Task Classifier", "definition": "The green head on the right: the supervised objective $L_2$, computed from a linear layer over the final activation. Both heads are drawn on the same stack because the paper trains them together during fine-tuning.", "conceptId": "supervised-fine-tuning"}, {"term": "Classification", "definition": "The first row on the right: a task whose input is a single span of text, such as sentiment or grammatical acceptability. It needs no restructuring beyond the bracketing tokens.", "conceptId": "text-classification"}, {"term": "Entailment", "definition": "The second row: given a premise and a hypothesis, decide whether the premise entails it, contradicts it, or leaves it open. The two parts are concatenated with a delimiter between them.", "conceptId": "entailment-input-transformation"}, {"term": "Similarity", "definition": "The third row: decide whether two sentences mean the same thing. Because neither sentence is naturally first, both orderings are built and processed.", "conceptId": "similarity-input-transformation"}, {"term": "Multiple Choice", "definition": "The fourth row: reading comprehension and commonsense tasks, where a context and question come with several candidate answers. One sequence is built per candidate.", "conceptId": "qa-and-commonsense-input-transformation"}, {"term": "Start", "definition": "The randomly initialized start token, written $\\langle s\\rangle$ in the text, placed at the front of every transformed sequence. Its embedding is one of the few parameters added at fine-tuning time.", "conceptId": "start-and-end-tokens"}, {"term": "Delim", "definition": "The delimiter token, written `$` in the text, inserted between the parts of a structured input to mark where one part ends and the next begins.", "conceptId": "delimiter-token"}, {"term": "Extract", "definition": "The end token $\\langle e\\rangle$ closing every sequence. It is labelled Extract because the final block's activation at this last position is the vector handed to the linear classifier.", "conceptId": "final-token-activation"}, {"term": "Text", "definition": "The single input span in the Classification row: the sentence or document being labelled.", "conceptId": null}, {"term": "Premise", "definition": "In the Entailment row, the statement assumed true. It is placed first in the sequence.", "conceptId": "natural-language-inference"}, {"term": "Hypothesis", "definition": "In the Entailment row, the statement whose status relative to the premise is being judged. It follows the delimiter.", "conceptId": null}, {"term": "Text 1 / Text 2", "definition": "The two sentences of a similarity pair. They appear in both orders across the two rows, so the model never sees only one arrangement.", "conceptId": null}, {"term": "Context", "definition": "In the Multiple Choice row, the document and question concatenated together, written $[z; q]$ in the text. It is repeated identically in every row of that block.", "conceptId": "structured-inputs"}, {"term": "Answer 1 / Answer 2 / Answer N", "definition": "The candidate answers, one per row. Each is appended after the delimiter to the same context.", "conceptId": null}, {"term": "Transformer (green box, right panel)", "definition": "A stand-in for the entire twelve-layer stack drawn in the left panel. Every green box in the right panel is the same pre-trained weights, not a separate model.", "conceptId": "task-agnostic-model"}, {"term": "Linear (orange box, right panel)", "definition": "The added output layer $W_y$ mapping the extracted activation to label scores, followed by a softmax. It is one of only two things added per task, the other being delimiter embeddings.", "conceptId": "linear-output-layer-wy"}, {"term": "⊕ (circled plus, Similarity row)", "definition": "Element-wise addition of the two sequence representations produced by the two orderings, before the single linear layer. Adding makes the result the same whichever sentence was called first.", "conceptId": null}, {"term": "Bar box (right of the Multiple Choice Linear heads)", "definition": "The small box with bars of different lengths: the output distribution over candidate answers, obtained by softmaxing the per-answer scores against each other.", "conceptId": null}, {"term": "Bracket (between the token row and the Transformer box)", "definition": "The tall brace on each row, grouping the token sequence as the single input handed to the stack. It carries no computation of its own.", "conceptId": null}], "numbers": [{"value": "12x", "meaning": "The number of times the drawn transformer block is stacked. The paper's model specification states a 12-layer decoder-only transformer; the analysis section then treats that depth as a dial, transferring varying numbers of these layers into fine-tuning."}, {"value": "2 (rows in Similarity)", "meaning": "Two rows because a similarity pair has no inherent ordering. The paper builds both orderings, processes each independently, and adds the results, so the prediction does not depend on which sentence was placed first."}, {"value": "1, 2, N (answer indices in Multiple Choice)", "meaning": "One row per candidate answer, with N standing for however many the dataset provides. RACE questions come with four options and the Story Cloze Test with two, so the figure leaves the count open."}, {"value": "3 (rows drawn for Multiple Choice)", "meaning": "Three rows are drawn only to show the pattern — first, second, and Nth. The vertical spacing implies the omitted middle rows."}, {"value": "768", "meaning": "The width of every token representation at every layer, from the embedding box to the top of the stack. Named in the model specification, not printed in the figure."}, {"value": "12 (attention heads)", "meaning": "The Masked Multi Self Attention box splits into twelve parallel heads, each attending in a 64-dimensional subspace since 768 divided by 12 is 64. Coincidentally equal to the layer count, but a separate setting."}, {"value": "3072", "meaning": "The inner width of the Feed Forward box: 768 in, 3072 in the middle, 768 out. Four times the state size, following the original transformer."}, {"value": "λ = 0.5", "meaning": "The weight on the Text Prediction head during fine-tuning, in $L_3 = L_2 + \\lambda L_1$. At 0.5 the language modelling term counts half as much as the task loss; the paper reports it helped generalization and convergence."}, {"value": "512", "meaning": "The context window in tokens, so the widest input any row of the right panel can present to the stack. Pre-training used contiguous sequences of this length."}], "sources": {"sections": [], "pages": [4]}}, {"id": "table-1", "kind": "table", "number": 1, "caption": "Table 1: A list of the different tasks and datasets used in our experiments.", "page": 5, "asset": "assets/table-1.png", "title": "The Twelve Evaluation Datasets", "takeaway": "This table is the paper's full evaluation menu: four families of supervised language understanding tasks covering twelve datasets in total. It establishes the breadth the paper is claiming for one pre-trained model, since the same weights are fine-tuned for every row rather than a different architecture being built per task.", "walkthrough": "You are looking at a two-column list, not a results table. The left column, \"Task\", names a family of supervised problems. The right column, \"Datasets\", names the specific benchmarks the paper fine-tunes and evaluates on inside that family. The bracketed numbers are citations to the papers that released each dataset, nothing more. Read it as an inventory: four rows, twelve datasets, and this is the complete set behind every number reported later. The paper calls this the [[evaluation-task-families]] set, and draws several entries from the [[glue-benchmark]], a then-recent bundle of language understanding datasets.\n\nRow one is [[natural-language-inference]]: read a premise and a hypothesis, then judge whether the premise entails it, contradicts it, or leaves it undecided. Five datasets stress that same task over different source text. [[snli]] is built from image captions. [[multinli]] mixes transcribed speech, popular fiction and government reports. [[qnli]] comes from Wikipedia articles. [[scitail]] is derived from science exam questions. [[rte]] is drawn from news.\n\nRow two is question answering, which the paper pairs with commonsense reasoning. [[race-dataset]] gives English exam passages from middle and high school with multiple-choice questions attached; the paper picks it because it says the questions demand more reasoning than other reading comprehension sets. [[story-cloze-test]] gives a short multi-sentence story and two candidate endings, and asks which one actually finishes it.\n\nRow three is sentence similarity, also called paraphrase detection: decide whether two sentences mean the same thing. [[mrpc]] pairs sentences from news sources. [[qqp]] pairs Quora questions and asks whether they ask the same thing. [[sts-b]] scores sentence pairs for degree of similarity.\n\nRow four is [[text-classification]], where the input is a single sentence. [[sst-2]] asks for binary sentiment. [[cola]] asks whether a sentence is grammatically acceptable, judged by experts.\n\nNotice the structural variety across rows: sentence pairs, document-question-answer triplets, single sentences. Handling all of it with one unchanged network is exactly what the [[task-specific-input-transformations]] are for, and what the paper means by a [[task-agnostic-model]]. Against these twelve, it reports [[state-of-the-art-9-of-12]].", "latex": null, "terms": [{"term": "Task", "definition": "The left column header. Each entry under it names a family of supervised problems that share a common input shape and a common notion of a correct answer.", "conceptId": "evaluation-task-families"}, {"term": "Datasets", "definition": "The right column header. Each entry under it is a specific labelled benchmark the paper fine-tunes on and reports a score for.", "conceptId": null}, {"term": "Natural language inference", "definition": "The first task family: given a premise sentence and a hypothesis sentence, decide whether the premise entails the hypothesis, contradicts it, or is neutral toward it. Also called recognizing textual entailment.", "conceptId": "natural-language-inference"}, {"term": "SNLI", "definition": "Stanford Natural Language Inference. An NLI dataset whose premises come from image captions; the paper describes it as the largest dataset in the whole evaluation.", "conceptId": "snli"}, {"term": "MultiNLI", "definition": "A multi-genre NLI dataset, spanning transcribed speech, popular fiction and government reports, so a model cannot rely on one text style. Also written MNLI in the results tables.", "conceptId": "multinli"}, {"term": "Question NLI", "definition": "QNLI, an NLI dataset built over Wikipedia articles in which a question and a sentence are paired and the model decides whether the sentence answers the question. The paper reports its largest NLI gain here.", "conceptId": "qnli"}, {"term": "RTE", "definition": "Recognizing Textual Entailment, an NLI dataset over news articles from the PASCAL challenge series. It is small, and it is the one NLI dataset where the paper does not beat the previous best.", "conceptId": "rte"}, {"term": "SciTail", "definition": "An entailment dataset constructed from science exam questions, so the premises and hypotheses carry science-domain content rather than everyday description.", "conceptId": "scitail"}, {"term": "Question Answering", "definition": "The second task family, which the paper elsewhere widens to question answering and commonsense reasoning. It asks the model to reason across one or several sentences of a passage to select an answer.", "conceptId": "question-answering-and-commonsense-reasoning"}, {"term": "RACE", "definition": "A reading comprehension dataset of English passages and multiple-choice questions taken from Chinese middle and high school exams. The paper chooses it on the grounds that it contains more reasoning-type questions than earlier comprehension sets.", "conceptId": "race-dataset"}, {"term": "Story Cloze", "definition": "The Story Cloze Test: given a multi-sentence story, pick which of two candidate final sentences is the correct ending. It tests commonsense expectations about how situations resolve.", "conceptId": "story-cloze-test"}, {"term": "Sentence similarity", "definition": "The third task family, also called paraphrase detection: decide whether two sentences are semantically equivalent, which requires handling rephrasing, negation and syntactic ambiguity.", "conceptId": "semantic-similarity"}, {"term": "MSR Paraphrase Corpus", "definition": "MRPC, a paraphrase detection dataset of sentence pairs collected from news sources and labelled for whether each pair says the same thing.", "conceptId": "mrpc"}, {"term": "Quora Question Pairs", "definition": "QQP, a dataset of pairs of questions posted to Quora, each labelled for whether the two questions are asking the same thing.", "conceptId": "qqp"}, {"term": "STS Benchmark", "definition": "STS-B, the Semantic Textual Similarity benchmark from a SemEval shared task, where sentence pairs carry a graded similarity score rather than a binary same/different label. It is the smallest training set in the evaluation.", "conceptId": "sts-b"}, {"term": "Classification", "definition": "The fourth task family. Here the input is a single sentence with no second part, and the model assigns it one label.", "conceptId": "text-classification"}, {"term": "Stanford Sentiment Treebank-2", "definition": "SST-2, the two-class version of the Stanford Sentiment Treebank: label a sentence as positive or negative sentiment.", "conceptId": "sst-2"}, {"term": "CoLA", "definition": "The Corpus of Linguistic Acceptability: expert judgements on whether a sentence is grammatical. The paper uses it as a probe of what it calls a model's innate linguistic bias.", "conceptId": "cola"}, {"term": "Bracketed numbers, e.g. [5]", "definition": "Reference markers pointing into the paper's bibliography, identifying the work that released each dataset. They carry no experimental meaning.", "conceptId": null}], "numbers": [{"value": "4", "meaning": "The number of rows, and so the number of task families the paper groups its evaluation into: natural language inference, question answering, sentence similarity, and classification. Section 4.2 lists the same four."}, {"value": "12", "meaning": "The total dataset count across the four rows: 5 + 2 + 3 + 2. The paper's headline claim is stated against this denominator."}, {"value": "5", "meaning": "Datasets in the natural language inference row (SNLI, MultiNLI, Question NLI, RTE, SciTail). The paper says it beats the previous best on four of these five, RTE being the exception."}, {"value": "2 (question answering row)", "meaning": "Datasets in the question answering row: RACE and Story Cloze. It is the shortest row, but the paper leans on it for the claim about handling long-range context."}, {"value": "3", "meaning": "Datasets in the sentence similarity row (MRPC, QQP, STS Benchmark). The paper reports state-of-the-art results on two of these three."}, {"value": "2 (classification row)", "meaning": "Datasets in the classification row: SST-2 and CoLA. Both take a single sentence as input rather than a pair."}, {"value": "-2 in Stanford Sentiment Treebank-2", "meaning": "Not a citation. It marks the two-class variant of the Sentiment Treebank, positive versus negative, as opposed to the finer-grained five-way version of the same corpus."}, {"value": "[5]", "meaning": "Cites Bowman et al., 2015, the paper that released SNLI."}, {"value": "[66]", "meaning": "Cites Williams et al., 2018, the paper that released MultiNLI."}, {"value": "[64]", "meaning": "Cites Wang et al., 2018, the GLUE benchmark paper. Question NLI is attributed to GLUE because it is packaged and distributed there rather than as a standalone release."}, {"value": "[4]", "meaning": "Cites Bentivogli et al., 2009, the fifth PASCAL recognizing textual entailment challenge, the source of RTE."}, {"value": "[25]", "meaning": "Cites Khot et al., 2018, the paper that released SciTail."}, {"value": "[30]", "meaning": "Cites Lai et al., 2017, the paper that released RACE."}, {"value": "[40]", "meaning": "Cites Mostafazadeh et al., 2017, the LSDSem shared task paper defining the Story Cloze Test."}, {"value": "[14]", "meaning": "Cites Dolan and Brockett, 2005, the paper that released the MSR Paraphrase Corpus."}, {"value": "[9]", "meaning": "Cites Chen et al., 2018, the Quora data release for the Question Pairs dataset."}, {"value": "[6]", "meaning": "Cites Cer et al., 2017, the SemEval-2017 Task 1 paper behind the STS Benchmark."}, {"value": "[54]", "meaning": "Cites Socher et al., 2013, the paper that released the Stanford Sentiment Treebank."}, {"value": "[65]", "meaning": "Cites Warstadt et al., 2018, the CoLA release."}, {"value": "9 of 12", "meaning": "Not printed in the table, but the count it underwrites: Section 4.2 reports new state-of-the-art results on nine of these twelve datasets, in many cases against ensembles."}, {"value": "≈550k / ≈5.7k", "meaning": "Training-example counts the paper gives for the largest and smallest datasets in this list, SNLI and STS-B respectively, used to argue the method works across dataset sizes."}, {"value": "2490", "meaning": "Training examples in RTE, the figure the paper offers to explain why it underperforms there (56% accuracy against a prior 61.7%)."}], "sources": {"sections": [], "pages": [5]}}, {"id": "table-2", "kind": "table", "number": 2, "caption": "Table 2: Experimental results on natural language inference tasks, comparing our model with current state-of-the-art methods. 5x indicates an ensemble of 5 models. All datasets use accuracy as the evaluation metric.", "page": 6, "asset": "assets/table-2.png", "title": "NLI Benchmark Scoreboard", "takeaway": "Table 2 compares one fine-tuned general model against task-built baselines on five natural language inference datasets, and reports it ahead on four of them — by 1.5 points on MNLI, 5 on SciTail, 5.8 on QNLI and 0.6 on SNLI — while losing on RTE, the smallest dataset, where a multi-task biLSTM scores 61.7 against this model's 56.0.", "walkthrough": "Table 2 is the scoreboard for one of the four task families in the paper's evaluation: [[natural-language-inference]]. The task is to read a premise and a hypothesis and judge the relationship between them as entailment, contradiction, or neutral. Rows are systems; columns are the five datasets those systems are measured on.\n\nEvery cell is accuracy in percent. The caption says all datasets here use accuracy, so numbers are comparable down a column. They are not comparable across columns, since each dataset has its own difficulty and its own label set.\n\nA dash means that system reported no number there. Most baselines are built for one or two datasets, so most of the grid is empty.\n\n### The columns\n\n[[multinli]] is split in two. MNLI-m is the matched development set, whose text genres also appear in training; MNLI-mm is the mismatched set, drawn from genres held out. [[snli]] is the largest dataset in the whole evaluation, roughly 550k training pairs from image captions. [[scitail]] comes from science exams, [[qnli]] from Wikipedia, and [[rte]] from news articles with only 2,490 training examples.\n\n### The row blocks\n\nThree horizontal rules cut the rows into four blocks. The top block is ensembles: `5x` means five separately trained copies whose predictions are combined, `3x` means three. The second block is CAFE again as a single model, which is why every score sits a point or so below its own `5x` row. The third block is two multi-task baselines from the [[glue-benchmark]] paper, each trained on many tasks at once — which is why they, alone among the [[baseline-comparisons]], can fill the QNLI and RTE columns. The bottom block is this paper's model: one [[task-agnostic-model]], fine-tuned per task, not an ensemble.\n\nBold marks the best number in a column. Underline marks the best prior result in columns where the bold belongs to this paper.\n\n### What it shows\n\nTake MNLI-m: the underlined 80.6 is the ensemble Stochastic Answer Network, and 82.1 beats it by 1.5 points. The same subtraction gives 5.0 on SciTail, 5.8 on QNLI, and 0.6 on SNLI — the [[absolute-improvement]] figures quoted in the text.\n\nRTE is the exception. At 56.0 the model falls 5.7 points short of 61.7. The paper attributes this to RTE's size and suggests multi-task training would likely help, while noting it did not try that.", "latex": null, "terms": [{"term": "Method", "definition": "The first column, listing the systems being compared. Each row is one system, identified by name, citation number, and ensemble size if it is an ensemble.", "conceptId": null}, {"term": "MNLI-m", "definition": "The matched development set of MultiNLI, where the test text comes from the same genres seen during training. Higher accuracy is better.", "conceptId": "multinli"}, {"term": "MNLI-mm", "definition": "The mismatched development set of MultiNLI, drawn from genres held out of training, so it measures how well a system transfers across text genres. It is the harder of the two MNLI columns for almost every row here.", "conceptId": "multinli"}, {"term": "SNLI", "definition": "The Stanford Natural Language Inference dataset, built from image captions and the largest dataset in the paper's whole evaluation at roughly 550k training pairs.", "conceptId": "snli"}, {"term": "SciTail", "definition": "An entailment dataset constructed from science exam questions. It is the column where the paper reports its largest absolute gain alongside QNLI.", "conceptId": "scitail"}, {"term": "QNLI", "definition": "A natural language inference dataset built over Wikipedia articles, part of the GLUE bundle. Only the multi-task baselines and this paper's model report numbers in this column.", "conceptId": "qnli"}, {"term": "RTE", "definition": "Recognizing Textual Entailment, a small NLI dataset over news articles with 2,490 training examples. It is the one column here where this paper's model does not win.", "conceptId": "rte"}, {"term": "ESIM + ELMo [44] (5x)", "definition": "An Enhanced Sequential Inference Model — a task-specific biLSTM architecture for NLI — with ELMo representations added as input features, run as a five-model ensemble. It reports only an SNLI number.", "conceptId": "elmo-deep-contextualized-word-representations"}, {"term": "ELMo", "definition": "Deep contextualized word representations from a pre-trained bidirectional language model, fed into a separate task model as extra features rather than fine-tuned. It is the feature-based transfer approach this paper contrasts itself with.", "conceptId": "elmo-deep-contextualized-word-representations"}, {"term": "CAFE [58]", "definition": "A compare-propagate architecture with alignment factorization, a task-specific NLI model of Tay et al. It appears twice in the table, once as a five-model ensemble and once as a single model.", "conceptId": "baseline-comparisons"}, {"term": "Stochastic Answer Network [35] (3x)", "definition": "An NLI model of Liu et al. that makes its prediction through multiple stochastic inference steps, run here as a three-model ensemble. It holds the previous best on both MNLI columns.", "conceptId": "baseline-comparisons"}, {"term": "GenSen [64]", "definition": "A multi-task sentence representation baseline reported in the GLUE paper. Because it is trained across tasks, it can report QNLI and RTE numbers that the single-dataset NLI systems cannot.", "conceptId": "baseline-comparisons"}, {"term": "Multi-task BiLSTM + Attn [64]", "definition": "A bidirectional LSTM with attention trained on multiple GLUE tasks at once. It is the system that beats this paper's model on RTE.", "conceptId": "lstm-gpt1"}, {"term": "Finetuned Transformer LM (ours)", "definition": "This paper's system: the transformer language model pre-trained on BooksCorpus, then fine-tuned on each dataset with the entailment input transformation. It is a single model, not an ensemble.", "conceptId": "two-stage-training-procedure"}, {"term": "5x", "definition": "Marks a row as an ensemble of five separately trained models whose predictions are combined. The caption defines it explicitly.", "conceptId": null}, {"term": "3x", "definition": "The same convention for an ensemble of three models. It appears only on the Stochastic Answer Network row.", "conceptId": null}, {"term": "accuracy", "definition": "The evaluation metric for every cell: the fraction of pairs whose relationship label the system predicts correctly, expressed as a percentage.", "conceptId": null}, {"term": "dash (-)", "definition": "A cell where that system reports no result for that dataset, usually because it was never evaluated on it. It is not a score of zero and should not be read as a failure.", "conceptId": null}, {"term": "bold", "definition": "Marks the highest accuracy in a column. It falls on this paper's model in five of six columns and on Multi-task BiLSTM + Attn in the RTE column.", "conceptId": null}, {"term": "underline", "definition": "Marks the best previous published result in a column, in the columns where the bold has gone to this paper's model. The gap between an underline and the bold below it is the paper's claimed absolute improvement.", "conceptId": "absolute-improvement"}, {"term": "horizontal rules", "definition": "The three interior rules group rows into ensembles, single-model task-specific systems, multi-task GLUE baselines, and this paper's model. They mark what kind of comparison each block is, not a ranking.", "conceptId": null}, {"term": "[44], [58], [35], [64]", "definition": "Bracketed citation numbers into the paper's reference list: [44] Peters et al. (ELMo), [58] Tay et al. (CAFE), [35] Liu et al. (Stochastic Answer Network), [64] Wang et al. (GLUE benchmark).", "conceptId": null}, {"term": "natural language inference", "definition": "Also called recognizing textual entailment: read a premise and a hypothesis, then choose entailment, contradiction, or neutral. All six columns are instances of this task.", "conceptId": "natural-language-inference"}, {"term": "multi-task training", "definition": "Training one model on several labelled tasks simultaneously, which is what the two [64] baselines do. The paper suggests this is why they hold up on the tiny RTE dataset.", "conceptId": "baseline-comparisons"}, {"term": "state-of-the-art methods", "definition": "The caption's term for the baseline rows: the best published systems on each dataset at the time of writing, most of them architectures designed for NLI specifically.", "conceptId": "task-specific-architectures"}], "numbers": [{"value": "89.3 (ESIM + ELMo 5x, SNLI)", "meaning": "The five-model ESIM+ELMo ensemble's SNLI accuracy, and the joint previous best on that dataset. It is underlined because this paper's 89.9 overtakes it."}, {"value": "80.2 (CAFE 5x, MNLI-m)", "meaning": "The five-model CAFE ensemble on matched MNLI. Not underlined, because the Stochastic Answer Network's 80.6 is higher."}, {"value": "79.0 (CAFE 5x, MNLI-mm)", "meaning": "The same ensemble on mismatched MNLI, 1.2 points below its own matched score — the usual pattern, since mismatched genres are unseen in training."}, {"value": "89.3 (CAFE 5x, SNLI)", "meaning": "CAFE's ensemble ties ESIM+ELMo's ensemble exactly on SNLI. Both are underlined as joint previous best."}, {"value": "80.6 (Stochastic Answer Network 3x, MNLI-m)", "meaning": "The previous best on matched MNLI, from a three-model ensemble, hence underlined. This paper's 1.5-point MNLI claim is measured against it."}, {"value": "80.1 (Stochastic Answer Network 3x, MNLI-mm)", "meaning": "The previous best on mismatched MNLI. This paper's 81.4 exceeds it by 1.3 points."}, {"value": "78.7 (CAFE single, MNLI-m)", "meaning": "Single-model CAFE on matched MNLI, 1.5 points below its own 5x ensemble row. The gap is the price of dropping the ensemble."}, {"value": "77.9 (CAFE single, MNLI-mm)", "meaning": "Single-model CAFE on mismatched MNLI, 1.1 points below its 5x version."}, {"value": "88.5 (CAFE single, SNLI)", "meaning": "Single-model CAFE on SNLI, 0.8 below its ensemble's 89.3 and 1.4 below this paper's 89.9."}, {"value": "83.3 (CAFE single, SciTail)", "meaning": "The only reported SciTail baseline in the table, and therefore the underlined previous best. This paper's 88.3 is 5.0 points above it."}, {"value": "71.4 / 71.3 (GenSen, MNLI-m / MNLI-mm)", "meaning": "GenSen's MNLI scores, roughly nine points below the dedicated NLI systems. A multi-task sentence encoder gives up accuracy on any one task in exchange for covering many."}, {"value": "82.3 (GenSen, QNLI)", "meaning": "The best baseline QNLI number, hence underlined. This paper's 88.1 clears it by 5.8 points, its largest NLI gain."}, {"value": "59.2 (GenSen, RTE)", "meaning": "GenSen's RTE accuracy. It is above this paper's 56.0 but below the 61.7 that takes the bold."}, {"value": "72.2 / 72.1 (Multi-task BiLSTM + Attn, MNLI-m / MNLI-mm)", "meaning": "This baseline's MNLI scores, slightly ahead of GenSen but roughly ten points behind this paper's model."}, {"value": "82.1 (Multi-task BiLSTM + Attn, QNLI)", "meaning": "Its QNLI accuracy, 0.2 below GenSen's underlined 82.3. Note this cell shares its value with the paper's MNLI-m result — the same digits in a different column."}, {"value": "61.7 (Multi-task BiLSTM + Attn, RTE)", "meaning": "The only bold number not on the paper's own row. It is the best RTE result in the table and beats this paper's model by 5.7 points."}, {"value": "82.1 (ours, MNLI-m)", "meaning": "This paper's matched MNLI accuracy: 80.6 + 1.5, the source of the abstract's 1.5% textual entailment claim."}, {"value": "81.4 (ours, MNLI-mm)", "meaning": "Mismatched MNLI, 1.3 points over the previous best 80.1. The model loses only 0.7 points moving from matched to mismatched genres."}, {"value": "89.9 (ours, SNLI)", "meaning": "SNLI accuracy, 0.6 above the two underlined 89.3 ensembles. The smallest of the paper's four NLI wins, on the largest dataset."}, {"value": "88.3 (ours, SciTail)", "meaning": "SciTail accuracy, 5.0 points above CAFE's 83.3."}, {"value": "88.1 (ours, QNLI)", "meaning": "QNLI accuracy, 5.8 points above GenSen's 82.3."}, {"value": "56.0 (ours, RTE)", "meaning": "The paper's RTE accuracy and its one loss in this table — below both [64] baselines. The text attributes it to RTE's small training set."}, {"value": "5 and 3 (in 5x, 3x)", "meaning": "The number of separately trained models combined in an ensemble row. The paper notes its single model still beats several of these ensembles."}, {"value": "2490", "meaning": "RTE's training set size, quoted in the text as the reason for the loss: too few labelled examples for fine-tuning alone to carry the model."}, {"value": "550k", "meaning": "SNLI's approximate training set size, quoted elsewhere in the paper as the largest of the twelve datasets. It sits at the opposite end of the size range from RTE."}, {"value": "1.5, 5, 5.8, 0.6", "meaning": "The four absolute improvements the text quotes, on MNLI, SciTail, QNLI and SNLI. Each is a bold cell minus the underlined cell above it in the same column."}, {"value": "5.7", "meaning": "The RTE shortfall: 61.7 minus 56.0. The paper states the loss rather than the difference, but this is its size."}, {"value": "4 of 5", "meaning": "How many of the five NLI datasets the paper claims to win, counting MNLI-m and MNLI-mm as one dataset. RTE is the fifth."}], "sources": {"sections": [], "pages": [6]}}, {"id": "table-3", "kind": "table", "number": 3, "caption": "Table 3: Results on question answering and commonsense reasoning, comparing our model with current state-of-the-art methods.. 9x means an ensemble of 9 models.", "page": 6, "asset": "assets/table-3.png", "title": "RACE and Story Cloze Results", "takeaway": "On the paper's two reading-and-reasoning benchmarks, a single fine-tuned transformer language model beats every previously published system, by 8.9 accuracy points on the Story Cloze Test and 5.7 points on RACE overall. The RACE baselines it passes are 9-model ensembles, while the paper's entry is one model.", "walkthrough": "This is the results table for the paper's [[question-answering-and-commonsense-reasoning]] family: two datasets, four score columns, five systems.\n\nEach row is a system and each column is a test set. Higher is better, and every number is an accuracy percentage. A dash means that system never reported a result on that dataset, so the row is simply blank there rather than scoring zero. The underlined number in each column is the best previously published result; the bold bottom row is this paper's model.\n\nThe datasets. [[story-cloze-test]] gives a multi-sentence story and two candidate endings, and asks which one is correct. [[race-dataset]] is reading comprehension built from English middle-school and high-school exam passages. RACE-m is the middle-school split, RACE-h the high-school split, and RACE the combined figure. Note that the combined score is not the average of the two splits: for the paper's model, 62.9 and 57.4 combine to 59.0, which sits nearer the high-school number, consistent with the high-school portion contributing more test questions. The same pattern holds for the baseline rows.\n\nThe \"(9x)\" annotation. Both RACE baselines are ensembles of nine separately trained models whose predictions are pooled — a standard way to buy a point or two of accuracy at nine times the compute. The paper's row carries no such annotation. It is one model, fine-tuned once per dataset from the same pre-trained weights ([[supervised-fine-tuning]]), with each candidate answer scored by appending it to the passage and question ([[qa-and-commonsense-input-transformation]]).\n\nThe margins. On Story Cloze, $86.5 - 77.6 = 8.9$. On RACE overall, $59.0 - 53.3 = 5.7$. Both are the [[absolute-improvement]] figures quoted in Section 4.2. The split columns show the gap is uneven: RACE-m improves by $62.9 - 60.2 = 2.7$, while RACE-h improves by $57.4 - 50.3 = 7.1$, so most of the RACE gain comes from the harder high-school questions.\n\nThe paper reads these margins as evidence that pre-training on long stretches of contiguous text lets the model use [[long-range-dependencies-gpt1]] — the passage detail several sentences away that answers the question. That is an interpretation, not something the table measures directly.", "latex": null, "terms": [{"term": "Method", "definition": "The first column, listing the system being scored. Four prior published systems on top, the paper's own model on the bottom row.", "conceptId": "baseline-comparisons"}, {"term": "Story Cloze", "definition": "Column for the Story Cloze Test: given a multi-sentence story, pick the correct ending out of two candidates. Scores are accuracy, so 50 would be chance.", "conceptId": "story-cloze-test"}, {"term": "RACE-m", "definition": "The middle-school split of RACE — exam reading-comprehension questions written for younger students, and the easier of the two splits for every system in the table.", "conceptId": "race-dataset"}, {"term": "RACE-h", "definition": "The high-school split of RACE. Every system scores lower here than on RACE-m, which is where the paper's largest RACE gain comes from.", "conceptId": "race-dataset"}, {"term": "RACE", "definition": "The combined score over both RACE splits. It is not the plain average of RACE-m and RACE-h; it lands closer to RACE-h, consistent with the high-school portion being the larger share of the test questions.", "conceptId": "race-dataset"}, {"term": "val-LS-skip [55]", "definition": "A prior Story Cloze system (Srinivasan, Arora and Riedl, 2018), cited in the paper as reference 55. Included as a Story Cloze baseline only; it reports nothing on RACE.", "conceptId": "baseline-comparisons"}, {"term": "Hidden Coherence Model [7]", "definition": "A prior Story Cloze system (Chaturvedi, Peng and Roth, 2017), reference 7. Its 77.6 is the underlined previous best on Story Cloze.", "conceptId": "baseline-comparisons"}, {"term": "Dynamic Fusion Net [67] (9x)", "definition": "A prior RACE system (Xu et al., 2017), reference 67, evaluated as a 9-model ensemble. It reports no Story Cloze result.", "conceptId": "baseline-comparisons"}, {"term": "BiAttention MRU [59] (9x)", "definition": "A prior RACE system (Tay, Tuan and Hui, 2018), reference 59, also a 9-model ensemble. It holds the underlined previous best in all three RACE columns.", "conceptId": "baseline-comparisons"}, {"term": "(9x)", "definition": "The caption's shorthand: this row is an ensemble of 9 separately trained models whose predictions are pooled. It marks the baseline as costing roughly nine times the compute of a single model.", "conceptId": "baseline-comparisons"}, {"term": "Finetuned Transformer LM (ours)", "definition": "The paper's own system: the pre-trained decoder-only transformer language model, fine-tuned on each task's labelled data. One model per task, not an ensemble.", "conceptId": "two-stage-training-procedure"}, {"term": "Bold (bottom row)", "definition": "Typographic marker for the paper's own results. Here bold also happens to mark the best score in every column.", "conceptId": null}, {"term": "Underline", "definition": "Marks the best previously published result in each column — the number the paper's margin is measured against.", "conceptId": "absolute-improvement"}, {"term": "Dash (-)", "definition": "No result reported by that system on that dataset. It signals a missing entry, not a score of zero, so those cells carry no information about the system's ability.", "conceptId": null}], "numbers": [{"value": "76.5", "meaning": "val-LS-skip's Story Cloze accuracy. The weaker of the two Story Cloze baselines, and not the underlined best."}, {"value": "77.6", "meaning": "Hidden Coherence Model's Story Cloze accuracy, underlined as the previous best on this dataset. It is the number the paper's 8.9-point gain is computed against."}, {"value": "55.6", "meaning": "Dynamic Fusion Net (9x) on RACE-m. Beaten by the other ensemble, so not underlined."}, {"value": "49.4", "meaning": "Dynamic Fusion Net (9x) on RACE-h. Below its own middle-school score, showing the high-school split is harder for this system too."}, {"value": "51.2", "meaning": "Dynamic Fusion Net (9x) on RACE overall. It sits between 49.4 and 55.6 and nearer the high-school figure, the same weighting pattern seen in every row."}, {"value": "60.2", "meaning": "BiAttention MRU (9x) on RACE-m, underlined as the previous best middle-school score."}, {"value": "50.3", "meaning": "BiAttention MRU (9x) on RACE-h, underlined as the previous best high-school score."}, {"value": "53.3", "meaning": "BiAttention MRU (9x) on RACE overall, underlined as the previous best. The reference point for the paper's 5.7-point RACE gain."}, {"value": "86.5", "meaning": "The paper's Story Cloze accuracy. The largest single-column margin in the table, and the paper's best absolute score here."}, {"value": "62.9", "meaning": "The paper's RACE-m accuracy, above the 60.2 ensemble baseline."}, {"value": "57.4", "meaning": "The paper's RACE-h accuracy. Notably, it is higher than any baseline's middle-school score except 60.2, despite being the harder split."}, {"value": "59.0", "meaning": "The paper's RACE overall accuracy, combining 62.9 and 57.4 with the high-school split weighted more heavily."}, {"value": "9 / 9x", "meaning": "The number of models pooled in each RACE baseline ensemble. The paper's row uses one model, so the comparison is single model against 9-model ensembles."}, {"value": "8.9", "meaning": "The Story Cloze margin, 86.5 minus 77.6. Section 4.2 quotes it as the paper's largest gain in this task family."}, {"value": "5.7", "meaning": "The RACE overall margin, 59.0 minus 53.3, quoted in Section 4.2 as the improvement 'on RACE'."}, {"value": "2.7", "meaning": "The RACE-m margin, 62.9 minus 60.2. The smallest gain in the table; the paper does not quote this number separately."}, {"value": "7.1", "meaning": "The RACE-h margin, 57.4 minus 50.3. Larger than the middle-school gain, so most of the RACE improvement comes from the harder split."}, {"value": "[55], [7], [67], [59]", "meaning": "Bracketed citation keys into the paper's reference list: Srinivasan et al. 2018, Chaturvedi et al. 2017, Xu et al. 2017, and Tay et al. 2018 respectively."}], "sources": {"sections": [], "pages": [6]}}, {"id": "table-4", "kind": "table", "number": 4, "caption": "Table 4: Semantic similarity and classification results, comparing our model with current state-of-the- art methods. All task evaluations in this table were done using the GLUE benchmark. (mc= Mathews correlation, acc=Accuracy, pc=Pearson correlation)", "page": 7, "asset": "assets/table-4.png", "title": "Classification and Similarity Results", "takeaway": "On the five GLUE tasks outside natural language inference, one fine-tuned transformer beats the previous best published number on CoLA, STS-B and QQP, and raises the overall GLUE score from 68.9 to 72.8. It does not win everywhere: on SST-2 and MRPC it stays below specialist systems that were built for those single datasets.", "walkthrough": "Six systems run down the left, five datasets run across the top, and one aggregate score sits in the last column.\n\nThe bottom row is the paper's model: the pre-trained transformer with a single linear layer trained on each task ([[two-stage-training-procedure]], [[supervised-fine-tuning]]). Every row above it is a previously published result ([[baseline-comparisons]]). The top three rows carry one number each, because those systems were built and evaluated for one dataset only. A dash means the paper has no comparable published number to cite, not a score of zero.\n\nThe column header has two levels. The upper level groups the datasets into task families: [[text-classification]] and [[semantic-similarity]]. The lower level names the dataset and, in parentheses, the metric it is scored with.\n\nThe metrics differ because the tasks differ. On [[cola]] the label is grammatical or not, and the two classes are unbalanced, so plain accuracy would flatter a model that always guesses the majority. *mc* is Matthews correlation instead — a correlation between prediction and truth where 0 is chance and 100 is perfect, printed here on a 0–100 scale. (The caption spells it \"Mathews\".) *acc* on [[sst-2]] is ordinary accuracy on a balanced binary sentiment label. *F1* on [[mrpc]] and [[qqp]] is the harmonic mean of precision and recall on the positive class — the pairs that really are paraphrases or duplicates — again because the positive class is the minority. *pc* on [[sts-b]] is Pearson correlation, used because that dataset's label is a graded similarity rating rather than a yes/no, so predictions are compared to human ratings by how well they track.\n\nThe final column is the [[glue-benchmark]] score: one number for the whole benchmark, so it folds in the inference datasets reported elsewhere in the paper, not only the five columns shown here.\n\nNo formatting key is given. In practice bold marks the highest number in a column, and underline marks the best prior number in the columns where the paper's model takes the top spot.\n\nReading the wins: CoLA moves 35.0 to 45.4, STS-B 81.0 to 82.0, QQP 66.1 to 70.3, and the GLUE total 68.9 to 72.8 ([[absolute-improvement]]).\n\nReading the losses: on SST-2 the model's 91.3 sits below both 93.2 and 91.6, and on MRPC its 82.3 sits below both 86.0 and 83.5. MRPC is also the one dataset where the paper's LSTM ablation beats its transformer ([[ablation-lstm-substitution]]). These are single reported runs, with no variance given.", "latex": null, "terms": [{"term": "Method", "definition": "The left-hand column, listing one system per row. The rows are ordered with prior published systems first and the paper's own model last.", "conceptId": null}, {"term": "Classification", "definition": "The upper-level header grouping the two single-sentence labelling datasets, CoLA and SST-2, where the model reads one sentence and emits one label.", "conceptId": "text-classification"}, {"term": "Semantic Similarity", "definition": "The upper-level header grouping the three sentence-pair datasets, MRPC, STS-B and QQP, where the model judges whether two sentences mean the same thing.", "conceptId": "semantic-similarity"}, {"term": "GLUE", "definition": "The rightmost column: a single score for the whole GLUE benchmark, which bundles these datasets together with the inference datasets the paper reports in its other tables.", "conceptId": "glue-benchmark"}, {"term": "CoLA", "definition": "Corpus of Linguistic Acceptability: expert judgements on whether a sentence is grammatical. The paper treats it as a probe of a model's implicit grasp of syntax.", "conceptId": "cola"}, {"term": "mc", "definition": "Matthews correlation, the metric for CoLA. It correlates predicted labels with true labels so that a majority-class guesser scores 0 rather than something high, and it is printed here scaled to 0-100.", "conceptId": null}, {"term": "SST2", "definition": "Stanford Sentiment Treebank, binary version: label each sentence as positive or negative sentiment.", "conceptId": "sst-2"}, {"term": "acc", "definition": "Accuracy, the metric for SST-2: the percentage of test sentences whose sentiment label the model gets right.", "conceptId": null}, {"term": "MRPC", "definition": "Microsoft Research Paraphrase Corpus: sentence pairs drawn from news sources, labelled for whether the two sentences are paraphrases.", "conceptId": "mrpc"}, {"term": "F1", "definition": "The harmonic mean of precision and recall on the positive class, used for MRPC and QQP. It is chosen over accuracy because the positive (paraphrase or duplicate) pairs are the minority class.", "conceptId": null}, {"term": "STSB", "definition": "Semantic Textual Similarity Benchmark: sentence pairs annotated with a graded similarity rating rather than a binary label. The paper calls it the smallest dataset in its evaluation, about 5.7k training examples.", "conceptId": "sts-b"}, {"term": "pc", "definition": "Pearson correlation, the metric for STS-B. Because the label is a graded score, the system is judged on how well its predicted similarities track the human ratings across the test set.", "conceptId": null}, {"term": "QQP", "definition": "Quora Question Pairs: pairs of questions labelled for whether they are asking the same thing.", "conceptId": "qqp"}, {"term": "Sparse byte mLSTM [16]", "definition": "The prior best on SST-2: a byte-level multiplicative LSTM language model trained with block-sparse GPU kernels, whose learned features are used for sentiment. Reference 16 is Gray, Radford and Kingma, GPU kernels for block-sparse weights, 2017.", "conceptId": "baseline-comparisons"}, {"term": "TF-KLD [23]", "definition": "The prior best on MRPC: a feature-engineered paraphrase system that reweights and factorizes a sentence-pair feature matrix. Reference 23 is Ji and Eisenstein, Discriminative improvements to distributional sentence similarity, 2013.", "conceptId": "baseline-comparisons"}, {"term": "ECNU (mixed ensemble) [60]", "definition": "The prior best on STS-B: a SemEval-2017 shared-task system combining hand-built kernel features with neural models in an ensemble. Reference 60 is Tian et al., 2017.", "conceptId": "baseline-comparisons"}, {"term": "Single-task BiLSTM + ELMo + Attn [64]", "definition": "A GLUE baseline: a bidirectional LSTM sentence encoder with attention, fed ELMo representations, trained separately on each task. Reference 64 is the GLUE benchmark paper, Wang et al., 2018.", "conceptId": "baseline-comparisons"}, {"term": "Multi-task BiLSTM + ELMo + Attn [64]", "definition": "The same GLUE baseline architecture, but trained jointly across the benchmark's tasks so that one model shares parameters over all of them.", "conceptId": "baseline-comparisons"}, {"term": "BiLSTM", "definition": "A bidirectional LSTM: two recurrent passes over the sentence, one left to right and one right to left, whose states are combined. It is the sentence encoder in both GLUE baseline rows.", "conceptId": "lstm-gpt1"}, {"term": "ELMo", "definition": "Deep contextualized word representations: hidden states taken from a pre-trained bidirectional language model and fed as extra input features into a separate task model, with the language model itself left frozen.", "conceptId": "elmo-deep-contextualized-word-representations"}, {"term": "Attn", "definition": "An attention mechanism added on top of the BiLSTM encoder in the GLUE baselines, letting the sentence-pair model align words across the two sentences.", "conceptId": null}, {"term": "Finetuned Transformer LM (ours)", "definition": "The paper's system: the transformer decoder pre-trained as a language model on BooksCorpus, then fine-tuned end to end on each labelled dataset with one added linear output layer.", "conceptId": "two-stage-training-procedure"}, {"term": "Dash (-)", "definition": "Marks a cell where the paper has no published number for that system on that dataset, usually because the system was only ever evaluated on one task. It is an absence, not a score of zero.", "conceptId": null}, {"term": "Bold", "definition": "Unexplained in the caption, but in practice bold marks the highest score in each column, whether that is the paper's model or a prior system.", "conceptId": null}, {"term": "Underline", "definition": "Marks the best prior published number in the columns where the paper's model takes the top score, so the reader can see what was beaten and by how much.", "conceptId": null}], "numbers": [{"value": "93.2", "meaning": "Sparse byte mLSTM accuracy on SST-2, the highest number in that column and the state of the art the paper does not beat. The paper describes its own 91.3 as competitive with this rather than better."}, {"value": "86.0", "meaning": "TF-KLD F1 on MRPC, the highest number in that column. It is a hand-engineered paraphrase system from 2013, and the paper's transformer stays 3.7 points below it."}, {"value": "81.0", "meaning": "ECNU ensemble Pearson correlation on STS-B, underlined as the prior best. The paper's 82.0 clears it, which is the '1 point absolute gain on STS-B' the text claims."}, {"value": "35.0", "meaning": "Single-task BiLSTM + ELMo + Attn Matthews correlation on CoLA, underlined as the prior best. The text calls the model's 45.4 'an especially big jump over the previous best result of 35.0'."}, {"value": "90.2", "meaning": "Single-task GLUE baseline accuracy on SST-2, about a point below both the multi-task version and the paper's model."}, {"value": "80.2", "meaning": "Single-task GLUE baseline F1 on MRPC. This is the one baseline number on MRPC that the paper's 82.3 does beat."}, {"value": "55.5", "meaning": "Single-task GLUE baseline Pearson correlation on STS-B, the weakest similarity score in the table. STS-B has roughly 5.7k training examples, and training on it alone leaves this baseline far behind the multi-task version's 72.8."}, {"value": "66.1", "meaning": "Single-task GLUE baseline F1 on QQP, underlined as the prior best. The paper reports a 4.2 point absolute improvement over it."}, {"value": "64.8", "meaning": "Single-task GLUE baseline overall benchmark score, the lowest GLUE total shown."}, {"value": "18.9", "meaning": "Multi-task GLUE baseline Matthews correlation on CoLA, far below the same architecture's 35.0 when trained on CoLA alone. Grammatical acceptability appears not to benefit from sharing parameters with the other GLUE tasks."}, {"value": "91.6", "meaning": "Multi-task GLUE baseline accuracy on SST-2. It sits above the paper's 91.3, so SST-2 is a column where the transformer trails a baseline as well as the specialist system."}, {"value": "83.5", "meaning": "Multi-task GLUE baseline F1 on MRPC, above the paper's 82.3. Together with TF-KLD's 86.0 this makes MRPC the clearest loss in the table."}, {"value": "72.8 (STS-B column)", "meaning": "Multi-task GLUE baseline Pearson correlation on STS-B, a 17.3 point gain over the same architecture trained single-task. It is numerically identical to the paper's GLUE total in the last column, which is coincidence, not a shared quantity."}, {"value": "63.3", "meaning": "Multi-task GLUE baseline F1 on QQP, below the single-task 66.1, so multi-task training helps STS-B and MRPC here but hurts QQP."}, {"value": "68.9", "meaning": "Multi-task GLUE baseline overall benchmark score, underlined as the prior best GLUE total. The paper's 72.8 is 3.9 points above it."}, {"value": "45.4", "meaning": "The paper's Matthews correlation on CoLA, the largest margin in the table at 10.4 points over the prior 35.0. The paper reads it as evidence that language model pre-training leaves the network with an implicit sense of what is grammatical."}, {"value": "91.3", "meaning": "The paper's accuracy on SST-2. It is below 93.2 and below 91.6, so it is neither bolded nor a win; the text only calls it competitive with the state of the art."}, {"value": "82.3", "meaning": "The paper's F1 on MRPC, above the single-task baseline's 80.2 but below the multi-task 83.5 and TF-KLD's 86.0. MRPC is also the single dataset where the paper's LSTM ablation outperforms its transformer."}, {"value": "82.0", "meaning": "The paper's Pearson correlation on STS-B, the top score in that column by one point over the ECNU ensemble."}, {"value": "70.3", "meaning": "The paper's F1 on QQP, the top score in that column and 4.2 points above the underlined 66.1."}, {"value": "72.8 (GLUE column)", "meaning": "The paper's overall GLUE score, the top score in that column. It aggregates across the benchmark's tasks, so it reflects the inference datasets too, not only the five columns printed here."}, {"value": "10.4 / 1.0 / 4.2 / 3.9", "meaning": "The four margins the paper wins by, in points: CoLA (45.4 minus 35.0), STS-B (82.0 minus 81.0), QQP (70.3 minus 66.1) and GLUE (72.8 minus 68.9). The paper states the last three of these in the text."}, {"value": "1.9 / 0.3 / 3.7 / 1.2", "meaning": "The margins the paper loses by, in points: SST-2 against 93.2 and against 91.6, MRPC against 86.0 and against 83.5. The paper does not itemize these; it simply calls SST-2 competitive and reports two of three similarity tasks as state of the art."}, {"value": "[16] [23] [60] [64]", "meaning": "Bracketed citation keys into the paper's reference list: 16 is the block-sparse GPU kernels work behind Sparse byte mLSTM, 23 is Ji and Eisenstein's TF-KLD, 60 is the ECNU SemEval-2017 system, and 64 is the GLUE benchmark paper that supplies both BiLSTM baselines."}, {"value": "0-100", "meaning": "The common scale of every cell. Accuracy and F1 are percentages; Matthews and Pearson correlations naturally run from -1 to 1 but are printed multiplied by 100, so all six columns can be scanned as if they were percentages."}], "sources": {"sections": [], "pages": [7]}}, {"id": "fig-2", "kind": "figure", "number": 2, "caption": "Figure 2: (left) Effect of transferring increasing number of layers from the pre-trained language model on RACE and MultiNLI. (right) Plot showing the evolution of zero-shot performance on different tasks as a function of LM pre-training updates. Performance per task is normalized between a random guess baseline and the current state-of-the-art with a single model.", "page": 7, "asset": "assets/fig-2.png", "title": "Layer Transfer and Zero-Shot Growth", "takeaway": "Two diagnostics for why the recipe works. The left panel says every pre-trained layer carries transferable value: dev accuracy on RACE and MultiNLI rises steadily as more of the twelve-layer stack is carried into fine-tuning, up to about 9% on MultiNLI for full transfer. The right panel says the pre-trained language model is already learning task-relevant behaviour before any fine-tuning: heuristic zero-shot scores on four tasks climb steadily across pre-training, and do so more smoothly for the transformer than for an LSTM trained the same way.", "walkthrough": "Two separate experiments, printed side by side. They share no axes and no data. The left is about [[layers-transferred]]; the right is about [[zero-shot-behaviors]].\n\n### Left panel\n\nThe x-axis counts how many layers of the pre-trained model are carried into [[supervised-fine-tuning]], from 0 to 13. The stack is [[twelve-layer-depth]] deep on top of an embedding layer, so the right edge is full transfer and the left edge is close to none. The paper's text describes the sweep as transferring embeddings first, then each transformer layer in turn.\n\nTwo datasets are drawn at once, each on its own vertical scale. Blue reads off the left axis, \"RACE Dev Accuracy\", spanning 30 to 100. Orange reads off the right axis, \"MultiNLI Matched Dev Accuracy\", spanning 70 to 100. That is a narrower window over the same plot height, so an orange rise looks about $2.5\\times$ steeper than the same number of accuracy points in blue. Read the colour first, then pick the axis.\n\nSolid lines are held-out dev accuracy. Dashed lines are training accuracy from the same runs.\n\nBoth dev curves climb roughly monotonically. [[race-dataset]] dev goes from about 39.7 to about 60; [[multinli]] dev from about 72.5 to about 82. The train curves climb further and sit well above dev, so more transferred layers fit the task data harder as well as generalizing better.\n\n### Right panel\n\nNo fine-tuning happens here at all. Each task is solved by a hand-written heuristic reading the generative model's probabilities directly, mostly by [[average-token-log-probability-scoring]].\n\nThe x-axis is pre-training updates on a log scale, $10^3$ to $10^6$. The y-axis, \"Relative Task Performance\", rescales each task so 0 is a random-guess baseline and 1 is the current state of the art with a single model. So 0.68 means the heuristic closes 68% of that gap. The rescaling is what lets four differently-scored tasks share one axis; it says nothing about absolute accuracy.\n\nColour is the task: sentiment analysis is [[sst-2]], linguistic acceptability is [[cola]], question answering is RACE, winograd schema resolution is DPRD ([[dprd-winograd-heuristic]]). Line style is the architecture: solid for the transformer, dashed for an LSTM language model ([[ablation-lstm-substitution]]).\n\nAll four solid curves rise and largely stay risen. The dashed LSTM curves reach lower and wobble more — its sentiment curve falls from 0.42 to 0.30 before recovering. The paper reads that as support for [[transformer-inductive-bias]]. That is a hypothesis drawn from one pair of runs, not a controlled measurement.", "latex": null, "terms": [{"term": "# of layers transferred (left x-axis)", "definition": "How many layers of the pre-trained language model are copied into the fine-tuned model instead of being freshly initialized. It runs 0 to 13, covering the embedding layer plus the twelve transformer blocks.", "conceptId": "layers-transferred"}, {"term": "RACE Dev Accuracy (left y-axis, blue)", "definition": "Multiple-choice accuracy on the development split of RACE, a reading-comprehension dataset built from English exam passages and questions. Only the blue curves are read against this axis.", "conceptId": "race-dataset"}, {"term": "MultiNLI Matched Dev Accuracy (right y-axis, orange)", "definition": "Three-way entailment accuracy on the MultiNLI development split. Only the orange curves are read against this axis.", "conceptId": "multinli"}, {"term": "Matched", "definition": "MultiNLI ships two dev splits: 'matched' draws from the same text genres as training, 'mismatched' from held-out genres. This panel uses the matched split, the easier of the two.", "conceptId": null}, {"term": "RACE Dev (solid blue)", "definition": "Held-out RACE accuracy at each transfer setting. This is the generalization number for RACE.", "conceptId": null}, {"term": "RACE Train (dashed light blue)", "definition": "Accuracy on RACE's own training data after fine-tuning at each transfer setting. It measures fit, not generalization.", "conceptId": null}, {"term": "MultiNLI Dev (solid orange)", "definition": "Held-out MultiNLI matched accuracy at each transfer setting, read on the right-hand axis.", "conceptId": null}, {"term": "MultiNLI Train (dashed light orange)", "definition": "Accuracy on MultiNLI's training data after fine-tuning, read on the right-hand axis.", "conceptId": null}, {"term": "Solid versus dashed (left panel)", "definition": "In the left panel the line style separates evaluation splits, not architectures: solid is dev, dashed is train. The right panel reuses the same styles for a different distinction, so the convention does not carry across.", "conceptId": null}, {"term": "Transferring embeddings", "definition": "The weakest transfer setting on this axis: only the token embedding table is carried over from pre-training, with the transformer blocks left randomly initialized. The paper calls its benefit 'the standard result'.", "conceptId": "word-embedding-transfer"}, {"term": "Pre-trained language model", "definition": "The decoder-only transformer trained to predict next tokens on BooksCorpus. Both panels vary something about it: how much of it is reused, or how long it was trained.", "conceptId": "generative-pretraining"}, {"term": "Fine-tuning", "definition": "The second stage, where the transferred weights plus one added linear layer are trained on a task's labelled data. The left panel's dev and train curves are all measured after fine-tuning.", "conceptId": "supervised-fine-tuning"}, {"term": "Relative Task Performance (right y-axis)", "definition": "A per-task rescaling of the raw score so that all four tasks fit one axis. It is not accuracy; it is a fraction of a gap.", "conceptId": null}, {"term": "Random guess baseline", "definition": "The lower anchor of that rescaling, mapped to 0.0: what a model with no knowledge would score. For a two-way choice like sentiment or winograd that is 50% accuracy; for four-way RACE it is 25%; for CoLA's correlation-based metric it is 0.", "conceptId": null}, {"term": "Current state-of-the-art with a single model", "definition": "The upper anchor, mapped to 1.0: the best published result at the time using one model rather than an ensemble. A value of 0.5 on the axis therefore means the heuristic covers half the distance from chance to that best system.", "conceptId": null}, {"term": "# of pre-training updates (right x-axis)", "definition": "How many gradient updates of language-model pre-training the checkpoint had received when the zero-shot heuristics were run against it. Plotted on a log scale.", "conceptId": "pre-training-optimization"}, {"term": "Zero-shot", "definition": "Performing an evaluation task with no supervised fine-tuning and no labelled examples, using only hand-written heuristics over the generative model's probabilities.", "conceptId": "zero-shot-behaviors"}, {"term": "sentiment analysis (blue, right panel)", "definition": "The SST-2 heuristic: append the token 'very' to the example, restrict the model's output distribution to the words 'positive' and 'negative', and take whichever is more probable.", "conceptId": "sst2-zero-shot-heuristic"}, {"term": "winograd schema resolution (orange, right panel)", "definition": "The DPRD heuristic: substitute each candidate referent for the definite pronoun, then pick the substitution under which the rest of the sentence scores higher.", "conceptId": "dprd-winograd-heuristic"}, {"term": "linguistic acceptability (green, right panel)", "definition": "The CoLA heuristic: score a sentence by the model's average token log-probability and threshold that score to call it grammatical or not.", "conceptId": "cola-zero-shot-heuristic"}, {"term": "question answering (red, right panel)", "definition": "The RACE heuristic: condition on the document and question, then pick the candidate answer with the highest average token log-probability.", "conceptId": "race-zero-shot-heuristic"}, {"term": "SST-2", "definition": "Stanford Sentiment Treebank, binary sentiment classification on single sentences. It appears in the right panel under the plain name 'sentiment analysis'.", "conceptId": "sst-2"}, {"term": "CoLA", "definition": "Corpus of Linguistic Acceptability, expert judgements of whether a sentence is grammatical. It appears in the right panel as 'linguistic acceptability'.", "conceptId": "cola"}, {"term": "DPRD", "definition": "The Definite Pronoun Resolution Dataset of winograd schemas: sentences where a pronoun's referent can only be settled by commonsense reasoning. It appears as 'winograd schema resolution'.", "conceptId": null}, {"term": "Transformer (solid, right legend)", "definition": "The paper's 12-layer decoder-only transformer language model. Solid lines in the right panel track its zero-shot scores.", "conceptId": "multi-layer-transformer-decoder"}, {"term": "LSTM (dashed, right legend)", "definition": "A recurrent language model pre-trained the same way, used as the architecture control. The corresponding ablation elsewhere in the paper uses a single-layer 2048-unit LSTM.", "conceptId": "ablation-lstm-substitution"}, {"term": "Average token log-probability", "definition": "The mean log-probability the language model assigns to the tokens of a candidate string. Three of the four heuristics rank options by this quantity, which normalizes away length.", "conceptId": "average-token-log-probability-scoring"}, {"term": "Inductive bias", "definition": "The paper's proposed reading of the right panel: the transformer's attention gives it a more structured memory than an LSTM's hidden state, which it suggests is why its zero-shot curves are smoother.", "conceptId": "transformer-inductive-bias"}], "numbers": [{"value": "0 to 13", "meaning": "The left panel's x-range. The model has 12 transformer blocks plus an embedding layer, so 14 tick positions cover transferring nothing, then embeddings, then blocks one at a time up to the whole stack. The paper's text describes the sweep this way but does not spell out the indexing."}, {"value": "12", "meaning": "Layers in the pre-trained stack, fixed by the model specification. It is what makes the left panel's x-axis end where it does."}, {"value": "30 to 100, ticks every 10", "meaning": "The left y-axis range (RACE Dev Accuracy). RACE is four-way multiple choice, so chance is 25% and the axis starts just above it."}, {"value": "70 to 100, ticks every 5", "meaning": "The right y-axis range (MultiNLI Matched Dev Accuracy). MultiNLI accuracies never fall below about 72 in this sweep, so the axis is zoomed in on that band."}, {"value": "2.5", "meaning": "The ratio between the two left-panel scales: the left axis spans 70 accuracy points over the same plot height as the right axis spans 30, so one orange point of accuracy occupies 2.5 times the vertical distance of one blue point. Ignoring this makes the MultiNLI gains look larger than the RACE ones."}, {"value": "about 39.7", "meaning": "RACE dev accuracy at 0 layers transferred, read off the plot. It is the floor of the blue solid curve."}, {"value": "about 60", "meaning": "RACE dev accuracy at full transfer, read off the plot. Roughly 20 points above the 0-layer setting, and consistent with the 59.0 overall RACE test accuracy the paper reports for its full model."}, {"value": "about 54, dipping to about 51.7", "meaning": "RACE train accuracy at 0 and at 2 layers transferred. The dashed blue curve is the only one that goes down before it goes up, so the earliest transfer settings do not immediately help RACE fit its own training data."}, {"value": "about 92", "meaning": "RACE train accuracy at full transfer. It sits roughly 32 points above the dev curve, so the fine-tuned model fits RACE's training set far better than it generalizes."}, {"value": "about 72.5", "meaning": "MultiNLI matched dev accuracy at 0 layers transferred, read on the right axis. This is the baseline the transfer gains are measured against."}, {"value": "about 82", "meaning": "MultiNLI matched dev accuracy at full transfer, read on the right axis. It lines up with the 82.1 MNLI-matched figure the paper reports for the full model in its results table."}, {"value": "9%", "meaning": "The paper's stated gain on MultiNLI from full transfer, and roughly the distance between the 72.5 and 82 endpoints of the orange dev curve. The paper offers it as evidence that every layer holds useful function, not just the embeddings."}, {"value": "about 79.5 rising to about 97", "meaning": "MultiNLI train accuracy at 0 and at full transfer. It climbs faster and saturates earlier than the dev curve, flattening after roughly 11 layers."}, {"value": "1.5% and 5.7%", "meaning": "The absolute improvements the paper reports over prior best results on MultiNLI and RACE. These two datasets are chosen for the left panel because they are the entailment and question-answering headline results."}, {"value": "0.0 to 1.0, ticks every 0.2", "meaning": "The right y-axis range. It is a normalized scale, so 0.0 is chance for that task and 1.0 is the best single-model result then published; no curve reaches 0.7."}, {"value": "10^3 to 10^6", "meaning": "The right panel's x-range in pre-training updates, on a log axis so early training gets as much horizontal room as late training. Pre-training ran 100 epochs of 64-sequence minibatches, which lands the full run at the order of 10^6 updates."}, {"value": "about 0.68", "meaning": "Where the solid sentiment-analysis curve plateaus, from roughly 3x10^5 updates onward. The highest value any curve reaches: the SST-2 heuristic closes about two-thirds of the gap from chance to the state of the art without a single labelled example."}, {"value": "about 0.10 then back to about 0.07", "meaning": "A blip in the solid sentiment curve around 8x10^3 updates before it drops again. The heuristic is near-worthless until roughly 10^4 updates, after which it climbs sharply."}, {"value": "about 0.47 at 2x10^4", "meaning": "The solid sentiment curve after its steep rise. Between 10^4 and 4x10^4 updates it goes from near zero to about 0.59, the fastest climb in the panel."}, {"value": "0.08, dipping to 0.05, then 0.45 and 0.54", "meaning": "The solid winograd curve at 10^3, at 2x10^3, at about 4x10^4, and at 10^6 updates. It plateaus near 0.44 through the middle of training and then rises again in the last decade of updates."}, {"value": "0.03 rising to about 0.40, then flat near 0.43", "meaning": "The solid linguistic-acceptability curve at 10^3, at about 8x10^3, and thereafter. It is the earliest riser and the flattest afterwards: grammaticality scoring is close to what the language modelling objective directly optimizes."}, {"value": "0 until about 4x10^3, peaking about 0.27, ending about 0.25", "meaning": "The solid question-answering curve. RACE stays the hardest of the four throughout, never closing more than about a quarter of the chance-to-state-of-the-art gap."}, {"value": "about 0.37", "meaning": "Where the dashed green LSTM acceptability curve plateaus, roughly 0.06 below its transformer counterpart. This is the LSTM's closest approach to matching the transformer."}, {"value": "about 0.20, spiking to 0.33, falling to 0.22, ending about 0.26", "meaning": "The dashed orange LSTM winograd curve. Its non-monotonic swings are the clearest instance of the higher variance the paper attributes to the LSTM."}, {"value": "0 until 10^4, then 0.42, 0.30, 0.49", "meaning": "The dashed blue LSTM sentiment curve at its start, at about 1.5x10^5, at about 3x10^5, and at 10^6 updates. It both starts later and drops mid-training, unlike the smooth solid transformer curve."}, {"value": "at most about 0.03", "meaning": "The dashed red LSTM question-answering curve across the whole run. The LSTM essentially never performs the RACE heuristic above chance, while the transformer reaches about 0.27."}, {"value": "5.6", "meaning": "The average score drop the paper reports elsewhere when the transformer is swapped for a single-layer 2048-unit LSTM in the full fine-tuning pipeline. It is the supervised counterpart to the architecture gap this panel shows without fine-tuning."}], "sources": {"sections": [], "pages": [7]}}, {"id": "table-5", "kind": "table", "number": 5, "caption": "Table 5: Analysis of various model ablations on different tasks. Avg. score is a unweighted average of all the results. (mc= Mathews correlation, acc=Accuracy, pc=Pearson correlation)", "page": 8, "asset": "assets/table-5.png", "title": "Three Ablations Against the Full Model", "takeaway": "Removing pre-training costs the most by far (14.8 average points), swapping the transformer for an LSTM costs 5.6, and dropping the auxiliary language modelling loss during fine-tuning actually gains 0.3 on average — helping only on the larger datasets (QQP and the two NLI sets) and hurting on the smaller ones.", "walkthrough": "### What you are looking at\n\nFour training recipes, each evaluated on the same eight datasets. This is the paper's [[ablation-studies]]: take the finished system apart one piece at a time and see what each piece was worth.\n\nThe top row, separated by a rule, is the full system — a pre-trained transformer fine-tuned with the [[auxiliary-lm-objective]] switched on. The three rows below each remove exactly one thing. Read down a column to compare recipes; read the leftmost number to compare them overall.\n\n### How to read it\n\nEach task column carries its own metric in the sub-header, because these datasets do not share one. $mc$ is Matthews correlation, $acc$ is accuracy, $F1$ is the harmonic mean of precision and recall, $pc$ is Pearson correlation. Higher is better in all four, but they are not on a common scale — a Matthews correlation of 45.4 and an accuracy of 91.3 are not comparable quantities.\n\nThe **Avg. Score** column simply averages the eight numbers in the row, unweighted. Nothing is rescaled and no dataset counts more than another, so a small dataset with a harsh metric — [[cola]], scored by correlation — pulls the average as hard as a large one. Bold marks the best value in each column.\n\n### What it shows\n\nDeleting [[generative-pretraining]] is the largest single loss: $74.7 - 59.9 = 14.8$ points, and every column drops. [[cola]] collapses from 45.4 to 18.9, which the paper reads as the linguistic bias coming from pre-training rather than from the labels.\n\nReplacing the [[multi-layer-transformer-decoder]] with a single-layer 2048-unit [[lstm-gpt1]] costs $74.7 - 69.1 = 5.6$ points. The LSTM beats the full transformer on exactly one dataset, [[mrpc]], at 83.2 against 82.3.\n\nThe third ablation cuts the other way. Fine-tuning *without* the auxiliary loss scores 75.0, three tenths of a point **above** the full model, and takes the best cell in five of eight columns. The loss earns its place only on [[qqp]], [[multinli]] and [[qnli]] — the larger datasets. The paper states the trend that way and does not claim more.", "latex": null, "terms": [{"term": "Method", "definition": "The leftmost column, naming which of the four training recipes a row reports. All four are trained and evaluated identically apart from the one component named in the row.", "conceptId": "ablation-studies"}, {"term": "Transformer w/ aux LM (full)", "definition": "The paper's complete system: a 12-layer decoder-only transformer pre-trained as a language model on BooksCorpus, then fine-tuned on each task with the language modelling loss kept on alongside the classification loss. This is the reference row the other three are subtracted from.", "conceptId": "two-stage-training-procedure"}, {"term": "Transformer w/o pre-training", "definition": "The same transformer architecture, same fine-tuning setup, but with weights initialized randomly instead of from the pre-trained language model. It isolates what stage one of the recipe contributed.", "conceptId": "ablation-no-pretraining"}, {"term": "Transformer w/o aux LM", "definition": "The full pre-trained transformer, fine-tuned with the supervised loss alone — the auxiliary language modelling term is dropped from the fine-tuning objective. It isolates what that extra loss term contributed.", "conceptId": "ablation-no-auxiliary-objective"}, {"term": "LSTM w/ aux LM", "definition": "Everything about the full recipe kept, except the transformer stack is swapped for a single-layer 2048-unit LSTM: pre-trained the same way, fine-tuned the same way, auxiliary loss on. It isolates the architecture choice.", "conceptId": "ablation-lstm-substitution"}, {"term": "aux LM", "definition": "The auxiliary language modelling objective used during fine-tuning: the model keeps predicting next tokens on the task's own text while it learns the labels, with the two losses combined as $L_3 = L_2 + \\lambda L_1$ at $\\lambda = 0.5$.", "conceptId": "auxiliary-lm-objective"}, {"term": "pre-training", "definition": "Stage one of the paper's recipe: train the network to predict the next token over a large unlabelled corpus, then carry those weights into the supervised task as the starting point.", "conceptId": "generative-pretraining"}, {"term": "Avg. Score", "definition": "The unweighted mean of that row's eight task scores. Every dataset contributes equally and no metric is rescaled first, so the column is a rough summary rather than a calibrated benchmark number.", "conceptId": null}, {"term": "CoLA", "definition": "Corpus of Linguistic Acceptability: expert judgements on whether a single sentence is grammatical. The paper treats it as a probe of linguistic bias picked up during pre-training.", "conceptId": "cola"}, {"term": "SST2", "definition": "Stanford Sentiment Treebank, binary version: label a sentence as positive or negative sentiment.", "conceptId": "sst-2"}, {"term": "MRPC", "definition": "Microsoft Paraphrase Corpus: given two sentences drawn from news sources, decide whether they mean the same thing. The one dataset in this table where the LSTM beats the full transformer.", "conceptId": "mrpc"}, {"term": "STSB", "definition": "Semantic Textual Similarity Benchmark: rate how similar two sentences are on a continuous scale, rather than making a binary paraphrase call. The smallest dataset in the paper's evaluation at roughly 5.7k training examples.", "conceptId": "sts-b"}, {"term": "QQP", "definition": "Quora Question Pairs: decide whether two questions are asking the same thing. One of the larger datasets here, and one of the three where the auxiliary objective helps.", "conceptId": "qqp"}, {"term": "MNLI", "definition": "MultiNLI: natural language inference across several genres of text, labelling a premise-hypothesis pair as entailment, contradiction or neutral.", "conceptId": "multinli"}, {"term": "QNLI", "definition": "An inference dataset built over Wikipedia articles, framed as deciding whether a sentence contains the answer to a question.", "conceptId": "qnli"}, {"term": "RTE", "definition": "Recognizing Textual Entailment: a small natural language inference dataset over news articles, about 2490 training examples. Its size makes its column the noisiest in the table.", "conceptId": "rte"}, {"term": "mc (Mathews correlation)", "definition": "Matthews correlation coefficient, the metric for CoLA. It scores a binary classifier on a scale where 0 is chance and 100 is perfect, and it stays low when a model just predicts the majority class — which is why CoLA's numbers look small next to the accuracy columns.", "conceptId": null}, {"term": "acc (Accuracy)", "definition": "Plain percentage of test examples labelled correctly, used for SST2, MNLI, QNLI and RTE.", "conceptId": null}, {"term": "F1", "definition": "The harmonic mean of precision and recall on the positive class, used for MRPC and QQP because both have imbalanced labels where raw accuracy would flatter a lazy classifier.", "conceptId": null}, {"term": "pc (Pearson correlation)", "definition": "Pearson correlation between predicted and human similarity ratings, used for STSB because its target is a continuous score rather than a class.", "conceptId": null}, {"term": "Bold", "definition": "Marks the best value in each column across the four rows. The full model takes bold in four columns and the no-auxiliary-objective row takes it in five, including the average.", "conceptId": null}], "numbers": [{"value": "74.7", "meaning": "Average score of the full model, the reference every ablation is compared against. It is the unweighted mean of that row's eight cells: $(45.4+91.3+82.3+82.0+70.3+81.8+88.1+56.0)/8 = 597.2/8 = 74.65$, printed to one decimal."}, {"value": "45.4 / 91.3 / 82.3 / 82.0 / 70.3 / 81.8 / 88.1 / 56.0", "meaning": "The full model's per-task scores in column order (CoLA, SST2, MRPC, STSB, QQP, MNLI, QNLI, RTE). These are the same headline numbers the paper reports in its main results tables; 45.4 on CoLA is called a large jump over a previous best of 35.0, and 56.0 on RTE is the one NLI dataset where the paper does not beat prior work (61.7)."}, {"value": "59.9", "meaning": "Average score with no pre-training. Mean of $(18.9+84.0+79.4+30.9+65.5+75.7+71.2+53.8)/8 = 479.4/8 = 59.925$."}, {"value": "14.8", "meaning": "The cost of removing pre-training: $74.7 - 59.9 = 14.8$ average points. The paper calls this a 14.8% decrease and notes that no task escapes — every one of the eight columns drops."}, {"value": "18.9", "meaning": "CoLA without pre-training, down from 45.4. The largest single-cell collapse in the table, and the paper's evidence that grammatical acceptability judgements come from the unlabelled text rather than from CoLA's own labels."}, {"value": "30.9", "meaning": "STSB without pre-training, down from 82.0. The second-largest collapse; STSB is the smallest training set in the evaluation, so a randomly initialized model has very little labelled data to learn from."}, {"value": "84.0 / 79.4 / 65.5 / 75.7 / 71.2 / 53.8", "meaning": "The remaining no-pre-training cells (SST2, MRPC, QQP, MNLI, QNLI, RTE). Each is below the full model's value in the same column; the smallest gap is RTE at $56.0 - 53.8 = 2.2$, which is also the smallest dataset and therefore the noisiest comparison."}, {"value": "75.0", "meaning": "Average score with the auxiliary language modelling objective removed during fine-tuning. Mean of $(47.9+92.0+84.9+83.2+69.8+81.1+86.9+54.4)/8 = 600.2/8 = 75.025$. It is the best average in the table."}, {"value": "+0.3", "meaning": "The amount removing the auxiliary objective helps on average: $75.0 - 74.7$. The full recipe keeps the objective anyway, and the paper justifies that on the pattern across datasets rather than on the average."}, {"value": "47.9 / 92.0 / 84.9 / 83.2", "meaning": "CoLA, SST2, MRPC and STSB without the auxiliary objective — all four beat the full model (45.4, 91.3, 82.3, 82.0) and take the bold. These are the paper's smaller datasets, which it says do not benefit from the extra loss term."}, {"value": "69.8 / 81.1 / 86.9", "meaning": "QQP, MNLI and QNLI without the auxiliary objective, each below the full model's 70.3, 81.8 and 88.1. These three are the larger datasets, and this is the whole basis for the paper's claim that the auxiliary objective helps on NLI tasks and QQP."}, {"value": "54.4", "meaning": "RTE without the auxiliary objective, below the full model's 56.0. RTE is an NLI task but a very small one, so it does not fit cleanly on either side of the size trend."}, {"value": "69.1", "meaning": "Average score for the LSTM. Mean of $(30.3+90.5+83.2+71.8+68.1+73.7+81.1+54.6)/8 = 553.3/8 = 69.16$, which the table prints as 69.1."}, {"value": "5.6", "meaning": "The cost of using an LSTM instead of the transformer: $74.7 - 69.1 = 5.6$ average points. The paper cites this figure directly as the architecture's contribution, holding pre-training and fine-tuning fixed."}, {"value": "83.2 (LSTM, MRPC)", "meaning": "The only cell where the LSTM beats the full transformer, 83.2 against 82.3. The paper states this exception explicitly rather than claiming a clean sweep. Note the bold on MRPC goes to 84.9 in the no-auxiliary-objective row, not to the LSTM."}, {"value": "30.3 / 90.5 / 71.8 / 68.1 / 73.7 / 81.1 / 54.6", "meaning": "The LSTM's remaining cells (CoLA, SST2, STSB, QQP, MNLI, QNLI, RTE), all below the full model. CoLA at 30.3 and STSB at 71.8 are the widest gaps, so most of the 5.6-point average drop comes from those two."}, {"value": "2048", "meaning": "The hidden unit count of the LSTM used in the substitution ablation, described in the analysis text as a single-layer 2048-unit LSTM. It is stated once in prose and does not appear in the table itself."}, {"value": "8", "meaning": "The number of task columns averaged into Avg. Score. Note the paper evaluates on twelve datasets overall; this table covers only the eight it reports here, so Avg. Score is not the paper's GLUE score of 72.8."}, {"value": "0.5", "meaning": "The weight $\\lambda$ on the auxiliary language modelling term during fine-tuning, from the setup section. The rows that keep the auxiliary objective use this value; the w/o aux LM row is the case $\\lambda = 0$."}], "sources": {"sections": [], "pages": [8]}}, {"id": "eq-lm-objective", "kind": "equation", "number": null, "caption": "The language modelling objective L1", "page": 3, "asset": null, "section": "3.1", "title": "The Pre-Training Likelihood $L_1$", "takeaway": "This is the entire training signal for stage one: over a corpus of unlabelled tokens, sum the log-probability the network assigns to each token given the $k$ tokens immediately before it, and adjust the network's parameters $\\Theta$ to make that sum as large as possible. No labels, no task, and one training term per token position.", "walkthrough": "This is Equation 1, the objective for the first half of the paper's [[two-stage-training-procedure]]. Everything the model learns before it ever sees a labelled example comes from this one line.\n\nStart with the corpus. $\\mathcal{U} = \\{u_1, \\dots, u_n\\}$ is the unlabelled text after tokenization: one long run of $n$ tokens, each $u_i$ a subword unit from the [[byte-pair-encoding-gpt1]] vocabulary. Nothing is annotated. The subscript in $L_1$ marks this as the first of three losses the paper defines; $L_2$ and $L_3$ appear later, in [[supervised-fine-tuning]].\n\nNow read the equation from the inside out. The term $P(u_i \\mid u_{i-k}, \\dots, u_{i-1}; \\Theta)$ is the probability the network assigns to the token that actually sits at position $i$, given the $k$ tokens immediately before it. The semicolon separates what is conditioned on from what is being fitted: $\\Theta$ is every weight in the network, and it is not data.\n\nTake the logarithm of that probability, then sum over $i$. Every position in the corpus contributes one term, so a corpus of $n$ tokens yields roughly $n$ terms. Maximizing the sum is ordinary [[maximum-likelihood-training]], done here with stochastic gradient descent on $\\Theta$.\n\nNote what the equation does not say. It fixes no architecture — Equation 2 supplies the [[multi-layer-transformer-decoder]] that computes $P$. The objective would read the same for an n-gram model or an LSTM.\n\nThat leaves $k$, the context window. It is the number of preceding tokens a single prediction is allowed to see, and it bounds the reach of what the model can learn: nothing further back than $k$ tokens can inform the prediction at position $i$. The paper sets it to 512 tokens in the trained model, so a prediction can condition on the previous several paragraphs rather than the current sentence ([[context-window-512-tokens]]).\n\nA large $k$ only helps if the tokens inside the window are genuinely related, which is why the paper chooses [[bookscorpus]] for its [[long-range-contiguous-text]] over the sentence-shuffled [[one-billion-word-benchmark]]. That is the paper's stated route to [[long-range-dependencies-gpt1]]: make the objective's window wide, then feed it text that fills the window with something worth conditioning on. It reports [[token-level-perplexity]] of 18.4 as evidence the model fit that corpus.", "latex": "L_1(\\mathcal{U}) = \\sum_i \\log P(u_i \\mid u_{i-k}, \\dots, u_{i-1}; \\Theta)", "terms": [{"term": "$L_1(\\mathcal{U})$", "definition": "The pre-training objective: a single scalar score for how well the model's parameters explain the whole unlabelled corpus. Training maximizes it.", "conceptId": "language-modeling-objective"}, {"term": "$\\mathcal{U}$", "definition": "The unsupervised corpus, written as an ordered set of tokens $\\{u_1,\\dots,u_n\\}$. In the experiments it is BooksCorpus after cleaning and byte-pair encoding.", "conceptId": "bookscorpus"}, {"term": "$u_i$", "definition": "The token at position $i$ in the corpus, and the prediction target of the $i$-th term in the sum. Each token also serves as context for the up-to-$k$ predictions that follow it.", "conceptId": null}, {"term": "$n$", "definition": "The number of tokens in the corpus, so the last token is $u_n$. Reused later in Equation 2 with a different meaning (number of transformer layers).", "conceptId": null}, {"term": "$i$", "definition": "The position index being predicted; also the variable the sum runs over. The paper leaves its exact range implicit.", "conceptId": null}, {"term": "$k$", "definition": "The size of the context window: how many immediately preceding tokens a prediction may condition on. It is a fixed hyperparameter, not something learned.", "conceptId": "context-window-512-tokens"}, {"term": "$u_{i-k}, \\dots, u_{i-1}$", "definition": "The window of context: the $k$ tokens directly before position $i$, in order. This is the entire input to the prediction of $u_i$.", "conceptId": null}, {"term": "$P(\\cdot \\mid \\cdot\\,;\\Theta)$", "definition": "The conditional next-token distribution the network computes over the whole vocabulary. Here only the probability mass on the observed token $u_i$ is read off.", "conceptId": "output-softmax-tied-embeddings"}, {"term": "$\\Theta$", "definition": "All parameters of the neural network that models $P$ — embeddings, attention and feed-forward weights. These are the quantities the maximization adjusts, and the thing carried into fine-tuning.", "conceptId": "generative-pretraining"}, {"term": "$\\sum_i$", "definition": "Summation over token positions, so every position in the corpus contributes one training term. This is what makes the supervision dense and free of annotation.", "conceptId": null}, {"term": "$\\log$", "definition": "Natural logarithm of the probability. Summing logs rather than multiplying probabilities keeps the objective numerically stable and turns the corpus likelihood into a sum.", "conceptId": "maximum-likelihood-training"}, {"term": "likelihood", "definition": "The probability the model assigns to the observed data. The paper says it maximizes this likelihood, which in practice means gradient descent on its negative.", "conceptId": "maximum-likelihood-training"}, {"term": "context window", "definition": "The paper's name for the span $k$ of preceding tokens visible to a prediction. It caps how far back any learned dependency can reach.", "conceptId": "context-window-512-tokens"}, {"term": "stochastic gradient descent", "definition": "The optimizer family the paper names for fitting $\\Theta$; the setup section specifies Adam with a warmup-then-cosine learning-rate schedule.", "conceptId": "pre-training-optimization"}], "numbers": [{"value": "1 (subscript of $L_1$)", "meaning": "Labels this as the paper's first objective. It is numbered because two more follow: $L_2$ for the supervised task and $L_3$ combining the two during fine-tuning."}, {"value": "1 (in $u_1$)", "meaning": "The first token of the corpus; the corpus is indexed from 1 to $n$."}, {"value": "$i-1$", "meaning": "The token immediately before the prediction target — the nearest edge of the context window."}, {"value": "$i-k$", "meaning": "The furthest-back token the prediction may use, $k$ positions before $i$. Anything earlier is invisible to this term of the sum."}, {"value": "$k$", "meaning": "The window size, left symbolic in Equation 1 because the objective does not depend on any particular value."}, {"value": "512", "meaning": "The value of $k$ in the trained model, given in the setup section: minibatches are 64 contiguous sequences of 512 tokens, so each prediction can look back up to 512 byte-pair tokens."}, {"value": "18.4", "meaning": "Token-level perplexity reached on BooksCorpus, reported as evidence the pre-training objective was fit well. Roughly, the model is on average about as uncertain as if choosing uniformly among 18.4 tokens."}], "sources": {"sections": [], "pages": [3]}}, {"id": "eq-decoder-stack", "kind": "equation", "number": null, "caption": "From tokens to a next-token distribution", "page": 3, "asset": null, "section": "3.1", "title": "The Decoder Stack, Input to Output Distribution", "takeaway": "Equation 2 spells out the whole pre-training network in three lines: embed the context tokens and their positions, push the result through $n$ identical transformer blocks, then project the top layer back through the transposed token embedding matrix and softmax it into a distribution over the next token. The same matrix $W_e$ does the work at both ends, so no separate output vocabulary matrix is introduced.", "walkthrough": "This is the definition of the network that Equation 1's language modelling loss is computed over. Equation 1 says *what* to maximize; Equation 2 says what the [[multi-layer-transformer-decoder]] actually computes. Read it top to bottom as three stages: get in, go through, get out.\n\n### Line one: getting in\n\n$h_0 = UW_e + W_p$ builds the layer-zero representation, the [[input-representation-h0]].\n\n$U = (u_{-k}, \\dots, u_{-1})$ is the context vector: the $k$ tokens immediately before the one being predicted, indexed backwards from the prediction point. Treat it as a stack of one-hot rows, one per position.\n\nMultiplying by the [[token-embedding-matrix]] $W_e$ therefore selects one embedding row per token. Adding $W_p$ adds a vector that depends only on the slot a token sits in, not on its identity. Those are [[learned-position-embeddings]] — trained parameters, not fixed sinusoids.\n\n### Line two: going through\n\n$h_l = \\texttt{transformer\\_block}(h_{l-1})$ is a recurrence over depth, not over time. Layer $l$ reads only the previous layer's output. Each block is a masked multi-head self-attention sublayer followed by a position-wise feed-forward sublayer, which is where the [[decoder-only-stack]] and its [[masked-self-attention]] live. Iterating from $l=1$ to $l=n$ gives $h_n$, the top layer.\n\nOne notational wrinkle: as printed, the quantifier reads $\\forall i \\in [1,n]$ while the subscript being varied is $l$. The index intended is $l$.\n\n### Line three: getting out\n\n$P(u) = \\texttt{softmax}(h_n W_e^T)$ turns the top-layer state into a distribution.\n\n$W_e$ maps a vocabulary index to a vector, so $W_e^T$ maps a vector back to one score per vocabulary entry. Concretely, the score for a candidate token is the dot product of $h_n$ with that token's embedding. Softmax normalizes those scores.\n\nSo $W_e$ appears twice — as the input lookup and, transposed, as the output scoring matrix. The paper states this without arguing for it, and it is the point at which the [[output-softmax-tied-embeddings]] is defined.\n\nNothing here is task-specific. That is what lets [[supervised-fine-tuning]] reuse the same stack unchanged.", "latex": "\\begin{aligned}\nh_0 &= UW_e + W_p \\\\\nh_l &= \\texttt{transformer\\_block}(h_{l-1}) \\,\\forall i \\in [1, n] \\\\\nP(u) &= \\texttt{softmax}(h_n W_e^T)\n\\end{aligned}", "terms": [{"term": "$U$", "definition": "The context vector of tokens, $U = (u_{-k}, \\dots, u_{-1})$: the $k$ tokens preceding the position being predicted. In the matrix product $UW_e$ it acts as a stack of one-hot row vectors, one row per context position.", "conceptId": null}, {"term": "$u$", "definition": "A single token from the corpus. In $P(u)$ it stands for the next token whose probability the model is producing.", "conceptId": null}, {"term": "$W_e$", "definition": "The token embedding matrix: one learned row vector per vocabulary entry. It is used once on the input side as a lookup, and again transposed on the output side to score candidate next tokens.", "conceptId": "token-embedding-matrix"}, {"term": "$W_e^T$", "definition": "The transpose of the token embedding matrix, used as the output projection. Multiplying $h_n$ by it produces one score per vocabulary entry, each score being the dot product of the hidden state with that token's embedding.", "conceptId": "output-softmax-tied-embeddings"}, {"term": "$W_p$", "definition": "The position embedding matrix: one learned vector per slot in the context window, added to the token embeddings so the model can tell positions apart. The paper says these are learned rather than the sinusoidal encodings of the original transformer.", "conceptId": "learned-position-embeddings"}, {"term": "$h_0$", "definition": "The layer-zero representation, formed as token embeddings plus position embeddings. It is the input handed to the first transformer block.", "conceptId": "input-representation-h0"}, {"term": "$h_l$", "definition": "The hidden state after transformer block $l$: one vector per context position. Each $h_l$ depends only on $h_{l-1}$.", "conceptId": null}, {"term": "$h_n$", "definition": "The hidden state after the last of the $n$ blocks. It is the representation fed into the output softmax.", "conceptId": null}, {"term": "$l$", "definition": "The layer index, running from $1$ to $n$. The recurrence is over depth in the stack, not over time steps in the sequence.", "conceptId": null}, {"term": "$n$", "definition": "The number of layers in the stack. Note that Equation 1 on the same page uses $n$ for the number of tokens in the corpus $\\mathcal{U}$; here it means depth.", "conceptId": "twelve-layer-depth"}, {"term": "$i$", "definition": "The index appearing in the printed quantifier $\\forall i \\in [1, n]$. The variable actually being ranged over in the recurrence is $l$, so this reads as a typographical slip in the paper.", "conceptId": null}, {"term": "transformer_block", "definition": "One decoder block: masked multi-head self-attention over the context positions, followed by a position-wise feed-forward network. The paper leaves the internals to the transformer reference and only names the function here.", "conceptId": "multi-layer-transformer-decoder"}, {"term": "softmax", "definition": "The normalization applied to the vocabulary scores $h_n W_e^T$, turning them into a probability distribution over the next token.", "conceptId": null}, {"term": "$P(u)$", "definition": "The model's output distribution over target tokens given the context $U$. It is the quantity that the pre-training likelihood in Equation 1 maximizes.", "conceptId": "language-modeling-objective"}, {"term": "$k$", "definition": "The size of the context window, defined in the text above Equation 1 and reused here through the index range of $U$. It sets how many preceding tokens a prediction may condition on.", "conceptId": "context-window-512-tokens"}, {"term": "Transformer decoder", "definition": "The architecture family the paper picks: the encoder half of the original encoder-decoder transformer is dropped, leaving a single stack that attends only to its own earlier positions.", "conceptId": "decoder-only-stack"}], "numbers": [{"value": "0", "meaning": "The layer index of $h_0$. It marks the embedding output as the input to the stack rather than the product of any block, so block $1$ is the first thing that transforms it."}, {"value": "$l-1$", "meaning": "The layer feeding block $l$. Written this way, the line says each block reads exactly one thing: the layer directly below it."}, {"value": "$[1, n]$", "meaning": "The range of the layer index: the recurrence is applied $n$ times, once for each block, starting at block 1 and ending at block $n$. The lower bound is 1, not 0, because $h_0$ is produced by the embedding line instead."}, {"value": "$-k$ to $-1$", "meaning": "The index range of the context vector $U$. Positions are numbered backwards from the token being predicted, so $u_{-1}$ is the immediately preceding token and $u_{-k}$ is the furthest one still inside the window."}, {"value": "12", "meaning": "The value the paper gives $n$ when it trains the model: a 12-layer decoder-only transformer. The analysis section then treats this depth as a dial, transferring varying numbers of these layers into fine-tuning."}, {"value": "768", "meaning": "The dimension of each $h_l$ vector in the trained model, so $W_e$ has 768 columns and $W_e^T$ has 768 rows. Reported in the model specification, not in the equation itself."}, {"value": "3072", "meaning": "The inner dimension of the position-wise feed-forward network inside each transformer_block: it expands from 768 to 3072 and projects back down."}, {"value": "512", "meaning": "The value of $k$ in the trained model: predictions condition on up to 512 contiguous preceding tokens. This also fixes the number of rows $W_p$ needs."}, {"value": "40,000", "meaning": "The number of byte-pair-encoding merges used to build the vocabulary. It determines how many rows $W_e$ has, and therefore the width of the softmax in the third line."}], "sources": {"sections": [], "pages": [3]}}, {"id": "eq-task-head", "kind": "equation", "number": null, "caption": "The task prediction head", "page": 3, "asset": null, "section": "3.2", "title": "The Linear Task Head on the Last Token", "takeaway": "Equation 3 is the entire task-specific classifier: take the final transformer block's activation at the last input token, multiply it by one matrix $W_y$, and softmax the result into a distribution over the task's labels. The paper states that $W_y$ (plus delimiter-token embeddings) is the only new parameter it adds when moving the pre-trained model to a new task.", "walkthrough": "### What you are looking at\n\nThis is Equation 3 in Section 3.2, the point where the pre-trained language model becomes a classifier. Everything to the right of the equals sign is one matrix multiply and one softmax.\n\n### Reading it left to right\n\n$x^1, \\dots, x^m$ is one labelled example: a sequence of $m$ input tokens, taken from the [[labeled-dataset-c]], paired with a label $y$. The superscripts index positions in the sequence, not powers.\n\nThat sequence is run through the [[multi-layer-transformer-decoder]] exactly as it was during [[generative-pretraining]]. No layer is removed and nothing is bolted on inside the stack.\n\n$h_l^m$ is the one number-vector pulled out of that forward pass. Read the two indices separately. The subscript $l$ picks the layer: the final transformer block, the top of the stack. The superscript $m$ picks the position: the last token in the input.\n\nSo the classifier does not see the whole sequence of hidden states. It sees a single vector — the [[final-token-activation]] — and that vector has to carry whatever the model noticed about the example. Because attention here is [[masked-self-attention]], the last position is the only one that has attended to every earlier token, which is what makes it the natural place to read from.\n\n$W_y$ is then the [[linear-output-layer-wy]]: a single matrix mapping that vector to one score per label. Softmax turns those scores into $P(y \\mid x^1, \\dots, x^m)$.\n\n### What it establishes\n\nThe claim being set up is about size, not accuracy. $W_y$ is freshly initialized; every other weight in the equation is a pre-trained weight being fine-tuned. Section 3.2 closes by saying the only extra parameters needed are $W_y$ and embeddings for delimiter tokens — the [[minimal-extra-parameters]] point.\n\nThat is the contrast the paper draws with [[feature-based-transfer]], which freezes the pre-trained model and trains a new [[task-specific-architectures|task-specific architecture]] on top of it, paying a much larger [[per-task-parameter-cost]] per task.\n\nOne notational wrinkle: Equation 2 called the top layer $h_n$ with $n$ layers, and here the final block is indexed $l$. Same layer, different letter.", "latex": "P(y|x^1,\\dots,x^m) = \\texttt{softmax}(h_l^m W_y).", "terms": [{"term": "$P(y \\mid x^1, \\dots, x^m)$", "definition": "The model's predicted probability distribution over the target task's labels, conditioned on the whole input token sequence. This is what the fine-tuning objective in Equation 4 maximizes on the correct label.", "conceptId": "supervised-objective-l2"}, {"term": "$y$", "definition": "The label attached to one training instance, for example the entailment class of a premise-hypothesis pair or the sentiment of a sentence. Its possible values are fixed per task.", "conceptId": null}, {"term": "$x^1, \\dots, x^m$", "definition": "The sequence of input tokens for one labelled instance; superscripts are position indices, not exponents. For structured tasks these are the tokens after the input has been flattened into one sequence.", "conceptId": "task-specific-input-transformations"}, {"term": "$m$", "definition": "The number of tokens in the input sequence, so also the index of its last token. It varies from example to example.", "conceptId": null}, {"term": "$h_l^m$", "definition": "The activation the pre-trained transformer produces at layer $l$ (the final block) and position $m$ (the last token). It is the single vector handed to the classifier.", "conceptId": "final-token-activation"}, {"term": "$l$ (subscript)", "definition": "The layer index, here denoting the final transformer block in the stack. Equation 2 wrote the same top layer as $h_n$ with $n$ layers, so this is a change of letter, not of meaning.", "conceptId": "multi-layer-transformer-decoder"}, {"term": "$m$ (superscript on $h$)", "definition": "The position index into the sequence, selecting the last token's hidden state rather than the whole sequence of states.", "conceptId": null}, {"term": "$W_y$", "definition": "The one weight matrix added on top of the pre-trained model, mapping the final activation to one unnormalized score per label. It is randomly initialized at the start of fine-tuning.", "conceptId": "linear-output-layer-wy"}, {"term": "softmax", "definition": "Here it normalizes the label scores $h_l^m W_y$ into a probability distribution over the task's label set. It is the same operation used at the output of pre-training, but over labels instead of over the vocabulary.", "conceptId": "output-softmax-tied-embeddings"}, {"term": "$\\mathcal{C}$", "definition": "The labelled dataset for a target task, defined just above the equation: a set of instances, each an input token sequence paired with one label.", "conceptId": "labeled-dataset-c"}, {"term": "linear output layer", "definition": "The paper's name for the $W_y$ multiply: a plain linear map with no hidden layer and no nonlinearity before the softmax.", "conceptId": "minimal-extra-parameters"}, {"term": "final transformer block's activation", "definition": "The paper's phrase for $h_l^m$ in the running text. It names the top of the pre-trained stack as the read-out point, as opposed to any intermediate layer.", "conceptId": "final-token-activation"}], "numbers": [{"value": "(3)", "meaning": "The equation number. Equation 3 defines the prediction; Equation 4 turns it into the objective $L_2$; Equation 5 adds the auxiliary language modelling term."}, {"value": "1", "meaning": "The first position index in $x^1$. Sequences are indexed from the first token, which in practice is the randomly initialized start token $\\langle s \\rangle$ added by the input transformations."}, {"value": "$m$", "meaning": "Length of the input sequence and index of its last token. It is a variable, not a fixed constant: each labelled instance has its own $m$, and the read-out always tracks whatever the last position happens to be."}, {"value": "$l$", "meaning": "Index of the final transformer block. In the model the paper actually trains this is 12, since Section 4.1 specifies a 12-layer decoder-only transformer, so $h_l^m$ is the output of block 12."}, {"value": "768", "meaning": "Not printed in this equation, but the length of $h_l^m$: Section 4.1 fixes 768-dimensional states at every layer. This is what makes $W_y$ a $768 \\times (\\text{number of labels})$ matrix."}, {"value": "2 (added representations)", "meaning": "For similarity tasks, Section 3.3 builds both sentence orderings and produces two vectors $h_l^m$, which are added element-wise before this equation is applied. The equation itself is unchanged; only its input is a sum of two activations."}], "sources": {"sections": [], "pages": [3]}}, {"id": "eq-supervised-objective", "kind": "equation", "number": null, "caption": "The supervised objective L2", "page": 3, "asset": null, "section": "3.2", "title": "Supervised Fine-Tuning Objective $L_2$", "takeaway": "Equation 4 is the loss used in the second training stage: over a target task's labelled dataset $\\mathcal{C}$, sum the log-probability the model assigns to each instance's correct label. It is ordinary maximum-likelihood classification training, written so that the only thing separating one task from another is which labelled set $\\mathcal{C}$ you plug in.", "walkthrough": "What you are looking at is the objective the paper maximizes during [[supervised-fine-tuning]], the second of its two training stages. It is one line, and every symbol in it has already been fixed by the two sentences above it on the page.\n\n### How to read it\n\nStart on the left. $L_2(\\mathcal{C})$ is a score attached to a dataset, not to a single example — the subscript 2 marks it as the second objective the paper defines, after the pre-training objective $L_1$.\n\n$\\mathcal{C}$ is the [[labeled-dataset-c]] of one target task. The paper describes each of its instances as a sequence of input tokens $x^1,\\dots,x^m$ together with a label $y$. So $\\mathcal{C}$ is a bag of (token sequence, label) pairs, and $m$ is the length of one particular sequence, which changes from instance to instance.\n\nThe sum runs over $(x,y)$, meaning one term per labelled instance in $\\mathcal{C}$.\n\nEach term is $\\log P(y \\mid x^1,\\dots,x^m)$: the log of the probability the model puts on that instance's correct label, given its tokens. Nothing here scores the wrong labels directly; pushing probability onto the right one drains it from the others, because the label distribution sums to one.\n\nThat distribution comes from the line just above, Equation 3: $P(y \\mid x^1,\\dots,x^m) = \\mathrm{softmax}(h_l^m W_y)$. The tokens are run through the pre-trained network, the [[final-token-activation]] $h_l^m$ is read off, and the [[linear-output-layer-wy]] turns it into one score per label.\n\n### What it shows\n\nMaximizing $L_2$ is [[maximum-likelihood-training]] of a classifier — the familiar cross-entropy setup, with a sign flip, since maximizing summed log-probability is minimizing summed negative log-probability.\n\nThe point is what is *not* in the equation. There is no task-specific term, no per-task architecture, and no per-task loss shape. Everything a task contributes enters through $\\mathcal{C}$, which is why the paper can claim that [[minimal-extra-parameters]] are needed to adapt: only $W_y$ and the delimiter embeddings introduced by the [[task-specific-input-transformations]].\n\nThe paper does not use $L_2$ alone. It reports better generalization and faster convergence when the pre-training loss is kept alongside it, giving the [[auxiliary-lm-objective]] of Equation 5.", "latex": "L_2(\\mathcal{C}) = \\sum_{(x,y)} \\log P(y|x^1, \\ldots, x^m).", "terms": [{"term": "$L_2(\\mathcal{C})$", "definition": "The supervised fine-tuning objective: a single number scoring how well the model's label predictions fit the whole labelled dataset $\\mathcal{C}$. The paper maximizes it.", "conceptId": "supervised-objective-l2"}, {"term": "$\\mathcal{C}$", "definition": "The labelled dataset of one target task. Each instance in it is a sequence of input tokens paired with a single correct label.", "conceptId": "labeled-dataset-c"}, {"term": "$\\sum_{(x,y)}$", "definition": "Sum over every labelled instance in $\\mathcal{C}$, one term per (token sequence, label) pair. Written as a plain sum with no normalization by dataset size.", "conceptId": null}, {"term": "$x$", "definition": "Shorthand for one instance's whole input token sequence, used as the summation index alongside its label.", "conceptId": null}, {"term": "$y$", "definition": "The correct label for that instance — the class the task asks the model to predict, such as an entailment decision or a sentiment tag.", "conceptId": null}, {"term": "$x^1, \\ldots, x^m$", "definition": "The individual input tokens of one instance, written out in order. Superscripts index position within the sequence, not exponentiation.", "conceptId": null}, {"term": "$m$", "definition": "The number of tokens in this instance's input sequence, so $x^m$ is its last token. It varies from instance to instance.", "conceptId": null}, {"term": "$\\log$", "definition": "Natural log of the label probability. Turning probabilities into logs makes the per-instance scores add rather than multiply, and maximizing the sum is maximum-likelihood fitting.", "conceptId": "maximum-likelihood-training"}, {"term": "$P(y|x^1,\\ldots,x^m)$", "definition": "The model's probability for label $y$ given the input tokens. Defined one line earlier in Equation 3 as a softmax over the label scores.", "conceptId": null}, {"term": "$\\mathrm{softmax}(h_l^m W_y)$", "definition": "From Equation 3: the label scores are exponentiated and normalized to sum to one, producing the label distribution that $L_2$ reads off.", "conceptId": null}, {"term": "$h_l^m$", "definition": "The final transformer block's activation at the last input token, position $m$ of layer $l$. This one vector is the model's summary of the input that the classifier sees.", "conceptId": "final-token-activation"}, {"term": "$W_y$", "definition": "The added linear output layer's parameter matrix, mapping the final activation to one score per label. It is the only weight matrix fine-tuning introduces.", "conceptId": "linear-output-layer-wy"}, {"term": "$L_1$", "definition": "The pre-training language modelling objective from Equation 1, referenced here because fine-tuning follows it and later re-uses it as an auxiliary term.", "conceptId": "language-modeling-objective"}, {"term": "$L_3(\\mathcal{C}) = L_2(\\mathcal{C}) + \\lambda * L_1(\\mathcal{C})$", "definition": "The objective actually optimized during fine-tuning, in the next equation: $L_2$ plus a weighted language modelling term computed on the same labelled data.", "conceptId": "auxiliary-lm-objective"}], "numbers": [{"value": "2 (in $L_2$)", "meaning": "An identifying subscript, not a quantity. The paper numbers its three objectives in the order it introduces them: $L_1$ for pre-training, $L_2$ for supervised fine-tuning, $L_3$ for their weighted combination."}, {"value": "(4)", "meaning": "The equation number printed in the right margin. It is the fourth numbered equation in the paper and the second one in Section 3.2, following Equation 3, which defines the $P(y \\mid x^1,\\dots,x^m)$ that this equation takes the log of."}, {"value": "3 (Equation 3)", "meaning": "The equation immediately above, $P(y|x^1,\\dots,x^m) = \\mathrm{softmax}(h_l^m W_y)$. It supplies the probability term inside the sum, so Equation 4 cannot be read without it."}, {"value": "1 (in $x^1$)", "meaning": "The position index of the first input token of an instance. Token positions are numbered from 1 up to $m$."}, {"value": "$m$", "meaning": "The index of the last token, i.e. the input length. It is a per-instance quantity with no fixed value here; the pre-trained model's context window caps how large it can be."}, {"value": "$l$ (in $h_l^m$)", "meaning": "The index of the final transformer block, so $h_l$ is the top layer's output. In the trained model this stack is 12 blocks deep."}], "sources": {"sections": [], "pages": [3]}}, {"id": "eq-combined-objective", "kind": "equation", "number": null, "caption": "The combined objective L3 = L2 + lambda L1", "page": 3, "asset": null, "section": "3.2", "title": "The Combined Fine-Tuning Objective", "takeaway": "During fine-tuning the paper does not drop the language modelling loss; it keeps optimizing it alongside the classification loss, scaled by a weight $\\lambda$, and computes it on the labelled task data rather than on the pre-training corpus. The paper reports this helped by improving generalization and speeding convergence, and its own ablation later qualifies that: the gain shows up on larger datasets, not on smaller ones.", "walkthrough": "Equation 5 is the loss actually optimized in stage two, [[supervised-fine-tuning]]. It is a sum of two terms the paper has already defined separately, plus a knob that trades one against the other.\n\nRead the pieces right to left. $L_1$ is the [[language-modeling-objective]] from Equation 1: the summed log-probability the model assigns to each token given the tokens before it. $L_2$ is the [[supervised-objective-l2]] from Equation 4: the summed log-probability of the correct label $y$ given the input sequence $x^1,\\dots,x^m$. Both are quantities to *maximize*, so Equation 5 is a likelihood, not an error being driven down.\n\nNow the argument. Every term in Equation 5 takes $\\mathcal{C}$, the [[labeled-dataset-c]]. That is the detail worth pausing on. In stage one, $L_1$ ran over the unlabelled corpus — [[bookscorpus]] during [[generative-pretraining]]. Here it runs over the labelled examples themselves. The model is asked to predict the next token *of the task's own input sentences* while it is learning to predict their labels. No unlabelled data is streamed in during fine-tuning; the same text serves both losses.\n\n$\\lambda$ sets how loudly the language modelling term speaks. At $\\lambda = 0$ you recover plain fine-tuning on $L_2$. Larger $\\lambda$ pulls the weights toward staying good at next-token prediction while they specialize. The paper fixes it at 0.5, so the auxiliary term carries half the weight of the task term. See [[auxiliary-objective-weight]] and the surrounding [[fine-tuning-hyperparameters]].\n\nWhat this is claimed to buy: the paper says it found the [[auxiliary-lm-objective]] \"helped learning\" by (a) improving generalization of the supervised model and (b) accelerating convergence. It places this in line with prior work that added a language modelling loss to a target-task loss — the [[auxiliary-training-objectives]] branch of semi-supervised learning.\n\nThe claim is stated as a found result, without a number attached at this point in the paper. The evidence arrives later in [[ablation-no-auxiliary-objective]], and it is mixed: removing the term helps on some datasets and hurts on others, with the trend that larger datasets benefit and smaller ones do not. So (a) and (b) as written here are broader than the ablation supports.", "latex": "L_3(\\mathcal{C}) = L_2(\\mathcal{C}) + \\lambda * L_1(\\mathcal{C})", "terms": [{"term": "$L_3(\\mathcal{C})$", "definition": "The combined objective optimized during fine-tuning: the task loss plus a weighted language modelling loss, both evaluated on the labelled data. It is maximized, like its two components.", "conceptId": "auxiliary-lm-objective"}, {"term": "$L_2(\\mathcal{C})$", "definition": "The supervised term, defined in Equation 4 as $\\sum_{(x,y)} \\log P(y \\mid x^1,\\dots,x^m)$: the summed log-probability the model gives the correct label for each labelled example.", "conceptId": "supervised-objective-l2"}, {"term": "$L_1(\\mathcal{C})$", "definition": "The language modelling term, defined in Equation 1 as $\\sum_i \\log P(u_i \\mid u_{i-k},\\dots,u_{i-1};\\Theta)$. Written with argument $\\mathcal{C}$ here, it is computed on the labelled task text, not on the pre-training corpus.", "conceptId": "language-modeling-objective"}, {"term": "$\\mathcal{C}$", "definition": "The labelled dataset for one target task. Each instance is a sequence of input tokens $x^1,\\dots,x^m$ paired with a label $y$.", "conceptId": "labeled-dataset-c"}, {"term": "$\\lambda$", "definition": "The scalar weight on the auxiliary language modelling term. It controls how much next-token prediction on the task's text pulls on the parameters relative to label prediction.", "conceptId": "auxiliary-objective-weight"}, {"term": "$*$", "definition": "Ordinary scalar multiplication, printed as an asterisk in the paper rather than as juxtaposition or a centred dot. It carries no special meaning here.", "conceptId": null}, {"term": "$x^1,\\dots,x^m$", "definition": "The input token sequence of one labelled example, $m$ tokens long. Structured inputs such as sentence pairs are first flattened into one such sequence.", "conceptId": "task-specific-input-transformations"}, {"term": "$y$", "definition": "The label of a labelled example, predicted by a softmax over the added linear output layer applied to the final block's activation at the last token.", "conceptId": "linear-output-layer-wy"}, {"term": "$u_i$", "definition": "The $i$-th token of a text sequence as seen by the language modelling term. During fine-tuning these tokens come from the task's own inputs.", "conceptId": null}, {"term": "$\\Theta$", "definition": "The parameters of the neural network computing the next-token distribution. In stage two these are the pre-trained transformer weights, now being updated by both terms at once.", "conceptId": "generative-pretraining"}, {"term": "$k$", "definition": "The context window inside $L_1$: how many preceding tokens a next-token prediction may condition on.", "conceptId": "context-window-512-tokens"}, {"term": "auxiliary objective", "definition": "A second loss added beside the task loss to shape learning, rather than to be scored. Here the language modelling loss plays that role during fine-tuning.", "conceptId": "auxiliary-training-objectives"}], "numbers": [{"value": "0.5", "meaning": "The value of $\\lambda$. Section 4.1's fine-tuning details state simply that $\\lambda$ was set to 0.5, giving the auxiliary language modelling term half the weight of the classification term. The paper reports no sweep or sensitivity analysis behind that choice."}, {"value": "1, 2, 3", "meaning": "The subscripts on $L$ are index labels, not quantities. $L_1$ is the pre-training objective introduced first (Equation 1), $L_2$ the supervised objective (Equation 4), and $L_3$ their combination. The numbering follows the order the paper introduces them, not any ordering of importance."}, {"value": "5", "meaning": "The equation number on page 3. It is the last numbered equation of Section 3.2, and the text immediately after it notes that the only extra parameters fine-tuning needs are $W_y$ and the delimiter-token embeddings."}, {"value": "512", "meaning": "The context window $k$ used when the language modelling objective was trained in stage one, in tokens. Fine-tuning reuses the pre-training hyperparameters unless stated otherwise, and the paper does not separately specify a window for $L_1(\\mathcal{C})$; labelled examples are typically far shorter than 512 tokens anyway."}], "sources": {"sections": [], "pages": [3]}}], "edges": [{"source": "two-stage-training-procedure", "target": "labeled-data-scarcity", "type": "depends-on", "label": "recipe presupposes scarce labels", "explanation": "The two-stage recipe only earns its complexity if labelled data for each task is small while raw text is plentiful. If every task had enough annotated examples, there would be nothing for a pre-training stage to buy. The paper opens from that asymmetry and designs backwards from it.", "strength": "load-bearing", "id": "e001"}, {"source": "supervised-fine-tuning", "target": "generative-pretraining", "type": "depends-on", "label": "fine-tuning starts from pre-trained weights", "explanation": "Stage two does not train a fresh network; it continues training the exact parameters stage one produced. The ablation puts a number on how much of the result comes from that starting point: training the same transformer directly on the supervised tasks costs 14.8% across the board.", "strength": "load-bearing", "id": "e002"}, {"source": "language-modeling-objective", "target": "masked-self-attention", "type": "depends-on", "label": "next-token loss needs future hidden", "explanation": "The loss asks the model to predict each token from the tokens before it, and it does this at every position at once. Without the mask, a position could attend to the token it is being asked to predict, and the objective would be solved by copying rather than by learning. The mask is what makes a single forward pass over a 512-token sequence produce 512 honest predictions.", "strength": "load-bearing", "id": "e003"}, {"source": "multi-layer-transformer-decoder", "target": "transformer-gpt1", "type": "depends-on", "label": "built from transformer blocks", "explanation": "The pre-training network is not a new architecture. It is the transformer block of prior work, stacked twelve deep and restricted to attend backwards. Everything the paper says about capacity and long-range conditioning inherits from that architecture.", "strength": "load-bearing", "id": "e004"}, {"source": "multi-layer-transformer-decoder", "target": "lstm-short-range-limitation", "type": "depends-on", "label": "choice argued from recurrent locality", "explanation": "The paper's stated reason for using a transformer rather than a recurrent network is that pre-trained LSTMs keep their predictive ability short-range, which limits how much structure they can hand to a target task. The architecture choice is presented as a response to that limitation. The LSTM ablation is the paper's own test of the claim, at a cost of 5.6 average score points.", "strength": "supporting", "id": "e005"}, {"source": "output-softmax-tied-embeddings", "target": "token-embedding-matrix", "type": "depends-on", "label": "output layer reuses input embeddings", "explanation": "There is no separate output projection in equation 2. The top block's states are multiplied by the transpose of the same matrix $W_e$ that turned tokens into vectors on the way in, and softmaxed. Reading the output head means reading the embedding table twice, once forwards and once backwards.", "strength": "supporting", "id": "e006"}, {"source": "input-representation-h0", "target": "learned-position-embeddings", "type": "depends-on", "label": "attention needs position injected", "explanation": "Self-attention sees a set of vectors, not an ordered sequence, so order has to be added to the input rather than inferred from it. Layer zero is $h_0 = UW_e + W_p$: the token vectors with a position vector added to each slot. Take $W_p$ away and the model cannot tell which token came first.", "strength": "supporting", "id": "e007"}, {"source": "context-window-512-tokens", "target": "learned-position-embeddings", "type": "depends-on", "label": "trained table fixes maximum length", "explanation": "The paper trains $W_p$ rather than using the original transformer's fixed sinusoids. A trained table has one row per slot, so the number of rows is the longest context the model can ever be given. The 512-token window is therefore a size in the parameter table, not a setting that can be raised at test time.", "strength": "supporting", "id": "e008"}, {"source": "context-window-512-tokens", "target": "long-range-contiguous-text", "type": "depends-on", "label": "long window needs contiguous training text", "explanation": "A 512-token window is only worth paying for if the tokens in it are actually related. Pre-training samples contiguous stretches from books, so a window usually holds several paragraphs of one story. On a sentence-shuffled corpus the same window would mostly hold unrelated neighbours.", "strength": "supporting", "id": "e009"}, {"source": "bookscorpus", "target": "long-range-dependencies-gpt1", "type": "depends-on", "label": "corpus chosen for long-range structure", "explanation": "The paper says the point of BooksCorpus is its long stretches of contiguous text, which let the model learn to condition on far-away information. It names the 1B Word Benchmark, of roughly the same size, as the alternative it rejects because sentence-level shuffling destroys that structure. The corpus choice is the goal of long-range conditioning made concrete.", "strength": "load-bearing", "id": "e010"}, {"source": "bookscorpus", "target": "domain-mismatch-tolerance", "type": "depends-on", "label": "fiction corpus assumes domain tolerance", "explanation": "The pre-training data is over 7,000 unpublished novels; the evaluation includes science exam entailment, news paraphrase and Quora question pairs. Using one for the other rests on the paper's stated assumption that the unlabelled corpus need not match the target domain. The assumption is stated rather than tested directly.", "strength": "supporting", "id": "e011"}, {"source": "token-embedding-matrix", "target": "byte-pair-encoding-gpt1", "type": "depends-on", "label": "vocabulary rows are BPE units", "explanation": "What counts as a token is decided by byte-pair encoding with 40,000 merges, so the rows of $W_e$ are subword pieces, not words. Common words survive as single rows and rare words are split into several. Because the output softmax reuses $W_e^T$, the distribution the model predicts is a distribution over those same subword units.", "strength": "supporting", "id": "e012"}, {"source": "language-modeling-objective", "target": "maximum-likelihood-training", "type": "depends-on", "label": "objective is a likelihood", "explanation": "$L_1$ is a sum of log-probabilities the model assigns to tokens that actually occurred, maximized by gradient descent. Nothing about the pre-training loss is special beyond fitting observed data by likelihood. The novelty in stage one is the data and the architecture, not the estimator.", "strength": "minor", "id": "e013"}, {"source": "weight-initialization", "target": "layer-normalization-gpt1", "type": "depends-on", "label": "layernorm makes simple init sufficient", "explanation": "The paper draws every weight from $\\mathcal{N}(0, 0.02)$ and says this was sufficient because layernorm is used extensively throughout the model. Normalizing activations at each position rescales whatever the initial weights produce, so the initialization does not have to be tuned to keep signal magnitudes in range. One choice is being justified by the other.", "strength": "supporting", "id": "e014"}, {"source": "decoupled-weight-decay", "target": "adam-optimizer-gpt1", "type": "depends-on", "label": "decay variant written for Adam", "explanation": "Plain L2 added into the loss gets rescaled by Adam's per-parameter adaptive step, so parameters with small gradient history are decayed differently from those with large history. The paper uses the modified version designed for this case, at $w = 0.01$ on all non-bias and non-gain weights. The regularizer is chosen because of the optimizer, not independently of it.", "strength": "minor", "id": "e015"}, {"source": "final-token-activation", "target": "start-and-end-tokens", "type": "depends-on", "label": "classifier reads the end token", "explanation": "The task head consumes one vector, the final block's activation at the last position of the input. That position needs to be the same kind of thing in every example, which is what bracketing every transformed input with $\\langle s\\rangle$ and $\\langle e\\rangle$ gives. The paper states the bracketing as part of the transformations rather than arguing this point explicitly.", "strength": "supporting", "id": "e016"}, {"source": "linear-output-layer-wy", "target": "final-token-activation", "type": "depends-on", "label": "one matrix over one vector", "explanation": "Equation 3 is $\\mathrm{softmax}(h_l^m W_y)$: the whole task-specific classifier is a single matrix applied to a single vector. That is only possible because the sequence has already been collapsed to one activation at the last token. If the head had to read the whole sequence, it could not be one matrix.", "strength": "supporting", "id": "e017"}, {"source": "auxiliary-lm-objective", "target": "output-softmax-tied-embeddings", "type": "depends-on", "label": "LM head survives into fine-tuning", "explanation": "$L_3(C) = L_2(C) + \\lambda L_1(C)$ keeps computing the pre-training loss on the task's own inputs during fine-tuning. That costs nothing extra in parameters because the language modelling head is just $W_e^T$, which is still there. A model with a separately trained output projection would have to carry it along deliberately.", "strength": "supporting", "id": "e018"}, {"source": "task-agnostic-model", "target": "task-specific-input-transformations", "type": "depends-on", "label": "one architecture needs flattened inputs", "explanation": "The claim of a single model for every task holds only because the tasks are made to look alike at the input. Entailment pairs, similarity pairs and document-question-answer triplets are all rewritten as one ordered token sequence before the model sees them. The task-specific work has been moved out of the architecture and into the serialization.", "strength": "load-bearing", "id": "e019"}, {"source": "minimal-extra-parameters", "target": "task-specific-input-transformations", "type": "depends-on", "label": "no new modules to initialize", "explanation": "The paper says the only extra parameters during fine-tuning are $W_y$ and embeddings for the delimiter tokens. That count stays small because structured inputs are handled by rewriting them, not by adding encoders or attention modules per task. The alternative the paper names, task-specific architectures stacked on transferred representations, re-introduces freshly initialized components for every task.", "strength": "load-bearing", "id": "e020"}, {"source": "similarity-input-transformation", "target": "final-token-activation", "type": "depends-on", "label": "last-token readout is order-sensitive", "explanation": "The two sentences in a similarity pair have no natural order, but the model reads left to right and summarizes at the last token, so whichever sentence comes second is closer to the readout. The paper builds both orderings, processes each independently, and adds the two final activations element-wise before the linear layer. The symmetric handling is a repair for an asymmetry the readout introduces.", "strength": "supporting", "id": "e021"}, {"source": "ablation-lstm-substitution", "target": "task-specific-input-transformations", "type": "depends-on", "label": "swap possible because framework is shared", "explanation": "Replacing the transformer with a single-layer 2048-unit LSTM is a clean comparison only because everything around the model stays fixed: the same serialized inputs, the same last-token readout, the same objectives. Since the transformations are architecture-independent, the 5.6-point average drop can be attributed to the sequence model itself.", "strength": "supporting", "id": "e022"}, {"source": "fine-tuning-lr-and-batch", "target": "generative-pretraining", "type": "depends-on", "label": "smaller step protects pre-trained weights", "explanation": "Fine-tuning uses 6.25e-5, about four times smaller than pre-training's peak of 2.5e-4, on batches of 32. The setting only makes sense as an adjustment to weights that already encode something worth keeping. The paper reports the numbers without arguing this reading.", "strength": "supporting", "id": "e023"}, {"source": "three-epochs-fine-tuning", "target": "generative-pretraining", "type": "depends-on", "label": "short schedule assumes work already done", "explanation": "Three passes over a task's training set would be a very short budget for a model starting from random weights, and the no-pre-training ablation loses 14.8% under the same framework. The paper says the model fine-tunes quickly and that three epochs sufficed for most cases. The brevity of stage two is a consequence of the cost paid in stage one, 100 epochs over BooksCorpus.", "strength": "supporting", "id": "e024"}, {"source": "zero-shot-behaviors", "target": "average-token-log-probability-scoring", "type": "depends-on", "label": "heuristics need a scoring rule", "explanation": "A generative model does not emit labels, so making it answer a task without fine-tuning requires turning it into a scorer. Three of the four heuristics do the same thing: score a candidate string by the mean log-probability the model assigns its tokens, then pick or threshold. Without that device there is no zero-shot curve to plot.", "strength": "load-bearing", "id": "e025"}, {"source": "average-token-log-probability-scoring", "target": "language-modeling-objective", "type": "depends-on", "label": "score is the training quantity", "explanation": "The number used to rank candidates is the same log-probability that $L_1$ maximizes, just averaged over the tokens of one candidate instead of summed over a corpus. That is why the zero-shot scores can rise steadily as pre-training proceeds: the heuristic reads out exactly what training is pushing on.", "strength": "supporting", "id": "e026"}, {"source": "sst2-zero-shot-heuristic", "target": "output-softmax-tied-embeddings", "type": "depends-on", "label": "restricting the vocabulary distribution", "explanation": "The heuristic appends the token 'very' and then restricts the model's output distribution to the words 'positive' and 'negative', taking whichever scores higher. That is only available because the model already produces a distribution over the whole vocabulary at each position. No classifier is involved anywhere in this procedure.", "strength": "supporting", "id": "e027"}, {"source": "transformer-inductive-bias", "target": "zero-shot-behaviors", "type": "depends-on", "label": "hypothesis rests on zero-shot variance", "explanation": "The paper's suggestion that the transformer's attention gives a more structured memory than an LSTM is supported by an observation inside this analysis: the LSTM shows higher variance in its zero-shot performance over the course of pre-training. That is one qualitative comparison, and the paper words it as a hypothesis rather than a finding.", "strength": "supporting", "id": "e028"}, {"source": "layers-transferred", "target": "twelve-layer-depth", "type": "depends-on", "label": "sweep only exists given depth", "explanation": "The analysis varies how many pre-trained layers are carried into fine-tuning, which is a dial with twelve settings only because the stack is twelve blocks deep. Going from embeddings alone to full transfer is worth up to 9% on MultiNLI. A shallower model would have fewer points on that curve and less room for the effect to show.", "strength": "minor", "id": "e029"}, {"source": "twelve-attention-heads", "target": "hidden-state-dimension-768", "type": "depends-on", "label": "heads split the 768 dimensions", "explanation": "The twelve heads do not each get their own 768 dimensions; they divide the state between them. 768 divided by 12 gives each head a 64-dimensional subspace to attend in. Changing the state size or the head count changes the other, unless the per-head width is allowed to move.", "strength": "minor", "id": "e030"}, {"source": "two-stage-training-procedure", "target": "table-5", "type": "supported-by", "label": "ablation without pre-training loses 14.8", "explanation": "The whole recipe rests on the claim that stage one matters. Table 5 trains the same transformer directly on the supervised tasks with no pre-training and reports a 14.8% drop across the board. That single row is the paper's strongest direct evidence for the two-stage design.", "strength": "load-bearing", "id": "e031"}, {"source": "multi-layer-transformer-decoder", "target": "table-5", "type": "supported-by", "label": "LSTM swap costs 5.6 points", "explanation": "The paper needs a reason to pick a transformer rather than a recurrent net. Table 5 holds everything else fixed and substitutes a single-layer 2048-unit LSTM, which costs 5.6 average score points. The LSTM wins on only one dataset, MRPC.", "strength": "load-bearing", "id": "e032"}, {"source": "ablation-no-pretraining", "target": "table-5", "type": "supported-by", "label": "14.8 percent drop reported", "explanation": "This ablation exists only as a row in Table 5. Removing pre-training hurts on every task measured, making it the largest of the three ablation effects.", "strength": "load-bearing", "id": "e033"}, {"source": "ablation-lstm-substitution", "target": "table-5", "type": "supported-by", "label": "5.6 average points, one exception", "explanation": "Table 5 supplies both halves of this ablation: the 5.6-point average drop, and the fact that MRPC is the one dataset where the LSTM comes out ahead. The exception is worth noticing, since it means the architecture claim is an average and not a sweep.", "strength": "supporting", "id": "e034"}, {"source": "auxiliary-lm-objective", "target": "table-5", "type": "supported-by", "label": "help is mixed, not uniform", "explanation": "The paper keeps the language modelling loss during fine-tuning, but Table 5 shows removing it helps on some datasets and hurts on others. The reported pattern is that the NLI tasks and QQP benefit while smaller datasets do not, so the evidence supports a size-dependent rule rather than a general one.", "strength": "supporting", "id": "e035"}, {"source": "language-modeling-objective", "target": "eq-lm-objective", "type": "supported-by", "label": "equation defines the pre-training loss", "explanation": "Equation 1 is the entire training signal for stage one: sum the log-probability the network assigns each token given the k tokens before it. Everything the model knows before fine-tuning comes from maximizing this one quantity.", "strength": "load-bearing", "id": "e036"}, {"source": "multi-layer-transformer-decoder", "target": "eq-decoder-stack", "type": "supported-by", "label": "three lines specify the network", "explanation": "Equation 2 writes the pre-training network out in full: embed the context tokens and add position embeddings, push the result through n identical transformer blocks, then project to a token distribution. Reading it is how you confirm there is no encoder and no cross-attention anywhere in the model.", "strength": "load-bearing", "id": "e037"}, {"source": "output-softmax-tied-embeddings", "target": "eq-decoder-stack", "type": "supported-by", "label": "output reuses transposed embedding matrix", "explanation": "The last line of Equation 2 multiplies the top block's states by the transpose of the same token embedding matrix used at the input, then softmaxes. The equation is where you see the tying, which is otherwise easy to miss in the prose.", "strength": "supporting", "id": "e038"}, {"source": "supervised-fine-tuning", "target": "eq-task-head", "type": "supported-by", "label": "whole task head in one equation", "explanation": "Equation 3 says the task-specific part is: take the final block's activation at the last token, multiply by one matrix, softmax. The paper's claim of minimal architectural change is checkable directly against this line.", "strength": "load-bearing", "id": "e039"}, {"source": "minimal-extra-parameters", "target": "eq-task-head", "type": "supported-by", "label": "only one new matrix appears", "explanation": "The claim that a new task costs almost no new parameters is verified by counting what Equation 3 introduces, which is the single matrix W_y. The delimiter token embeddings are the only other addition, and they are not in the equation.", "strength": "supporting", "id": "e040"}, {"source": "supervised-objective-l2", "target": "eq-supervised-objective", "type": "supported-by", "label": "equation states the task loss", "explanation": "Equation 4 sums the log-probability of the correct label over the labelled dataset. It is ordinary supervised training, and stating it plainly is what lets the next equation combine it with the pre-training loss.", "strength": "supporting", "id": "e041"}, {"source": "auxiliary-lm-objective", "target": "eq-combined-objective", "type": "supported-by", "label": "combined loss written explicitly", "explanation": "Equation 5 gives L3 = L2 + lambda times L1, showing that fine-tuning optimizes both losses at once rather than switching between them. The weight lambda is where the balance between task fitting and continued language modelling is set.", "strength": "supporting", "id": "e042"}, {"source": "auxiliary-objective-weight", "target": "eq-combined-objective", "type": "supported-by", "label": "lambda's position in the loss", "explanation": "The equation shows lambda scaling only the language modelling term, so a value of 0.5 means that loss enters at half the weight of the classification loss. The paper reports the value but gives no sweep, so 0.5 is a stated setting rather than a tuned finding.", "strength": "minor", "id": "e043"}, {"source": "task-specific-input-transformations", "target": "fig-1", "type": "supported-by", "label": "figure draws all four input shapes", "explanation": "Figure 1's right panel is the concrete content of this idea: classification, entailment, similarity and multiple choice each shown as a token sequence with start, delimiter and end markers. Without the picture the claim that structured inputs become one ordered sequence stays abstract.", "strength": "load-bearing", "id": "e044"}, {"source": "similarity-input-transformation", "target": "fig-1", "type": "supported-by", "label": "two orderings summed before head", "explanation": "The figure shows the similarity task running both sentence orderings through the stack separately and adding the two final activations element-wise before the linear layer. That detail is only legible in the diagram.", "strength": "minor", "id": "e045"}, {"source": "task-agnostic-model", "target": "fig-1", "type": "supported-by", "label": "one stack serves every task", "explanation": "The left panel draws the repeated block and the right panel shows four different tasks feeding that same stack. The figure is the paper's visual argument that no task gets its own architecture.", "strength": "supporting", "id": "e046"}, {"source": "evaluation-task-families", "target": "table-1", "type": "supported-by", "label": "lists the twelve datasets", "explanation": "Table 1 sets out the four task families and names all twelve datasets. It fixes the denominator that the headline 9-of-12 count is measured against.", "strength": "supporting", "id": "e047"}, {"source": "natural-language-inference", "target": "table-2", "type": "supported-by", "label": "beats baselines on four of five", "explanation": "Table 2 puts the fine-tuned general model against task-built systems on five NLI datasets. It reports gains of 1.5% on MNLI, 5% on SciTail, 5.8% on QNLI and 0.6% on SNLI, and a loss on RTE.", "strength": "load-bearing", "id": "e048"}, {"source": "rte", "target": "table-2", "type": "supported-by", "label": "result undercuts the general claim", "explanation": "On RTE the model reaches 56% accuracy against 61.7% from a multi-task biLSTM. RTE has 2490 training examples, and the paper reads the loss as a small-data effect and suggests multi-task training might help, but it did not run that experiment.", "strength": "supporting", "id": "e049"}, {"source": "state-of-the-art-9-of-12", "target": "table-2", "type": "supported-by", "label": "headline count assembled from tables", "explanation": "The 9-of-12 figure is not reported in any single place; it is the sum of wins across Tables 2, 3 and 4, of which Table 2 contributes four. Reading the tables also shows the three losses, which the headline number hides.", "strength": "supporting", "id": "e050"}, {"source": "question-answering-and-commonsense-reasoning", "target": "table-3", "type": "supported-by", "label": "8.9 on Cloze, 5.7 on RACE", "explanation": "Table 3 reports the paper's largest margins: 8.9% on the Story Cloze Test and 5.7% overall on RACE, ahead of every previously published system on both. These are the two numbers the abstract leads with.", "strength": "load-bearing", "id": "e051"}, {"source": "long-range-dependencies-gpt1", "target": "table-3", "type": "supported-by", "label": "reasoning benchmarks as indirect proxy", "explanation": "The paper reads its RACE and Story Cloze margins as showing the model handles long-range context. The link is inferential rather than measured, since neither table separates long-range from short-range items, so the evidence is one step weaker than the claim it is used for.", "strength": "supporting", "id": "e052"}, {"source": "long-range-contiguous-text", "target": "table-3", "type": "supported-by", "label": "corpus choice never directly tested", "explanation": "BooksCorpus is chosen over the sentence-shuffled 1B Word Benchmark because it preserves long stretches of text, and the multi-sentence reasoning results are offered as the payoff. No pre-training corpus was swapped and rerun, so the corpus argument rests on downstream scores rather than a controlled comparison.", "strength": "supporting", "id": "e053"}, {"source": "semantic-similarity", "target": "table-4", "type": "supported-by", "label": "best on two of three datasets", "explanation": "Table 4 reports a 1 point absolute gain on STS-B and a 4.2% improvement on QQP over a single-task BiLSTM with ELMo and attention. MRPC is the third dataset, and the paper does not claim a win there.", "strength": "supporting", "id": "e054"}, {"source": "cola", "target": "table-4", "type": "supported-by", "label": "45.4 against previous best 35.0", "explanation": "This is the largest relative jump in Table 4: a grammatical acceptability score of 45.4 where the previous best was 35.0. The paper reads it as evidence of linguistic bias picked up during pre-training, which is an interpretation the number alone does not settle.", "strength": "supporting", "id": "e055"}, {"source": "sst-2", "target": "table-4", "type": "supported-by", "label": "competitive but not state of the art", "explanation": "The reported 91.3% accuracy on SST-2 is one of the three datasets where the paper does not take the top spot. It is included in the table rather than omitted, which is what makes the 9-of-12 count auditable.", "strength": "minor", "id": "e056"}, {"source": "glue-benchmark", "target": "table-4", "type": "supported-by", "label": "72.8 overall against 68.9", "explanation": "The aggregate GLUE score of 72.8 against a previous best of 68.9 is the paper's one summary number spanning several datasets at once. Being an average, it can be lifted by large wins on individual tasks such as CoLA.", "strength": "supporting", "id": "e057"}, {"source": "layers-transferred", "target": "fig-2", "type": "supported-by", "label": "each layer adds up to 9 percent", "explanation": "The left panel of Figure 2 varies how many pre-trained layers are carried into fine-tuning and plots dev accuracy on MultiNLI and RACE. Accuracy climbs with each additional layer, reaching up to 9% for full transfer on MultiNLI, which is the paper's case that the depth of the stack, not just the embeddings, holds transferable function.", "strength": "load-bearing", "id": "e058"}, {"source": "zero-shot-behaviors", "target": "fig-2", "type": "supported-by", "label": "heuristic scores rise during pre-training", "explanation": "The right panel tracks four fine-tuning-free heuristics across pre-training updates and shows their performance rising steadily and staying stable. The curves are relative trends, not absolute task scores, so they show the ability growing rather than showing it is competitive.", "strength": "supporting", "id": "e059"}, {"source": "generative-pretraining", "target": "fig-2", "type": "supported-by", "label": "task ability grows without supervision", "explanation": "The zero-shot curves are the paper's attempt to say why pre-training works rather than just that it works: task-relevant behaviour appears while only the language modelling loss is being optimized. This is offered as support for a hypothesis, and the paper words it that way.", "strength": "supporting", "id": "e060"}, {"source": "transformer-inductive-bias", "target": "fig-2", "type": "supported-by", "label": "LSTM shows higher zero-shot variance", "explanation": "The claim that the transformer's attentional memory aids transfer rests on one observation in the right panel: the LSTM's zero-shot performance varies more across pre-training. No variance figure is quoted, so this reads as a qualitative reading of a plot rather than a measurement.", "strength": "minor", "id": "e061"}, {"source": "world-knowledge", "target": "fig-2", "type": "supported-by", "label": "conclusion outruns the diagnostic", "explanation": "The conclusion says pre-training leaves the model with significant world knowledge, and the nearest evidence is the zero-shot panel plus the downstream scores. Neither measures facts about the world directly, so the phrase is a summary of the paper's expectations more than something the figures establish.", "strength": "minor", "id": "e062"}, {"source": "generative-pretraining", "target": "token-level-perplexity", "type": "supported-by", "label": "perplexity 18.4 shows corpus fit", "explanation": "The paper reports a token-level perplexity of 18.4 on BooksCorpus as a sign that stage one trained well. It measures fit to the pre-training corpus only, and says nothing on its own about whether the weights transfer.", "strength": "minor", "id": "e063"}, {"source": "two-stage-training-procedure", "target": "semi-supervised-learning-for-nlp", "type": "instance-of", "label": "the paper's semi-supervised recipe", "explanation": "Semi-supervised learning for NLP is the general family: a large unlabelled corpus plus a small labelled dataset. The paper's two-stage recipe is one specific member of that family, where the unlabelled corpus is used first to set the weights and the labelled data second to adjust them. The paper places itself inside this family explicitly rather than claiming a new category.", "strength": "load-bearing", "id": "e064"}, {"source": "two-stage-training-procedure", "target": "lm-pretraining-then-finetuning-predecessors", "type": "instance-of", "label": "another entry in this line", "explanation": "The paper names a line of prior work that pre-trains with a language modelling objective and then fine-tunes the whole network on a supervised task. Its own procedure is a further instance of exactly that shape. What changes is the backbone and the scale, not the shape of the recipe.", "strength": "supporting", "id": "e065"}, {"source": "generative-pretraining", "target": "unsupervised-pretraining", "type": "instance-of", "label": "unlabelled data sets the weights", "explanation": "The survey splits semi-supervised methods into two branches: unlabelled data can choose a starting point for the weights, or it can add a term to the supervised loss. Stage one is a concrete case of the first branch, since the corpus produces parameters and nothing else is carried forward. The outputs of the language model are discarded; only Theta survives into fine-tuning.", "strength": "supporting", "id": "e066"}, {"source": "auxiliary-lm-objective", "target": "auxiliary-training-objectives", "type": "instance-of", "label": "second loss kept during fine-tuning", "explanation": "The other branch of semi-supervised learning adds an unsupervised loss term alongside the supervised one. The paper's L3(C) = L2(C) + lambda*L1(C) is a concrete instance of that branch, used during stage two. So the method takes something from both branches the related-work section separates.", "strength": "supporting", "id": "e067"}, {"source": "language-modeling-objective", "target": "choice-of-pretraining-objective", "type": "instance-of", "label": "next-token prediction as the pick", "explanation": "The introduction says it is unclear which unsupervised objective produces representations that transfer best. Next-token log-likelihood is the paper's specific answer to that open question. The paper does not argue it is the best available objective; it reports what happens when you use it.", "strength": "supporting", "id": "e068"}, {"source": "multi-layer-transformer-decoder", "target": "transformer-gpt1", "type": "instance-of", "label": "decoder-only variant of transformer", "explanation": "The transformer architecture is the general design the paper starts from. The language model here is one particular cut of it: the encoder half is dropped and a single stack of blocks with masked multi-head self-attention and position-wise feed-forward layers is kept. Nothing about the block itself is redesigned.", "strength": "load-bearing", "id": "e069"}, {"source": "multi-layer-transformer-decoder", "target": "task-agnostic-model", "type": "instance-of", "label": "the one stack every task uses", "explanation": "Task-agnostic model is the claim: one architecture, pre-trained once, applied everywhere without redesign. The 12-block decoder stack is what actually fills that role in this paper. Every one of the twelve datasets is run through this same stack.", "strength": "load-bearing", "id": "e070"}, {"source": "masked-self-attention", "target": "language-modeling-objective", "type": "instance-of", "label": "architecture realizing left-context conditioning", "explanation": "L1 conditions each token only on the tokens before it. Masking the attention so a position can see itself and earlier positions but never later ones is the architectural realization of that constraint. Without the mask the model could read the token it is asked to predict, and the objective would be trivial.", "strength": "load-bearing", "id": "e071"}, {"source": "language-modeling-objective", "target": "eq-lm-objective", "type": "instance-of", "label": "L1 is defined by Equation 1", "explanation": "Equation 1 is where the symbol L1 gets its meaning: sum over positions of log P(u_i | u_{i-k}, ..., u_{i-1}; Theta). Every later mention of the pre-training loss, including the lambda-weighted term during fine-tuning, refers back to this line. The parameters Theta are fitted by stochastic gradient descent on it.", "strength": "load-bearing", "id": "e072"}, {"source": "context-window-512-tokens", "target": "eq-lm-objective", "type": "instance-of", "label": "k set to 512 tokens", "explanation": "In Equation 1, k is written as a free symbol: the size of the context window a prediction may condition on. The trained model fixes k at 512 contiguous tokens. That number is what turns the abstract window into something that can span several paragraphs of a book.", "strength": "supporting", "id": "e073"}, {"source": "bookscorpus", "target": "eq-lm-objective", "type": "instance-of", "label": "BooksCorpus is the corpus U", "explanation": "Equation 1 sums over an unlabelled corpus of tokens U, left unspecified in the framework section. In the experiments U is BooksCorpus, over 7,000 unpublished books. The paper's stated reason for this choice is that the books hold long stretches of contiguous text, so the 512-token window has real long-range structure to condition on.", "strength": "supporting", "id": "e074"}, {"source": "input-representation-h0", "target": "eq-decoder-stack", "type": "instance-of", "label": "h0 defined by Equation 2", "explanation": "The first line of Equation 2 defines the layer-zero input as h0 = U*W_e + W_p: look up the embedding of each context token, add the embedding of its position, and hand that to the first block. This is the only place position information enters the model. Everything above layer zero is a stack of identical blocks.", "strength": "supporting", "id": "e075"}, {"source": "output-softmax-tied-embeddings", "target": "eq-decoder-stack", "type": "instance-of", "label": "output distribution from Equation 2", "explanation": "The last line of Equation 2 defines P(u) = softmax(h_n * W_e^T): take the top block's states and multiply by the transpose of the same token embedding matrix used at the input. Reusing W_e in both places means one table serves as both the lookup and the output scorer. That distribution is what L1 takes the log of.", "strength": "supporting", "id": "e076"}, {"source": "final-token-activation", "target": "eq-task-head", "type": "instance-of", "label": "h_l^m named by Equation 3", "explanation": "Equation 3 fixes which activation the classifier reads: the final transformer block's output at the last input token of the sequence. That single vector is the model's summary of the whole labelled input. Everything task-specific downstream reads only from it.", "strength": "supporting", "id": "e077"}, {"source": "linear-output-layer-wy", "target": "eq-task-head", "type": "instance-of", "label": "W_y defined by Equation 3", "explanation": "Equation 3, P(y | x_1..x_m) = softmax(h_l^m * W_y), introduces W_y as the one matrix mapping that final activation to label scores. It is the entire task-specific classifier. The paper's claim of minimal task machinery rests on this equation having only one new parameter matrix in it.", "strength": "supporting", "id": "e078"}, {"source": "supervised-objective-l2", "target": "eq-supervised-objective", "type": "instance-of", "label": "L2 defined by Equation 4", "explanation": "Equation 4 defines L2(C) as the sum over labelled pairs of log P(y | x_1..x_m), using the distribution Equation 3 just built. It is the ordinary supervised loss, stated so the next equation can add a term to it. Nothing here is specific to any one of the twelve datasets.", "strength": "supporting", "id": "e079"}, {"source": "auxiliary-objective-weight", "target": "eq-combined-objective", "type": "instance-of", "label": "lambda set to 0.5", "explanation": "Equation 5 writes the fine-tuning loss as L3(C) = L2(C) + lambda*L1(C), leaving lambda as a free weight. The setup section fixes it at 0.5, so the language modelling term is counted at half the weight of the classification term. That one number is the whole tuning of how much stage one's objective persists into stage two.", "strength": "supporting", "id": "e080"}, {"source": "minimal-extra-parameters", "target": "per-task-parameter-cost", "type": "instance-of", "label": "this method's per-task cost", "explanation": "Per-task parameter cost is the quantity the paper uses to separate itself from feature-based transfer, where each new task brings a freshly initialized model on top. Here the cost is a specific, small amount: the matrix W_y plus embeddings for the delimiter tokens. That concrete figure is what gives the comparison its force.", "strength": "supporting", "id": "e081"}, {"source": "entailment-input-transformation", "target": "traversal-style-approach", "type": "instance-of", "label": "walking a premise-hypothesis pair", "explanation": "The traversal-style approach is the general strategy: flatten a structured input into one ordered token sequence rather than build an architecture shaped like the structure. Entailment is the simplest case of it, concatenating premise and hypothesis with a delimiter between them. The model sees one sequence and is never told there were two sentences.", "strength": "supporting", "id": "e082"}, {"source": "similarity-input-transformation", "target": "traversal-style-approach", "type": "instance-of", "label": "traversal with both orderings summed", "explanation": "For similarity there is no natural order to the two sentences, so a single traversal would impose one arbitrarily. The paper's case builds both orderings, runs each through the stack separately, and adds the two final activations element-wise before the linear layer. It is still the traversal strategy, applied twice and then pooled.", "strength": "supporting", "id": "e083"}, {"source": "qa-and-commonsense-input-transformation", "target": "traversal-style-approach", "type": "instance-of", "label": "one traversal per candidate answer", "explanation": "A document, a question and a set of candidate answers do not flatten into one sequence. The paper's case builds [z; q; $; a_k] once per candidate, processes each independently, and softmaxes the resulting scores across candidates. The variable-size structure is handled by running the fixed model several times rather than by changing it.", "strength": "supporting", "id": "e084"}, {"source": "cola-zero-shot-heuristic", "target": "average-token-log-probability-scoring", "type": "instance-of", "label": "thresholding a sentence's mean score", "explanation": "Three of the four zero-shot heuristics share one device: score a candidate string by the mean log-probability the language model assigns its tokens. For CoLA the whole heuristic is that score plus a threshold, and the prediction is whether the sentence is grammatical. No supervised layer is involved at all.", "strength": "supporting", "id": "e085"}, {"source": "race-zero-shot-heuristic", "target": "average-token-log-probability-scoring", "type": "instance-of", "label": "scoring candidate answers by likelihood", "explanation": "The same mean-log-probability device is applied to RACE by conditioning the model on the document and question, then scoring each candidate answer. The highest-scoring answer is the prediction. The multiple-choice structure is what makes a scoring rule enough to produce an answer.", "strength": "supporting", "id": "e086"}, {"source": "dprd-winograd-heuristic", "target": "average-token-log-probability-scoring", "type": "instance-of", "label": "scoring each pronoun substitution", "explanation": "For Winograd schemas the device is applied to the rest of the sentence after substituting each possible referent for the definite pronoun. Whichever substitution leaves the remainder scoring higher is taken as the resolution. This is the same scoring rule as CoLA and RACE, pointed at a different span of text.", "strength": "supporting", "id": "e087"}, {"source": "dprd-winograd-heuristic", "target": "coreference", "type": "instance-of", "label": "a coreference decision, scored", "explanation": "A Winograd schema asks which earlier noun a pronoun refers to, which is a coreference question in the narrowest possible form. The heuristic turns that question into a comparison between two rewritten sentences. It is the one zero-shot probe aimed directly at reference rather than at a task label.", "strength": "minor", "id": "e088"}, {"source": "coreference", "target": "long-range-dependencies-gpt1", "type": "instance-of", "label": "pronoun and antecedent far apart", "explanation": "Long-range dependencies are relationships spanning many tokens. Coreference is the concrete case the paper leans on: a pronoun and the name it stands for, which can sit sentences apart. It is the example that makes the 512-token window and the contiguous-text corpus matter.", "strength": "supporting", "id": "e089"}, {"source": "race-dataset", "target": "long-range-dependencies-gpt1", "type": "instance-of", "label": "question and the passage detail", "explanation": "RACE pairs an exam passage with questions about it, so answering means linking a question to a detail that may be far back in the document. That is the other concrete case of a long-range dependency the paper cares about. It is also why RACE was chosen over reading comprehension sets the paper says need less reasoning.", "strength": "supporting", "id": "e090"}, {"source": "twelve-attention-heads", "target": "masked-self-attention", "type": "instance-of", "label": "twelve heads of 64 dimensions", "explanation": "Masked self-attention is the mechanism; the head count is its concrete setting here. Each layer splits its 768-dimensional state across twelve heads, so each head attends in a 64-dimensional subspace. Twelve heads and twelve layers happen to match, but they are separate dials.", "strength": "minor", "id": "e091"}, {"source": "position-wise-feedforward-3072", "target": "multi-layer-transformer-decoder", "type": "instance-of", "label": "feed-forward width in this model", "explanation": "Each block in the stack ends with a position-wise feed-forward sublayer, and this is the size it was given. The layer expands each 768-dimensional vector to 3072 dimensions and projects it back, a four-fold widening. That is the concrete setting of a slot the general architecture leaves open.", "strength": "minor", "id": "e092"}, {"source": "residual-embedding-attention-dropout", "target": "dropout-gpt1", "type": "instance-of", "label": "dropout at three specific points", "explanation": "Dropout as an idea is assumed known; what the paper specifies is where and how hard. Rate 0.1 is applied at three points during pre-training: the residual branches, the embedding layer, and attention. Same mechanism, three placements, one rate.", "strength": "minor", "id": "e093"}, {"source": "classifier-dropout", "target": "dropout-gpt1", "type": "instance-of", "label": "dropout on the fine-tuning head", "explanation": "Fine-tuning adds one more placement of the same mechanism, at the task classifier, again at rate 0.1. It is the only regularizer the second stage adds; everything else is inherited from pre-training. The head is the newest and smallest part of the model, so it is the part most able to overfit a small labelled set.", "strength": "minor", "id": "e094"}, {"source": "fine-tuning-lr-and-batch", "target": "adam-optimizer-gpt1", "type": "instance-of", "label": "Adam re-tuned for stage two", "explanation": "Fine-tuning reuses the pre-training optimizer and changes its settings. The peak learning rate drops from 2.5e-4 to 6.25e-5, a factor of four smaller, and the batch size is 32. The smaller step is what keeps the pre-trained weights from being washed out in the three epochs the paper says are enough.", "strength": "supporting", "id": "e095"}, {"source": "token-level-perplexity", "target": "language-modeling-objective", "type": "instance-of", "label": "L1 read out as perplexity", "explanation": "Perplexity is the pre-training objective restated on a per-token scale, so 18.4 is a concrete value of how well L1 was fitted on BooksCorpus. The paper offers it as evidence that stage one actually learned the corpus. It says nothing on its own about whether the weights transfer, which is what the later sections are for.", "strength": "supporting", "id": "e096"}, {"source": "task-agnostic-model", "target": "task-specific-architectures", "type": "contrasts-with", "label": "one model versus bespoke networks", "explanation": "The paper's central comparison is between a single pre-trained stack applied everywhere and the prevailing practice of hand-designing a network around each task's structure. It claims the general model beats those discriminatively trained task-specific systems on 9 of the 12 datasets.", "strength": "load-bearing", "id": "e097"}, {"source": "task-specific-input-transformations", "target": "task-specific-architectures", "type": "contrasts-with", "label": "task work moved to the input", "explanation": "Both approaches accept that tasks differ; they disagree about where that difference is absorbed. Prior work adds task-shaped modules on top of transferred representations, which the paper says re-introduces customization that gets no benefit from transfer, whereas here the structured input is rewritten as one token sequence and the model is left alone.", "strength": "load-bearing", "id": "e098"}, {"source": "two-stage-training-procedure", "target": "feature-based-transfer", "type": "contrasts-with", "label": "fine-tune weights versus frozen features", "explanation": "Feature-based transfer keeps the pre-trained model fixed and feeds its hidden states into a separate task model as extra inputs. The paper instead carries the pre-trained weights themselves into the target task and keeps training them, which is the difference it draws with the closest competing line of work.", "strength": "load-bearing", "id": "e099"}, {"source": "minimal-extra-parameters", "target": "per-task-parameter-cost", "type": "contrasts-with", "label": "one matrix versus many new parameters", "explanation": "The paper measures the two transfer styles by how many freshly initialized parameters a new task needs. Feature-based methods bring a substantial number of new parameters per task; here the additions are the linear output layer and the delimiter token embeddings.", "strength": "load-bearing", "id": "e100"}, {"source": "elmo-deep-contextualized-word-representations", "target": "supervised-fine-tuning", "type": "contrasts-with", "label": "features added versus network adapted", "explanation": "ELMo supplies hidden states from a pre-trained bidirectional language model as extra features to a task model that is trained from scratch. Fine-tuning here does the opposite: no new task network, and every pre-trained weight is updated on the labelled data.", "strength": "supporting", "id": "e101"}, {"source": "masked-self-attention", "target": "elmo-deep-contextualized-word-representations", "type": "contrasts-with", "label": "left-to-right versus bidirectional pre-training", "explanation": "The pre-training objective here forces each position to attend only to itself and earlier tokens, because the model has to predict the next token. ELMo's pre-trained language model reads in both directions, so the two approaches give up different things: one gives up the right context, the other gives up a single stack that can be fine-tuned as-is.", "strength": "supporting", "id": "e102"}, {"source": "bookscorpus", "target": "one-billion-word-benchmark", "type": "contrasts-with", "label": "contiguous text versus shuffled sentences", "explanation": "The paper names 1B Word Benchmark, the corpus ELMo uses, as roughly the same size as BooksCorpus. The stated difference is that it is shuffled at the sentence level, which destroys the long-range structure the paper wants the language model to condition on.", "strength": "supporting", "id": "e103"}, {"source": "multi-layer-transformer-decoder", "target": "ablation-lstm-substitution", "type": "contrasts-with", "label": "transformer versus LSTM, same framework", "explanation": "The ablation keeps the whole recipe and swaps only the architecture for a single-layer 2048-unit LSTM. The average score falls by 5.6 points, which is the paper's own measurement of what the architecture choice buys.", "strength": "load-bearing", "id": "e104"}, {"source": "mrpc", "target": "ablation-lstm-substitution", "type": "contrasts-with", "label": "the one dataset LSTM wins", "explanation": "The LSTM ablation loses on average but beats the transformer on MRPC, the one dataset out of the set. The architecture claim is an average, not a sweep, and the paper reports the exception rather than hiding it.", "strength": "supporting", "id": "e105"}, {"source": "lstm-short-range-limitation", "target": "long-range-dependencies-gpt1", "type": "contrasts-with", "label": "local predictions versus distant structure", "explanation": "The paper argues that recurrent pre-trained models keep their predictions local, so the structure they can transfer is capped. Its claim for the transformer is the opposite: a more structured memory that reaches relationships spanning many tokens.", "strength": "supporting", "id": "e106"}, {"source": "context-window-512-tokens", "target": "lstm-short-range-limitation", "type": "contrasts-with", "label": "512 tokens against short range", "explanation": "The concrete form of the short-range argument is the size of the context each prediction may condition on. Here every prediction sees up to 512 contiguous preceding tokens, which is the counterpoint to the claim that LSTM pre-training stays local.", "strength": "minor", "id": "e107"}, {"source": "ablation-no-auxiliary-objective", "target": "auxiliary-lm-objective", "type": "contrasts-with", "label": "auxiliary loss helps some, hurts others", "explanation": "Dropping the language modelling loss during fine-tuning does not simply degrade the model. It helps on the NLI tasks and QQP and hurts elsewhere, with the paper reading the trend as larger datasets benefiting and smaller ones not. The design choice is conditional, not settled.", "strength": "load-bearing", "id": "e108"}, {"source": "auxiliary-objective-weight", "target": "ablation-no-auxiliary-objective", "type": "contrasts-with", "label": "one lambda, dataset-dependent effect", "explanation": "Lambda is fixed at 0.5 for every task. The ablation shows the auxiliary term's sign of effect changes with dataset size, so a single weight is being applied across cases where the evidence says it should differ.", "strength": "minor", "id": "e109"}, {"source": "auxiliary-lm-objective", "target": "supervised-objective-l2", "type": "contrasts-with", "label": "two losses competing during fine-tuning", "explanation": "Fine-tuning optimizes the sum of the label loss and the language modelling loss, so gradient capacity is split between predicting labels and predicting the next token. The weight of 0.5 is the paper's chosen balance between the two pulls.", "strength": "supporting", "id": "e110"}, {"source": "auxiliary-lm-objective", "target": "auxiliary-training-objectives", "type": "contrasts-with", "label": "auxiliary loss as branch versus supplement", "explanation": "Prior work treats an added unsupervised loss as the transfer mechanism itself. Here it is a secondary term on top of pre-training, and the paper says pre-training has already learned the linguistic aspects the auxiliary objective would otherwise supply.", "strength": "supporting", "id": "e111"}, {"source": "ablation-no-pretraining", "target": "ablation-lstm-substitution", "type": "contrasts-with", "label": "14.8 points versus 5.6 points", "explanation": "The two ablations rank the paper's two design choices against each other. Removing pre-training costs 14.8 across the board, while replacing the transformer costs 5.6 on average, so the data matters more than the architecture by roughly a factor of three.", "strength": "supporting", "id": "e112"}, {"source": "ablation-no-pretraining", "target": "generative-pretraining", "type": "contrasts-with", "label": "same transformer, no pre-training", "explanation": "Training the identical architecture directly on the supervised tasks isolates what stage one contributes. Performance drops on all tasks, by 14.8 compared with the full model, which is the paper's strongest single number for pre-training itself.", "strength": "load-bearing", "id": "e113"}, {"source": "rte", "target": "state-of-the-art-9-of-12", "type": "contrasts-with", "label": "the NLI dataset it loses", "explanation": "The headline is new best results on nine of twelve datasets, and RTE is one of the three misses. The model reaches 56% against 61.7% from a multi-task biLSTM, and the paper offers dataset size as the likely reason without testing it.", "strength": "supporting", "id": "e114"}, {"source": "rte", "target": "snli", "type": "contrasts-with", "label": "2490 examples versus 550k", "explanation": "These are the smallest and largest NLI datasets in the evaluation. The model gains 0.6% on SNLI and falls 5.7 points short of the previous best on RTE, so the claim of working across dataset sizes holds less well at the small end of NLI.", "strength": "supporting", "id": "e115"}, {"source": "sts-b", "target": "rte", "type": "contrasts-with", "label": "small datasets disagree with each other", "explanation": "Both are small, roughly 5.7k and 2490 training examples. STS-B gains a point over the previous best while RTE loses, so dataset size alone does not predict where fine-tuning succeeds.", "strength": "supporting", "id": "e116"}, {"source": "cola", "target": "sst-2", "type": "contrasts-with", "label": "large jump versus merely competitive", "explanation": "The two text classification tasks give different verdicts. CoLA rises to 45.4 from a previous best of 35.0, which the paper reads as evidence of learned linguistic bias, while SST-2 reaches 91.3% and only matches the state of the art.", "strength": "supporting", "id": "e117"}, {"source": "generative-pretraining", "target": "supervised-fine-tuning", "type": "contrasts-with", "label": "predict the text versus predict the label", "explanation": "The two stages train the same weights against opposite kinds of target. Stage one maximizes the probability of the next token over unlabelled text; stage two maximizes the probability of the correct label given the input.", "strength": "load-bearing", "id": "e118"}, {"source": "unsupervised-pretraining", "target": "auxiliary-training-objectives", "type": "contrasts-with", "label": "initialization versus modified objective", "explanation": "The related-work section splits semi-supervised learning into two branches. One uses unlabelled data only to choose where the weights start; the other leaves initialization alone and adds an unsupervised term to the supervised loss. The paper's recipe sits in the first branch and borrows from the second.", "strength": "supporting", "id": "e119"}, {"source": "word-embedding-transfer", "target": "generative-pretraining", "type": "contrasts-with", "label": "word-level versus whole-network transfer", "explanation": "Pre-trained word embeddings move one vector per word into the target model and nothing else. The paper wants what it calls higher-level semantics, so it transfers every layer of the pre-trained stack instead of only the lookup table.", "strength": "supporting", "id": "e120"}, {"source": "layers-transferred", "target": "word-embedding-transfer", "type": "contrasts-with", "label": "embeddings alone leave value behind", "explanation": "The layer-transfer analysis reproduces the standard result that transferring embeddings helps, then shows each additional transformer layer helps further, up to 9% on MultiNLI for full transfer. Stopping at the embedding table gives up most of that.", "strength": "supporting", "id": "e121"}, {"source": "decoder-only-stack", "target": "transformer-gpt1", "type": "contrasts-with", "label": "one stack, no encoder half", "explanation": "The original transformer pairs an encoder that sees a whole source with a decoder that generates. This model keeps only the decoder side, attending to its own past, because a language modelling objective has no separate source to encode.", "strength": "supporting", "id": "e122"}, {"source": "zero-shot-behaviors", "target": "supervised-fine-tuning", "type": "contrasts-with", "label": "heuristics with no labelled training", "explanation": "The zero-shot section runs the same evaluation tasks through the pre-trained model with hand-built scoring rules and no fine-tuning at all. It is a weaker way of getting answers, used as a diagnostic for how much task-relevant behaviour pre-training alone produces.", "strength": "supporting", "id": "e123"}, {"source": "transformer-inductive-bias", "target": "lstm-gpt1", "type": "contrasts-with", "label": "stable versus high-variance zero-shot", "explanation": "Tracked across pre-training, the transformer's zero-shot heuristics rise steadily while the LSTM shows higher variance in the same measurements. The paper reads that gap as an argument for the transformer's inductive bias, though it is a hypothesis stated from one comparison.", "strength": "supporting", "id": "e124"}, {"source": "fine-tuning-lr-and-batch", "target": "pre-training-optimization", "type": "contrasts-with", "label": "6.25e-5 against 2.5e-4 peak", "explanation": "Fine-tuning reuses the pre-training settings except for a learning rate about four times smaller, batch size 32 rather than 64, and three epochs rather than 100. The smaller steps reflect that the weights are already where the model wants them.", "strength": "minor", "id": "e125"}, {"source": "race-dataset", "target": "cnn-and-squad-contrast", "type": "contrasts-with", "label": "reasoning questions versus extraction", "explanation": "CNN and SQuAD appear only as a foil. The paper picks RACE because it has been shown to contain more reasoning-type questions than those datasets, which makes it the test it wants for a model trained on long contexts.", "strength": "supporting", "id": "e126"}, {"source": "similarity-input-transformation", "target": "entailment-input-transformation", "type": "contrasts-with", "label": "order matters, or it does not", "explanation": "Entailment has an inherent direction, so premise and hypothesis are concatenated once with a delimiter. Similarity has none, so both orderings are built and run separately and their final activations are added before the linear layer, at twice the compute per example.", "strength": "minor", "id": "e127"}, {"source": "choice-of-pretraining-objective", "target": "language-modeling-objective", "type": "contrasts-with", "label": "one objective among competing candidates", "explanation": "The introduction lists language modelling, machine translation and discourse coherence as candidate pre-training objectives, each ahead of the others on different tasks. The paper commits to language modelling and shows it works broadly here, but does not settle which objective transfers best.", "strength": "supporting", "id": "e128"}, {"source": "ulmfit", "target": "fine-tuning-hyperparameters", "type": "contrasts-with", "label": "staged schedule versus plain fine-tuning", "explanation": "ULMFiT adapts a pre-trained LSTM using a carefully staged schedule, which the paper groups with the intricate learning schemes it wants to avoid. Fine-tuning here is three epochs at a single learning rate with a short warmup and linear decay.", "strength": "minor", "id": "e129"}, {"source": "eq-task-head", "target": "baseline-comparisons", "type": "contrasts-with", "label": "one matrix against built architectures", "explanation": "The task head is a single matrix on the last token's activation, followed by a softmax. The systems it is measured against are mostly task-specific biLSTMs, sometimes with attention, ELMo features, or ensembling, and the paper reports beating ensembles in many cases.", "strength": "supporting", "id": "e130"}], "themes": [{"id": "theme-the-problem-and-the-open-questions", "name": "The Problem and the Open Questions", "summary": "The paper starts from an imbalance: raw text is plentiful, while labelled data for any particular language understanding task is small and costly to produce. It frames the diverse supervised tasks it cares about under one label, and asks whether one model trained on unlabelled text could serve them all. Two questions are left open at this point and the rest of the paper answers them: which unsupervised objective produces representations worth transferring, and how those representations should be moved into a target task. This sits first because every later choice is a response to one of these two questions.", "members": ["labeled-data-scarcity", "generative-vs-discriminative-training", "natural-language-understanding", "choice-of-pretraining-objective", "how-to-transfer-representations"], "order": 1, "kind": "concept-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 8]}}, {"id": "theme-where-this-sits-in-prior-work", "name": "Where This Sits in Prior Work", "summary": "The paper places itself inside semi-supervised learning for NLP and then separates that field into branches so it can say which one it is joining. One branch learns word, phrase or sentence vectors and hands them to a task model as features; another adds an unsupervised loss term alongside the supervised one; another uses unlabelled data only to choose the starting weights. The closest prior line pre-trains a recurrent language model and fine-tunes the whole network, and the paper argues that recurrence keeps such models' predictions short-range. Reading this before the method makes clear which existing pieces the paper keeps and which it is arguing against.", "members": ["semi-supervised-learning-for-nlp", "word-embedding-transfer", "phrase-and-sentence-embeddings", "unsupervised-pretraining", "pretraining-as-regularization", "auxiliary-training-objectives", "feature-based-transfer", "elmo-deep-contextualized-word-representations", "per-task-parameter-cost", "lm-pretraining-then-finetuning-predecessors", "semi-supervised-sequence-learning", "ulmfit", "lstm-short-range-limitation"], "order": 2, "kind": "concept-theme", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "theme-one-model-two-stages", "name": "One Model, Two Stages", "summary": "The recipe in outline: train a network to predict next tokens on a large unlabelled corpus, then take those same weights as the starting point for supervised training on a target task. Nothing is frozen and no task-specific network is built on top, so the same architecture is what gets fine-tuned every time. The paper also states that the unlabelled corpus need not come from the target task's domain. This chapter is the hinge between the problem and the machinery, and the two stages that follow are its halves.", "members": ["two-stage-training-procedure", "transfer-learning", "domain-mismatch-tolerance", "task-agnostic-model", "task-specific-architectures"], "order": 3, "kind": "concept-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 7, 8]}}, {"id": "theme-stage-one-next-token-prediction", "name": "Stage One: Predicting the Next Token", "summary": "Stage one trains on a single loss: the log-probability the model assigns each token given a window of preceding tokens, summed over the corpus. The window here is 512 contiguous tokens, which is what lets a prediction condition on material several sentences back. The network is a stack of transformer blocks used as a decoder alone, with self-attention masked so each position sees only itself and its past, learned position vectors rather than fixed sinusoids, and an output layer that reuses the token embedding matrix transposed. This chapter also fixes the exact sizes trained, and closes with the claim the paper makes about what such training leaves behind.", "members": ["generative-pretraining", "language-modeling-objective", "context-window-512-tokens", "long-range-dependencies-gpt1", "multi-layer-transformer-decoder", "decoder-only-stack", "masked-self-attention", "input-representation-h0", "token-embedding-matrix", "learned-position-embeddings", "output-softmax-tied-embeddings", "model-specification", "twelve-layer-depth", "hidden-state-dimension-768", "twelve-attention-heads", "position-wise-feedforward-3072", "gelu", "weight-initialization", "world-knowledge"], "order": 4, "kind": "concept-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "theme-corpus-tokens-and-training-setup", "name": "Corpus, Tokens and Training Setup", "summary": "The corpus is over 7,000 unpublished books, chosen because the text stays in its original order across sentences and paragraphs; the paper contrasts it with a same-sized benchmark that is shuffled sentence by sentence. Raw text is cleaned, tokenized, then cut into subword units by byte-pair encoding with 40,000 merges. Training uses Adam with a learning rate warmed up over 2000 updates and then annealed on a cosine curve, for 100 passes over the corpus, with dropout and a decoupled weight decay. The reported perplexity of 18.4 is offered as evidence the model fit the corpus, not as a result about any task; it sits here rather than in the results chapter for that reason.", "members": ["bookscorpus", "long-range-contiguous-text", "one-billion-word-benchmark", "text-preprocessing-pipeline", "ftfy", "spacy-tokenizer", "byte-pair-encoding-gpt1", "bpe-merges-40000", "pre-training-optimization", "adam-optimizer-gpt1", "linear-warmup", "cosine-annealing", "pretraining-schedule", "regularization-setup", "residual-embedding-attention-dropout", "decoupled-weight-decay", "token-level-perplexity"], "order": 5, "kind": "concept-theme", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [3, 4, 5, 8]}}, {"id": "theme-stage-two-fine-tuning-and-input-shapes", "name": "Stage Two: Fine-Tuning and Reshaping Task Inputs", "summary": "Stage two runs a labelled input through the pre-trained stack, takes the final block's activation at the last token, and multiplies it by one added matrix to score labels. The language modelling loss is not dropped: it keeps being optimized alongside the task loss, scaled by a weight the paper sets to 0.5. Tasks whose inputs have several parts are handled by writing those parts into one ordered sequence with a start token, an end token and a delimiter between parts, rather than by building an architecture that mirrors the structure. The chapter ends with the settings actually used, which are the pre-training settings with a smaller learning rate and three passes over the task data.", "members": ["supervised-fine-tuning", "labeled-dataset-c", "final-token-activation", "linear-output-layer-wy", "supervised-objective-l2", "minimal-extra-parameters", "auxiliary-lm-objective", "auxiliary-objective-weight", "task-specific-input-transformations", "structured-inputs", "traversal-style-approach", "start-and-end-tokens", "delimiter-token", "entailment-input-transformation", "similarity-input-transformation", "qa-and-commonsense-input-transformation", "fine-tuning-hyperparameters", "fine-tuning-lr-and-batch", "three-epochs-fine-tuning", "fine-tuning-lr-schedule", "classifier-dropout"], "order": 6, "kind": "concept-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "theme-what-the-twelve-datasets-show", "name": "What the Twelve Datasets Show", "summary": "The same fine-tuned model is measured on four families of tasks across twelve datasets: inference, reading and commonsense reasoning, sentence similarity, and single-sentence classification. Gains are reported as differences in percentage points against the previous best published number, mostly task-built recurrent systems, some of them ensembles or using ELMo features. The headline is new best results on nine of the twelve; this chapter also names the three where that does not happen, including the smallest inference dataset. It comes after the method because it is the method's only test, and before the analysis because the analysis asks why these numbers came out this way.", "members": ["evaluation-task-families", "glue-benchmark", "baseline-comparisons", "absolute-improvement", "natural-language-inference", "coreference", "snli", "multinli", "qnli", "scitail", "rte", "question-answering-and-commonsense-reasoning", "race-dataset", "cnn-and-squad-contrast", "story-cloze-test", "semantic-similarity", "mrpc", "qqp", "sts-b", "text-classification", "cola", "sst-2", "state-of-the-art-9-of-12"], "order": 7, "kind": "concept-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "theme-taking-the-recipe-apart", "name": "Taking the Recipe Apart", "summary": "Three diagnostics ask which parts of the recipe are doing the work. Transferring more pre-trained layers keeps helping rather than saturating early, and hand-built heuristics show the pre-trained model already doing several tasks at some level with no supervised training at all, improving steadily as pre-training runs. The removals are blunter: no pre-training costs the most, swapping the transformer for an LSTM costs less, and dropping the auxiliary language modelling loss helps on some datasets and hurts on others. The paper's reading of why attention transfers better than recurrence is stated as a hypothesis, and the zero-shot heuristics are hand-designed, so both carry less weight than the ablation numbers.", "members": ["layers-transferred", "zero-shot-behaviors", "average-token-log-probability-scoring", "cola-zero-shot-heuristic", "sst2-zero-shot-heuristic", "race-zero-shot-heuristic", "dprd-winograd-heuristic", "transformer-inductive-bias", "ablation-studies", "ablation-no-pretraining", "ablation-lstm-substitution", "ablation-no-auxiliary-objective"], "order": 8, "kind": "concept-theme", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 7, 8]}}, {"id": "etheme-scarce-labels-borrowed-weights", "name": "Scarce Labels, Borrowed Weights", "summary": "The paper opens on a mismatch: unlabelled text is abundant, while the labelled dataset for any one language understanding task is small and expensive to build. Its answer is the two-stage training procedure — fit a language model on raw text, then keep those weights and adapt the same network with labels — and it presents that recipe as one entry in semi-supervised learning for NLP, specifically the branch where unlabelled data chooses a starting point for the weights rather than adding a term to the supervised loss. The stance is drawn by contrast: feature-based transfer, and ELMo in particular, freezes a pre-trained model and feeds its hidden states into a separately built task model, whereas here the whole network is adjusted; word-embedding transfer moves one vector per word, whereas here every layer moves. Stage one and stage two also predict different things — the next token of the text against the label of the example — which is why the fine-tuning settings back off rather than restart: a learning rate of 6.25e-5 against the pre-training peak of 2.5e-4, batch size 32, and three passes over the task's training set on the assumption that most of the work is already done.", "members": ["e001", "e002", "e064", "e065", "e066", "e099", "e101", "e118", "e119", "e120", "e023", "e024", "e094", "e095", "e125", "e129"], "order": 1, "kind": "edge-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "etheme-the-next-token-machine", "name": "The Next-Token Machine", "summary": "Stage one is one loss and one network, and the paper writes both down. The loss, $L_1$ in Equation 1, is the summed log-probability the model assigns to each token given the $k$ tokens before it, which is ordinary maximum-likelihood fitting applied to text; the paper treats picking this objective as a choice among candidates, since which unsupervised objective transfers best was one of the open questions it names. The network is a stack of transformer blocks used as a decoder only, with the encoder half of the original encoder-decoder design dropped, and its self-attention masked so that each position sees only itself and earlier positions — that masking is what makes next-token prediction a well-posed target instead of a lookup. Equation 2 gives the rest in three lines: the layer-zero input is token embeddings plus a trained table of position embeddings, one vector per slot; $n$ identical blocks run over it; the top states are multiplied by the transpose of the same token embedding matrix and softmaxed into a distribution over the vocabulary, so input and output layers share parameters. The concrete model fills in the sizes — twelve heads splitting 768 dimensions into 64 each, a feed-forward sublayer widening to 3072 and back, weights drawn from $\\mathcal{N}(0, 0.02)$ on the argument that layer normalization throughout makes a plain initialization enough, and dropout at 0.1 on residual branches, embeddings and attention.", "members": ["e003", "e004", "e006", "e007", "e008", "e012", "e013", "e014", "e015", "e030", "e036", "e037", "e038", "e068", "e069", "e071", "e072", "e075", "e076", "e091", "e092", "e093", "e102", "e122", "e128"], "order": 2, "kind": "edge-theme", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "etheme-the-long-range-bet", "name": "The Bet on Long Stretches of Text", "summary": "The corpus is chosen as an argument, not a convenience. BooksCorpus is over 7,000 unpublished books, and what the paper wants from it is long stretches of contiguous text — sentences left in their original order across paragraphs — which it sets against the 1B Word Benchmark, a corpus of roughly the same size but shuffled at the sentence level. The context window follows: $k$ is fixed at 512 tokens, which only means something if the training text actually runs that long without breaking, and 512 tokens is the counter to the paper's complaint that recurrent pre-training keeps its predictions local and so transfers less structure. The dependencies this is meant to capture are named concretely — a pronoun and the antecedent it refers to several sentences back, or a RACE exam question and the passage detail that answers it, RACE being chosen over CNN and SQuAD on the grounds that it asks for reasoning rather than extraction. The evidence for the corpus choice stays indirect: the paper reports a token-level perplexity of 18.4 to show the model fit BooksCorpus, and points at the RACE and Story Cloze results as a proxy, but it never runs the comparison against a shuffled corpus that would test the claim directly.", "members": ["e005", "e009", "e010", "e011", "e052", "e053", "e063", "e073", "e074", "e089", "e090", "e096", "e103", "e106", "e107", "e126"], "order": 3, "kind": "edge-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "etheme-one-stack-any-input-shape", "name": "One Stack, Any Input Shape", "summary": "A pre-trained decoder reads one ordered sequence of tokens, but the evaluation tasks hand over premise-hypothesis pairs and document-question-answer triplets. The paper's move is to change the input rather than the model: each structured input is walked into a single sequence, bracketed by a start and an end token and split by a `$` delimiter, so entailment becomes premise-delimiter-hypothesis, similarity is built in both orderings and processed twice, and multiple choice becomes one sequence per candidate answer. What sits on top is Equation 3 and nothing else — take the final block's activation at the last token and multiply it by one matrix $W_y$ to get label scores, with Equation 4 stating the summed log-probability of the correct labels as the objective. Two properties follow from this and are the point of the design: the same architecture serves every task, against the prevailing practice of hand-designing a network around each task's structure, and the per-task parameter cost is one matrix plus embeddings for the delimiter tokens, against transfer styles that initialize a fresh task model each time. The last-token readout is also why the similarity transformation exists at all — the readout is order-sensitive, so both orderings are summed element-wise before the head, where entailment simply keeps its one order.", "members": ["e016", "e017", "e019", "e020", "e021", "e039", "e040", "e041", "e044", "e045", "e046", "e070", "e077", "e078", "e079", "e081", "e082", "e083", "e084", "e097", "e098", "e100", "e127", "e130"], "order": 4, "kind": "edge-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "etheme-two-losses-and-three-removals", "name": "Two Losses, and Three Things Taken Away", "summary": "Fine-tuning here optimizes two objectives at once: the task loss $L_2$ and the original language modelling loss kept alive on the labelled data, combined as $L_3 = L_2 + \\lambda L_1$ with $\\lambda$ set to 0.5. This is the same auxiliary-objective idea the related work describes as a branch of semi-supervised learning, used here as a supplement to pre-training rather than as a replacement for it, and it puts two losses in competition over the same weights — the language modelling head survives from stage one because the output layer reuses the token embeddings. Table 5 tests it by removal alongside two other removals, and the auxiliary term is the one whose effect is not uniform: it helps on the larger datasets and hurts on the smaller ones, with one $\\lambda$ across the board. The other two removals are larger and cleaner. Training the same transformer directly on the supervised tasks, with no pre-training, costs 14.8 percent across the board; swapping the transformer for a single-layer 2048-unit LSTM inside the identical framework — a swap the shared input-transformation scheme makes possible — costs 5.6 average points, with MRPC the single dataset where the LSTM comes out ahead. Fourteen-point-eight against five-point-six is the paper's own ordering of what matters: the pre-training, then the architecture.", "members": ["e018", "e022", "e031", "e032", "e033", "e034", "e035", "e042", "e043", "e067", "e080", "e104", "e105", "e108", "e109", "e110", "e111", "e112", "e113"], "order": 5, "kind": "edge-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "etheme-the-scoreboard-and-its-gaps", "name": "The Scoreboard and Its Gaps", "summary": "The evaluation is twelve datasets across four families — natural language inference, question answering and commonsense reasoning, semantic similarity, and text classification — and the headline is new best published results on nine of them, reported as absolute percentage-point differences against the previous best. On inference the fine-tuned model leads task-built baselines on four of five datasets; on the reading-and-reasoning benchmarks it gains 8.9 on Story Cloze and 5.7 on RACE over every previously published system; on the remaining GLUE tasks it takes CoLA, STS-B and QQP, with an overall GLUE score of 72.8 against 68.9. CoLA is the largest single jump, 45.4 against a previous best of 35.0, and SST-2 sits beside it as the contrast — 91.3 percent is competitive but does not beat the state of the art. The gaps are where the general claim thins: RTE is the one inference dataset it loses and one of the three it misses overall, and RTE has 2490 training examples against SNLI's roughly 550k, which invites the small-data explanation — except that STS-B, smaller still at about 5.7k, is one of the wins.", "members": ["e047", "e048", "e049", "e050", "e051", "e054", "e055", "e056", "e057", "e114", "e115", "e116", "e117"], "order": 6, "kind": "edge-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "etheme-watching-pre-training-work", "name": "Watching Pre-Training Do the Work", "summary": "Two diagnostics in Figure 2 try to say why the recipe works, rather than that it works. The first varies how many pre-trained layers are carried into fine-tuning, a sweep that only exists because the stack is twelve blocks deep, and finds each transferred layer adding performance, up to 9 percent on MultiNLI for the full transfer — which is the paper's case that moving embeddings alone leaves value in the upper layers. The second runs the pre-trained model on the tasks with no labelled training at all, using heuristics built on one device: score a candidate string by the mean log-probability the language model assigns its tokens, which is the training quantity read back out. That device carries CoLA by thresholding a sentence's mean score, RACE by ranking candidate answers, and the Winograd-style DPRD set by substituting each referent for the pronoun and keeping the higher-scoring resolution, a coreference decision made by scoring; SST-2 works differently, appending 'very' and restricting the output distribution to two words. These heuristic scores rise steadily over pre-training, which the paper reads as task ability accumulating without supervision, and it adds the hypothesis that the transformer's attention gives a more structured memory than an LSTM, pointing at the LSTM's higher zero-shot variance as support. Two claims run ahead of the diagnostic: the inductive-bias hypothesis rests on a variance comparison, and the conclusion's talk of world knowledge acquired from predicting text is broader than the curves shown.", "members": ["e025", "e026", "e027", "e028", "e029", "e058", "e059", "e060", "e061", "e062", "e085", "e086", "e087", "e088", "e121", "e123", "e124"], "order": 7, "kind": "edge-theme", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "pages": [{"id": "page-theme-the-problem-and-the-open-questions", "forId": "theme-the-problem-and-the-open-questions", "kind": "theme", "body": "What should you do when the text you have is not the text you need? The paper opens on that mismatch: unlabelled text exists in enormous quantity, while the labelled examples for any single language understanding task are few and expensive to produce.\n\n### The imbalance, and why it bites\n\n[[natural-language-understanding]] is not one task in this paper. It is an umbrella over a set of supervised problems — textual entailment, question answering, [[semantic-similarity]], document classification — that share an input type and little else. Each comes with its own dataset, its own labels, its own notion of a correct answer. [[table-1]] lays out the twelve datasets the paper will eventually use.\n\nGrouping them under one name is what makes a single-model claim sayable at all. If these are separate problems, one model per problem is the natural answer.\n\nInside that group sits the actual constraint, [[labeled-data-scarcity]]. The annotated sets are small: [[rte]], one of the twelve, has 2,490 training examples. Annotation is slow and costly, so the small ones stay small.\n\nScarcity hurts a particular kind of model hardest. A discriminatively trained network learns $P(y \\mid x)$, so its only teacher is the label attached to each input; with 2,490 labels there are 2,490 supervision events. A generative model predicts the data itself, so every token in a corpus is a supervision event. That contrast is [[generative-vs-discriminative-training]], and it is why unlabelled text looks like an unused resource rather than a different problem.\n\nThe paper grants that this is already established at the word level. [[word-embedding-transfer|Pre-trained word embeddings]] are named as the most compelling existing evidence that unlabelled text helps supervised tasks. The open ground is everything above the word.\n\n### The two things nobody had settled\n\nMoving beyond word-level information was hard for two reasons, and the introduction states them as two questions rather than two difficulties.\n\nThe first is [[choice-of-pretraining-objective]]. Language modelling, machine translation and discourse coherence had all been tried as unsupervised objectives, and each came out ahead on some tasks and behind on others. There was no ordering to appeal to.\n\nThe second is [[how-to-transfer-representations]]. Even granting a good pre-trained representation, prior work moved it into a target task by some mixture of task-specific architecture changes, staged learning schedules, and extra auxiliary losses. No single recipe was standard.\n\nThese two questions are not independent of the scarcity problem — they are what stands between the abundance of raw text and the shortage of labels. That is the sense in which the paper's [[two-stage-training-procedure|two-stage recipe]] presupposes scarcity: without it there would be no reason to pay for a pre-training stage at all.\n\n### What the rest of the paper is doing\n\nEvery later choice answers one of the two. [[language-modeling-objective|The language modelling loss $L_1$]] is the answer to the first question, chosen rather than derived. [[supervised-fine-tuning]] with [[task-specific-input-transformations|input transformations]] is the answer to the second: keep the architecture fixed and reshape the task input instead. Together they support the claim of a [[task-agnostic-model]].\n\nThe scarcity framing is also testable, and the paper tests it. [[ablation-no-pretraining|Removing pre-training entirely]] costs 14.8% across the tasks in [[table-5]], which is the largest of the three ablations.\n\nRead on with one question in hand for each design decision that follows: is this answering *which objective*, or *how to transfer*? The immediate next step is where the paper places itself among existing [[semi-supervised-learning-for-nlp|semi-supervised methods]], and which of them it says it is closest to.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-theme-where-this-sits-in-prior-work", "forId": "theme-where-this-sits-in-prior-work", "kind": "theme", "body": "Using unlabelled text to help a supervised task was not new when this paper was written. So the related work section has one job: name the family the method belongs to, cut it into branches, and say which branch it joins and which it argues against.\n\nThe family is [[semi-supervised-learning-for-nlp]]: a large unlabelled corpus plus a small labelled dataset. The earliest members computed word- and phrase-level counts from raw text and passed them to a supervised model as features.\n\nThe best-known member is [[word-embedding-transfer]]. Train one vector per word on unlabelled text, then reuse that table inside a task model. The paper grants this works, and then names its ceiling: what moves across is word-level information, and the paper wants higher-level semantics.\n\n[[phrase-and-sentence-embeddings]] is the direct response to that ceiling — learn a vector for a whole phrase or sentence instead of a word. The pattern is still the same, though. Something fixed is handed to a task model that is otherwise trained from scratch.\n\n### Two branches, split by what the unlabelled data changes\n\nAt this point the section splits the field on a single question: what does unlabelled data get to touch?\n\n[[unsupervised-pretraining]] lets it choose only where the weights start. The supervised objective is left exactly as it was. [[auxiliary-training-objectives]] does the reverse: initialization stays ordinary, and a second unsupervised loss is added alongside the supervised one, so the model keeps learning from raw text while it learns the task.\n\nThe paper's recipe sits in the first branch and then borrows from the second — it keeps a language modelling loss running during fine-tuning, weighted by $\\lambda$ ([[eq-combined-objective]]). The two branches are presented as alternatives, but the paper takes from both.\n\nInitialization is worth arguing about at all because of [[pretraining-as-regularization]]: the cited finding that pre-training does not merely make optimization easier, it lands the network somewhere that generalizes better.\n\n### Inside the pre-training branch, two ways to spend the weights\n\nOnce you have a pre-trained network, you still have to decide what to do with it.\n\n[[feature-based-transfer]] freezes it. Its hidden states become extra input features for a separate model that was designed around the target task. [[elmo-deep-contextualized-word-representations|ELMo]] is the best-known instance, and several of the baselines the paper measures against are task-built biLSTMs using exactly those features ([[table-2]], [[table-4]]).\n\nThe paper's objection is a count, not a score: [[per-task-parameter-cost]]. Every new task brings a substantial block of freshly initialized parameters, because the task model itself is new. That is the number [[minimal-extra-parameters|the paper's own transfer step]] is set up to contrast with.\n\nThe other way is [[lm-pretraining-then-finetuning-predecessors]], which the paper calls the closest line to its own: pre-train with a language modelling objective, then fine-tune the whole network. [[semi-supervised-sequence-learning]] and [[ulmfit]] both do this for [[text-classification]].\n\nHere the paper agrees with the shape and disagrees about the network. Its argument is [[lstm-short-range-limitation]]: recurrent pre-trained models keep their predictions local, so less structure survives the transfer. This is stated as a reason for a design choice, and the supporting evidence is indirect — the zero-shot curves in [[fig-2]] rise more smoothly for the transformer than for an LSTM, which is not a direct measurement of dependency length.\n\nYou should now be able to read [[two-stage-training-procedure]] and say, for each piece of it, which prior branch it keeps and which one it is answering.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-theme-one-model-two-stages", "forId": "theme-one-model-two-stages", "kind": "theme", "body": "Raw text is everywhere; labelled examples for any one language understanding task are few and expensive ([[labeled-data-scarcity]]). So what is the least you can change about ordinary supervised training to make all that unlabelled text count?\n\nThe paper's answer is that the raw text should decide *where supervised training starts*, not what it optimizes. That is the [[two-stage-training-procedure]], and everything else in the paper is a consequence of taking it seriously.\n\n### The same weights, used twice\n\nStage one fits a network to predict the next token over a large unlabelled corpus ([[generative-pretraining]]). Stage two takes those finished parameters and continues training them on a target task's labelled data with that task's own loss ([[supervised-fine-tuning]]).\n\nThe load-bearing word is *initial*. The pre-trained weights are a starting point, and from there they keep moving under the supervised gradient.\n\nThat is what [[transfer-learning]] means here, and it is a specific choice rather than the obvious one. The alternative on offer at the time was [[feature-based-transfer]]: freeze the pre-trained model, read out its hidden states, and feed them as extra inputs to a separate network built for the task. Under that arrangement the task network's parameters are all freshly initialized, so the transferred model helps only as a feature extractor.\n\nFine-tuning the whole stack instead means the new parameters per task are close to none. Placing the recipe this way puts it inside [[semi-supervised-learning-for-nlp]] — unlabelled data changing the initialization rather than the objective.\n\nOne more assumption rides along. The introduction states the target tasks need not come from the same domain as the unlabelled corpus ([[domain-mismatch-tolerance]]). The paper asserts this rather than testing it directly; what stands behind it is that twelve datasets, none of them books, are all fine-tuned from one book-trained model.\n\n### One stack, not twelve\n\nIf nothing is frozen and nothing substantial is added, the network you fine-tune is the network you pre-trained. That is the [[task-agnostic-model]] claim: one architecture, pre-trained once, applied to every task without redesign. The stack in question is a [[multi-layer-transformer-decoder]].\n\nThe contrast is with [[task-specific-architectures]], the prevailing practice of hand-designing a network around each task's structure. The paper's objection is not that such networks perform badly. It is that their custom components start from scratch, so the transferred representation never reaches them.\n\nSomething still has to absorb the fact that entailment takes a sentence pair and question answering takes a document, a question and a list of candidates. The paper moves that work out of the architecture and into the input format, via [[task-specific-input-transformations]] — [[structured-inputs]] walked into one token sequence with special tokens marking the seams. [[fig-1]] draws both halves of that split: one repeated block on the left, four input shapes on the right.\n\n### What the evidence carries\n\nThe ablation in [[table-5]] is the sharpest support for stage one: the same transformer trained directly on the supervised tasks, with no pre-training, loses 14.8 points on average. The one-model claim rests on the scoreboards — [[table-2]], [[table-3]] and [[table-4]] — which give new best published results on nine of twelve datasets.\n\nThey also record where it does not win. RTE, SST-2 and [[mrpc]] go to specialist systems, and the smallest datasets are where the general model looks weakest.\n\nFrom here you can read either stage on its own terms and know what it is for: what stage one's objective is and why the corpus was chosen, then how stage two adds almost nothing to the network. The question worth carrying into both is which parts of the recipe the ablations actually isolate.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-theme-stage-one-next-token-prediction", "forId": "theme-stage-one-next-token-prediction", "kind": "theme", "body": "Stage one has no labels, so the first question is what to train on at all. The paper takes the signal that raw text already carries: given the tokens so far, predict the one that comes next. What [[generative-pretraining|stage one]] keeps at the end is not those predictions but the weights that learned to make them.\n\nThat signal is written as [[language-modeling-objective|$L_1$]], set out in [[eq-lm-objective]]. Over an unlabelled corpus, sum the log-probability the network gives each token conditioned on the $k$ tokens immediately before it, and move the parameters $\\Theta$ to make that sum larger. This is ordinary [[maximum-likelihood-training]], with one term per token position and nothing task-specific anywhere in it.\n\nThe size of $k$ is where the objective starts making demands. Here it is [[context-window-512-tokens|512 tokens]], which is long enough that a prediction can reach back past the current sentence. That reach is the point: the paper wants the model to pick up [[long-range-dependencies-gpt1|long-range dependencies]], the pronoun whose antecedent sat three sentences earlier, or the passage detail that answers a question asked later. The corpus was chosen to supply them, which is the argument made on the [[bookscorpus]] page.\n\n### What the loss forces the architecture to be\n\n$L_1$ is scored at every position of a sequence at once, so one forward pass over 512 tokens has to produce 512 separate predictions. That only works if no position can see its own answer. [[masked-self-attention]] enforces it: a position attends to itself and to earlier positions, never to later ones. Drop the mask and the objective becomes copying rather than prediction.\n\nMasking is also why the encoder is not needed. There is no source sequence to read, only the model's own past, so the paper keeps a [[decoder-only-stack]] and discards the other half of the original encoder-decoder design. The result is the [[multi-layer-transformer-decoder]], and [[eq-decoder-stack]] writes it out in three lines.\n\nLine one is [[input-representation-h0|$h_0 = UW_e + W_p$]]. Attention sees an unordered set of vectors, so order has to be added at the input. [[token-embedding-matrix|$W_e$]] supplies the token vectors and [[learned-position-embeddings|$W_p$]] adds one trained vector per slot, in place of the original transformer's fixed sinusoids. A trained table has a fixed number of rows, which is why 512 is a shape in the parameters rather than a knob you can turn at test time.\n\nLine three closes the loop: [[output-softmax-tied-embeddings|$P(u) = \\mathrm{softmax}(h_n W_e^T)$]]. No separate output projection is introduced. The same embedding table is read forwards on the way in and backwards on the way out.\n\n### The sizes actually trained\n\n[[model-specification|The trained model]] fills in every slot the architecture leaves open. It is [[twelve-layer-depth|twelve blocks]] deep with [[hidden-state-dimension-768|768-dimensional states]]. The [[twelve-attention-heads|twelve heads]] do not each get 768 dimensions; they divide it, so 768 over 12 leaves each head a 64-dimensional subspace. The feed-forward sublayer widens 768 to [[position-wise-feedforward-3072|3072]] and projects back, a four-fold expansion. [[gelu|GELU]] replaces ReLU, [[layer-normalization-gpt1|layernorm]] runs throughout, and the paper says layernorm is why plain [[weight-initialization|$\\mathcal{N}(0, 0.02)$]] initialization was enough.\n\nThe architecture choice is not free-floating. [[table-5]] reports that swapping the transformer for an LSTM inside the same framework costs 5.6 average points.\n\nWhat does all this prediction leave behind? The conclusion claims [[world-knowledge|world knowledge]] and an ability to handle long-range structure. That claim is inferred rather than measured directly, from downstream gains and from the zero-shot curves in [[fig-2]], so read it as the paper's interpretation.\n\nYou can now ask the sharper question the next stage answers: these weights were fitted to predict text, so what has to change for them to predict a label instead? That is [[supervised-fine-tuning]].", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "page-theme-corpus-tokens-and-training-setup", "forId": "theme-corpus-tokens-and-training-setup", "kind": "theme", "body": "The pre-training objective [[eq-lm-objective]] says what to maximize. It does not say what text to maximize it over, how that text becomes tokens, or what optimizer turns the sum into a fitted model. This chapter covers those three choices, in that order.\n\n### Why these books\n\nThe corpus is [[bookscorpus]], over 7,000 unpublished books across genres. The reason the paper gives is not size. It is [[long-range-contiguous-text]]: sentences and paragraphs are kept in the order the author wrote them.\n\nThat property is load-bearing because of the window. A prediction conditions on the [[context-window-512-tokens]] before it. If the text a few hundred tokens back has nothing to do with the current token, the cheapest way to lower the loss is to ignore it and model the current sentence only.\n\nContiguous text is what gives the gradient a reason to reach further back. This is the corpus being picked for [[long-range-dependencies-gpt1]] rather than for volume.\n\nThe paper makes the point by contrast. It names [[one-billion-word-benchmark]], the corpus ELMo pre-trains on, as roughly the same size but shuffled at the sentence level, which it says destroys long-range structure. Worth being plain here: this is an argument about the data, not an experiment. The paper does not pre-train on both corpora and compare.\n\n### From raw text to subword units\n\nThe [[text-preprocessing-pipeline]] is three steps. [[ftfy]] repairs mangled characters and standardizes some punctuation and whitespace. [[spacy-tokenizer]] splits the cleaned text into words. Then [[byte-pair-encoding-gpt1]] cuts those words into subword units.\n\nBPE builds its vocabulary by counting. Start with characters, find the adjacent pair that occurs most often across the corpus, and fuse it into one symbol. Repeat, each merge adding one entry to the vocabulary.\n\nRun it [[bpe-merges-40000|40,000 times]] and frequent words have been merged all the way back into single symbols, while a rare proper noun from one book stays in pieces. Nothing is out of vocabulary, because the character level is always underneath. The merge count is the one knob: fewer merges means smaller vocabulary and longer token sequences, more merges the reverse.\n\n### Fitting the model\n\nThe [[pre-training-optimization]] settings are conventional and interlock. [[adam-optimizer-gpt1]] runs at a maximum learning rate of 2.5e-4, but training does not start there. [[linear-warmup]] raises the rate from zero across the first 2000 updates, so the steps stay small while Adam's per-parameter moment estimates are still built from very few gradients. [[cosine-annealing]] then brings the rate back down to zero over the rest of the run.\n\n\"The rest of the run\" has to be a known quantity for a cosine to be defined over it, which is what [[pretraining-schedule]] fixes: 100 passes over the corpus, minibatches of 64 contiguous 512-token sequences.\n\nThe [[regularization-setup]] has the same dependence. [[residual-embedding-attention-dropout]] is ordinary. [[decoupled-weight-decay]] is chosen because of the optimizer: L2 added into the loss becomes a gradient term that Adam then rescales per parameter, so weights with small gradient history get pulled toward zero harder than weights with large history. The modified version applies the decay outside that rescaling, at $w = 0.01$, on everything except biases and gains.\n\nThe reported outcome is a [[token-level-perplexity]] of 18.4. Perplexity is the exponentiated mean negative log-likelihood per token, so 18.4 says the model is about as uncertain as a uniform choice among eighteen options. It is measured on the training corpus, under this tokenization, so it does not compare to perplexities quoted elsewhere. The paper offers it as evidence that stage one fit the data, not as a result about any task.\n\nFrom here you can ask which of these choices the paper actually tests. [[fig-2]] probes the model rather than the recipe, and the settings themselves reappear almost unchanged in [[fine-tuning-hyperparameters]].", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "page-theme-stage-two-fine-tuning-and-input-shapes", "forId": "theme-stage-two-fine-tuning-and-input-shapes", "kind": "theme", "body": "Stage one produced a stack of weights that predicts the next token. Stage two asks how to turn those weights into something that predicts a label — and how to do that the same way for every task, rather than once per task.\n\n[[supervised-fine-tuning|Fine-tuning]] assumes a [[labeled-dataset-c|labelled dataset $C$]]: token sequences, each paired with one label. A sequence is pushed through the [[generative-pretraining|pre-trained]] stack exactly as a pre-training sequence would be. What changes is what gets read off the top.\n\nThe paper takes [[final-token-activation|the final block's activation at the last input token]] — one vector — and uses nothing else from the sequence. That collapse is what lets the classifier stay small. [[linear-output-layer-wy|One added matrix $W_y$]] multiplies the vector, and a softmax turns the product into a distribution over the task's labels; [[eq-task-head]] is the entire head. Had the head needed to read every position, it could not have been a single matrix.\n\nTraining it maximizes [[supervised-objective-l2|$L_2$]], the summed log-probability of the correct labels over $C$ ([[eq-supervised-objective]]). That is ordinary maximum-likelihood classification. The only thing separating one task from another is which $C$ you plug in.\n\n### The language modelling loss stays on\n\nThe paper does not drop $L_1$ when fine-tuning starts. It keeps [[auxiliary-lm-objective|optimizing it alongside the label loss]], computed on the task's own labelled text rather than the pre-training corpus, giving $L_3(C) = L_2(C) + \\lambda L_1(C)$ ([[eq-combined-objective]]). [[auxiliary-objective-weight|$\\lambda$ is set to 0.5]].\n\nSo gradient capacity is split between predicting labels and predicting the next token, and 0.5 is the paper's chosen balance between the two pulls. The reasons given are better generalization and faster convergence.\n\nThe paper's own [[ablation-no-auxiliary-objective|ablation]] qualifies that later. Dropping the auxiliary loss actually gains 0.3 points on average ([[table-5]]); keeping it helps on the larger datasets and hurts on the smaller ones. The claim in Section 3.2 is broader than the evidence in Section 5.\n\n### Structured inputs get flattened, not architected\n\nSeveral tasks do not hand you one run of text. [[structured-inputs|Some inputs have parts]] — an ordered sentence pair, or a document with a question and candidate answers. The pre-trained model only ever saw contiguous text.\n\nThe available repair was a [[task-specific-architectures|task-specific architecture]] stacked on the transferred representation. The paper rejects it because every such module is freshly initialized and gets no transfer, which drives up [[per-task-parameter-cost|per-task parameter cost]].\n\nIt uses a [[traversal-style-approach|traversal-style approach]] instead: walk the parts of the structure into one ordered sequence. Every transformed input is bracketed by [[start-and-end-tokens|randomly initialized start and end tokens]], so the last position — the one the head reads — is the same kind of thing in every example. A [[delimiter-token|`$` delimiter]] marks where one part ends and the next begins.\n\n[[entailment-input-transformation|Entailment]] is the plain case: premise, delimiter, hypothesis. [[similarity-input-transformation|Similarity]] needs a fix, because its two sentences have no inherent order while the readout sits at the end and so favours whichever came second; both orderings are built, run separately, and their final activations added element-wise. [[qa-and-commonsense-input-transformation|Question answering]] builds one sequence per candidate answer and softmaxes the resulting scores across candidates. [[fig-1]] draws all four shapes.\n\nThe payoff is [[minimal-extra-parameters|the parameter count the paper claims]]: $W_y$ plus delimiter embeddings, and nothing more. [[task-agnostic-model|One architecture for every task]] and [[task-specific-input-transformations|rewriting the input]] are a package deal — neither works without the other.\n\n### What was actually run\n\n[[fine-tuning-hyperparameters|The settings]] are the pre-training settings with four exceptions: [[fine-tuning-lr-and-batch|learning rate 6.25e-5 at batch size 32]], about four times below pre-training's peak, [[fine-tuning-lr-schedule|linear decay after a 0.2% warmup]], [[classifier-dropout|dropout 0.1 on the classifier]], and [[three-epochs-fine-tuning|three epochs]].\n\nThree passes is a small number, and the paper offers it as something it observed rather than something it tuned.\n\nYou should now be able to read any of the twelve dataset results and say which input shape it used and which parameters were new.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "page-theme-what-the-twelve-datasets-show", "forId": "theme-what-the-twelve-datasets-show", "kind": "theme", "body": "The recipe makes one bet: pre-train a single stack once, then adapt it to a task by [[theme-stage-two-fine-tuning-and-input-shapes|rewriting that task's input]] instead of redesigning the network. The twelve datasets are where that bet gets settled.\n\nFirst the terms of the comparison, because they shape everything after. Gains are reported as [[absolute-improvement|absolute improvements]], meaning differences in percentage points against the previous best published number rather than reductions in error. What is being beaten are [[baseline-comparisons|task-built systems]]: mostly bidirectional [[lstm-gpt1|LSTM]] architectures, some with attention or ELMo features, several of them ensembles. A few of the tasks arrive bundled through the [[glue-benchmark|GLUE benchmark]]. [[table-1]] is the full menu of [[evaluation-task-families|four families and twelve datasets]].\n\n### Walking the four families\n\n[[natural-language-inference|Natural language inference]] is the largest family, at five datasets. The task is to read a premise and a hypothesis, then decide whether the first entails the second, contradicts it, or leaves it open. Deciding that requires resolving [[coreference|coreference]] and handling lexical and syntactic ambiguity — the kind of structure a model would have to bring with it rather than learn from a few thousand labels.\n\nThe five are picked for different sources: image captions in [[snli|SNLI]], mixed genres in [[multinli|MultiNLI]], Wikipedia in [[qnli|QNLI]], science exams in [[scitail|SciTail]], news in [[rte|RTE]]. [[table-2]] puts the model ahead on four of them, by 5.8 points on QNLI, 5 on SciTail, 1.5 on MNLI and 0.6 on SNLI.\n\nRTE is the exception, and it is also the smallest, at 2490 training examples against SNLI's roughly 550k. There the model gets 56.0 against 61.7 from a multi-task biLSTM. The paper suggests multi-task training would probably help, given how the larger NLI sets went, and says plainly it has not tried it.\n\n[[question-answering-and-commonsense-reasoning|Question answering and commonsense reasoning]] is where the long pre-training context should pay off. [[race-dataset|RACE]] is exam passages with questions, chosen over [[cnn-and-squad-contrast|CNN and SQuAD]] because it has been shown to hold more reasoning-type questions than those; that contrast is the whole reason RACE is in the paper. [[story-cloze-test|Story Cloze]] asks for the right ending to a multi-sentence story. [[table-3]] holds the two largest margins in the paper, 8.9 points on Story Cloze and 5.7 on RACE, both over ensembles.\n\n[[semantic-similarity|Semantic similarity]] asks whether two sentences mean the same thing. The model gains 4.2 points on [[qqp|QQP]] and one point on [[sts-b|STS-B]], and stays below a specialist system on [[mrpc|MRPC]].\n\nSet STS-B beside RTE for a moment. STS-B has about 5.7k training examples, RTE 2490. One gains and one loses, so size alone does not predict where fine-tuning lands.\n\n[[text-classification|Text classification]] is two single-sentence tasks that also disagree. [[cola|CoLA]] rises to 45.4 from a previous best of 35.0, which the paper reads as linguistic bias picked up during pre-training. [[sst-2|SST-2]] reaches 91.3% and only matches the state of the art. [[table-4]] carries both, plus the GLUE total moving from 68.9 to 72.8.\n\n### What the count amounts to\n\n[[state-of-the-art-9-of-12|Nine of twelve]], with RTE, MRPC and SST-2 the three that fall short. The paper reads the spread as evidence the approach works across dataset sizes, from STS-B up to SNLI. That reading holds better across families than inside NLI, where the smallest set is the one loss.\n\nNone of this says why. It establishes only that one pre-trained stack, plus a linear layer and some delimiter tokens ([[fig-1]]), covers all four input shapes. [[theme-taking-the-recipe-apart|The analysis next]] splits the credit between pre-training, the architecture and the auxiliary loss. Carry MRPC into it: that is the single dataset where swapping in an LSTM beats the transformer.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-theme-taking-the-recipe-apart", "forId": "theme-taking-the-recipe-apart", "kind": "theme", "body": "The results say the recipe works. They do not say which part of it is doing the work — the pre-training, the architecture, the extra loss during fine-tuning, or the depth of the stack. Section 5 attacks that question three ways: turn one dial, look inside the pre-trained model before fine-tuning, and remove pieces one at a time.\n\n### Turning the depth dial\n\nThe first diagnostic is [[layers-transferred]]. Fine-tuning normally starts from all twelve pre-trained blocks. Here the paper varies how many of them are carried over, and initializes the rest fresh.\n\nAccuracy on MultiNLI and RACE rises steadily as more layers come across — [[fig-2]], left panel — reaching about 9% for full transfer on MultiNLI over transferring embeddings alone.\n\nThe shape of that curve is the finding. It does not flatten after two or three layers, so no single layer holds the transferable content. Each block is carrying something the target task can use.\n\nThat raises the obvious follow-up. If every layer holds useful function, what function is it?\n\n### Looking at the model before fine-tuning\n\n[[zero-shot-behaviors]] is the attempt to answer that directly, by making the pre-trained model do the evaluation tasks with no supervised training at all.\n\nThere is an obstacle. A language model emits a distribution over next tokens; it does not emit labels. Something has to convert one into the other.\n\nThat something is [[average-token-log-probability-scoring]]: score a candidate string by the mean log-probability the model assigns its tokens. Three of the four heuristics are that one device pointed at different text. [[cola-zero-shot-heuristic|CoLA]] scores the sentence and thresholds. [[race-zero-shot-heuristic|RACE]] conditions on document and question, then takes the highest-scoring answer. [[dprd-winograd-heuristic|DPRD]] substitutes each candidate referent for the pronoun and scores the rest of the sentence. Only [[sst2-zero-shot-heuristic|SST-2]] works differently, appending the token *very* and restricting the output distribution to *positive* and *negative*.\n\nThese scores are low in absolute terms, and the heuristics are hand-designed, so the interesting quantity is not the level but the trend. In [[fig-2]]'s right panel all four climb steadily across pre-training. The paper reads that as the generative objective picking up task-relevant behaviour on its way to better next-token prediction.\n\nThe same plot carries a weaker claim. An LSTM trained the same way shows higher variance in its zero-shot scores, and the paper offers [[transformer-inductive-bias|structured attentional memory]] as the explanation. It words this as a hypothesis, and one qualitative comparison is all that stands behind it.\n\n### Removing pieces\n\n[[ablation-studies]] are blunter, and the numbers are in [[table-5]].\n\n[[ablation-no-pretraining]] trains the same transformer straight on the supervised tasks. It loses 14.8% across the board — the cost of removing [[generative-pretraining]] entirely.\n\n[[ablation-lstm-substitution]] keeps the pre-training and swaps the [[multi-layer-transformer-decoder]] for a single-layer 2048-unit LSTM. That costs 5.6 average points, and the LSTM wins on only one dataset, [[mrpc]].\n\nSet the two side by side: 14.8 against 5.6, roughly a factor of three. Within this framework, the pre-training matters more than the architecture choice.\n\n[[ablation-no-auxiliary-objective]] does not fit that pattern. Dropping [[auxiliary-lm-objective|the auxiliary loss]] gains 0.3 on average; it helps on the larger datasets and hurts on the smaller ones. That makes it a setting to tune per dataset, not a load-bearing part of the recipe.\n\nYou should now be able to say, for any claim in this paper, whether an ablation number backs it or a hypothesis does.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-scarce-labels-borrowed-weights", "forId": "etheme-scarce-labels-borrowed-weights", "kind": "edge-theme", "body": "The argument on this page is that if annotated data is the binding constraint, then the right thing to buy with unlabelled text is a starting point for the weights — not an extra term in the loss, and not a separate bank of frozen features. Everything else follows from that commitment: the family it claims, the neighbours it argues against, and why the second stage is so short.\n\n### Designing backwards from the constraint\n\nThe opening premise is [[labeled-data-scarcity]]: raw text is abundant, while the annotated set for any single task is small and expensive to build. [[two-stage-training-procedure]] only earns its extra machinery under that asymmetry. If every task came with enough labels, a pre-training stage would have nothing to sell.\n\nThe paper then places itself rather than claiming new ground. It calls its work an instance of [[semi-supervised-learning-for-nlp]], a family the related-work section splits in two. In [[unsupervised-pretraining]], unlabelled data chooses where the weights start. In [[auxiliary-training-objectives]], initialization is left alone and an unsupervised term is added to the supervised loss. This recipe sits in the first branch and borrows from the second, since [[auxiliary-lm-objective]] keeps the language modelling loss running during fine-tuning at $\\lambda = 0.5$.\n\nInside the first branch it draws two contrasts. [[word-embedding-transfer]] moves one vector per word into a model that is otherwise trained from scratch; the paper says it wants more than word-level information. [[feature-based-transfer]], and [[elmo-deep-contextualized-word-representations|ELMo]] as its best-known case, freezes a pre-trained model and feeds its hidden states as extra inputs to a task network built separately. The paper's stated objection is [[per-task-parameter-cost]]: that route needs a substantial block of freshly initialized parameters for every new task, whereas here [[minimal-extra-parameters|the only additions]] are the output matrix $W_y$ and embeddings for the delimiter tokens.\n\n### Why stage two is small\n\nThe two stages train the same $\\Theta$ against different targets. [[generative-pretraining]] maximizes the probability of the next token over unlabelled text. [[supervised-fine-tuning]] maximizes the probability of the correct label given the input. Stage two does not restart; it continues from exactly the parameters stage one produced.\n\nThat is why the settings back off instead of starting over. [[pre-training-optimization]] runs Adam at a peak of 2.5e-4, on minibatches of 64 sequences, for 100 passes over BooksCorpus. [[fine-tuning-lr-and-batch]] uses 6.25e-5 on batches of 32 — multiply 6.25e-5 by four and you land on the pre-training peak. [[three-epochs-fine-tuning|Three epochs]] is the whole second stage, against a hundred in the first, and [[classifier-dropout]] at rate 0.1 on the new head is the only regularizer stage two adds.\n\nThe paper groups [[ulmfit]], which adapts a pre-trained LSTM through a carefully staged schedule, with the intricate learning schemes it wants to avoid. Its own [[fine-tuning-hyperparameters|schedule]] is one learning rate, a 0.2% warmup, linear decay, done. It files its recipe with the earlier work of the same shape, [[lm-pretraining-then-finetuning-predecessors]].\n\n### How much of this is measured\n\nOne link in the chain is measured directly. [[ablation-no-pretraining|Removing pre-training]] and training the same transformer on the supervised tasks costs 14.8% across the board in [[table-5]] — its own number for what the starting point is worth.\n\nThe rest is thinner than it reads. The paper reports 6.25e-5 and three epochs and says the model fine-tunes quickly. It sweeps neither setting, so \"the small step protects the pre-trained weights\" is a reading of the numbers, not a result. The comparison against feature-based transfer is an argument about parameter counts, not a controlled experiment: ELMo appears only inside baselines that differ in architecture and pre-training corpus at once. And [[choice-of-pretraining-objective|which unsupervised objective transfers best]] is named as an open question in the introduction and left open — nothing here tests an alternative to language modelling.\n\nOne result cuts against the framing. If pre-training is what rescues small labelled sets, the scarcest set should benefit most, but on [[rte]] — 2490 training examples — the model reaches 56% against 61.7% for a multi-task biLSTM.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-the-next-token-machine", "forId": "etheme-the-next-token-machine", "kind": "edge-theme", "body": "The argument stage one makes is that one decision — predict the next token — settles almost everything else about the network. The paper does not present the loss and the architecture as two independent choices; it writes the loss down first, and most of the architecture is what survives once that loss is taken literally.\n\nBegin with the decision itself. The introduction names [[choice-of-pretraining-objective|which unsupervised objective transfers best]] as an open question, listing language modelling, machine translation and discourse coherence as candidates that each beat the others on different tasks. [[language-modeling-objective|Next-token log-likelihood]] is this paper's answer, set out in [[eq-lm-objective|Equation 1]]. As an estimator it is unremarkable: sum the log-probability the network gives each token that actually occurred, and maximize by stochastic gradient descent. That is [[maximum-likelihood-training]] with nothing added on top.\n\n### What the loss forces\n\n$L_1$ conditions each token on the $k$ tokens before it, and the paper trains every position of a sequence in one pass. If a position could attend to the token it is being asked to predict, the loss would be minimized by copying. Hence [[masked-self-attention]]: each position sees itself and earlier positions only. That mask is what turns one forward pass over 512 tokens into 512 predictions that have not seen their own answers.\n\nThe mask also removes the encoder. There is no separate source sequence to encode when the input is the model's own past, so the paper keeps a [[decoder-only-stack]] and drops the other half. The [[multi-layer-transformer-decoder]] is therefore a cut of [[transformer-gpt1]], not a redesign of it.\n\n[[eq-decoder-stack|Equation 2]] supplies the remaining three lines. Layer zero is [[input-representation-h0|$h_0 = UW_e + W_p$]]: rows of the [[token-embedding-matrix|token embedding matrix $W_e$]] plus [[learned-position-embeddings|a trained position vector]] per slot, because attention alone sees a set and not an order. Choosing a trained table over fixed sinusoids has a consequence the prose does not spell out: the table has one row per slot, so the [[context-window-512-tokens|512-token window]] is a parameter count, not a runtime setting. The top line multiplies the final states by $W_e^T$ and softmaxes — [[output-softmax-tied-embeddings|the output head is the input table read backwards]] — and since the rows are subword pieces from [[byte-pair-encoding-gpt1|byte-pair encoding]] with 40,000 merges, the predicted distribution is over those pieces.\n\nThe sizes then fill in slots the architecture leaves open. States are [[hidden-state-dimension-768|768-dimensional]], and [[twelve-attention-heads|twelve heads]] divide rather than duplicate them: $768/12 = 64$ dimensions each. The [[position-wise-feedforward-3072|feed-forward sublayer]] goes 768 up to 3072 and back, a fourfold widening. Two settings are justified by other settings: [[weight-initialization|$\\mathcal{N}(0, 0.02)$]] is called sufficient because [[layer-normalization-gpt1|layernorm]] rescales activations everywhere, and [[decoupled-weight-decay|the modified L2 term]] at $w = 0.01$ is the variant written for [[adam-optimizer-gpt1|Adam]], whose per-parameter step would otherwise rescale a plain penalty unevenly. [[residual-embedding-attention-dropout|Dropout at 0.1]] appears at three points, which is all the paper specifies about [[dropout-gpt1|dropout]] here.\n\n### Where the chain is reasoning, not measurement\n\nThe step from $L_1$ to masking is the paper's own logic and is tight. The step from masking to a decoder-only stack is mine as much as theirs — the paper states the choice rather than arguing it.\n\nEverything after that is unmeasured within stage one. No ablation isolates weight tying, learned versus sinusoidal positions, the head count, or the 512-token window. The only number stage one reports on its own terms is [[token-level-perplexity|18.4 perplexity]] on BooksCorpus, which shows the corpus was fit, not that these particular choices caused the fit. The contrast with [[elmo-deep-contextualized-word-representations|ELMo]] is likewise argued, not tested: masking gives up right-hand context in exchange for one stack that can be fine-tuned whole, and the paper never measures what that trade cost.", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-the-long-range-bet", "forId": "etheme-the-long-range-bet", "kind": "edge-theme", "body": "The paper argues that a pre-trained model can only hand a target task the kind of structure it was able to see during pre-training. Three separate choices — the architecture, the corpus, and the size of the context window — are each justified by the same goal, which is conditioning a prediction on information sitting far back in the text.\n\nThe chain starts as a complaint about other people's work. Reviewing the closest prior methods, the paper says their use of LSTM models \"restricts their prediction ability to a short range\" ([[lstm-short-range-limitation]]). Its own [[multi-layer-transformer-decoder]] is offered as the answer, on the stated grounds that attention gives a more structured memory for long-term dependencies than recurrence does.\n\nThen comes the step that is easy to skip. An architecture that *can* reach far back buys nothing if the training text has no far-back structure in it. So the corpus is picked to supply that: [[bookscorpus]], over 7,000 unpublished books, whose selling point in this paper is [[long-range-contiguous-text|long stretches of contiguous text]]. The paper names the alternative it turned down, [[one-billion-word-benchmark|the 1B Word Benchmark]], as approximately the same size but shuffled at the sentence level. Same token budget, different shape. The choice is an argument about structure, not about scale.\n\nThe window is the third piece. In [[eq-lm-objective]], the [[language-modeling-objective|pre-training loss]] conditions each token on the $k$ tokens before it, with $k$ left as a free symbol. The setup section fixes it at [[context-window-512-tokens|512 tokens]], and trains on minibatches of 64 randomly sampled contiguous sequences of that length. On a sentence-shuffled corpus those 512 slots would mostly hold unrelated neighbours; on books they usually hold several paragraphs of one story.\n\nWhat all three are supposed to capture is named concretely: [[long-range-dependencies-gpt1|relationships spanning many tokens]], such as [[coreference|a pronoun and the name it stands for]] several sentences back, or a question and the passage detail that answers it. The evaluation is then picked to need them. [[race-dataset|RACE]] is chosen over [[cnn-and-squad-contrast|CNN and SQuAD]] because it \"has been shown to contain more reasoning type questions\", which the paper calls \"the perfect evaluation for our model which is trained to handle long-range contexts.\"\n\n### What the evidence actually reaches\n\n[[token-level-perplexity|A token-level perplexity of 18.4]] shows that [[generative-pretraining|stage one]] fit BooksCorpus. It says nothing about how far back the model looks, and nothing about transfer.\n\n[[table-3]] carries the payoff: 8.9 points on Story Cloze and 5.7 on RACE over the previous best. The paper reads these as demonstrating \"the ability of our model to handle long-range contexts effectively.\" That reading is inferential. Neither benchmark separates items that need distant context from items answerable from a nearby sentence, so the margin is consistent with the claim without isolating it.\n\nThe architecture half does get a controlled test. Swapping in a single-layer LSTM costs [[ablation-lstm-substitution|5.6 average score points]] in [[table-5]].\n\n### What was never run\n\nThe corpus half has no ablation. No model was pre-trained on the shuffled 1B Word Benchmark and rerun, so the contiguity argument rests on downstream scores from a single training recipe rather than on a comparison.\n\nMy reading, not the paper's: the LSTM ablation moves capacity and architecture together — a single-layer 2048-unit LSTM against a 12-layer transformer — and the paper attributes the whole 5.6 to architecture.\n\n[[domain-mismatch-tolerance]] sits underneath all of this. Fiction is used to prepare a model for science-exam entailment, news paraphrase and [[qqp|Quora question pairs]]. The paper states that assumption and the results are consistent with it, but nothing here tests it on its own.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-one-stack-any-input-shape", "forId": "etheme-one-stack-any-input-shape", "kind": "edge-theme", "body": "The paper argues that the work of adapting to a task does not have to live in the architecture — it can live in how the input is written down. Every structured input is rewritten as one ordered run of tokens, so the same pre-trained stack reads every task, and the only machinery added on top is a single matrix.\n\n### From four input shapes to one vector\n\nThe chain starts with a mismatch. The pre-trained network is a [[multi-layer-transformer-decoder]], and Section 3.3 says it was trained on contiguous sequences of text. The evaluation tasks do not hand over contiguous text: entailment gives an ordered sentence pair, and reading comprehension gives a document, a question and a set of candidate answers.\n\nThe paper names the route it is not taking. Prior work put [[task-specific-architectures]] on top of transferred representations, and the objection given is that those added components are freshly initialized, so transfer buys them nothing.\n\nThe alternative is the [[traversal-style-approach]]: walk the parts of a structured input into one sequence. That is the whole content of [[task-specific-input-transformations]]. [[entailment-input-transformation|Entailment]] concatenates premise and hypothesis with a `$` between them, and the model is never told there were two sentences. The [[qa-and-commonsense-input-transformation|question-answering case]] does not flatten at all, so the paper builds `[z; q; $; a_k]` once per candidate answer, runs each through the same stack, and softmaxes the resulting scores across candidates. Variable structure is absorbed by running the fixed model several times. [[fig-1]] draws all four shapes feeding one stack.\n\nNow the readout. Whatever the sequence was, the classifier sees exactly one vector: [[final-token-activation]], the final block's output at the last input token. Every transformed input is bracketed by [[start-and-end-tokens]], which makes that last position the same kind of token in every example — the paper states the bracketing as part of the transformations rather than arguing this consequence, so the connection is my reading of it.\n\nThat single vector is what makes the head small. [[eq-task-head]] is $\\mathrm{softmax}(h_l^m W_y)$, so the entire task-specific classifier is [[linear-output-layer-wy|one matrix]]. [[eq-supervised-objective|Equation 4]] then states [[supervised-objective-l2|the loss]] as the summed log-probability of the correct labels — ordinary supervised training, nothing task-shaped in it. The paper's own summary of [[supervised-fine-tuning]] follows: the [[minimal-extra-parameters|only extra parameters]] are $W_y$ and embeddings for the delimiter tokens.\n\nTwo claims land from this. One architecture is a [[task-agnostic-model]] across all twelve datasets, and the [[per-task-parameter-cost]] of a new task is one matrix plus a couple of embeddings.\n\n### What the design is and is not shown to do\n\nThe outcome numbers are real: new best results on 9 of 12 datasets against [[baseline-comparisons|mostly task-built biLSTM systems]], including 8.9% absolute on Story Cloze, 5.7% on RACE and 5.8% on QNLI, beating ensembles in several cases. On RTE the model gets 56% against a multi-task biLSTM's 61.7%.\n\nWhat those numbers do not isolate is the transformation scheme itself. The paper never runs a task-specific architecture on top of its own pre-trained stack, so the comparison in Section 3.3 is against other people's systems, not a controlled swap. The ablations test pre-training, the transformer-versus-LSTM choice and the auxiliary objective — not the serialization.\n\nThe [[similarity-input-transformation]] is the clearest case. The last-token readout is order-sensitive, so the paper builds both orderings and adds the two final activations element-wise, at twice the compute per example. The motive is stated plainly; the one-ordering control that would price the repair is not reported.\n\nThe parameter-cost comparison is likewise qualitative. [[feature-based-transfer|Feature-based transfer]] is described as needing \"a substantial amount of new parameters\" per task, with no count set beside $W_y$.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-two-losses-and-three-removals", "forId": "etheme-two-losses-and-three-removals", "kind": "edge-theme", "body": "The paper's second training stage carries two losses at once, and its analysis section removes three pieces of the recipe one at a time to find out which pieces the results actually rest on. The removals produce a ranking: pre-training first by a wide margin, the transformer second, and the extra loss third — third because its effect does not have one sign.\n\n### Two losses over the same weights\n\nFine-tuning starts from a task loss. [[supervised-objective-l2|$L_2$]] sums the log-probability of the correct label over the labelled data.\n\nThe paper does not optimize that alone. It keeps computing the pre-training language modelling loss on the labelled task's own inputs and adds it in, as [[eq-combined-objective|$L_3(C) = L_2(C) + \\lambda L_1(C)$]]. The [[auxiliary-objective-weight|weight $\\lambda$]] is set to 0.5, so the language modelling term is counted at half the strength of the label term. Two objectives now pull on the same weights.\n\nKeeping the second one costs almost nothing in parameters. The language modelling head is not a separate matrix: the model scores next tokens with [[output-softmax-tied-embeddings|$\\mathrm{softmax}(h_n W_e^T)$]], the transpose of the [[token-embedding-matrix]] it already carries. So the head survives from stage one without anyone deciding to keep it.\n\nThe related work files this move under a branch of semi-supervised learning it names [[auxiliary-training-objectives|auxiliary training objectives]], where the added unsupervised loss *is* the transfer mechanism. Here it is not the mechanism. It rides on top of [[generative-pretraining|pre-training]], and the paper's reason is that pre-training has already learned the linguistic aspects such an objective would otherwise supply. Section 3.2 says the [[auxiliary-lm-objective|auxiliary objective]] helps by improving generalization and by speeding up convergence. Neither of those two effects is measured separately anywhere in the paper.\n\n### Three removals, one ranking\n\n[[table-5]] takes the full recipe and knocks out one piece per row.\n\nRemove [[ablation-no-pretraining|pre-training]] and train the identical transformer directly on the supervised tasks. Performance falls on every task measured, 14.8% below the full model. That row is the strongest single piece of evidence the paper has for the [[two-stage-training-procedure|two-stage design]].\n\nNow swap the [[multi-layer-transformer-decoder|transformer]] for a single-layer 2048-unit LSTM. The average score drops [[ablation-lstm-substitution|5.6 points]]. The swap is a clean comparison because [[task-specific-input-transformations|the input transformations]] are architecture-independent — same serialized sequences, same last-token readout, same objectives — so the sequence model is what changed. [[mrpc|MRPC]] is the one dataset where the LSTM comes out ahead.\n\nSet 14.8 against 5.6. By the paper's own measurement, the pre-training matters about three times as much as the architecture choice.\n\nThen remove the auxiliary loss. The result is not a uniform drop: [[ablation-no-auxiliary-objective|it helps on the NLI tasks and QQP and does not help elsewhere]], which the paper reads as larger datasets benefiting and smaller ones not.\n\n### Where the evidence is thinner than the claim\n\nThe size trend is the paper's own reading of a handful of dataset scores in one table. It is not a controlled study that holds a task fixed and varies training-set size.\n\n$\\lambda$ is fixed at 0.5 for every task, with no sweep reported. So the one removal whose sign changes with dataset size was run at a single weight across all the cases where the evidence says the balance should differ. Whether a per-task $\\lambda$ would close the split is untested here — that reading is mine, not the paper's.\n\nTwo more gaps, also my reading rather than the paper's. The LSTM has one layer and 2048 units against twelve layers of 768; no parameter or compute matching is stated, so 5.6 points mixes architecture with capacity. And the fine-tuning settings — three epochs, learning rate 6.25e-5 — were chosen for a pre-trained model, then inherited by the row that has no pre-training to fine-tune.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-the-scoreboard-and-its-gaps", "forId": "etheme-the-scoreboard-and-its-gaps", "kind": "edge-theme", "body": "The paper's result is one number: new best published results on nine of twelve datasets. That number is not measured anywhere in the paper — it is a count assembled by reading three separate tables — and this page follows how it is built, what it leaves out, and where the paper's own explanation of its failures does not hold.\n\n### Building the count\n\nThe denominator comes first. [[table-1]] lays out [[evaluation-task-families|four task families across twelve datasets]], so the count has a fixed base before any result is reported.\n\nThe numerator is spread across three tables. [[table-2]] covers [[natural-language-inference]] and reports the fine-tuned model ahead on four of five datasets: 1.5% on [[multinli|MNLI]], 5% on SciTail, 5.8% on QNLI and 0.6% on SNLI. [[table-3]] adds two more, with margins of 8.9% on the [[story-cloze-test]] and 5.7% overall on RACE, the paper's largest and the two the abstract leads with. [[table-4]] contributes three: [[cola]], [[sts-b]] and [[qqp]].\n\nFour plus two plus three is nine. The three that are left over are [[rte]], [[sst-2]], and — by subtraction from the claim of state-of-the-art on two of the three [[semantic-similarity]] datasets — [[mrpc]]. The paper names the first two in the text and never names the third.\n\nA count also flattens the margins. The 0.6% on SNLI and the 8.9% on Story Cloze each contribute exactly one to the nine, even though the paper reports its gains as [[absolute-improvement|absolute percentage-point differences]] and those two differ by more than a factor of ten.\n\n### Where the general claim thins\n\n[[rte]] is the clearest gap. The model reaches 56% against 61.7% from a multi-task biLSTM, so it falls 5.7 points short of the previous best on the one NLI dataset it loses.\n\nThe paper's explanation is dataset size: RTE has 2490 training examples, and it suggests the model would likely benefit from multi-task training too. It then says plainly that it has not run that experiment. The explanation is a hypothesis, not a result.\n\nThe explanation also sits awkwardly beside the section's closing sentence, which says the approach works well across dataset sizes from STS-B at roughly 5.7k examples up to [[snli]] at roughly 550k. RTE at 2490 is smaller than either endpoint of that stated range. Reading those two passages together — the paper does not connect them itself — the size claim is made over the datasets that support it, while the one dataset below the range is the one that fails.\n\nOne arithmetic gap is worth checking directly. Section 4.2 reports an overall [[glue-benchmark]] score of 72.8 against a previous best of 68.9, a difference of 3.9 points, while the introduction claims 5.5% on GLUE. The paper does not reconcile the two figures.\n\n### How strong is each link\n\nThe dataset-size reading of RTE and the untested multi-task suggestion are the paper's own, and it hedges both. The observation that RTE is smaller than the range the paper claims to cover is my reading of two sentences it keeps apart.\n\nTwo interpretations rest on assertion rather than measurement. The paper reads the CoLA jump from 35.0 to 45.4 as showing the linguistic bias the model learned, but a single score does not separate that from any other reason for the gain — and [[sst-2]] at 91.3%, competitive but not ahead, is the other [[text-classification]] task and gets no such reading. Likewise, the NLI margins are said to demonstrate reasoning over multiple sentences and handling of linguistic ambiguity; no experiment in the paper isolates either capability.\n", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-etheme-watching-pre-training-work", "forId": "etheme-watching-pre-training-work", "kind": "edge-theme", "body": "The analysis section asks a different question from the rest of the paper: not whether the two-stage recipe wins, but why it does. Its answer comes in two halves — transferable function is spread through the whole depth of the stack rather than sitting in the embedding table, and task-relevant behaviour accumulates during pre-training while only the language modelling loss is being optimized.\n\n### Every layer holds something\n\n[[layers-transferred|The layer-transfer sweep]] fine-tunes on MultiNLI and RACE while varying how many pre-trained layers are carried across, from the embeddings alone up to the full stack. That sweep is a dial with twelve settings only because the model is [[twelve-layer-depth|twelve blocks deep]]. A shallower model would leave fewer points on the curve.\n\nThe left panel of [[fig-2]] shows dev accuracy climbing with each additional layer, and the paper puts the gap at up to 9% for full transfer on MultiNLI. The bottom of that curve reproduces a known result: [[word-embedding-transfer|transferring word embeddings]] helps. The rest is the paper's own point — stopping at the embedding table gives up most of the available gain.\n\n### The model scoring itself\n\nThe second half needs a device first. A generative model emits a distribution over next tokens, not task labels, so making it answer anything without [[supervised-fine-tuning|fine-tuning]] means turning it into a scorer.\n\n[[average-token-log-probability-scoring|The scoring rule]] is: take a candidate string, ask the model for the log-probability of each of its tokens, and average them. That number is the same quantity [[language-modeling-objective|$L_1$]] maximizes in [[eq-lm-objective]], read out over one candidate instead of summed over a corpus.\n\nThree of the four heuristics are that one rule pointed at different spans of text. [[cola-zero-shot-heuristic|CoLA]] thresholds a sentence's mean score to predict grammaticality. [[race-zero-shot-heuristic|RACE]] conditions on the document and question, then keeps the highest-scoring candidate answer. [[dprd-winograd-heuristic|DPRD]] substitutes each possible referent for the definite pronoun and keeps the resolution whose remaining text scores higher, turning a [[coreference]] question into a comparison between two rewritten sentences.\n\n[[sst2-zero-shot-heuristic|SST-2]] works another way, appending the token 'very' and restricting [[output-softmax-tied-embeddings|the output distribution]] to 'positive' and 'negative'. No classifier is trained anywhere in any of this.\n\nBecause the read-out is the training quantity, [[zero-shot-behaviors|these heuristics]] can be tracked across pre-training updates. The right panel of the figure shows their scores rising steadily and staying stable, which the paper takes as [[generative-pretraining|pre-training]] supporting a wide variety of task-relevant functionality.\n\n### What the diagnostic does not settle\n\nThe curves are relative trends over training, not absolute task scores. They are evidence that the ability grows; they are not evidence that it is competitive with the fine-tuned numbers, and the paper does not claim otherwise. Its own wording is \"suggesting\", not \"showing\".\n\nTwo claims run further than the plot. [[transformer-inductive-bias|The structured-memory hypothesis]] rests on one observation: [[lstm-gpt1|the LSTM]] shows higher variance in the same zero-shot measurements. No variance figure is quoted, so this is a qualitative reading of a curve rather than a measurement, and the paper states it as a hypothesis.\n\nThe conclusion's [[world-knowledge|claim about world knowledge]] is broader still. The nearest supporting evidence is the zero-shot panel plus the downstream scores, and neither measures facts about the world directly.\n\nMy own reading of the layer sweep is similarly limited: it shows depth helps on two datasets, and says nothing about what any individual layer contains.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-labeled-data-scarcity", "forId": "labeled-data-scarcity", "kind": "concept", "body": "Deep models for the tasks the paper groups under [[natural-language-understanding]] are normally fitted on examples that a person labelled by hand. The paper's opening claim is that there are not nearly enough of those examples, and this page comes first because every later design choice is an answer to that shortage.\n\nPut the two resources side by side with real numbers. The evaluation includes [[rte]], an inference dataset with 2,490 training examples, and [[sts-b]], a similarity dataset with roughly 5,700. The largest labelled set anywhere in the evaluation, [[snli]], has about 550,000.\n\nAgainst those figures, the pre-training corpus [[bookscorpus]] is over 7,000 unpublished books of running prose. Nobody annotated a word of it. The text was written for its own reasons and was already there.\n\nSo the asymmetry is not only in size. It is in cost per example: an annotated pair has to be commissioned from a person, while a sentence of raw text is free.\n\n### What the shortage costs\n\nA model trained only to predict a label given an input — the discriminative framing set out in [[generative-vs-discriminative-training]] — has to learn everything from those pairs. With RTE that means estimating how English sentences relate to each other from 2,490 examples. Capacity the labelled data cannot fill goes into memorising it instead.\n\nThis is the asymmetry [[two-stage-training-procedure]] is designed backwards from. Spend the plentiful resource to relieve the scarce one: let unlabelled text decide where the weights start, so the labelled set only has to adjust a model that already reads, rather than build one from nothing. If every task had 550,000 examples, the extra stage would buy little.\n\nThe paper adds a second, softer motive. Even where supervision is plentiful, it says, learning representations without labels still gives a boost — and the evidence offered for that is the existing record of [[word-embedding-transfer]] inside [[semi-supervised-learning-for-nlp]], not anything measured here.\n\n### How strong the evidence is\n\nThe direct test is [[ablation-no-pretraining]] in [[table-5]]: the same transformer, the same fine-tuning, with stage one removed costs 14.8% on average. That isolates pre-training cleanly.\n\nIt does not isolate scarcity, though. There is no curve of performance against labelled-set size, so the 14.8% is an average over twelve datasets rather than a demonstration that small datasets are where the gain lives.\n\n[[table-2]] complicates it further. RTE, the smallest set in the evaluation, is the one inference dataset where the model loses — 56% against 61.7% for a multi-task biLSTM. On the simplest reading of the scarcity story, that is exactly where the gain should have been largest.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-semi-supervised-learning-for-nlp", "forId": "semi-supervised-learning-for-nlp", "kind": "concept", "body": "Semi-supervised learning for NLP means training on a large unlabelled corpus and a small labelled dataset for the same end task. The paper opens its related-work section by claiming this category outright, because [[labeled-data-scarcity|annotation is the binding constraint]] and it needs to say which of several existing answers to that constraint it is adopting.\n\nThe category fixes what may move. The task, its labels and its metric stay exactly as they were. Unlabelled text is allowed to change the model — its input features, its loss, or its starting weights — but not the definition of the problem.\n\n### The sorting axis\n\nThe paper's split is about *where* the unlabelled text enters, and it walks the branches roughly in order of when they appeared.\n\nThe oldest branch computes word- and phrase-level counts from raw text and appends them as features to a supervised model. [[word-embedding-transfer]] replaced those counts with learned vectors, and [[phrase-and-sentence-embeddings]] pushed the same idea up to longer spans. The delivery mechanism does not change across that progression: something is computed once on unlabelled text, then handed to a task model that is otherwise trained from the labelled set alone.\n\nThe paper's objection is specific. A table of one vector per word moves word-level information and nothing else; whatever composes those words into meaning is still learned from the small dataset.\n\nTwo other branches exist. [[auxiliary-training-objectives]] add an unsupervised loss term next to the supervised one. [[unsupervised-pretraining]] leaves the objective alone and uses unlabelled data only to pick the initialization — this is where the paper puts itself, and [[two-stage-training-procedure|its own recipe is one member of that branch]], not a new category.\n\nInside that branch it draws one more line. [[feature-based-transfer]] freezes the pre-trained model and feeds its states into a separate task network, which means [[per-task-parameter-cost|fresh parameters for every task]]. [[lm-pretraining-then-finetuning-predecessors]] instead fine-tunes the whole network, and the paper calls this the closest work to its own; its disagreement there is architectural, not procedural, and rests on the [[lstm-short-range-limitation|claim that recurrence keeps predictions local]].\n\n### How much of this is shown\n\nAlmost none of it, in this section. Related work argues; the numbers arrive later.\n\nTwo claims do get a measurement. [[table-5]] reports that removing pre-training costs 14.8 average points, and that substituting a single-layer 2048-unit LSTM costs 5.6. The second is one substitution at one size inside this paper's own pipeline, not a study of what recurrence can carry.\n\nThe claim about capturing more than word-level semantics is never tested against word embeddings directly. [[fig-2]]'s layer-transfer curve is the nearest thing to support.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 7, 8]}}, {"id": "page-two-stage-training-procedure", "forId": "two-stage-training-procedure", "kind": "concept", "body": "Train one network to predict the next token on unlabelled text, then keep training that same network on a labelled task. The procedure exists because of the asymmetry the paper opens with: raw text is abundant, while [[labeled-data-scarcity|annotated data for any one task]] is small and expensive, so the unlabelled corpus is asked to pay for what annotation cannot.\n\nThe paper does not claim a new category for this. It places the recipe inside [[semi-supervised-learning-for-nlp]], as one particular member of that family — the one where unlabelled data chooses where the weights start rather than adding a term to the supervised loss.\n\n### What actually crosses the boundary\n\nStage one, [[generative-pretraining]], maximizes the [[language-modeling-objective|likelihood $L_1$]] over a corpus of tokens. The output it cares about is not a prediction. It is $\\Theta$: every weight of the twelve-block, 768-dimensional decoder described in [[model-specification]].\n\nStage two, [[supervised-fine-tuning]], loads those same weights and continues from them. A labelled input runs through the stack, the final block's activation at the last token is read off, and one added matrix [[linear-output-layer-wy|$W_y$]] maps it to label scores under [[supervised-objective-l2|$L_2$]].\n\nCount what stage two adds. For a three-way label, $W_y$ is $768 \\times 3$, so 2304 fresh weights — against a whole pre-trained stack whose every weight is also updated by the same backward pass. Nothing is frozen, and no task-specific network is built on top.\n\nThat is the line the paper draws against [[feature-based-transfer]], where the pre-trained model stays fixed and its hidden states are fed to a separate task model as inputs. Here the parameters themselves move, which is what makes it [[transfer-learning]] rather than feature extraction. Keeping the architecture fixed across twelve datasets is only possible because [[structured-inputs]] are flattened first — see [[task-specific-input-transformations]]. The paper also assumes the corpus need not match the target domain ([[domain-mismatch-tolerance]]).\n\n### How strong the evidence is\n\nThe load-bearing number is in [[table-5]]: the same transformer trained directly on the supervised tasks, with no stage one, drops 14.8% across the board. That is one controlled removal, reported as an average with no variance across seeds, but it is a genuine ablation and it isolates the recipe.\n\nThe same table complicates it. Swapping the transformer for an LSTM costs 5.6, so part of the margin belongs to the backbone rather than to the two stages. [[fig-2]] adds that each transferred layer helps, up to 9% on MultiNLI.\n\nThe scoreboards — [[table-2]], [[table-4]] — measure the whole package against differently built systems, and lose on RTE, SST-2 and [[mrpc]]. They show the recipe is competitive; they do not, on their own, show which part of it works.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-generative-pretraining", "forId": "generative-pretraining", "kind": "concept", "body": "Stage one trains a single network against a single loss: predict the next token, over a corpus that carries no labels anywhere in it. It is here because [[supervised-fine-tuning|stage two]] needs somewhere to start, and next-token prediction is the one objective that scales to the amount of text that exists.\n\nThe training signal is written out in [[eq-lm-objective]]. The [[language-modeling-objective|objective $L_1$]] walks every position $i$ in the corpus, reads off the log-probability the network assigns to the actual token $u_i$ given the $k$ tokens immediately before it, and sums those numbers. Gradient ascent on that sum is the whole of stage one. Here $k$ is [[context-window-512-tokens|512 contiguous tokens]], so a prediction can condition on material several paragraphs back.\n\nThe conditional itself is computed by a [[multi-layer-transformer-decoder]], and the [[model-specification|trained configuration]] is twelve blocks, 768-dimensional states, twelve heads, and 3072-dimensional inner feed-forward states.\n\nIt is worth walking what one update contains. A minibatch is 64 sampled sequences of 512 tokens, so 32,768 token positions go through the stack at once. Each of those positions contributes its own term to $L_1$. No part of that batch had to be annotated by anyone.\n\n### Why pay for this\n\nThe [[pre-training-optimization|optimization run]] makes 100 passes over [[bookscorpus|BooksCorpus]], which the paper picks for [[long-range-contiguous-text|unbroken stretches of text]] rather than for size. Nothing about the target tasks enters. When it finishes, the output distribution is thrown away and only $\\Theta$ moves forward, which is what makes this an instance of [[unsupervised-pretraining|weight-initializing]] rather than loss-shaping semi-supervision. It also separates the method from [[word-embedding-transfer]], which moves one vector per word instead of every layer.\n\nThe cost is paid entirely up front. Those 100 epochs buy a stage two of [[three-epochs-fine-tuning|three epochs]] at [[fine-tuning-lr-and-batch|a learning rate four times smaller]] — a budget that only makes sense as an adjustment to weights already worth keeping.\n\n### How strong the evidence is\n\nThe direct number is the [[ablation-no-pretraining|no-pre-training ablation]] in [[table-5]]: the same transformer trained straight on the supervised tasks loses 14.8 points on average. That isolates stage one cleanly and is the paper's strongest single result for it.\n\nThe rest is weaker. [[fig-2]] shows zero-shot task scores climbing during pre-training, which the paper offers as a reason the recipe works, and words as a hypothesis. The reported [[token-level-perplexity|perplexity of 18.4]] says the model fit BooksCorpus, not that the fit transfers. The conclusion's claim about acquired [[world-knowledge]] is asserted rather than measured.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "page-language-modeling-objective", "forId": "language-modeling-objective", "kind": "concept", "body": "$L_1$ is the loss that trains stage one, and it is the only loss stage one has. It is here because the paper wants a training signal that costs no annotation, so that a large corpus of raw text can set the network's starting weights before any labelled task appears.\n\n### The operation\n\nFix a position $i$ in the corpus. The model reads the $k$ tokens immediately before it, $u_{i-k},\\dots,u_{i-1}$, and emits one distribution over the whole vocabulary. That vocabulary is the byte-pair set built with 40,000 merges, so the softmax spreads mass over roughly forty thousand entries.\n\nThe objective then reads a single number off that distribution: the log-probability it placed on $u_i$, the token that actually came next. [[eq-lm-objective]] sums that number over every position in the corpus and maximizes the sum by stochastic gradient descent on the parameters $\\Theta$. Nothing about the estimator goes past [[maximum-likelihood-training]] — what is new in stage one is the corpus and the network, not the fitting. The three lines that turn a context into the distribution are [[eq-decoder-stack]].\n\nNow the shapes. $k$ is fixed at 512 ([[context-window-512-tokens]]), and each minibatch holds 64 such sequences, so a single gradient step carries $64 \\times 512 = 32{,}768$ separate prediction terms.\n\nThat density depends on [[masked-self-attention]]. Without the mask, a position could attend to the token it is being asked to predict, and the objective would be satisfied by copying. Every forward pass would then yield one honest prediction rather than 512.\n\n### What the choice costs\n\nThe introduction is explicit that nobody knows which unsupervised objective produces representations that transfer best, and it names language modelling, machine translation and discourse coherence as candidates that each lead on different tasks ([[choice-of-pretraining-objective]]). Next-token likelihood is this paper's pick, not its argument. It reports what happens when you use it.\n\nThe price is the strict left-to-right conditioning. A token's representation never sees anything to its right, at any layer, at any point in pre-training.\n\n### How strong the evidence is\n\nOn [[bookscorpus]] the trained model reaches a token-level perplexity of 18.4 ([[token-level-perplexity]]). Perplexity is $L_1$ restated on a per-token scale, so that figure says the corpus was fitted well.\n\nIt is one number on the pre-training corpus, and on its own it says nothing about whether the weights transfer. The claim that they do rests on the fine-tuning results, and most directly on [[ablation-no-pretraining]].\n\n$L_1$ is also not retired when stage one ends; it returns weighted during fine-tuning as the [[auxiliary-lm-objective]].", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "page-multi-layer-transformer-decoder", "forId": "multi-layer-transformer-decoder", "kind": "concept", "body": "This is the network that computes the next-token probability in [[language-modeling-objective|the stage-one objective]] — the only thing trained on BooksCorpus, and the thing whose weights are later handed to every task. It is not a new design: it is the [[transformer-gpt1|transformer]] block of prior work, stacked twelve deep and cut down to one side.\n\n### What the three lines compute\n\n[[eq-decoder-stack|Equation 2]] writes the whole network in three lines, and reading it is how you confirm there is no encoder and no cross-attention anywhere in the model.\n\nLine one builds the input. Take the context $U$, up to 512 token ids, look each one up in the [[token-embedding-matrix|token embedding matrix]] $W_e$, and add the [[learned-position-embeddings|position embedding]] for its slot. That gives [[input-representation-h0|$h_0$]], a $512 \\times 768$ array of activations.\n\nLine two runs the stack: $h_l = \\mathrm{transformer\\_block}(h_{l-1})$ for $l \\in [1, n]$, with $n = 12$ in the [[model-specification|trained model]]. Each block does masked multi-head self-attention, then a position-wise feed-forward layer. The 768 dimensions are split across twelve heads, so each head attends in a 64-dimensional subspace; the feed-forward layer widens 768 to 3072 and projects back, a fourfold expansion. The shape entering a block and the shape leaving it are the same, which is what lets you stack identical blocks.\n\nLine three reads the stack out. Multiply $h_n$ by $W_e^{T}$ and softmax, giving a distribution over the vocabulary at each position. The [[output-softmax-tied-embeddings|same matrix does the work at both ends]], so no separate output vocabulary matrix exists.\n\nTwo restrictions make this a decoder rather than a transformer: the encoder half is [[decoder-only-stack|dropped entirely]], and attention is [[masked-self-attention|masked]] so position $i$ sees only positions $\\le i$.\n\n### Why a transformer, and how firmly that is shown\n\nThe paper's stated reason is that recurrent pre-trained models keep their predictions [[lstm-short-range-limitation|short-range]], which caps how much structure they can hand to a target task. Attention is offered as the fix. The wider argument depends on it: one stack serving twelve datasets is what makes the model [[task-agnostic-model|task-agnostic]] at all, and [[fig-1]] draws exactly that.\n\nThe measurement is one row of [[table-5]]. Holding the rest of the recipe fixed and substituting a single-layer 2048-unit LSTM costs 5.6 average points, and the LSTM wins on one dataset, [[mrpc|MRPC]]. That is a single ablation, at one recurrent configuration, with no parameter matching and no repeated runs reported. The right panel of [[fig-2]] adds a softer signal: zero-shot scores grow more smoothly for the transformer than for an LSTM trained the same way. Note the scale — removing pre-training altogether costs 14.8, so the architecture is the smaller of the two effects the paper measures.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-decoder-only-stack", "forId": "decoder-only-stack", "kind": "concept", "body": "The [[transformer-gpt1|original transformer]] is two stacks. An encoder reads a source sequence with unrestricted self-attention, and a decoder generates a target while attending to its own past through masking and, through a separate cross-attention sublayer, to the encoder's output states.\n\nThe [[language-modeling-objective|language modelling objective]] used here has no source sequence. There is nothing to encode, so the paper keeps the decoder side alone and deletes the sublayer that would have had nothing to attend to.\n\n### What is left in one block\n\nEach block is now two sublayers: [[masked-self-attention]] over the context, then a [[position-wise-feedforward-3072|position-wise feed-forward network]].\n\nFollow the shapes. A context of [[context-window-512-tokens|512 tokens]] enters as a $512 \\times 768$ matrix — [[input-representation-h0|one row per position]], each row a [[token-embedding-matrix|token embedding]] added to a [[learned-position-embeddings|learned position vector]].\n\nAttention splits those [[hidden-state-dimension-768|768 dimensions]] into [[twelve-attention-heads|12 heads]] of $768/12 = 64$ dimensions each. The feed-forward sublayer then takes each of the 512 rows on its own, widens it from 768 to 3072, and projects it back to 768.\n\nSo a block returns exactly the shape it was given. That is why the same block can be stacked [[twelve-layer-depth|twelve times]] with nothing between the copies, and why the top states can be sent straight back through [[output-softmax-tied-embeddings|the transposed embedding matrix]] to score the next token. [[eq-decoder-stack]] writes the whole network in three lines:\n\n$$h_0 = UW_e + W_p, \\qquad h_l = \\mathrm{transformer\\ block}(h_{l-1}), \\qquad P(u) = \\mathrm{softmax}(h_n W_e^{\\top})$$\n\n### What the choice costs\n\nDropping cross-attention removes the model's only second input port. From here on, anything the model reads — a premise and a hypothesis, a document with a question and a candidate answer — has to arrive as one ordered sequence, which is the work [[task-specific-input-transformations|the input transformations]] are there to do.\n\nThe masking is permanent too. No position ever sees its right context, in pre-training or in fine-tuning.\n\n### How firm the evidence is\n\nThe left panel of [[fig-1]] draws the repeated block, and [[model-specification|Section 4.1]] states the configuration flatly: a 12-layer decoder-only transformer with masked self-attention heads. Both are descriptions of what was built, not tests of it.\n\nThe one architectural comparison the paper does run is [[table-5]], which replaces the transformer with [[ablation-lstm-substitution|a single-layer 2048-unit LSTM]] and loses 5.6 average points. That weighs attention against recurrence. It says nothing about whether an encoder half would have added anything, and the paper does not argue that it would.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "page-masked-self-attention", "forId": "masked-self-attention", "kind": "concept", "body": "Masked self-attention is the edit that turns a general transformer block into a language model block: before the attention softmax, every score pointing from a position to a position on its right is set to $-\\infty$. It is here because [[language-modeling-objective|the pre-training loss $L_1$]] asks the model to predict each token from the tokens before it, and an unmasked block would let a position read the very token it is being scored on.\n\n### The operation\n\nTake one head at one layer. The 512 positions of a [[context-window-512-tokens|training sequence]] produce queries and keys, and their dot products form a $512 \\times 512$ score matrix — row $i$ holds position $i$'s affinity for every position in the window.\n\nThe mask is an additive term over that matrix. Entries above the diagonal get $-\\infty$; the diagonal and everything below it are left alone. Softmax over a row then sends those entries to exactly zero.\n\nSo row 400 has 401 non-zero weights and 111 zeros. Position 400 mixes values from tokens 0 through 400 and nothing else — precisely the conditioning set $u_{i-k},\\dots,u_i$ that $L_1$ writes down.\n\nThis happens independently in each of the [[twelve-attention-heads|twelve heads]], each working in a 64-dimensional slice of the [[hidden-state-dimension-768|768-dimensional state]], at all [[twelve-layer-depth|twelve layers]]. That is 144 masked score matrices per forward pass, all sharing one triangular pattern.\n\nThe payoff is throughput. One pass over 512 tokens yields 512 predictions that are all honest, rather than one prediction per pass, because no position could have peeked.\n\n### What it costs\n\nThe mask is what makes [[decoder-only-stack|a single stack with no encoder]] coherent, but it buys that by giving up the right context permanently. A token's representation never sees what follows it. [[elmo-deep-contextualized-word-representations|ELMo]] makes the opposite trade: its pre-trained language model reads both directions, and pays by not being a single stack you can fine-tune as-is.\n\nThe mask also does not lift at fine-tuning time. Only the last position has seen the whole input, which is why the classifier reads [[final-token-activation|the final block's activation at the last token]] instead of pooling, and why a structured input has to be flattened into [[task-specific-input-transformations|one ordered sequence]] first.\n\n### How well is this shown\n\nThinly, as a direct claim. The paper states the heads are masked and [[fig-1|the architecture figure]] labels the sublayer, but there is no ablation isolating the mask — nothing in the paper compares masked against unmasked pre-training. The [[token-level-perplexity|perplexity of 18.4]] shows the arrangement trained well; it does not separate the mask's contribution from anything else. The ELMo contrast is a comparison between published systems, not a controlled test.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-supervised-fine-tuning", "forId": "supervised-fine-tuning", "kind": "concept", "body": "Stage two continues training the exact weights that [[generative-pretraining|stage one]] left behind, now on a task's labelled examples. It is here because a language model emits distributions over tokens, not labels, and something has to turn its hidden states into a decision about entailment, sentiment, or which candidate answer is right.\n\n### The task head\n\nA target task supplies [[labeled-dataset-c|labelled data $C$]]: each instance is a token sequence $x_1,\\dots,x_m$ paired with one label $y$. That sequence is pushed through the same twelve pre-trained blocks used during pre-training, unchanged.\n\nThen take one vector out of the stack: the last block's output at the final position, $h_l^m$, described under [[final-token-activation]]. Multiply it by an added matrix [[linear-output-layer-wy|$W_y$]] and softmax the scores. That is the entire task-specific network, and [[eq-task-head]] is the whole of it on one line.\n\nWalk the sizes. The activation is 768-dimensional ([[hidden-state-dimension-768]]), so for a three-way inference task $W_y$ holds $768 \\times 3 = 2304$ numbers, sitting on top of roughly 117 million pre-trained parameters. Adding a task costs about two parameters in a hundred thousand — the point [[minimal-extra-parameters]] makes and [[fig-1]] draws.\n\nThe gradient, though, does not stop at $W_y$. Maximizing [[supervised-objective-l2|$L_2$]] ([[eq-supervised-objective]]) backpropagates through all twelve blocks and into the embeddings, so every pre-trained weight moves. That is the difference from [[elmo-deep-contextualized-word-representations|feature-based transfer]], where pre-trained states are frozen features handed to a task network trained from scratch. The target also flips — [[generative-vs-discriminative-training|predict the label, not the text]] — though the paper does not flip it all the way, since [[auxiliary-lm-objective|the language modelling loss keeps running]] alongside.\n\n### What it costs, and how firm the evidence is\n\nUpdating a whole 117M-parameter model on a few thousand labelled examples invites overfitting, so the budget is deliberately short: [[fine-tuning-hyperparameters]] give a learning rate of 6.25e-5, batches of 32, and three passes over the data. The paper hedges on that last number — three epochs was \"sufficient for most cases\", which leaves unnamed tasks needing more. There is also an unstated cost: since all weights change, each task ends up with its own full copy of the model.\n\nThe strongest number for why any of this works is the ablation in [[table-5]]. Training the same transformer straight on the supervised tasks, skipping pre-training, drops the average by 14.8% ([[ablation-no-pretraining]]).\n\nThat is one run per configuration, on the paper's own dataset selection, with no variance reported. The layer-transfer curve in [[fig-2]] is thinner still: dev accuracy on two datasets, rising to about 9% on MultiNLI at full transfer. It supports \"more transferred layers help\" rather than any claim about a particular layer.\n", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-auxiliary-lm-objective", "forId": "auxiliary-lm-objective", "kind": "concept", "body": "The next-token loss does not switch off when stage two begins. Fine-tuning maximizes a sum of two losses at once, written out in [[eq-combined-objective|Equation 5]]:\n\n$$L_3(C) = L_2(C) + \\lambda\\, L_1(C)$$\n\n### What actually gets computed\n\nTake one labelled example from [[labeled-dataset-c|$C$]]: a token sequence $x_1,\\dots,x_m$ and its label $y$. A single forward pass through the stack produces a hidden state at each of the $m$ positions.\n\nThe state at the last position is multiplied by the added matrix $W_y$ and softmaxed over labels. The log-probability of the correct $y$ is the classification term [[supervised-objective-l2|$L_2$]], given in [[eq-supervised-objective|Equation 4]].\n\nNow read the same sequence as ordinary text and ignore the label. At each position the hidden state is projected to vocabulary scores, and the log-probability of the token that actually came next is read off. Summed over positions, that is [[language-modeling-objective|$L_1$]] — the pre-training loss, recomputed on the task's own inputs instead of on [[bookscorpus|BooksCorpus]].\n\nBoth terms come off the same activations, so there is no second forward pass. There are no extra parameters either: the language modelling head is just [[output-softmax-tied-embeddings|the transpose of the token embedding matrix]], which the model is carrying regardless. A method with a separately learned output projection would have to keep that projection alive deliberately for this to be free.\n\nThe extra work is that the vocabulary-sized projection now runs at every position rather than only at the last one.\n\n$\\lambda$ sets the balance between the two terms. The paper uses 0.5, discussed below in [[auxiliary-objective-weight]].\n\n### Why it is here, and what it costs\n\nSection 3.2 reports two effects from including the term: better generalization of the supervised model, and faster convergence. Both are stated as findings. No mechanism is offered, and the paper points to prior work that saw similar gains from adding a language modelling term to a supervised loss.\n\nThe framing is worth pinning down. In [[auxiliary-training-objectives|the auxiliary-objective line of work]], the added unsupervised loss *is* the transfer mechanism. Here it is a secondary term sitting on top of pre-training, and the paper says pre-training has already learned much of what such an objective would otherwise supply.\n\nThe cost is a split gradient. Across three passes over the task data, part of the update is pulling towards predicting next tokens rather than labels.\n\n### How strong the evidence is\n\n[[table-5]] reruns the recipe [[ablation-no-auxiliary-objective|without the term]]. Removing it *gains* 0.3 points on average. Keeping it helps on the [[natural-language-inference]] datasets and on [[qqp]], and hurts on the smaller sets; the paper reads that as larger datasets benefiting.\n\nThis is thinner than the claim in Section 3.2. It is one run per dataset with no variance reported, and the size rule is inferred after the fact from twelve numbers. The faster-convergence claim is never measured anywhere in the paper.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-task-specific-input-transformations", "forId": "task-specific-input-transformations", "kind": "concept", "body": "Pre-training saw one thing: contiguous runs of text, read left to right. Many target tasks do not arrive in that shape, so before [[supervised-fine-tuning|stage two]] can run them through the stack, their parts have to be written out as a single ordered token stream.\n\n[[text-classification]] needs no work. A sentence already is one sequence. [[structured-inputs|The other three families]] — an ordered sentence pair for entailment, an unordered pair for similarity, a document plus question plus candidate answers for multiple choice — need a flattening rule.\n\n### The rule\n\nConcatenate the parts, and mark the seams. Every transformed input is wrapped in [[start-and-end-tokens|a randomly initialized start and end token]], and a [[delimiter-token|`$` delimiter]] sits between adjacent parts. The paper calls this a [[traversal-style-approach|traversal-style approach]], citing earlier work that walks structured input into a sequence.\n\nSo [[entailment-input-transformation|entailment]] becomes $\\langle s\\rangle\\,p\\;\\$\\;h\\,\\langle e\\rangle$ — premise tokens, delimiter, hypothesis tokens. Length is the sum of the two pieces plus three. The last position is always $\\langle e\\rangle$, which is why [[eq-task-head|the linear head]] can always read the same slot.\n\nTwo transformations do more than concatenate. [[similarity-input-transformation|Similarity]] builds both orderings and runs each through the model, then adds the two 768-dimensional final activations element-wise before the output layer. [[qa-and-commonsense-input-transformation|Question answering]] builds one sequence per candidate answer and softmaxes across their scores, so a four-option RACE question is four forward passes.\n\n### What it buys and what it costs\n\nThe paper's objection to [[task-specific-architectures|task-specific architectures]] is not that they are ugly. It is that a module built on top of transferred representations is freshly initialized, so it gets no benefit from pre-training at all. Rewriting the input instead keeps every parameter that touches the task a pre-trained one, apart from $W_y$ and the delimiter embeddings — which is the whole basis for the [[minimal-extra-parameters|small extra-parameter count]], and for the claim of a [[task-agnostic-model|single model across tasks]].\n\nThe costs are real if unmentioned. Compute per example scales with the number of candidates rather than staying at one pass. Document, question and answer must all fit inside [[context-window-512-tokens|the 512-token window]] together. And the new marker embeddings are learned from the labelled set alone, which on RTE means 2,490 examples.\n\n### How strong the evidence is\n\n[[fig-1]]'s right panel draws all four shapes side by side, but it is a specification, not a result. No experiment here isolates serialization against a task-shaped module trained the same way; the support is end-to-end, that the fine-tuned model beats task-built baselines on nine of twelve datasets. That shows the format is sufficient, not that it wins a controlled comparison. What the shared format does buy directly is clean ablation: [[ablation-lstm-substitution|swapping in an LSTM]] varies only the sequence model, since inputs and readout stay fixed ([[table-5]]).", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-task-agnostic-model", "forId": "task-agnostic-model", "kind": "concept", "body": "\"Task-agnostic\" is the claim the paper is making about its own system, not a component of it: one network, pre-trained once, fine-tuned on each of twelve datasets without any of them getting a network of its own. It sits here because everything else in the paper — the pre-training corpus, the objective, the input rewriting — is machinery in service of this one claim.\n\nConcretely, the model is a stack of twelve transformer blocks, the [[multi-layer-transformer-decoder|multi-layer transformer decoder]], with 768-dimensional states. That stack is identical for entailment, for question answering, for similarity and for sentence classification. What each task adds on top is a single matrix, the [[linear-output-layer-wy|added linear output layer $W_y$]], applied to the final block's activation at the last token.\n\nWalk the size of that. A three-way entailment task needs $W_y$ of shape $768 \\times 3$, which is 2,304 weights. Alongside it come embeddings for the delimiter tokens. The paper states these are the only extra parameters fine-tuning requires — [[minimal-extra-parameters|minimal extra fine-tuning parameters]].\n\n### Where the task-specific work went\n\nIt did not disappear. A model with no structural notion of \"sentence pair\" can only read a sentence pair if something else makes it look like ordinary text, and that is the job of [[task-specific-input-transformations|task-specific input transformations]]. Premise and hypothesis are concatenated with a delimiter between them; a document, question and candidate answer are walked into one sequence.\n\nSo the architecture is task-agnostic because the serialization is task-aware. The paper's contrast is with [[task-specific-architectures|task-specific architectures]], the prevailing practice of hand-designing a network around each task's structure. [[fig-1]] is the visual form of that argument: one block diagram on the left, four differently shaped inputs feeding it on the right.\n\n### How strong the evidence is\n\nThe headline is a count: new best published results on [[state-of-the-art-9-of-12|9 of the 12 datasets]] across [[evaluation-task-families|four task families]], including 8.9 points on the [[story-cloze-test]] and 5.7 on RACE. That count is a comparison against a different prior system on each dataset, not a controlled experiment, and each of those systems differs from this one in architecture, in pre-training data and in scale at once. It is breadth, not isolation.\n\nTwo of the misses are worth naming: [[rte]], the smallest NLI set at 2,490 examples, and [[mrpc]], where [[ablation-lstm-substitution|swapping in an LSTM]] actually helps. And [[ablation-no-pretraining|removing pre-training]] costs 14.8 average points from the same architecture, which suggests the gains come mostly from what pre-training put in the weights rather than from the architecture being shared.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-bookscorpus", "forId": "bookscorpus", "kind": "concept", "body": "BooksCorpus is the unlabelled text that stage one actually trains on: over 7,000 unpublished books spanning genres such as Adventure, Fantasy and Romance. It is here because [[generative-pretraining]] needs some corpus of tokens to run [[eq-lm-objective|its likelihood]] over, and the paper picks this one for the shape of its text rather than for its subject matter.\n\nConcretely, the raw text is cleaned and cut into subword units by the [[text-preprocessing-pipeline]], then sliced into training sequences. A minibatch is 64 randomly sampled contiguous runs of 512 tokens each, matching the [[context-window-512-tokens|512-token context window]]. Every one of those 512 positions contributes its own next-token term to the loss, so a single update carries $64 \\times 512 = 32{,}768$ predictions. Training makes 100 passes over the corpus at that rate; the schedule is spelled out in [[pretraining-schedule]].\n\n### Why the slicing matters\n\nThe word doing the work is *contiguous*. Because a book arrives as one unbroken run of sentences in their original order, a sampled window of 512 tokens is 512 tokens of the same passage. Roughly 400 words of prose, which is several paragraphs.\n\nSo a token near the end of that window has up to 511 real predecessors to condition on. Some of the information that would help predict it - who the pronoun refers to, what the scene is - sits paragraphs back. That is what [[long-range-contiguous-text]] buys, and it is how the abstract goal of modelling [[long-range-dependencies-gpt1]] becomes a data-selection decision.\n\nThe contrast the paper draws makes the point sharper. The [[one-billion-word-benchmark]] is about the same size, but shuffled sentence by sentence. Fill a 512-token window from it and the history behind any token is a run of unrelated sentences, so conditioning on anything past the current sentence boundary is noise. Same token count, and by the paper's argument a weaker training signal.\n\n### What it costs and what is shown\n\nThe corpus is fiction. The evaluation is science exam entailment, news paraphrase and [[qqp|Quora question pairs]]. Bridging that gap rests entirely on [[domain-mismatch-tolerance]], which the paper states as an assumption and does not test with a matched-domain control.\n\nThe evidence is thin in a second way too. The paper argues for contiguity but never runs the experiment: there is no ablation pre-training the same model on the shuffled corpus and comparing transfer. The only number offered is [[token-level-perplexity]], and it is measured on BooksCorpus itself. It says the model fit the text it was trained on. The paper does not connect it to any downstream result, and neither should a reader.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-model-specification", "forId": "model-specification", "kind": "concept", "body": "This is the configuration the paper actually trained, and every number it reports comes out of this one model. It fills in the free parameters that the [[multi-layer-transformer-decoder|multi-layer transformer decoder]] description leaves open: that description says what kind of network to build, not how big to build it.\n\nThe stack is twelve blocks deep ([[twelve-layer-depth]]). Each position carries a 768-dimensional vector from the embedding layer to the top of the stack ([[hidden-state-dimension-768]]). Attention inside a block splits that vector across twelve heads ([[twelve-attention-heads]]), so each head forms queries, keys and values in $768/12 = 64$ dimensions, and the twelve 64-dimensional outputs concatenate back to 768. The feed-forward sublayer widens 768 to 3072 and projects straight back down ([[position-wise-feedforward-3072]]), a factor of four out and back.\n\nWalk the weight count. Attention per block is four $768 \\times 768$ projections, about 2.4M parameters. The feed-forward sublayer is two $768 \\times 3072$ matrices, about 4.7M. That is roughly 7.1M per block, so about 85M across twelve. The [[byte-pair-encoding-gpt1|BPE]] vocabulary of roughly 40k entries adds another 31M in the embedding table, and 512 learned position slots add 0.4M. Around 117M weights in total — a number the paper itself never states.\n\n### Where it departs from the original transformer\n\nThe encoder half is gone ([[decoder-only-stack]]), and attention is masked so a position sees only itself and its past ([[masked-self-attention]]). Position information comes from a trained table rather than fixed sinusoids ([[learned-position-embeddings]]). That table has exactly 512 rows, matching the [[context-window-512-tokens|512-token window]] and going no further. The activation is [[gelu]] rather than ReLU.\n\n[[layer-normalization-gpt1|Layernorm]] is used throughout the stack, and the paper credits that for letting a plain $\\mathcal{N}(0, 0.02)$ draw serve as [[weight-initialization|initialization]] with nothing more careful layered on. That is asserted, not tested.\n\n### What supports the numbers\n\nLittle, taken as sizes. The paper says it \"largely follows\" the original transformer and then lists its numbers; there is no sweep over width, depth or head count. The one direct sign the spec fits its job is [[token-level-perplexity|token-level perplexity of 18.4]] on BooksCorpus.\n\nDepth is probed after the fact. The transfer curve in [[fig-2]] varies how many of the twelve layers are carried into fine-tuning ([[layers-transferred]]) and finds each one still adds accuracy. That argues twelve was not too many. It does not argue twelve was right.\n\nThe architecture family gets one check, in [[table-5]]: substituting a single-layer 2048-unit LSTM costs 5.6 average points ([[ablation-lstm-substitution]]). Parameter counts are not matched there, so it separates two families more than it isolates the transformer.", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [3, 4, 5, 7, 8]}}, {"id": "page-pre-training-optimization", "forId": "pre-training-optimization", "kind": "concept", "body": "The paper trains the language model with [[adam-optimizer-gpt1|Adam]], and reports the optimizer settings in the same breath as the architecture. These are the numbers that turn [[eq-lm-objective|the pre-training likelihood $L_1$]] into an actual set of weights, so they are what a reader would need to rebuild the model that every later experiment starts from.\n\nThe learning rate moves in two phases. It starts at zero and rises in a straight line to 2.5e-4 over the first 2000 parameter updates — this is [[linear-warmup|the warmup]]. From there it falls along a cosine curve, reaching zero at the moment training stops, which is [[cosine-annealing|the annealing half]].\n\nThat second phase hides a dependency worth naming. A cosine that has to land on zero needs to know in advance where the end of training is. So the length of the run is not a separate knob: [[pretraining-schedule|100 epochs over the corpus]] fixes the horizon the curve is drawn against.\n\n### What one update actually sees\n\nEach minibatch holds 64 sequences. Each sequence is a contiguous span of 512 tokens sampled at random from [[bookscorpus|BooksCorpus]] — a filled [[context-window-512-tokens|512-token context window]], not a short padded fragment.\n\nOne update therefore covers $64 \\times 512 = 32{,}768$ token positions. [[language-modeling-objective|The objective]] contributes one term per position, so each gradient is an average over 32,768 next-token predictions.\n\nRun the same arithmetic on warmup: 2000 updates times 64 sequences is 128,000 sequences, or roughly 65 million predicted tokens, passing through the model before the step size reaches full size.\n\nSampling contiguous spans rather than shuffled sentences is where the corpus choice cashes out. A 512-token window only buys long-range conditioning if the 512 tokens genuinely follow one another.\n\nThree regularizers run alongside all of this — dropout in three places, and a weight decay adapted for Adam. They are set out in [[regularization-setup|the regularization setup]], and they, rather than the schedule, are where the run's defence against overfitting sits.\n\n### How strong the evidence is\n\nThin, in the way that matters: none of these choices is ablated. The paper reports [[token-level-perplexity|a token-level perplexity of 18.4]] on the corpus, which says the run fit the data. It does not say a different schedule would have fit it worse.\n\nThe right panel of [[fig-2]] shows zero-shot task scores rising steadily across pre-training rather than stalling or collapsing, which is consistent with a stable run. It was built to argue something else, though, and is not a hyperparameter check.\n\nThe one further signal is indirect and arrives later in the paper: [[fine-tuning-lr-and-batch|fine-tuning reuses these settings]], changing only the peak learning rate — about four times smaller — the batch size, and the epoch count. The pre-training recipe was good enough to keep as the default.", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [1, 2, 3, 4, 5, 7]}}, {"id": "page-fine-tuning-hyperparameters", "forId": "fine-tuning-hyperparameters", "kind": "concept", "body": "This is the settings list for stage two: the actual optimizer configuration used when [[supervised-fine-tuning|the pre-trained stack is adapted to a labelled task]]. It is here because the paper's argument is not only that transfer works but that it is cheap, and a hyperparameter list is where \"cheap\" becomes checkable.\n\nThe stated default is inheritance. Unless the paper names an exception, fine-tuning keeps whatever [[pre-training-optimization|stage one used]] — Adam, the [[decoupled-weight-decay]] at $w = 0.01$, the residual, embedding and attention dropouts at 0.1, the same vocabulary, the same 512-token window. Nothing is frozen and nothing is re-initialized except the task head.\n\nFour things change. A fresh dropout goes on the classifier ([[classifier-dropout]]); the optimization settings drop to [[fine-tuning-lr-and-batch|6.25e-5 with batches of 32]]; the run lasts [[three-epochs-fine-tuning|three epochs]]; and the schedule becomes [[fine-tuning-lr-schedule|linear decay after a 0.2% warmup]]. The auxiliary language modelling term is carried alongside the task loss at [[auxiliary-objective-weight|$\\lambda = 0.5$]].\n\n### Warmup as a fraction, not a count\n\nPre-training warmed up over a fixed 2000 updates. Fine-tuning instead warms up over 0.2% of whatever the run turns out to be, which makes the same line of configuration mean different things on different datasets.\n\nWalk it. [[snli|SNLI]] has roughly 550k training examples, so three epochs at batch 32 is about $550{,}000 \\times 3 / 32 \\approx 51{,}500$ updates, and 0.2% of that is around 100 warmup steps. [[rte|RTE]] has 2490 examples, giving about 233 updates in total, so its warmup is well under a single step.\n\nOn the small datasets, then, the warmup is decoration. One expression covers twelve datasets without per-task tuning, and that uniformity is the point.\n\n### What the numbers rest on\n\nThe contrast the paper wants is with methods like [[ulmfit|ULMFiT]], which adapts a pre-trained LSTM through a staged schedule of unfreezing and per-layer rates. Here every layer moves at one rate for three passes. The paper groups staged schemes with the intricacy it is trying to avoid.\n\nThe evidence is indirect. No ablation varies the learning rate, the epoch count or the warmup fraction; [[table-5]] ablates the auxiliary objective, the architecture and pre-training itself, not these settings. Support for \"3 epochs was sufficient\" is just that the reported [[evaluation-task-families|benchmark numbers]] were produced under it.\n\nAnd the hedges are doing work. \"For most tasks\" and \"for most cases\" concede that some runs used something else, and the paper does not say which tasks deviated or what they used instead.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-evaluation-task-families", "forId": "evaluation-task-families", "kind": "concept", "body": "This is the paper's evaluation menu: the fixed list of supervised tasks the single pre-trained model is asked to do. It exists because the claim being tested is breadth — that one set of weights, adapted cheaply, competes with systems built one per task — and breadth can only be shown by measuring on many tasks at once.\n\n### What varies across the twelve runs, and what does not\n\nThe twelve datasets are grouped into four families, laid out in [[table-1]]. [[natural-language-inference|Natural language inference]] takes five of them, [[question-answering-and-commonsense-reasoning|question answering and commonsense reasoning]] two, [[semantic-similarity]] three, and [[text-classification]] two. Five plus two plus three plus two is twelve. Several are pulled from the [[glue-benchmark|GLUE]] bundle, which is why an aggregate GLUE score can also be reported.\n\nEach dataset gets its own fine-tuning run, so there are twelve fine-tuned models, not one. But they all start from the same pre-trained weights, and what differs between runs is small: the [[task-specific-input-transformations|input transformation]] that flattens a premise-hypothesis pair or a document-question-answer triplet into one token sequence, and the [[linear-output-layer-wy|linear output layer]] sized to that task's label set. The stack itself is untouched, which is what [[supervised-fine-tuning]] describes.\n\n### What the spread buys and what it costs\n\nThe datasets differ by about two orders of magnitude in size, from roughly 5.7k training examples on [[sts-b|STS-B]] to roughly 550k on [[snli|SNLI]]. The paper uses that range to head off the obvious objection that pre-training only pays on tasks that already have plenty of labels.\n\nThe headline is [[state-of-the-art-9-of-12|nine of twelve]]. The three that are not beaten are informative: [[rte|RTE]], where 56% falls short of 61.7% from a multi-task biLSTM, [[sst-2|SST-2]] at 91.3%, described as competitive rather than better, and [[mrpc|MRPC]]. The paper offers a guess for RTE — that its model would likely also benefit from multi-task training — and says plainly it did not try.\n\nRead the numbers with some care. Each is a single run against a single previously published best, with no variance reported and no shared training budget across the [[baseline-comparisons|baselines]], some of which are ensembles and some single models. Gains are stated as [[absolute-improvement|percentage-point differences]], which flatters a task with a low ceiling and understates one near saturation. What the table supports well is that the recipe does not collapse on any family of [[natural-language-understanding|language understanding]] task tried; the per-dataset margins carry less weight than the count.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-layers-transferred", "forId": "layers-transferred", "kind": "concept", "body": "Fine-tuning does not have to start from the whole pre-trained network. This analysis turns the amount transferred into a dial, and measures what each turn of it buys.\n\nThe dial has thirteen settings. At zero, nothing but the embeddings comes across from pre-training: the token table $W_e$ and the position table $W_p$ that together form the layer-zero input [[input-representation-h0|$h_0$]]. At twelve, every block of the stack comes across as well, which is the ordinary [[supervised-fine-tuning|fine-tuning]] setup. The settings in between carry the bottom $k$ blocks and leave the remaining $12-k$ to be initialized fresh, though the paper does not spell that detail out. The sweep only has this many settings because the model is [[twelve-layer-depth|twelve blocks deep]]; a shallower stack would give a shorter curve and less room for a trend to appear.\n\nEach setting is then fine-tuned normally and scored on the development sets of [[multinli|MultiNLI]] and [[race-dataset|RACE]].\n\n### What the curve shows\n\nThe result is the left panel of [[fig-2]]. Accuracy rises with $k$ rather than flattening after the first block or two, and the gap between zero layers and full transfer reaches about 9% on MultiNLI.\n\nThe first part of that is the expected part. Carrying a pre-trained embedding table into a supervised model is [[word-embedding-transfer|long-standing practice]], and the paper calls the gain from it the standard result.\n\nThe rest is the argument. If most of the transferable content lived in the embeddings, the curve would climb early and then level off. It does not, so the paper reads each layer as containing useful functionality for the target task.\n\n### How much this carries\n\nThe claim is stated carefully in the paper, and it is worth keeping it that careful. What is measured is end accuracy at each setting, not what any individual layer holds; \"useful functionality\" is an inference from the shape of a curve, not something the experiment isolates.\n\nThe evidence is also thin in the ordinary ways. It is one figure, two datasets, development accuracy, and no reported repeats or variance across seeds. The 9% is the best case at the best setting on one of the two tasks, not a typical figure — RACE gains less.\n\nRead against the [[ablation-no-pretraining|no-pre-training ablation]], which costs 14.8% on average, the ranking is consistent: pre-training matters most, and depth of transfer accounts for a substantial share of it.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-zero-shot-behaviors", "forId": "zero-shot-behaviors", "kind": "concept", "body": "The paper wants an explanation, not only a scoreboard: why does [[generative-pretraining|generative pre-training]] of a transformer transfer so well? Its stated hypothesis is that the generative model learns to do many of the evaluation tasks in the course of getting better at predicting the next token, and this analysis is the attempt to look at that directly.\n\nThe test removes the supervised half of the recipe. There is no [[supervised-fine-tuning|fine-tuning]], no trained classifier head and no labelled data — the pre-trained model has to produce answers as it stands.\n\n### Turning the model into a scorer\n\nThat is not free, because a language model does not emit labels. It emits a distribution over the vocabulary at each position. So each task needs a hand-written rule that converts *what probability do you assign this string* into *which option do you pick*.\n\nThree of the four rules use the same device, [[average-token-log-probability-scoring|average token log-probability]]. Take a candidate string of $m$ tokens. Sum the log-probabilities the model gives those tokens, under the same likelihood [[eq-lm-objective|$L_1$]] it was trained on. Divide by $m$.\n\nThe division is doing work. Every extra token adds a negative number, so a raw sum systematically favours the shortest candidate. The mean takes that length effect out, which matters when the options are answers of different lengths.\n\nFrom there the four settings differ. [[cola-zero-shot-heuristic|CoLA]] thresholds the score of a single sentence. [[race-zero-shot-heuristic|RACE]] takes the highest-scoring answer given the document and question. [[dprd-winograd-heuristic|DPRD]] compares the two pronoun substitutions. [[sst2-zero-shot-heuristic|SST-2]] is the one that does not use a mean at all, and instead reads off a restricted two-word output distribution.\n\n### What the curves support\n\nEach heuristic is then run at checkpoints across pre-training and plotted against updates, in the right panel of [[fig-2]]. The reported pattern is that the scores are stable and rise steadily. The paper reads that as pre-training supporting task-relevant functionality, rather than fine-tuning building it — the same direction as [[layers-transferred|the layer-transfer curve]] on the left.\n\nThe same heuristics were run on an [[lstm-gpt1|LSTM]] trained in the same framework, which the paper says shows higher variance across pre-training. That single observation is the whole support for [[transformer-inductive-bias]], and the paper words it as a suggestion.\n\nBe clear about the strength. The heuristics are the authors' own inventions, so an absolute number says as much about the rule as about the model, and the curves are trends rather than competitive task scores. There are four settings, one of them (DPRD) outside the twelve evaluation datasets. \"Higher variance\" is read off a plot with no interval attached. This diagnostic carries less weight than the [[ablation-studies|ablation]] numbers.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-ablation-studies", "forId": "ablation-studies", "kind": "concept", "body": "The benchmark tables show the full recipe winning. [[table-5]] is the paper's attempt to find out which parts of the recipe are responsible, by building three cut-down versions of the system and running each one through the same evaluation.\n\nEvery ablation is a separate end-to-end training run. One piece is removed or replaced, everything else — the serialized inputs, the last-token readout, the fine-tuning schedule — is held fixed, and the resulting scores are compared against the full model on an unweighted average across the tasks in the table.\n\nThe first removal deletes stage one. [[ablation-no-pretraining|Skipping pre-training]] keeps the same 12-layer decoder and trains it straight on each labelled dataset, so the weights it starts from are random rather than inherited from [[generative-pretraining|generative pre-training]]. That costs 14.8%, and the paper reports it hurting on every task, not just on average.\n\nThe second removal keeps the two stages and changes the sequence model. [[ablation-lstm-substitution|Substituting an LSTM]] puts a single-layer, 2048-unit recurrent net where the [[multi-layer-transformer-decoder|transformer decoder]] was. The average falls by 5.6 points, and [[mrpc|MRPC]] is the one dataset where the LSTM comes out ahead.\n\nThe third removal touches only the loss. [[ablation-no-auxiliary-objective|Dropping the auxiliary objective]] switches off the $\\lambda L_1$ term that [[auxiliary-lm-objective|keeps language modelling alive during fine-tuning]], leaving the label loss alone in [[supervised-fine-tuning|stage two]]. Removing it gains 0.3 on average. It helps on [[qqp]] and the NLI sets and hurts on the smaller ones, which the paper reads as a size-dependent effect.\n\nPut the three numbers side by side and an ordering falls out. 14.8 against 5.6 is roughly three to one, so on this evidence the pre-training matters about three times as much as the architecture choice it runs on. The third effect is not even reliably positive; the aggregate mildly favours removing the term the paper chose to keep.\n\n### How much weight the numbers carry\n\nEach row is one training run at one setting. There are no seeds, no error bars, and no sweep behind them, so a few points of average score is a soft measurement.\n\nThe architecture comparison is the loosest of the three. A single-layer 2048-unit LSTM differs from a twelve-layer transformer in depth and parameter count as well as in recurrence, so 5.6 points is not cleanly attributable to attention alone.\n\nThe auxiliary result is confounded in a different way: [[auxiliary-objective-weight|$\\lambda$ is fixed at 0.5]] everywhere, so a term whose sign of effect tracks dataset size is being applied at one strength across all of them.\n\nThe no-pre-training row is the cleanest and the largest, and it is the number the rest of the paper leans on.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "page-relations-gpt-1", "forId": "gpt-1", "kind": "relations", "body": "GPT-1 trains a single transformer decoder to predict the next token over 7,000-plus unpublished books, then keeps those weights and fine-tunes them, with one linear layer on top, on twelve labelled datasets. Most of the machinery inside that network was defined in other papers; what this paper puts forward is the [[two-stage-training-procedure]] and the input rewrites that let one unchanged architecture cover four task families.\n\n### What it takes from papers already here\n\nThe backbone is the architecture of [[transformer]], adopted more or less wholesale: Section 4.1 says the model \"largely follows the original transformer work\" and then records only the deltas. What GPT-1 keeps is the [[decoder-stack]]'s pair of sublayers — masked multi-head self-attention, then a position-wise feed-forward network — and what it drops is [[encoder-decoder-attention]], because there is no encoder for it to read. That cut is not described in GPT-1 either; Section 3.1 cites [34] for it, where deleting the encoder module and leaving one stack is set out as [[transformer-decoder-t-d]]. The motivation there is [[transduction-as-single-sequence-lm]]: concatenate source and target into one stream with a separator and train a plain language model on it. GPT-1 takes the shape and not the motivation. Its stream is contiguous book text, and its [[model-specification]] fills the shape in at 12 layers, 768-dimensional states, 12 heads and 3072-dimensional feed-forward inner states.\n\nTokenization is a merge count and nothing more. GPT-1 says it used \"a bytepair encoding (BPE) vocabulary with 40,000 merges\" and moves on. The greedy loop that produces those merges is [[bpe-merge-algorithm]], and the reason a merge count is a sufficient specification is [[bpe-vocabulary-size]]: the final symbol vocabulary is the initial character vocabulary plus the number of merges, and that count is the algorithm's only knob. The unit matters for reading GPT-1's numbers — the token-level [[perplexity]] of 18.4 on BooksCorpus is measured in 40,000-merge subwords, not words.\n\nThree more pieces are named and left undefined. GPT-1 uses [[gelu]] at the 3072-dimensional point of every feed-forward sublayer without writing the formula down; [[gelu-definition]] gives it as $x \\cdot \\Phi(x)$, [[gelu-tanh-approximation]] gives the cheap substitute most implementations actually run, and [[gelu-vs-relu-and-elu]] is where it is placed against the [[relu]] the original transformer used. The optimizer line is similar: \"a modified version of L2 regularization proposed in [37], with $w = 0.01$ on all non bias or gain weights\". What the modification is, and why an adaptive step size makes L2 and weight decay come apart, is [[adaptive-preconditioner-dilutes-l2]]; the resulting update is [[decoupled-weight-decay-update]]. And the serialization that makes [[task-specific-input-transformations]] possible — premise, delimiter, hypothesis, read as one left-to-right stream — is [[conditional-encoding]], with the separator token itself as [[premise-hypothesis-delimiter]] and the read-off-the-last-vector classifier as [[last-output-vector-classifier]]. That paper's own reader is an LSTM; GPT-1 borrows the serialization, not the architecture.\n\nLayer normalization is the odd one. GPT-1 mentions it once, as a justification rather than a component: \"since layernorm [2] is used extensively throughout the model, a simple [[weight-initialization]] of $N(0, 0.02)$ was sufficient\". The scheme itself is [[layer-normalization-statistics]], and the closest thing to a reason for that inference is [[normalization-invariance-properties]] — the network's output is invariant to rescaling a whole weight matrix. But neither paper runs the initialization experiment. GPT-1 asserts sufficiency in one clause and reports no sweep over it.\n\nSome of what GPT-1 leans on has no paper here at all. Adam is cited to Kingma & Ba, which is not in this project; [[adam-optimizer]] appears only as a one-line description in the transformer paper, so the update rule behind GPT-1's 2.5e-4 cosine schedule is not covered. Nor is the semi-supervised line the paper places itself in — ELMo, ULMFiT, Dai and Le, pre-trained word vectors — or any of the twelve evaluation datasets.\n\n### Where it diverges, and where it goes elsewhere\n\nAgainst [[encoder-decoder-architecture]] the difference is not a tweak. That design exists to do [[sequence-transduction]]: an encoder reads a source sequence with unmasked attention, and a decoder generates a target while attending back into it. GPT-1 has no source sequence. It has one stack with [[masked-self-attention]] at every layer, trained to continue text, and then bent to twelve tasks whose output is a label from a linear layer. The consequence is the whole of Section 3.3. With no encoder to hand structure to, anything a task needs — a premise and a hypothesis, a document and a question and four candidate answers — has to be flattened into the one stream the pre-trained model can read.\n\nPositions diverge in the other direction, and this one is a swap rather than a cut. The original scheme is [[sinusoidal-positional-encoding]], fixed rather than trained, and that paper gives a reason for the fixed form: it may let the model extrapolate to sequence lengths longer than those seen in training. GPT-1 uses [[learned-position-embeddings]] instead — the [[learned-positional-embedding]] alternative the transformer paper reports as producing nearly identical translation results. The consequence is a table with one row per position, sized to GPT-1's 512-token training spans, learned from the pre-training corpus like any other parameter.\n\nThe evidence differs too, and so does what counts as success. The transformer is scored in [[bleu]] on [[wmt-2014-en-de]] and [[wmt-2014-en-fr]], with [[constituency-parsing]] as its one test outside translation — still a sequence generated from a sequence. GPT-1 reports accuracy and correlation across [[evaluation-task-families]]: entailment, [[question-answering-and-commonsense-reasoning]], [[semantic-similarity]], and classification. Neither set of numbers can be read against the other. Even the training data is chosen for a different property: GPT-1 takes contiguous 512-token spans from books over the same-sized 1B Word Benchmark precisely because sentence-level shuffling destroys the long-range structure it wants to condition on.\n\n### What this does not establish\n\nNone of these papers were run against each other. No shared model, corpus, or metric connects them, and nothing here is an ablation: removing GELU or learned positions from GPT-1 was not tested, so their contribution to its results is not measured by anything on this page. Reading a mechanism in the paper that defines it tells you what GPT-1 turned on, and at which setting. It does not tell you how much that setting bought.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "narrative": {"title": "One Pre-Trained Stack, Twelve Tasks", "chapters": [{"id": "the-mismatch", "title": "The Mismatch, and the Claim", "body": "Labelled data for a language task is made by people. Someone reads a pair of sentences and writes down whether the second follows from the first. That is slow, and it costs money, so the datasets stay small ([[labeled-data-scarcity]]).\n\nRaw text has no such ceiling. There is far more of it than anyone could annotate.\n\nThe paper gathers a spread of tasks under one heading — entailment, question answering, sentence similarity, document classification — and calls the set [[natural-language-understanding]]. Each has its own dataset and its own idea of a correct answer. The standard treatment trains a network to predict the label directly from the input, which is [[generative-vs-discriminative-training|discriminative training]]. The scarce labels then have to pay for everything the network learns, down to how sentences are put together.\n\nThe alternative is to learn from raw text first, and spend the labels on the task alone. The paper says two things stood in the way of doing that. Nobody knew which unsupervised objective produced representations that transfer well ([[choice-of-pretraining-objective]]). And nobody agreed on how to move a learned representation into a target task once you had one ([[how-to-transfer-representations]]).\n\nWhat is offered here is a [[two-stage-training-procedure]]. Train a language model on unlabelled text. Then keep those weights and go on training the same network on the labelled task.\n\nThe network is the [[transformer-gpt1|transformer]] of prior work, not a new design. Nothing is frozen, and no task-shaped module is bolted on top.\n\nThe claim is that this beats systems built by hand for each individual task. The paper reports new best published numbers on [[state-of-the-art-9-of-12|nine of the twelve datasets]] it measures, its largest margins being 8.9 points on commonsense story completion and 5.7 on exam-style reading comprehension.\n\n[[theme-the-problem-and-the-open-questions|The problem and the two open questions]] have their own page.", "childId": "n-the-mismatch", "number": "1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "which-family-this-joins", "title": "Which Family This Joins", "body": "Using unlabelled text to help a supervised task was already ordinary practice. So the related work section has one job: name the family, cut it into branches, and say which branch this is.\n\nThe family is [[semi-supervised-learning-for-nlp]] — a large unlabelled corpus alongside a small labelled one. Its best-known members train one vector per word on raw text and reuse that table inside a task model ([[word-embedding-transfer]]). The paper grants that this works, then notes it carries word-level information only. Later work pushed upward to [[phrase-and-sentence-embeddings]], one vector for a longer span.\n\nCut the family a second way, by what the unlabelled data is allowed to change. One branch adds a second unsupervised loss beside the supervised one ([[auxiliary-training-objectives]]), so the training objective itself changes. The other leaves the objective alone and uses unlabelled data only to choose where optimization starts ([[unsupervised-pretraining]]). A cited result there says the benefit is not only easier optimization: the starting point also generalizes better ([[pretraining-as-regularization]]).\n\nThe paper sits in that second branch, and splits it once more.\n\n[[feature-based-transfer]] freezes the pre-trained model and feeds its hidden states into a separate task network as extra inputs; [[elmo-deep-contextualized-word-representations|ELMo]] is the example named. The objection is [[per-task-parameter-cost]]. The task network is built fresh for every task, so each task pays for a substantial set of newly initialized parameters.\n\nThe line the paper calls closest to its own carries the weights themselves forward instead ([[lm-pretraining-then-finetuning-predecessors]]). [[semi-supervised-sequence-learning]] did this with a recurrent network for [[text-classification]], and [[ulmfit]] with a staged fine-tuning schedule for the same kind of task.\n\nSo the disagreement is not about the recipe. It is about the architecture and the reach. The paper argues a recurrent pre-trained model keeps its predictions local ([[lstm-short-range-limitation]]), and that it evaluates on far more than classification.\n\n[[theme-where-this-sits-in-prior-work|The full map of branches]] goes deeper.", "childId": "n-which-family-this-joins", "number": "2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "one-set-of-weights-used-twice", "title": "One Set of Weights, Used Twice", "body": "The recipe in outline. Stage one, [[generative-pretraining]]: fit a language model to a large unlabelled corpus, and keep the weights rather than any text it generates. Stage two, [[supervised-fine-tuning]]: take those exact weights as the initialization and go on training them on a task's labelled examples.\n\nThat is all [[transfer-learning|the transfer]] amounts to here. No layer is frozen. The pre-trained model is not consulted from outside as a feature extractor — it becomes the task model.\n\nTwo consequences follow, and the paper leans on both.\n\nFirst, the same stack is what gets fine-tuned every time. That is what it means by a [[task-agnostic-model]], and the comparison it wants is against [[task-specific-architectures]]: networks designed around one task's structure, which is what most of the published baselines are.\n\nSecond, the pre-training text need not resemble the task text. The paper states that the target tasks are not required to be in the same domain as the unlabelled corpus ([[domain-mismatch-tolerance]]). Books are the pre-training text; the evaluation includes science exams, news, image captions and Wikipedia.\n\nThat is an assumption stated, not a result shown. No matched-domain corpus is run as a control.\n\nWhat remains to specify is what stage one optimizes, what network it optimizes, and what stage two does with the result. The next chapters take those in order.\n\n[[theme-one-model-two-stages|The two-stage recipe]], and [[etheme-scarce-labels-borrowed-weights|the line from scarce labels to borrowed weights]].", "childId": "n-one-set-of-weights-used-twice", "number": "3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 7, 8]}}, {"id": "predicting-the-next-token", "title": "Predicting the Next Token", "body": "Stage one has no labels, so the training signal has to come out of the text itself. The paper takes the oldest one available: given the tokens so far, predict the one that comes next.\n\nWritten down, that is [[eq-lm-objective|Equation 1]]. Over an unlabelled corpus of tokens $\\mathcal{U}$, maximize\n\n$$L_1(\\mathcal{U}) = \\sum_i \\log P(u_i \\mid u_{i-k},\\dots,u_{i-1};\\Theta)$$\n\nRead it position by position. At each $i$ the network sees the $k$ tokens before it and produces a distribution over the vocabulary. The number added into the sum is the log-probability it gave the token that actually appeared.\n\nThis is [[maximum-likelihood-training|maximum likelihood]] applied to text, and it is the whole of stage one. Every parameter the model has is set by pushing this single sum up ([[language-modeling-objective]]).\n\nThe network is a [[multi-layer-transformer-decoder]]: the transformer block of prior work with the encoder half removed, leaving one stack that reads only its own past ([[decoder-only-stack]]).\n\nThat removal is load-bearing. The objective scores every position at once, and a position must not see the token it is being asked to predict. [[masked-self-attention]] enforces it — each position attends to itself and to earlier positions, never to later ones. Without the mask the loss would be trivial to drive down and would teach nothing.\n\n[[eq-decoder-stack|Equation 2]] writes the network out in three lines. Embed the context tokens and add position vectors, giving $h_0 = UW_e + W_p$ ([[input-representation-h0]]). $W_e$ is the [[token-embedding-matrix]]; $W_p$ is a trained table with one vector per slot ([[learned-position-embeddings]]) rather than the fixed sinusoids of the original transformer. Push the result through $n$ identical blocks. Multiply the top layer by $W_e^{\\mathsf{T}}$ and softmax ([[output-softmax-tied-embeddings]]), so the matrix that turns tokens into vectors also turns vectors back into token scores.\n\n[[theme-stage-one-next-token-prediction|Stage one in full]], and [[etheme-the-next-token-machine|the loss and the network taken as one argument]].", "childId": "n-predicting-the-next-token", "number": "4", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [1, 2, 3, 4, 5]}}, {"id": "the-corpus-and-the-training-run", "title": "The Corpus, the Model, the Run", "body": "The objective says what to maximize. It does not say over what text, in what units, or with which optimizer.\n\nThe corpus is [[bookscorpus]]: over 7,000 unpublished books across genres. The stated reason for choosing it is not size. It is that a book keeps its sentences in their original order across paragraphs ([[long-range-contiguous-text]]).\n\nThe comparison makes the point. The [[one-billion-word-benchmark|1B Word Benchmark]] is about the same size, and is the corpus ELMo used, but it is shuffled sentence by sentence. Shuffling leaves the word statistics intact and destroys everything above the sentence.\n\nThat matters because of how much the model may look at. The context window $k$ is fixed at 512 tokens ([[context-window-512-tokens]]). 512 tokens is several paragraphs, so a prediction can condition on material from well before the current sentence — the [[long-range-dependencies-gpt1|far-apart relations]] the paper wants learned. A window that wide only earns its cost if the text inside it is genuinely continuous.\n\nText becomes tokens in three steps ([[text-preprocessing-pipeline]]): clean the raw text, tokenize it, then cut the tokens into subword units with [[byte-pair-encoding-gpt1|byte-pair encoding]]. BPE starts from characters and repeatedly merges the most frequent adjacent pair. The count of merges is the single knob, set to [[bpe-merges-40000|40,000]] — enough that common words survive whole while rare ones break into pieces seen elsewhere.\n\nThe trained model is 12 blocks deep, with [[hidden-state-dimension-768|768-dimensional states]], [[twelve-attention-heads|12 attention heads]] and a [[position-wise-feedforward-3072|3072-dimensional]] inner feed-forward layer ([[model-specification]]). The numbers are related: 768 split across 12 heads leaves each head a 64-dimensional subspace, and 3072 is four times 768. [[twelve-layer-depth|The depth of 12]] is also what makes a later experiment possible — you can transfer 0 through 12 layers and watch what happens. [[gelu|GELU]] stands in for ReLU as the activation.\n\nThe run uses [[adam-optimizer-gpt1|Adam]] at a peak rate of 2.5e-4, [[linear-warmup|raised from zero over 2000 updates]] then [[cosine-annealing|annealed back to zero on a cosine curve]], for [[pretraining-schedule|100 passes]] over minibatches of 64 sequences ([[pre-training-optimization]]). Dropout in three places and a [[decoupled-weight-decay]] do the regularizing ([[regularization-setup]]).\n\nThe reported outcome is one number: [[token-level-perplexity|18.4]] token-level perplexity on the corpus. It says the model fit the books. It says nothing yet about any task.\n\n[[theme-corpus-tokens-and-training-setup|Corpus, tokens and setup]]; [[etheme-the-long-range-bet|the bet on long stretches of text]].", "childId": "n-the-corpus-and-the-training-run", "number": "5", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "from-language-model-to-classifier", "title": "From Language Model to Classifier", "body": "Stage two has to turn a next-token predictor into a label predictor, the same way for every task.\n\nThe labelled data is [[labeled-dataset-c|$\\mathcal{C}$]]: each instance is a token sequence $x_1,\\dots,x_m$ paired with one label $y$.\n\nRun the sequence through the pre-trained stack. Take the final block's activation at the last token ([[final-token-activation]]) — one vector, which has attended over everything before it. Multiply it by one added matrix $W_y$ ([[linear-output-layer-wy]]) and softmax. That is [[eq-task-head|Equation 3]], and it is the entire task-specific classifier.\n\nThe loss is then ordinary supervised likelihood: sum $\\log P(y \\mid x_1,\\dots,x_m)$ over the labelled data ([[eq-supervised-objective|Equation 4]], [[supervised-objective-l2|$L_2$]]).\n\nThe paper does not stop there. It keeps the language modelling loss running during fine-tuning, computed on the labelled task data, and adds it in ([[auxiliary-lm-objective]]):\n\n$$L_3(\\mathcal{C}) = L_2(\\mathcal{C}) + \\lambda\\, L_1(\\mathcal{C})$$\n\nwith [[auxiliary-objective-weight|$\\lambda = 0.5$]] ([[eq-combined-objective]]). The stated reasons are better generalization and faster convergence.\n\nNotice what has happened. This is the auxiliary-objective idea the related work described as a rival branch, used here on top of pre-training instead of in place of it. The last chapter reports what happens when it is taken away, and the answer is not uniform.\n\nFine-tuning is short. Most tasks use a learning rate of 6.25e-5, about four times smaller than pre-training's peak, at batch size 32 ([[fine-tuning-lr-and-batch]]). The rate warms up over the first 0.2% of updates and then decays linearly to zero ([[fine-tuning-lr-schedule]]). [[three-epochs-fine-tuning|Three passes]] over a task's training set sufficed for most datasets, with [[classifier-dropout|dropout 0.1]] on the added head and everything else inherited from stage one ([[fine-tuning-hyperparameters]]).\n\n[[theme-stage-two-fine-tuning-and-input-shapes|Stage two in full]].", "childId": "n-from-language-model-to-classifier", "number": "6", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "one-sequence-per-task", "title": "One Sequence Per Task", "body": "A decoder reads one ordered run of tokens. Several of these tasks do not hand over one run of tokens. Entailment gives an ordered sentence pair; reading comprehension gives a document, a question and a list of candidate answers ([[structured-inputs]]).\n\nThere are two places to absorb that difference. Prior work absorbs it in the architecture, building a module shaped like the task and stacking it on the transferred representation. The paper's objection is that this puts per-task design back in, and that the new module gets nothing from pre-training.\n\nSo it absorbs the difference in the input ([[task-specific-input-transformations]]). Each structured input is walked into a single sequence ([[traversal-style-approach]]), bracketed by a randomly initialized start and end token ([[start-and-end-tokens]]) and split by a `$` [[delimiter-token|delimiter]].\n\nEntailment becomes premise, delimiter, hypothesis, read as one sequence ([[entailment-input-transformation]]).\n\nSimilarity has no natural order between its two sentences. So both orderings are built and run through the stack separately, and the two final activations are added element-wise before the linear layer ([[similarity-input-transformation]]).\n\nQuestion answering builds one sequence per candidate — document, question, delimiter, that answer. Each is scored on its own, and the scores are softmaxed across candidates ([[qa-and-commonsense-input-transformation]]).\n\n[[fig-1]] draws all four shapes beside the block they feed.\n\nThis is what keeps the parameter count small. The only weights a new task adds are $W_y$ and embeddings for the delimiter tokens ([[minimal-extra-parameters]]), which is the paper's direct answer to the per-task cost it charged against [[feature-based-transfer|feature-based transfer]].\n\nIt is also what makes the evaluation menu possible: [[evaluation-task-families|four families across twelve datasets]], listed in [[table-1]], several drawn from the [[glue-benchmark|GLUE]] bundle.\n\n[[etheme-one-stack-any-input-shape|One stack, any input shape]].", "childId": "n-one-sequence-per-task", "number": "7", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}], "pages": [1, 2, 3, 4, 5, 6, 7]}}, {"id": "the-scoreboard", "title": "The Scoreboard", "body": "Gains are reported as [[absolute-improvement|differences in percentage points]] against the previous best published number, not as relative error reduction. On the other side are mostly biLSTMs built for the individual task, some with attention, some with ELMo features, some ensembles ([[baseline-comparisons]]).\n\n[[natural-language-inference]] asks for a judgement on a premise and hypothesis: entailment, contradiction or neutral. Five datasets, in [[table-2]]. The fine-tuned model leads on four — 1.5 points on [[multinli|MultiNLI]], 5 on [[scitail|SciTail]], 5.8 on [[qnli|QNLI]], and 0.6 on [[snli|SNLI]], the largest set at roughly 550k training pairs.\n\nIt loses the fifth. [[rte|RTE]] has 2,490 training examples, and the model reaches 56% against 61.7% from a multi-task biLSTM. The paper's reading is that its approach would probably also benefit from multi-task training, and it says it has not tried.\n\n[[question-answering-and-commonsense-reasoning|Reading and commonsense reasoning]] give the widest margins ([[table-3]]). On [[race-dataset|RACE]], middle- and high-school exam passages with questions, the gain is 5.7 points overall. On the [[story-cloze-test|Story Cloze Test]], choosing the right ending to a short story from two options, it is 8.9. Both reward conditioning on a long passage, which is what the corpus and the 512-token window were chosen for.\n\n[[semantic-similarity]] and [[text-classification]] fill out [[table-4]]. [[qqp|Quora Question Pairs]] gains 4.2 points over a single-task biLSTM with ELMo and attention. [[sts-b|STS-B]], the smallest set in the evaluation at about 5.7k examples, gains 1 point. On [[cola|CoLA]], expert judgements of whether a sentence is grammatical, the score is 45.4 against a previous best of 35.0 — a jump of 10.4 points, the widest gap on the board. On [[sst-2|SST-2]] sentiment the model reaches 91.3%, which the paper calls competitive rather than best. The overall GLUE score is 72.8 against a previous 68.9.\n\nCounted up: new best published results on [[state-of-the-art-9-of-12|nine of twelve datasets]], over training sets spanning two orders of magnitude in size.\n\n[[theme-what-the-twelve-datasets-show|Dataset by dataset]]; [[etheme-the-scoreboard-and-its-gaps|the scoreboard and its gaps]].", "childId": "n-the-scoreboard", "number": "8", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "which-parts-do-the-work", "title": "Which Parts Do the Work, and What Is Left Open", "body": "The results say the recipe works. They do not say which part of it works. The analysis section asks three times.\n\nFirst, how much of the stack is worth carrying. Fine-tune with the embeddings alone transferred, then with one block, then two, up to all twelve, and plot dev accuracy ([[layers-transferred]], left panel of [[fig-2]]). Accuracy climbs with each added layer, up to 9 points on MultiNLI at full transfer. Nothing saturates early. The reading offered is that every layer holds something a target task can use, so moving embeddings alone leaves most of the value behind.\n\nSecond, what the model can already do with no fine-tuning at all ([[zero-shot-behaviors]]). A generative model does not emit labels, so each task is turned into a scoring problem. Three of four heuristics use the same device — the mean log-probability the model assigns a candidate string ([[average-token-log-probability-scoring]]). Threshold that score for grammatical acceptability ([[cola-zero-shot-heuristic]]); pick the highest-scoring answer given document and question ([[race-zero-shot-heuristic]]); or substitute each candidate referent for a pronoun and keep the reading that scores better ([[dprd-winograd-heuristic]]). Sentiment is done differently: append the token *very*, restrict the output to *positive* and *negative*, take the higher ([[sst2-zero-shot-heuristic]]).\n\nTracked across pre-training, all four rise steadily and stay stable. The paper reads that as pre-training picking up task-relevant behaviour on its way to better next-token prediction. An LSTM run the same way is noisier, offered as support for [[transformer-inductive-bias|the transformer's more structured memory helping transfer]] — a hypothesis resting on one comparison.\n\nThird, the removals ([[ablation-studies]], [[table-5]]). Training the same transformer straight on the labelled tasks with no pre-training costs 14.8 average points and hurts on every task ([[ablation-no-pretraining]]). That is the strongest single number in the paper. Swapping the transformer for a single-layer 2048-unit LSTM costs 5.6, and the LSTM wins on exactly one dataset, [[mrpc|MRPC]] ([[ablation-lstm-substitution]]).\n\nThe third removal is the awkward one. Dropping the auxiliary language modelling loss during fine-tuning does not simply degrade the model — it helps on some datasets and hurts on others ([[ablation-no-auxiliary-objective]]). The paper reads the pattern as larger datasets benefiting from the loss and smaller ones not.\n\n### What is established, and what is not\n\nPre-training on unlabelled books and then fine-tuning the same weights beats task-built systems on nine of twelve datasets, and the no-pre-training row says most of that comes from stage one. Depth keeps paying across all twelve layers on the two datasets swept. Those are the results that hold their weight.\n\nThe gaps are visible in the paper's own numbers. RTE, the smallest inference set, is a loss, and the explanation given — that multi-task training would help — is not tested here. The auxiliary loss is part of the recipe but its own ablation shows it helping only on the larger sets, a trend drawn from twelve points with no repeated runs. Every number is a single run against a published best, with no variance reported on either side. And the GLUE figure does not sit still: the results section compares 72.8 against 68.9, a difference of 3.9, while the introduction's headline for GLUE is 5.5.\n\nThe conclusion also reaches past the experiments, saying the model acquires [[world-knowledge|significant world knowledge]] from predicting text. Nothing in the evaluation separates knowledge from the reading ability these tasks also reward.\n\n[[theme-taking-the-recipe-apart|The three diagnostics]], [[etheme-watching-pre-training-work|what pre-training is doing]], and [[etheme-two-losses-and-three-removals|the two losses and the three removals]].", "childId": "n-which-parts-do-the-work", "number": "9", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}], "nodes": {"n-the-mismatch": {"id": "n-the-mismatch", "parentId": "root", "parentChapterId": "the-mismatch", "depth": 1, "title": "The Mismatch, and the Claim", "intro": "The parent gave the problem and the promise. This level reads the introduction as an argument: two separate reasons for wanting raw text, two questions the paper says were blocking anyone from using it, the preconditions the recipe quietly assumes, the single sentence offered in defence of the architecture, and what the headline claim does and does not cover.", "chapters": [{"id": "two-arguments", "title": "Two Arguments, Not One", "body": "The parent gave one reason to want raw text. The introduction gives two, and they are not the same reason.\n\nThe first is about coverage. Most deep learning methods need substantial hand-labelled data, and that requirement rules them out entirely in domains where annotation is thin ([[labeled-data-scarcity]]). The argument here is that supervised learning is unavailable, not that it is weak.\n\nThe second argument is a different shape. The paper says that even where considerable supervision is available, learning good representations without labels still gives a real gain.\n\nScarcity plays no part in that claim. It says unsupervised learning finds structure that training on a task's own labels would not find, however many labels you had ([[generative-vs-discriminative-training]]).\n\nThat second claim needs evidence, and the introduction names some. Pre-trained word embeddings are already in wide use across [[natural-language-understanding|language understanding tasks]], and the paper calls this the most compelling evidence so far that unsupervised representations help ([[word-embedding-transfer]]).\n\nThen it names the limit of that evidence. It is word-level. One vector per word type, learned once, reused everywhere.\n\nThe stated difficulty is getting above that line — using more than word-level information from unlabelled text ([[phrase-and-sentence-embeddings]]).\n\nSo the question the paper opens on is not whether unlabelled text helps at all. Inside [[semi-supervised-learning-for-nlp|semi-supervised NLP]] that is treated as already answered at the word level. What is open is whether anything larger than a word transfers.", "childId": null, "number": "1.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 8]}}, {"id": "two-questions", "title": "What the Two Open Questions Were Made Of", "body": "The parent said two things stood in the way. The introduction says what each one consisted of.\n\nThe first is the objective ([[choice-of-pretraining-objective]]). The problem was not a shortage of candidates. The paper names three recent lines of work: predicting the next token ([[language-modeling-objective|language modelling]]), translating between languages, and judging discourse coherence.\n\nEach one, the paper says, outperforms the others on different tasks. That is the actual state of the evidence — not a ranking, a scatter.\n\nThe footnote attached to that sentence is not a citation. It is a link to a public leaderboard ([[glue-benchmark]]), which is a fair signal of how live the question still was.\n\nNote what the introduction does not do. It picks language modelling and offers no argument here for the choice. The argument is deferred to measurements later in the paper.\n\nThe second question is transfer ([[how-to-transfer-representations]]). Suppose you already hold a pre-trained representation. Existing practice, as the paper describes it, mixed three kinds of machinery: changes to the model architecture shaped around the target task ([[task-specific-architectures]]), intricate learning schemes, and extra unsupervised loss terms carried alongside the supervised one ([[auxiliary-training-objectives]]). A further option was to freeze the pre-trained model and pipe its hidden states into a separate task network as features ([[feature-based-transfer]]).\n\nSo \"no consensus\" means something specific. Several mechanisms were in use at once, each traced to a different paper, with no agreement about which was carrying the result.\n\nThe paper's own diagnosis closes the paragraph. These two uncertainties are why effective semi-supervised approaches for language had been difficult to build.", "childId": "n-the-mismatch--two-questions", "number": "1.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}], "pages": [1, 2, 3, 4, 5, 6, 7]}}, {"id": "what-it-assumes", "title": "What the Recipe Assumes It Has", "body": "The [[two-stage-training-procedure|two-stage procedure]] has preconditions, and the introduction states them before describing the method.\n\nOne: access to a large corpus of unlabelled text — here, a collection of books ([[bookscorpus]]). Two: several datasets of manually annotated training examples, which the paper calls the target tasks ([[labeled-dataset-c]]).\n\nThen comes one sentence that is easy to read past. The setup does not require the target tasks to be in the same domain as the unlabelled corpus ([[domain-mismatch-tolerance]]).\n\nIt is worth sitting with that. If domain match were required, every target task would need its own matched pile of raw text.\n\nThe scarcity problem would then return one level up, in a different currency — unlabelled text is abundant in general, but not necessarily abundant and on-topic. The point of pre-training once is that the same weights ([[transfer-learning]]) serve tasks whose text looks nothing like the corpus.\n\nThe paper asserts this rather than testing it directly. The evidence is indirect: one corpus of books, then [[evaluation-task-families|twelve datasets]] drawn from image captions, news wire, Wikipedia, science exams and a question forum.\n\nThe goal is stated as a universal representation that transfers with little adaptation. Two separate commitments are packed into that phrase.\n\nUniversal means one representation for all the tasks, rather than one per task ([[task-agnostic-model]]).\n\nLittle adaptation means the cost of taking on a new task should be small. Later in the paper that becomes a countable quantity: how many freshly initialized parameters each new task adds ([[minimal-extra-parameters]]).", "childId": null, "number": "1.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "architecture-reason", "title": "The One Sentence on the Architecture", "body": "The parent said the network is prior work's transformer, not a new design. The introduction does give a reason for that choice, and the reason is one sentence long.\n\nThe [[transformer-gpt1|transformer]] is said to provide a more structured memory for handling long-term dependencies in text, compared with alternatives like recurrent networks ([[lstm-gpt1]]).\n\nUnpack that. A recurrent network carries everything it has read in a single hidden state of fixed size, rewritten at every step. Older material survives only to the extent that it survived each rewrite.\n\nSelf-attention instead keeps every earlier position addressable. A prediction can reach back to a specific token directly, without that token having to have been preserved through hundreds of updates.\n\nWhat the paper wants from that reach is [[long-range-dependencies-gpt1|dependencies spanning many tokens]] — a pronoun and the name it stands for several sentences earlier, or an exam question and the one line of the passage that answers it.\n\nThen the introduction takes a further step. It says this structured memory results in robust transfer performance across diverse tasks ([[transformer-inductive-bias]]).\n\nAt this point in the paper that is an assertion. The citations offered are for the transformer's strength on machine translation, document generation and syntactic parsing. None of those are transfer results.\n\nThe evidence comes much later, and as a removal: hold the whole recipe fixed, swap in a single-layer LSTM, and the average score falls by 5.6 points ([[ablation-lstm-substitution]]).\n\nThe same paragraph also commits early to handling [[structured-inputs|multi-part inputs]] by walking them into one contiguous sequence ([[traversal-style-approach]]), rather than by building task-shaped modules ([[task-specific-input-transformations]]).", "childId": null, "number": "1.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-claim", "title": "The Claim, and What It Leaves Out", "body": "The parent gave the headline: new best published results on [[state-of-the-art-9-of-12|nine of twelve datasets]]. Read the sentence closely and three things sharpen.\n\nFirst, the comparison class. The model is said to outperform discriminatively trained models that use architectures specifically crafted for each task ([[baseline-comparisons]]). The claim is staked against hand-built task systems. It is not a claim about beating other pre-trained models.\n\nSecond, the spread. Four families are named up front: [[natural-language-inference|inference]], [[question-answering-and-commonsense-reasoning|question answering]], [[semantic-similarity|semantic similarity]] and [[text-classification|text classification]], covering [[table-1|twelve datasets]] between them. Breadth is part of the claim itself, since a single model that only worked on one family would settle nothing.\n\nThird, how gains are counted. The introduction reports two figures the parent had no room for: 1.5 points on [[multinli|MultiNLI]] and 5.5 on the GLUE multi-task benchmark, beside 8.9 on the [[story-cloze-test|Story Cloze Test]] and 5.7 on [[race-dataset|RACE]].\n\nThese are absolute improvements ([[absolute-improvement]]). A gain of 8.9 means the accuracy figure moved 8.9 percentage points.\n\nIt does not mean errors fell by 8.9 percent. That relative figure would be the larger-sounding one on any task already scoring well, and the paper does not use it.\n\nNow what the claim leaves out. Nine of twelve means three datasets where the previous best still stands, and the introduction does not name them.\n\nOne further piece of evidence is promised here. The paper says it also analysed [[zero-shot-behaviors|zero-shot behaviours]] across four settings, offered as a sign that pre-training alone leaves useful linguistic knowledge behind before any label is seen.", "childId": null, "number": "1.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-which-family-this-joins": {"id": "n-which-family-this-joins", "parentId": "root", "parentChapterId": "which-family-this-joins", "depth": 1, "title": "Which Family This Joins", "intro": "The parent named the branches. This level says what each branch actually does to a model — which parameters move, which stay frozen, which loss terms are summed — and checks how much of the paper's own placement is argument and how much is measurement.", "chapters": [{"id": "what-a-word-table-carries", "title": "What a Word Table Can Carry", "body": "The oldest members of [[semi-supervised-learning-for-nlp]] learned nothing at all. They computed word-level and phrase-level statistics over the unlabelled corpus — counts, co-occurrence figures — and handed those to a supervised model as extra input features.\n\nLearned vectors came later. [[word-embedding-transfer]] trains one vector per vocabulary entry on raw text, then drops that table into a task model.\n\nThe mechanism is a lookup. Each word type owns one row. The row returned for a word is the same row every time that word appears, whatever sentence it appears in.\n\nSo the unlabelled corpus contributes a fixed quantity per word, settled before the task model sees anything. The tasks this was shown on match that granularity: sequence labelling, and [[text-classification]].\n\n[[phrase-and-sentence-embeddings]] push the unit upward. One vector now stands for a whole phrase or sentence, trained on unlabelled text, then used as a feature for the target task. The vector is longer-range, but it is still a frozen quantity passed to a separately built network.\n\nThe paper's own model contains a table of exactly the first kind. [[token-embedding-matrix]] $W_e$ maps each token to a dense vector, and [[input-representation-h0]] adds position vectors to it: $h_0 = UW_e + W_p$.\n\nThat is layer zero. Twelve blocks sit above it, and [[final-token-activation]] at any position depends on every preceding token in the window.\n\nSo the thing carried across is not the table. It is the stack that reads the table — which is what lets a [[natural-language-understanding]] task see [[long-range-dependencies-gpt1]] rather than a bag of per-word constants.", "childId": null, "number": "2.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "loss-or-starting-point", "title": "Change the Loss, or Change the Starting Point", "body": "The second cut is about which part of training the unlabelled data touches.\n\n[[auxiliary-training-objectives]] touch the loss. There is one training run, and the objective is a sum: the supervised term plus an unsupervised term computed on raw text. Gradients from both flow into the same shared weights at the same time.\n\nThe cited instances are concrete. Collobert and Weston attached a spread of auxiliary NLP tasks — part-of-speech tagging, chunking, named entity recognition, language modelling — to improve semantic role labelling. Rei added a single language modelling term beside a sequence labelling objective and reported gains.\n\n[[unsupervised-pretraining]] leaves the objective alone. The supervised loss is exactly what it would have been; only the initial value of the weights differs.\n\nThat is a clean distinction, and the paper does not sit cleanly on one side of it.\n\n[[supervised-fine-tuning]] here keeps a language modelling term running during stage two. [[auxiliary-lm-objective]] is written as $L_3(C) = L_2(C) + \\lambda\\, L_1(C)$, and [[eq-combined-objective]] is the paper's Equation 5. [[auxiliary-objective-weight]] is fixed at $\\lambda = 0.5$.\n\nBy the branch definition, the paper is doing both things.\n\nIts defence is a claim about magnitude, not category: pre-training already learns the linguistic aspects the auxiliary term would supply, so the term is a top-up rather than the engine.\n\n[[ablation-no-auxiliary-objective]] is where that claim is cashed. In [[table-5]] the auxiliary term helps the larger datasets and hurts the smaller ones, and its effect is by far the smallest of the three removals tested.", "childId": null, "number": "2.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "borrowed-technique", "title": "A Technique Borrowed From Elsewhere", "body": "The branch the paper joins did not start in NLP.\n\nThe early citations are image classification and regression. Unsupervised pre-training there was a way to get a deep network to train at all, by putting the weights somewhere reasonable before the supervised gradient arrived.\n\nThen came a sharper finding. [[pretraining-as-regularization]] reports that the benefit is not only that optimization gets easier — the initialization also lands the network somewhere that generalizes better on held-out data.\n\nThat matters for how the paper reads its own results. If pre-training were only an optimization aid, its value would shrink as labelled data grew and optimization stopped being the binding constraint. The regularization reading says otherwise.\n\nThe paper cites this result. It does not re-run it.\n\nMore recent applications named are image classification again, speech recognition, entity disambiguation and machine translation. So the technique arrives already established across domains, and what is specific here is the domain and the choice of objective.\n\nOne consequence is stated as an assumption rather than tested directly. [[domain-mismatch-tolerance]] holds that the unlabelled corpus need not match the target domain, which is what permits books to initialize models scored on news sentences, Quora questions and science exams.\n\nThe paper's own measurement of what initialization is worth comes from [[ablation-no-pretraining]] in [[ablation-studies]]: the same transformer, the same [[two-stage-training-procedure]] minus stage one, trained straight on the supervised tasks, loses 14.8% across the board.\n\nThat number isolates [[transfer-learning]] cleanly, because architecture and fine-tuning objective are held fixed and only [[generative-pretraining]] is removed.", "childId": null, "number": "2.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 7, 8]}}, {"id": "freeze-or-carry", "title": "Freeze the Model, or Carry Its Weights", "body": "Inside the initialization branch, the split is over what happens to the pre-trained weights once the target task arrives.\n\n[[feature-based-transfer]] keeps them still. A pre-trained language or translation model is run over the task input, hidden states are read out of it, and those states are fed to a separate supervised network as extra features. No gradient from the task updates the pre-trained model.\n\n[[elmo-deep-contextualized-word-representations]] is the instance named. Its features come from a pre-trained bidirectional language model, and they are consumed by a task network that is still designed and initialized per task.\n\nThat network is the cost. [[per-task-parameter-cost]] is the paper's objection: each new target task brings a substantial set of freshly initialized parameters, trained from scratch on that task's small labelled set.\n\nThe paper gives no count for this. The argument stays qualitative on the other side.\n\nOn its own side the arithmetic is short. [[minimal-extra-parameters]] amounts to [[linear-output-layer-wy]], a matrix from a 768-dimensional activation to however many classes the task has, plus embedding rows for the [[delimiter-token]] and the bracketing symbols. For a three-way inference task that is a few thousand new weights against a twelve-layer stack inherited whole.\n\nEverything else is [[task-agnostic-model]]: one architecture, pre-trained once, not redesigned for anything — against [[task-specific-architectures]] built around each task's shape.\n\nThe divergence reaches the data as well. [[one-billion-word-benchmark]], the corpus behind the feature-based comparison, is about the same size as [[bookscorpus]] but shuffled at the sentence level, which removes the [[long-range-contiguous-text]] this paper says its corpus was chosen for.", "childId": null, "number": "2.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "closest-line", "title": "The Closest Line, and What It Is Missing", "body": "[[lm-pretraining-then-finetuning-predecessors]] is the line the paper calls closest to its own, and the closeness is real: pre-train with a language modelling objective, then fine-tune the whole network with supervision.\n\n[[semi-supervised-sequence-learning]] did this with a recurrent network, pre-trained by language modelling or by autoencoding, then fine-tuned for [[text-classification]]. [[ulmfit]] pre-trained an LSTM language model and fine-tuned it on a staged schedule, again for classification.\n\nThe recipe is therefore not what is being claimed.\n\nTwo differences are claimed instead. [[lstm-short-range-limitation]] is the first: the paper argues a recurrent pre-trained model restricts its prediction ability to a short range, so however much linguistic information the pre-training phase captures, only nearby structure survives the transfer.\n\nIn the related work section this is asserted, with a forward pointer to the experiments. Nothing is measured there.\n\nWhat arrives later is indirect but real. [[ablation-lstm-substitution]] swaps in a single-layer 2048-unit LSTM inside the same framework and loses 5.6 average points, winning on exactly one dataset, [[mrpc]]. [[layers-transferred]] in [[fig-2]] shows each transferred block adding accuracy, up to 9% on MultiNLI. [[transformer-inductive-bias]] rests on the LSTM showing higher variance in zero-shot scores.\n\nNone of that measures range directly. Range is inferred from an averaged score gap, supported by a [[context-window-512-tokens]] over contiguous book text.\n\nThe second difference needs no inference. The predecessors were evaluated on text classification; [[evaluation-task-families]] here spans inference, paraphrase detection and story completion across the twelve datasets of [[table-1]].", "childId": "n-which-family-this-joins--closest-line", "number": "2.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-one-set-of-weights-used-twice": {"id": "n-one-set-of-weights-used-twice", "parentId": "root", "parentChapterId": "one-set-of-weights-used-twice", "depth": 1, "title": "One Set of Weights, Used Twice", "intro": "The parent gave the recipe's shape. This level takes it apart at the level of parameters: what actually crosses from stage one into stage two, what is added, what fine-tuning everything costs, where the per-task work went once it left the architecture, and how much weight the domain assumption is carrying.", "chapters": [{"id": "what-crosses", "title": "What Crosses the Boundary", "body": "Fine-tuning here begins by loading a file of numbers. What sits in that file is the entire product of [[generative-pretraining|stage one]]: the [[token-embedding-matrix]], the position embeddings, and every weight in every block of the stack.\n\n[[supervised-fine-tuning|Stage two]] does not wrap that file in anything. It sets the network's parameters to those values and carries on running gradient descent, now against a different loss. That is the whole of [[transfer-learning|the transfer]] in this [[two-stage-training-procedure|two-stage recipe]].\n\nWhich makes the interesting question an accounting one. How many parameters does a new task need that stage one did not already supply?\n\nThe paper's answer is two kinds, and it states them as a total ([[minimal-extra-parameters]]).\n\nThe first is the output layer [[linear-output-layer-wy|$W_y$]]. It maps the 768-dimensional activation at the last token to one score per label, so for a three-way entailment decision it is $768 \\times 3$ numbers ([[eq-task-head]]).\n\nThe second is an embedding for each [[delimiter-token|delimiter symbol]] the rewritten inputs introduce, because those symbols carry no meaning learned during pre-training. Everything else is inherited.\n\nSet that against the alternative the paper is arguing with. In [[feature-based-transfer]], the pre-trained model is frozen and run only to produce hidden states, which are handed to a separate supervised network as extra input features; [[elmo-deep-contextualized-word-representations|ELMo]] is the best-known instance. That separate network is designed and initialized for each task, so its full parameter count is a per-task cost.\n\nThe paper turns this into its comparison metric, [[per-task-parameter-cost]], and says such approaches involve a substantial number of new parameters for each separate target task.\n\nNote what form that comparison takes. It is asserted, not counted: no parameter totals for either side appear anywhere in the paper.", "childId": null, "number": "3.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "nothing-frozen", "title": "The Price of Not Freezing", "body": "If no layer is frozen, every weight in the twelve blocks is a free variable while the task loss is being minimized. Two consequences follow that the paper does not dwell on.\n\nThe first is bookkeeping. Fine-tuning ends with a full, separately modified copy of the [[model-specification|12-layer, 768-dimensional stack]] for each dataset, so twelve datasets means twelve models on disk.\n\nA frozen pre-trained model with small task heads would keep one copy and add little per task. The paper's accounting counts freshly initialized parameters, where it wins; the storage accounting runs the other way, and is not reported.\n\nThe second is that gradients from a small labelled set can move those weights anywhere, including away from whatever made them worth transferring. Nothing in the framework prevents that.\n\nThe paper does not measure it either. It cites the older finding that [[unsupervised-pretraining|unsupervised pre-training]] acts as [[pretraining-as-regularization|a regularizer]] rather than only an optimization aid, which is a claim that the starting point keeps mattering — but that is a citation, not a measurement made here.\n\nTwo of its own choices bear on the risk without being presented as remedies for it. Fine-tuning runs at a learning rate well below the pre-training peak, for three passes over the task data ([[fine-tuning-hyperparameters]]). And the language modelling loss keeps being optimized during stage two ([[auxiliary-lm-objective]]), which the paper justifies by generalization and convergence speed, not by drift.\n\nWhat the paper does supply is evidence that carrying the weights across is worth doing at all: one row of [[table-5]] retrains the same architecture with [[ablation-no-pretraining|no pre-training]], and a sweep in [[layers-transferred]] carries only part of the stack. Both live in a later chapter.", "childId": null, "number": "3.2", "sources": {"sections": [{"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [2, 3, 4, 5, 7, 8]}}, {"id": "where-the-task-work-went", "title": "Where the Task-Specific Work Went", "body": "The tasks in this evaluation are not the same shape. A sentiment example is one sentence; an entailment example is an ordered pair; a reading comprehension example is a document, a question and several candidate answers.\n\nSomething has to absorb that difference. It does not vanish because a model is called general.\n\nIn the systems the paper measures against, the architecture absorbs it. Those are [[task-specific-architectures]]: [[baseline-comparisons|mostly biLSTM]] networks with attention arranged around one task's structure, sometimes ensembled, which is what most published numbers on these datasets came from at the time.\n\nHere the input absorbs it. [[structured-inputs]] are walked into a single ordered token sequence, a [[traversal-style-approach]], so the [[multi-layer-transformer-decoder|same stack]] can read them unchanged ([[fig-1]], [[task-specific-input-transformations]]).\n\nSo [[task-agnostic-model|task-agnostic]] is a claim about the network, not about the pipeline. Per-task work still exists. It has moved from choosing layers to choosing a token order and a set of separator symbols.\n\nThe abstract is more careful than the shorthand suggests: it says task-aware input transformations, used to achieve transfer while requiring minimal changes to the model architecture.\n\nAnd for two task families the per-task decision reaches slightly past the token string. [[similarity-input-transformation|Similarity]] runs both sentence orderings through the stack and adds the two final activations. [[qa-and-commonsense-input-transformation|Multiple choice]] runs one sequence per candidate answer and normalizes the scores across them.\n\nThose are choices about how many forward passes to make and how to combine them. The stack itself is untouched, but the claim of no task-specific structure is doing slightly less work than it first appears.", "childId": null, "number": "3.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "books-to-exams", "title": "Books In, Science Exams Out", "body": "The [[domain-mismatch-tolerance|domain assumption]] appears once, in the introduction, as a single sentence about the setup: the target tasks are not required to be in the same domain as the unlabelled corpus.\n\nIt is worth seeing how wide the gap actually is. [[bookscorpus]] is over 7,000 unpublished books, in genres the paper lists as adventure, fantasy and romance.\n\nNow the other end. [[snli]] is written over image captions. [[qnli]] is built from Wikipedia. [[scitail]] comes from science exam questions. [[rte]] and [[mrpc]] come from news. [[race-dataset]] is English exam passages set for Chinese students.\n\nNone of those reads like a work of fiction. The assumption is carrying every one of these datasets.\n\nWhat would test it is a second pre-training run on a matched corpus, scored the same way. No such run is reported, so the assumption stays an assumption.\n\nThe corpus argument the paper does make runs on a different axis entirely. It names the [[one-billion-word-benchmark]] as the rejected alternative and argues from [[long-range-contiguous-text|contiguity]], not from subject matter — and even that comparison is made by argument rather than by training on both.\n\nThere is weak support in the results. The same weights do well across captions, news, Wikipedia and exam text, which is at least consistent with domain mattering little, though nothing here isolates domain as the variable.\n\nOne case is worth flagging. RTE is the single inference dataset where the paper does not take the best published number, and it reads that as a small-data effect at 2,490 training examples. RTE is also news text. The paper's reading may be right, but a domain reading is available and is not ruled out.\n\nThe conclusion goes further still, claiming the books leave the model with [[world-knowledge|world knowledge]] that transfers. That is an interpretation of the gains, not a separate measurement.", "childId": null, "number": "3.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 4, 5, 6, 7, 8]}}], "number": "3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-predicting-the-next-token": {"id": "n-predicting-the-next-token", "parentId": "root", "parentChapterId": "predicting-the-next-token", "depth": 1, "title": "Predicting the Next Token", "intro": "The parent gave the loss and named the network. This level reads both at working scale: what one 512-token sequence actually buys in scored predictions, what the mask does inside a single attention head, what each line of Equation 2 commits the model to, and how large the stack that results is.", "chapters": [{"id": "one-sum-many-terms", "title": "Reading the Sum as Work Done", "body": "$k$ is a number, and the paper fixes it. [[eq-lm-objective|Equation 1]] writes the context as $u_{i-k},\\dots,u_{i-1}$, and the trained model reads contiguous sequences of 512 tokens ([[context-window-512-tokens]]). A prediction can therefore condition on up to 511 tokens of preceding text.\n\nThat is paragraphs, not words. A pronoun and the name it stands for can sit several sentences apart, and a window this wide holds both at once ([[long-range-dependencies-gpt1]]).\n\nNow read the sum as work rather than as notation. Take one sequence of 512 tokens. Every position after the first contributes a term to $L_1$, so a single sequence yields on the order of 511 scored predictions.\n\nEach token in it plays two roles. Once it is the target, at its own position. Up to 511 times it is context, for the positions that come after it.\n\nNothing was annotated to arrange this. The target at position $i$ is the token already sitting at position $i$, so the label is the data shifted by one ([[generative-pretraining]]).\n\nThe terms are log-probabilities, so each is at most zero. A model that puts probability $0.5$ on the token that appeared contributes about $-0.69$; at $0.05$ it contributes about $-3.0$; at $0.9$, about $-0.11$. Driving the sum up means moving probability mass onto the tokens that actually occurred, and stage one applies no other pressure ([[maximum-likelihood-training]], [[language-modeling-objective]]).\n\nThe paper says these parameters are trained with stochastic gradient descent, and says no more than that here. They are the same parameters the second stage will start from ([[two-stage-training-procedure]]).", "childId": null, "number": "4.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "the-mask", "title": "The Mask, and What the Missing Encoder Costs", "body": "Inside one attention head the model forms a score for every ordered pair of positions: the query at $i$ against the key at $j$. [[masked-self-attention]] intervenes before the softmax over those scores. Every entry with $j > i$ is set to $-\\infty$, so its weight after the softmax is exactly zero.\n\nThe output at position $i$ is then a mixture of values drawn from positions $1$ through $i$ and nothing else.\n\nThat property composes. If each layer is causal, a stack of them is causal, so a state at the top of the blocks still depends on no token after its own ([[multi-layer-transformer-decoder]]).\n\nThis is what makes scoring every position in one pass legitimate. Without the mask you would need a separate forward pass per position, each with the future cut away. With it, one pass over a 512-token sequence produces every term of the sum, and no term has seen its own answer.\n\nThe encoder is dropped for a separate reason. In the architecture this builds on ([[transformer-gpt1]]) a decoder block carries three sublayers, the middle one attending to an encoder's output. Pre-training has no source sequence and no target sequence, only one running stream of text, so that sublayer has nothing to read. Removing it leaves masked self-attention and a position-wise feed-forward layer per block ([[decoder-only-stack]]) — the block drawn on the left of [[fig-1]].\n\nThe cost is standing: no position ever sees its right context, in this stage or in the next one.\n\nMasking buys causality that a recurrent network gets by construction. The paper's own measurement of that trade is the swap to a single-layer LSTM, which costs 5.6 average points ([[ablation-lstm-substitution]]).", "childId": null, "number": "4.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "equation-two-line-by-line", "title": "Equation 2, Line by Line", "body": "[[eq-decoder-stack|Equation 2]] is three lines. Take them in order.\n\nLine one. $U$ is the context written as one-hot rows, so $UW_e$ is a matrix product on paper and a row lookup in practice: token $u$ fetches row $u$ of [[token-embedding-matrix]]. Each row is 768 numbers wide ([[hidden-state-dimension-768]]), and there is one row per entry of the subword vocabulary ([[byte-pair-encoding-gpt1]]).\n\nThen $W_p$ is added. Added, not concatenated — [[input-representation-h0]] hands position and identity the same 768 coordinates to share, rather than reserving a slice of the vector for each.\n\n$W_p$ is a trained table with one row per slot ([[learned-position-embeddings]]). It has as many rows as the window and none beyond; the sinusoids it replaces are defined at any index, and a table is not. The paper states the substitution without reporting a comparison.\n\nLine two is $h_l = \\text{transformer\\_block}(h_{l-1})$, applied $n$ times. Shape in equals shape out, which is what makes the blocks stackable at all, and what later lets the analysis carry over some of them rather than all.\n\nLine three is $P(u) = \\mathrm{softmax}(h_n W_e^{\\mathsf{T}})$. Read the multiplication as inner products: the 768-dimensional state at the top is dotted against every row of the embedding table, giving one score per vocabulary entry ([[output-softmax-tied-embeddings]]).\n\nSo a token scores high exactly when the final state points along that token's own input embedding.\n\nTwo consequences follow. The output layer costs no parameters of its own, saving a matrix of vocabulary size by 768. And every row of $W_e$ takes gradient from two directions: wherever that token appeared as input, and at every position where it stood as a candidate.", "childId": null, "number": "4.3", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "stack-dimensions", "title": "The Numbers the Stack Was Built With", "body": "[[model-specification]] pins the stack down: twelve blocks ([[twelve-layer-depth]]), 768-dimensional states, twelve attention heads in each block ([[twelve-attention-heads]]), and a feed-forward sublayer whose inner width is 3072 ([[position-wise-feedforward-3072]]).\n\nTwo of those numbers settle a third the paper never prints. Twelve heads splitting 768 dimensions leaves each head a 64-dimensional subspace to attend in.\n\nThe feed-forward width is really a ratio: 3072 is four times 768. Each block expands its representation fourfold, applies a nonlinearity, then projects back down to 768.\n\nThat nonlinearity is [[gelu]] rather than ReLU. It multiplies each input by the probability that a standard normal draw falls below it, so instead of a hard cut at zero the curve bends through it.\n\nThe size is worth working out, since no parameter count is reported. Attention in one block uses four $768 \\times 768$ projections, about 2.4M weights. The feed-forward sublayer uses $768 \\times 3072$ twice, about 4.7M. That is roughly 7.1M per block, so about 85M across the twelve, with a further 31M or so sitting in the embedding table.\n\nInitialization is $\\mathcal{N}(0, 0.02)$ for every weight ([[weight-initialization]]). The paper's stated reason is that [[layer-normalization-gpt1]] is used throughout the stack, so a simple scheme sufficed. It offers no experiment behind that.\n\nDepth is the one of these dimensions the paper later turns as a dial. [[fig-2]] varies how many of the twelve pre-trained blocks are carried into fine-tuning ([[layers-transferred]]) and reports the score climbing with each one added.", "childId": "n-predicting-the-next-token--stack-dimensions", "number": "4.4", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [3, 4, 5, 7, 8]}}, {"id": "what-crosses-over", "title": "What Stage One Hands Over", "body": "Stage one's output is a distribution over the vocabulary, and that distribution is not what gets used next. What crosses into the second stage is the fitted parameters ([[transfer-learning]]).\n\nAnd it is not a partial handover. Because the output layer is the transposed embedding matrix, there is no separate head to discard — every weight the language model has is a weight the next stage inherits ([[supervised-fine-tuning]]).\n\nThe loss itself is not discarded either. $L_1$ returns during fine-tuning as a second term sitting alongside the task loss ([[auxiliary-lm-objective]]).\n\nWhat the paper wants from all this is stated plainly enough. The objective never names a task, so any task-relevant ability in the weights arrives as a byproduct of predicting text ([[task-agnostic-model]]).\n\nThe conclusion claims that training this way leaves the model with knowledge about the world ([[world-knowledge]]). The analysis section puts a mechanism to it as a hypothesis: the generative model picks up abilities the evaluation tasks need because those abilities improve its language modelling, and the transformer's more structured attentional memory assists transfer compared with a recurrent state ([[transformer-inductive-bias]]).\n\nBoth are hypotheses in the paper's own wording. Nothing in the objective or the architecture establishes them; the measurements that bear on them come later.", "childId": null, "number": "4.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 7, 8]}}], "number": "4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, "n-the-corpus-and-the-training-run": {"id": "n-the-corpus-and-the-training-run", "parentId": "root", "parentChapterId": "the-corpus-and-the-training-run", "depth": 1, "title": "The Corpus, the Model, the Run", "intro": "The parent listed the choices. This level shows the mechanisms behind them: what sentence-level shuffling actually removes and what the paper never tested, how raw book text becomes 40,000-merge subword units, how the dimensions of one block fit together, and what a 100-epoch run costs in updates. It ends where the parent ended, on a single perplexity number, and says what that number does and does not establish.", "chapters": [{"id": "corpus-as-argument", "title": "The Corpus as an Argument", "body": "The case for [[bookscorpus]] is comparative, and it repays separating what the comparison establishes from what it assumes.\n\nBoth corpora are about the same size. Size is therefore held fixed, and one property differs: order. Shuffling the [[one-billion-word-benchmark|1B Word Benchmark]] at the sentence level leaves every unigram, every bigram and every within-sentence dependency exactly where it was. What it removes is any statistical relation between one sentence and the next one.\n\nName those relations concretely. A pronoun and the name it stands for, several sentences back, is [[coreference]]. A character introduced in one paragraph and referred to by role in the next is another. These are the [[long-range-dependencies-gpt1|far-apart relations]] that [[language-modeling-objective|the objective]] can only learn if the training text contains them at all.\n\nNow the sampling. Each training sequence is a contiguous run of 512 tokens taken from one book, not 512 tokens assembled from separate pieces. In a shuffled corpus the window would still be full. Most of what filled it would simply be unrelated to the token being predicted. The window is [[context-window-512-tokens|as wide as $k$ allows]] either way; only in [[long-range-contiguous-text|ordered text]] does the extra width carry anything.\n\nThen the part the paper leaves open. It runs no control. It does not pre-train the same model on the shuffled corpus and compare the downstream numbers. Contiguity is given as a reason for a choice, not tested as a hypothesis — [[generative-pretraining|stage one]] was run once, on books.\n\nOne thing the choice does not claim to secure. Books are fiction-heavy; the evaluation tasks include news, science exam questions and Wikipedia. The paper's stated position is [[domain-mismatch-tolerance|that no domain match is required]].", "childId": null, "number": "5.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "raw-text-to-subwords", "title": "Raw Text to Subword Units", "body": "The [[text-preprocessing-pipeline|three steps]] each do a separate job.\n\n[[ftfy]] goes first. Raw book text carries encoding damage: characters mangled by a bad decode, curly and straight quotes mixed together, irregular whitespace. ftfy repairs that and standardizes some punctuation and whitespace. The step matters more than it sounds, because every surface variant the cleaner fails to merge becomes its own set of subword pieces further down.\n\nThe [[spacy-tokenizer|spaCy tokenizer]] then cuts the cleaned text into word-level tokens, splitting punctuation off words and handling contractions.\n\nThen [[byte-pair-encoding-gpt1|byte-pair encoding]]. Start with each word written as its sequence of characters. Count every adjacent symbol pair across the corpus. Take the most frequent pair and record it as a merge: those two symbols are now one symbol. Recount. Merge again. Repeat.\n\nEach merge adds exactly one symbol to the vocabulary. Frequent sequences rise to the top early, so ordinary words become single symbols within the first few thousand merges. Rare words never top the frequency list as wholes, so they stay split into pieces that other words also use.\n\n[[bpe-merges-40000|40,000 merges]] is the entire setting, and it trades two ways. Too few, and almost everything splits toward characters: sequences get longer, and a fixed window spans less text. Too many, and the vocabulary grows while each rare embedding is trained on fewer occurrences.\n\nTwo consequences follow. There is no unknown token, since any string decomposes into pieces already present, down to single characters. And the vocabulary size fixes the shape of the largest matrix in the model: the [[token-embedding-matrix|token embedding matrix $W_e$]], which enters at [[input-representation-h0|$h_0$]] and returns transposed in the [[output-softmax-tied-embeddings|output softmax]].", "childId": null, "number": "5.2", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "shape-of-the-stack", "title": "How the Dimensions Fit Together", "body": "The numbers in the [[model-specification|specification]] are not four independent choices.\n\n[[hidden-state-dimension-768|768]] divided by [[twelve-attention-heads|12 heads]] gives each head a 64-dimensional subspace to attend in. The [[position-wise-feedforward-3072|3072-dimensional]] inner layer is $4 \\times 768$: each block expands fourfold and projects back down. Both ratios come straight from the original transformer.\n\nWalk the parameter count, which the paper does not report. Inside one block, the attention sublayer holds four $768 \\times 768$ projections — queries, keys, values, output — at $589{,}824$ each, so about $2.4$M. The feed-forward sublayer holds $768 \\times 3072$ going up and $3072 \\times 768$ coming back, about $4.7$M. That is roughly $7$M per block, and [[twelve-layer-depth|twelve blocks]] of it come to around $85$M. Add roughly $31$M for a 40,000-row embedding table of width 768. The [[decoder-only-stack|single stack]] is therefore on the order of a hundred million parameters.\n\nThree smaller choices are stated, two with reasons and one without.\n\n[[learned-position-embeddings|Position embeddings are learned]] rather than sinusoidal. That makes the window a parameter shape: $W_p$ has exactly 512 rows, one per slot, and nothing is defined beyond them.\n\n[[gelu|GELU]] replaces ReLU. It computes $x\\,\\Phi(x)$, gating each input by the probability that a standard normal draw falls below it — smooth everywhere, and slightly negative for small negative inputs. No ablation is offered for it.\n\nInitialization is a plain $\\mathcal{N}(0, 0.02)$ draw, and the paper says [[weight-initialization|that sufficed]] because [[layer-normalization-gpt1|layer normalization]] is used throughout the stack.\n\nThe depth is also a dial the [[layers-transferred|transfer analysis]] turns later.", "childId": "n-the-corpus-and-the-training-run--shape-of-the-stack", "number": "5.3", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [3, 4, 5, 7, 8]}}, {"id": "the-run", "title": "The Run, Counted in Updates", "body": "The [[pre-training-optimization|optimization setup]] is easier to judge once the schedule is counted in updates rather than epochs.\n\nOne minibatch is 64 sequences of 512 tokens, which is $32{,}768$ tokens per update. The [[linear-warmup|warmup]] runs 2000 updates, so the learning rate climbs from zero to $2.5 \\times 10^{-4}$ over roughly $65$M tokens. If the corpus is on the order of a billion tokens, warmup is a small fraction of the first pass alone. [[pretraining-schedule|100 passes]] over such a corpus works out to a few million updates in total.\n\nWhy warm up at all. [[adam-optimizer-gpt1|Adam]] scales each step by running estimates of the gradient's first and second moments, and those estimates are built from almost no data at the start. Full-size steps taken on them are steps taken on noise.\n\nAfter the peak, [[cosine-annealing|the rate follows a cosine curve]] back to zero across the remaining updates. The curve spends a long stretch near the peak and slows late, and the endpoint is zero rather than a floor.\n\nThe [[regularization-setup|regularizers]] are three plus one. [[dropout-gpt1|Dropout]] at rate 0.1 is applied [[residual-embedding-attention-dropout|on residual branches, at the embedding layer, and inside attention]]. Alongside it runs a [[decoupled-weight-decay|modified L2 penalty]] at $w = 0.01$, applied to every weight that is not a bias or a gain. The exclusion is deliberate: layer normalization's gains and biases exist to rescale activations, and shrinking them toward zero would work against the normalization.\n\nNo compute cost, wall-clock time or sweep over these settings is reported.", "childId": null, "number": "5.4", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "one-number", "title": "What 18.4 Establishes", "body": "[[token-level-perplexity|18.4]] is the exponential of the mean negative log-likelihood per token. Loosely, at each position the model is about as uncertain as someone choosing uniformly among eighteen options.\n\nTwo qualifications sit on the number.\n\nThe token is a BPE unit, not a word. Splitting rare words into pieces produces more tokens, and each piece is individually easier to predict than the whole rare word would have been, so a token-level figure is not comparable with a word-level one on the same text.\n\nAnd the paper reports the figure on the corpus, without naming a held-out split. After 100 passes over that corpus, a number stated this way does not separate fit from generalization. It is offered as evidence that [[maximum-likelihood-training|maximizing likelihood]] did what it was asked to do.\n\nThat is the limit of what it carries. A perplexity says nothing about whether the weights help on a labelled task, which is the only thing [[two-stage-training-procedure|the recipe]] is finally judged on. The paper does not argue from it either. Its evidence that pre-training matters comes later, from [[ablation-no-pretraining|the ablation that removes pre-training]] and from [[zero-shot-behaviors|heuristics run on the generative model directly]], not from this line. The claim in the conclusion that the model has picked up [[world-knowledge|knowledge about the world]] rests on those, not on 18.4.\n\nWhat the number does mark is the end of stage one. From here the same weights stop being a language model and start being an initialization for [[supervised-fine-tuning|something else]].", "childId": null, "number": "5.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}], "number": "5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-from-language-model-to-classifier": {"id": "n-from-language-model-to-classifier", "parentId": "root", "parentChapterId": "from-language-model-to-classifier", "depth": 1, "title": "From Language Model to Classifier", "intro": "The summary said what stage two does: read the last token, multiply by one matrix, keep the language modelling loss running, train briefly. This level asks the questions that answer skips — why that position and not another, what the gradient actually touches, what the second loss is computed on, and what the reported settings amount to on a small dataset versus a large one.", "chapters": [{"id": "reading-the-last-position", "title": "Reading the Last Position", "body": "Start with the choice of where to read.\n\nThe stack is causally masked: under [[masked-self-attention]] the activation at position $i$ has attended to positions $1$ through $i$ and nothing after. So the final block's output at position 1 has seen one token. The output at position $m$ has seen all $m$.\n\nOnly the last position is a summary of the whole input. That is why [[eq-task-head]] reads [[final-token-activation]] rather than pooling across positions — under this masking, no other single position has the whole sequence available.\n\nWhat sits on top of it is small. The activation is a 768-dimensional vector ([[hidden-state-dimension-768]]), so [[linear-output-layer-wy]] is a $768 \\times |Y|$ matrix. For a three-way inference task that is 2,304 numbers, added to a stack of twelve blocks ([[twelve-layer-depth]]), each with a 3072-dimensional inner feed-forward layer. The paper never states a total parameter count, but the ratio is not close.\n\nNotice what the head is not. There is no hidden layer, no task-specific attention, no learned pooling. Any nonlinear work a task needs has to already be available inside the pre-trained blocks, because the only thing between them and the label scores is one matrix multiply and a softmax.\n\nThe paper does not argue for this. It writes Equation 3 and lets the scoreboard carry the claim.\n\n[[minimal-extra-parameters]] is the tally: $W_y$, plus embeddings for the [[delimiter-token]] that separates the parts of an input. [[fig-1]] draws this head and the language modelling head sitting on the same stack. Which token sequence gets fed in is a separate question, handled in the next chapter over.", "childId": null, "number": "6.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "what-l2-moves", "title": "What the Label Loss Actually Moves", "body": "[[eq-supervised-objective]] has the same shape as the pre-training loss. Both are [[maximum-likelihood-training]]: sum a log-probability the model assigns to something observed.\n\nThe difference is what is being summed over. $L_1$ runs over token positions and scores a distribution over the vocabulary. [[supervised-objective-l2]] runs over instances in [[labeled-dataset-c]] and scores a distribution over that task's labels.\n\nWrite it that way and the only thing separating one task from another is which $\\mathcal{C}$ you plug in.\n\nNow the part the equation leaves implicit. Nothing in $L_2$ restricts the gradient to $W_y$. The loss is differentiated through the whole stack, so every pre-trained weight moves — embeddings, attention projections, feed-forward layers, all twelve blocks.\n\nThat is worth separating from the parameter-count claim. \"Only $W_y$ is added\" is a statement about what has to be freshly initialized. It is not a claim that the rest is frozen. Each fine-tuned task ends up owning a full, separately modified copy of the stack.\n\nThis is what distinguishes the recipe from [[feature-based-transfer]]. There the pre-trained model is held fixed and its hidden states are fed as features into a task network trained from scratch, as in [[elmo-deep-contextualized-word-representations]]. The [[per-task-parameter-cost]] in that setup is a whole new model per task. Here it is one matrix, bought at the price of updating everything behind it.\n\nWhich raises the obvious worry. A twelve-block stack is being fitted on [[rte]]'s 2,490 training examples, or [[sts-b]]'s roughly 5,700.\n\nThe paper does not confront overfitting directly. It adds a second loss.", "childId": null, "number": "6.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}], "pages": [1, 2, 3, 4, 5, 6, 7]}}, {"id": "why-the-old-loss-stays-on", "title": "Why the Old Loss Stays On", "body": "Look closely at the argument in [[eq-combined-objective]]. The auxiliary term is $L_1(\\mathcal{C})$, not $L_1(U)$.\n\nSo the next-token loss is no longer computed on [[bookscorpus]]. It runs on the task's own labelled inputs, read simply as text. A premise, a delimiter and a hypothesis get scored token by token as if they were a passage from a book, at the same time as they are scored for their label.\n\nThe machinery for that is already present. The language modelling head is the transposed token embedding matrix ([[output-softmax-tied-embeddings]], reusing [[token-embedding-matrix]]), so keeping [[auxiliary-lm-objective]] switched on costs no new parameters at all. A model with a separately trained output projection would have had to carry one along on purpose.\n\n[[auxiliary-objective-weight]] sets the balance at $0.5$. The paper reports the value in its setup section, and does not report searching over it or testing how sensitive results are to it.\n\nThe two stated benefits — better generalization, faster convergence — are given as findings, not as consequences of an argument. No mechanism is offered. Prior work is cited as having seen the same thing.\n\nThen the paper's own ablation complicates it. Removing the term ([[ablation-no-auxiliary-objective]] in [[table-5]]) raises the unweighted average by 0.3 points. It helps on the inference tasks and on [[qqp]], and hurts on the smaller sets, which the paper reads as a size trend.\n\nSo the default configuration carries a term whose average measured effect, in this paper, is slightly negative.\n\nOne more thing has happened here. [[auxiliary-training-objectives]] appeared in the related work as a rival branch, the transfer mechanism in its own right. Here the same device is demoted to a supplement sitting on top of pre-training.", "childId": "n-from-language-model-to-classifier--why-the-old-loss-stays-on", "number": "6.3", "sources": {"sections": [{"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [2, 3, 4, 5, 6, 7, 8]}}, {"id": "three-passes-quarter-rate", "title": "Three Passes at a Quarter of the Rate", "body": "[[fine-tuning-hyperparameters]] states a default: unless the paper says otherwise, stage two keeps stage one's settings. [[adam-optimizer-gpt1]] stays, [[regularization-setup]] stays, the vocabulary stays.\n\nThe exceptions are few, and each is a step down in scale.\n\nThe rate is $6.25\\text{e-}5$ ([[fine-tuning-lr-and-batch]]). Divide [[pre-training-optimization]]'s peak of $2.5\\text{e-}4$ by it and you get exactly 4. Batch size drops from 64 sequences to 32. Since a pre-training batch was 64 contiguous sequences of 512 tokens ([[pretraining-schedule]]), about 32,768 tokens, a fine-tuning batch is smaller in tokens too, by however short the task inputs happen to be.\n\nThe schedule changes shape as well. Pre-training annealed on a cosine curve ([[cosine-annealing]]); [[fine-tuning-lr-schedule]] decays linearly to zero.\n\nAnd the warmup is now relative. Pre-training warmed up over a fixed 2,000 updates ([[linear-warmup]]); fine-tuning warms up over the first 0.2% of training.\n\nWalk that through. [[snli]] has around 550,000 training examples, so [[three-epochs-fine-tuning]] at batch 32 is about 51,500 updates, and 0.2% of that is roughly 103 updates of warmup. [[rte]] has 2,490 examples: about 233 updates in total, and 0.2% of that is under half of one. The same rule gives a real warmup on the largest set and none at all on the smallest. The paper does not comment on this.\n\nThe only addition is [[classifier-dropout]] at 0.1 on the new head.\n\nRead against [[ulmfit]]'s staged schedule, the point of this list is what is missing from it. No layer-wise rates, no unfreezing order. Three passes, one rate, decay to zero — and, the paper hedges, that sufficed for most datasets.", "childId": null, "number": "6.4", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}], "pages": [1, 2, 3, 4, 5, 6, 7]}}], "number": "6", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-one-sequence-per-task": {"id": "n-one-sequence-per-task", "parentId": "root", "parentChapterId": "one-sequence-per-task", "depth": 1, "title": "One Sequence Per Task", "intro": "The parent said where the paper puts the task's structure: in the input, not the architecture. This level says why that is the only place it can go given what sits on top of the stack, what each of the four input shapes costs to run, and what the parameter claim does and does not cover.", "chapters": [{"id": "where-the-difference-goes", "title": "What the Other Option Actually Was", "body": "Start with the alternative, drawn concretely.\n\nThe systems this paper measures itself against are mostly task-built recurrent networks ([[baseline-comparisons]]). For an entailment dataset that typically means a biLSTM reading each sentence, an attention mechanism aligning one against the other, and a classifier on the aligned result. Under [[feature-based-transfer]] — [[elmo-deep-contextualized-word-representations]] is the named case — the transferred part is a set of contextual vectors, and that pairing network is built on top of them.\n\nTwo things follow from that arrangement.\n\nThe pairing network starts from random weights. And it learns from exactly one source: the target task's labelled examples.\n\nSo the component that does the structural work — the part that actually knows there are two sentences and has to relate them — is the component trained on the least data. That is the sharp form of the paper's objection. Counted in parameters rather than in data, the same objection is the [[per-task-parameter-cost]] complaint, and the scarcity it runs into is the one the paper opened on ([[labeled-data-scarcity]]).\n\nThe paper's replacement is credited to earlier work, not claimed as its own: it cites the [[traversal-style-approach]] and applies it.\n\nBut the swap has a price, and the paper does not dwell on it. [[structured-inputs]] arrive with their parts already separated and named. After the transformation, the only surviving trace of that structure is token order plus one symbol. Whatever the pairing network was computing explicitly, the stack must now compute implicitly, using weights trained only to predict the next word. The paper does not argue that this suffices. It reports scores for [[task-agnostic-model]] instead, and lets them carry the point.", "childId": null, "number": "7.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "one-vector-at-one-position", "title": "One Vector, at One Position", "body": "The transformations look like a stylistic choice until you look at what consumes their output.\n\n[[eq-task-head]] is the whole task-specific classifier. Take the final block's activation at the last input token ([[final-token-activation]]), multiply by one matrix ([[linear-output-layer-wy]]), softmax.\n\nNotice what the head never receives. It does not read the sequence. It reads a single vector, at a single position.\n\nAnd because attention is masked ([[masked-self-attention]]), that position is the only one that could serve. Every earlier token was forbidden from attending rightward, so only the last position has seen the whole input.\n\nThe format therefore has one hard requirement: that last position must exist and must mean the same thing in every example. This is the job of [[start-and-end-tokens]]. Each transformed input is wrapped, so the vector the classifier reads is always the activation over $\\langle e\\rangle$ — never over whatever content word happened to land last, which would vary example to example.\n\nThe [[delimiter-token]] handles the complementary job inside the sequence, marking where one part stops and the next starts.\n\nBoth symbols are new. Neither occurred during pre-training, so their embeddings are initialized randomly and fitted during fine-tuning alone — three passes over the task's labelled set, at a learning rate of $6.25\\times10^{-5}$ ([[fine-tuning-hyperparameters]]).\n\nThat is a thin budget for symbols that have to come to mean \"a boundary happens here\" and \"the input ends here\". The paper reports the recipe works; it never isolates this piece. No ablation removes the brackets or the delimiter, so how much of the result rests on them is untested.\n\nOne small ambiguity: the delimiter is written `$`, a character books already contain, yet delimiter embeddings are counted among the parameters a new task adds. So it is being treated as its own entry in the [[byte-pair-encoding-gpt1]] vocabulary, not as the ordinary currency symbol reused.", "childId": null, "number": "7.2", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "the-four-shapes", "title": "Four Shapes, and What Each Costs to Run", "body": "The four templates are not equally cheap, and the differences are worth naming.\n\n[[text-classification]] needs no transformation at all. A single sentence already is one ordered run of tokens, so those datasets are fine-tuned directly.\n\nEntailment adds one symbol and nothing else: premise, delimiter, hypothesis, one forward pass ([[entailment-input-transformation]]). The task hands over the order, so there is no decision to make.\n\nSimilarity is where the readout bites. The stack runs left to right and summarizes at the end, so whichever sentence is placed second sits nearer the summary, while the first has to survive the whole second sentence to reach it. Picking an order would make the prediction depend on an arbitrary choice the task never made.\n\nSo both orderings are built, each is run through the stack on its own, and the two final activations are added before the linear layer ([[similarity-input-transformation]]). Element-wise addition is symmetric, so swapping which sentence you called first leaves the head's input unchanged. The fix costs two forward passes per example.\n\nQuestion answering has a different problem: the number of candidates varies, and a fixed architecture cannot have a variable number of output slots. Building $[z; q; \\$; a_k]$ once per candidate sidesteps that by running the same fixed model several times ([[qa-and-commonsense-input-transformation]]). The softmax then normalizes across sequences rather than across label columns inside one sequence. The paper does not state the head's shape here, but for a distribution over candidates to come out, each pass must yield a single score.\n\nCost scales with the option count: two passes for the two endings of the [[story-cloze-test]], more for a multi-option exam question ([[race-dataset]]).\n\nOne limit goes unmentioned. The stack reads at most 512 tokens ([[context-window-512-tokens]]), while a comprehension sequence carries a full passage plus a question plus an answer. The paper says nothing about what happens when that overflows.\n\n[[fig-1]] draws all four beside the [[decoder-only-stack]] they feed.", "childId": "n-one-sequence-per-task--the-four-shapes", "number": "7.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "what-a-new-task-adds", "title": "Counting What a New Task Adds", "body": "The parameter claim ([[minimal-extra-parameters]]) is checkable, so check it.\n\n$W_y$ maps one 768-dimensional activation ([[hidden-state-dimension-768]]) to label scores. Three-way inference needs $768 \\times 3$, which is $2{,}304$ weights. Binary sentiment needs $1{,}536$. Multiple choice, producing one score per sequence, needs $768$. A delimiter embedding is another $768$ numbers.\n\nNow the denominator. From [[model-specification]], each block's self-attention holds four $768 \\times 768$ matrices; $768 \\times 768$ is $589{,}824$, so that sublayer is about $2.4$ million weights. The feed-forward sublayer holds two matrices of $768 \\times 3072$, which is $2{,}359{,}296$ each, so about $4.7$ million more. Call it $7$ million per block. With [[twelve-layer-depth]], the stack alone is roughly $85$ million, before the token embedding table is counted.\n\nThe arithmetic is mine from the stated dimensions; the paper reports no total.\n\nSo the comparison is a couple of thousand new numbers against tens of millions of transferred ones. The claim survives.\n\nBut read what it counts. These are the parameters that start from random initialization — not the parameters that change. The supervised loss ([[eq-supervised-objective]]) backpropagates through every block, so fine-tuning moves the entire stack.\n\nThat means each of the twelve datasets ends with its own complete copy of the weights. Nothing here is shared at deployment time.\n\nThe claim is about how much untrained machinery a task requires, not about storage. Which is the right claim for the argument it answers, since the objection to the alternative was precisely that its new components learn from scratch on scarce labels.", "childId": null, "number": "7.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "format-decides-the-menu", "title": "Four Templates, Twelve Datasets", "body": "Line the templates up against the evaluation menu ([[evaluation-task-families]], [[table-1]]) and the ratio is the point.\n\n[[natural-language-inference]] supplies five datasets, all of them the premise-delimiter-hypothesis shape. [[semantic-similarity]] supplies three, all on the two-pass symmetric shape. [[question-answering-and-commonsense-reasoning]] supplies two, both on the one-sequence-per-candidate shape. Classification supplies two, on no shape at all.\n\nFive plus three plus two plus two is twelve.\n\nSo breadth of tasks is not breadth of formats. Twelve datasets are covered by four templates, one of which is the empty template. Several of the datasets come bundled in [[glue-benchmark]], which is part of why the menu could be assembled this quickly.\n\nThe sizes are not uniform either. They run from roughly $5{,}700$ training examples on [[sts-b]] up to roughly $550{,}000$ on [[snli]], a spread of about two orders of magnitude, and the paper uses that spread to argue the recipe is not only a large-data technique.\n\nOne thing the menu holds constant is worth naming, because the transformations depend on it. Every one of the twelve ends in a label from a fixed set, or a choice among candidates the dataset supplies. None asks for generated text.\n\nThat is what lets the whole task-side apparatus be a serializer plus one scoring matrix. A task whose output is itself structured would need something else, and the paper does not claim it.\n\n[[etheme-one-stack-any-input-shape|One stack, any input shape]] — with the shapes counted, and the outputs kept simple.", "childId": null, "number": "7.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "7", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-the-scoreboard": {"id": "n-the-scoreboard", "parentId": "root", "parentChapterId": "the-scoreboard", "depth": 1, "title": "Reading the Scoreboard", "intro": "The parent gave the margins. This level gives the numbers on both sides of them, the units each column is measured in, and the three rows where the model does not come first.", "chapters": [{"id": "reading-the-columns", "title": "What a Point Means, and Who Is on the Other Side", "body": "Before any margin means anything, two things about the tables need saying.\n\nThe first is that a \"point\" is not one currency. [[absolute-improvement|Gains in percentage points]] are quoted across every task, but the columns of [[table-4]] are not all measuring the same quantity. Its header spells this out: [[cola|CoLA]] is scored by Matthews correlation, [[sst-2|SST-2]] by accuracy, [[mrpc|MRPC]] and [[qqp|QQP]] by F1, [[sts-b|STS-B]] by Pearson correlation.\n\nMatthews correlation is computed from the confusion matrix of a binary classifier and runs from $-1$ to $+1$, with $0$ at chance, reported here multiplied by 100. F1 is the harmonic mean of precision and recall on the positive class. Pearson correlation compares the model's graded similarity scores against the human ones.\n\nSo a 10.4 move on CoLA and a 4.2 move on QQP are moves along different scales. Adding them together is exactly what an aggregate score does, and the tables do it.\n\nThe second is what the numbers are being beaten. The [[baseline-comparisons|previous bests]] are not one system but a shelf of them, each built for its own dataset, and mostly recurrent — a [[lstm-gpt1|biLSTM]] core with attention, ELMo features, or both.\n\nSeveral are ensembles. [[table-2|Table 2]] annotates rows with `5x` and `3x` to mark ensembles of five and three models, and marks the previous best in each column by underlining it.\n\nThe paper's own entry is one row in each table, and it is a single model everywhere. That is the comparison being set up: one set of fine-tuned weights against a per-dataset field, some of which is voting.", "childId": null, "number": "8.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}, {"id": "the-margins", "title": "The Numbers Behind the Margins", "body": "With the units fixed, the head-to-head figures are worth reading directly.\n\nOn [[natural-language-inference|inference]], [[multinli|MultiNLI]] is reported in two columns, matched and mismatched: 82.1 and 81.4, against 80.6 and 80.1 from a three-model ensemble. The 1.5 the paper quotes is the matched column; the mismatched gain is 1.3.\n\n[[snli|SNLI]] moves from 89.3 to 89.9. The 89.3 was posted by two separate five-model ensembles, so the 0.6 is small but taken off a crowded ceiling.\n\n[[scitail|SciTail]] goes 83.3 to 88.3 and [[qnli|QNLI]] 82.3 to 88.1 — five and 5.8 points, both against single systems rather than ensembles.\n\nThe [[question-answering-and-commonsense-reasoning|reading and reasoning]] numbers in [[table-3]] have more inside them than the headline. [[race-dataset|RACE]] is split into middle-school and high-school questions. Middle school goes 60.2 to 62.9, a gain of 2.7. High school goes 50.3 to 57.4, a gain of 7.1.\n\nThe 5.7 overall is a blend of those two, and it is the harder split that carries it. The system passed on both is a nine-model ensemble.\n\nNote also the absolute level: 59.0 overall on RACE. The margin is wide, but it sits low on the scale, on a dataset picked because it holds more reasoning-type questions than the [[cnn-and-squad-contrast|extraction-style alternatives]].\n\n[[story-cloze-test|Story Cloze]] is the widest gap on any single number, 77.6 to 86.5. The paper reads the pair as evidence about long-range context, which is an interpretation laid over the numbers, not something the numbers separate out on their own.", "childId": "n-the-scoreboard--the-margins", "number": "8.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-three-it-loses", "title": "The Three Rows It Does Not Win", "body": "Nine of twelve leaves three, and the tables name them.\n\n[[rte|RTE]] is the one the paper discusses: 56.0 against 61.7 from a multi-task biLSTM. Its explanation is dataset size, 2,490 training examples, and its proposed fix is multi-task training, which it states it did not run.\n\nThe other two are quieter. On [[mrpc]] the model scores 82.3 F1 against a previous best of 86.0 — and the multi-task biLSTM in the same table scores 83.5, so this is third place, not second. On SST-2 the same pattern: 91.3 against 93.2 from the best system, with the multi-task biLSTM at 91.6 in between.\n\nSo one loss falls in [[semantic-similarity|similarity]] and one in [[text-classification|classification]], and neither is explained.\n\nThe size story does not hold on its own either. STS-B has roughly 5,700 training examples, more than twice RTE's but still the smallest set in the [[evaluation-task-families|evaluation]], and it is a win. Size alone does not sort the wins from the losses.\n\nThere is one more thing visible in the same table that the paper does not take up. The multi-task biLSTM that beats it on RTE scores 18.9 on CoLA, where the single-task version of the same architecture scores 35.0.\n\nMulti-task training, in the paper's own comparison set, helps on some columns and costs heavily on others. That makes the suggested fix for RTE less obviously free than the sentence proposing it implies, and it remains untested here either way — one of the softer spots in the [[state-of-the-art-9-of-12|nine of twelve]] claim.", "childId": null, "number": "8.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "adding-up", "title": "The Aggregate, and Where the Count Comes From", "body": "Two summary numbers close the evaluation, and both are assembled rather than measured.\n\nThe [[glue-benchmark|GLUE]] score of 72.8 against 68.9 is an aggregate over the tasks in its column, so a large move anywhere inside it lifts the total. The single-task biLSTM with ELMo and attention scores 64.8 on the same aggregate; the multi-task version, 68.9.\n\nThe column that moves furthest inside that aggregate is CoLA, and CoLA is also the column whose metric is least like an accuracy. The paper reads its 45.4 as evidence of linguistic bias picked up in pre-training. That reading is plausible and the number does not settle it.\n\nThe headline count is assembled the same way. Nine of twelve appears in no table. You get it by reading three of them and counting the bold rows: four inference wins, two reading wins, [[qqp]], STS-B and CoLA — with [[table-1]] fixing the denominator at twelve datasets across four families.\n\nWhat the whole board does establish is narrow and real. One pre-trained stack, fine-tuned per task with a task-shaped input and a linear head as in [[fig-1]], beats per-task systems on most rows and several ensembles among them.\n\nWhat it does not establish is which part of the recipe earned that. The scoreboard measures the finished pipeline end to end, and separating the pre-training, the architecture and the auxiliary objective takes a different experiment.\n\n[[theme-what-the-twelve-datasets-show|The twelve datasets in full]]; [[etheme-the-scoreboard-and-its-gaps|the gaps in the board]].", "childId": null, "number": "8.4", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 4, 5, 6, 7, 8]}}], "number": "8", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-which-parts-do-the-work": {"id": "n-which-parts-do-the-work", "parentId": "root", "parentChapterId": "which-parts-do-the-work", "depth": 1, "title": "Which Parts Do the Work, and What Is Left Open", "intro": "The parent named the three diagnostics. This level reads them as experiments: what was actually varied and what was held fixed, how each panel of Figure 2 is drawn and what its axes hide, which datasets the ablation table covers, and where the paper's own numbers disagree with each other.", "chapters": [{"id": "layer-sweep", "title": "Thirteen Runs Up the Stack", "body": "The left panel of [[fig-2]] is not one training run. It is a series of them, one per point.\n\nThe x-axis counts layers transferred, from 0 to 13. That is one slot for the embedding layer plus one for each block in the [[twelve-layer-depth]] stack. At position 1 only the [[token-embedding-matrix]] and the [[learned-position-embeddings]] carry over from [[generative-pretraining]]; every transformer block is initialized fresh. At 13 the whole pre-trained network carries over. Each position gets its own [[supervised-fine-tuning]] run.\n\nSo the leftmost useful point is roughly the older practice of [[word-embedding-transfer]], and the sweep asks what the blocks add on top of it.\n\nTwo datasets are plotted, and the axes are not shared. [[race-dataset]] dev accuracy reads off a left axis spanning 30 to 100, rising from about 39.7 to about 60. [[multinli]] dev accuracy reads off a right axis spanning 70 to 100, rising from about 72.5 to about 82.\n\nThat second window is a third as tall over the same plot height. A MultiNLI point therefore looks about two and a half times steeper than a RACE point of the same size. Read the colour before the slope.\n\nDashed lines are training accuracy from the same runs. They sit above the dev lines and climb further, so extra transferred layers also fit the labelled data harder.\n\nWhat the panel licenses is the monotone total. What it does not measure is any individual layer: the sweep only ever adds blocks from the bottom up, so it never asks what layers 6 through 12 are worth on their own. The reading in [[layers-transferred]] is consistent with the curve rather than demonstrated by it, on two datasets, on dev sets, one run each.", "childId": null, "number": "9.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "scoring-not-labelling", "title": "Turning a Next-Token Model Into a Scorer", "body": "The pre-trained model emits one thing: a distribution over the next token, formed by [[output-softmax-tied-embeddings]]. Nothing in it names a class.\n\nTo compare two candidate answers you can score each string by the summed log-probability of its tokens. That comparison is broken by length. Every token contributes a negative number, so the shorter candidate wins by default.\n\nDivide by the token count and the bias goes away. That mean is [[average-token-log-probability-scoring]], and three of the four constructions in [[zero-shot-behaviors]] rest on it.\n\nOn RACE the model is conditioned on the document and the question, each candidate answer is scored, and the highest wins ([[race-zero-shot-heuristic]]). This is the fine-tuning-time [[qa-and-commonsense-input-transformation]] with the classifier removed.\n\nDPRD is a set of Winograd schemas: a definite pronoun with two possible antecedents ([[coreference]]). The heuristic substitutes each antecedent for the pronoun and scores the rest of the sequence after the substitution ([[dprd-winograd-heuristic]]). Both readings score the same trailing tokens, so length is matched exactly and only the conditioning context differs.\n\n[[cola-zero-shot-heuristic]] is the odd one of the three. Acceptability is a single-sentence judgement with no competing candidate, so the score is compared against a threshold instead. The paper does not say how that threshold is set, which makes it a free parameter fitted somewhere outside the described procedure, unlike the three argmax constructions.\n\nSentiment uses a different device entirely ([[sst2-zero-shot-heuristic]]). Appending *very* and reading off the relative probability of *positive* against *negative* consults one next-token distribution, not a whole-string score. It also assumes the corpus phrases sentiment that way. The paper calls all four heuristic solutions and does not argue they are the best available ones for [[cola]] or [[sst-2]].", "childId": null, "number": "9.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "curves-over-training", "title": "Watching the Heuristics Climb", "body": "The right panel of [[fig-2]] shares nothing with the left one but the page. Its x-axis is pre-training updates on a log scale, $10^3$ to $10^6$, which is the run described in [[pre-training-optimization]] sampled as it went.\n\nThe y-axis is rescaled per task. Zero is a random-guess baseline and one is the best published single-model result on that task. A value of 0.68 means the heuristic closed 68% of that gap.\n\nThat rescaling is what lets four differently-scored tasks share an axis. It also means the ceiling is a moving reference from the [[baseline-comparisons]] of the day, and that no absolute accuracy can be read off the plot at all.\n\nAll four solid curves rise and largely stay risen. Nothing in the run is optimizing them: the only loss being minimized is [[language-modeling-objective]], and the corpus is books. The behaviours arrive as a side effect of fitting it, which the [[token-level-perplexity]] of 18.4 says was fitted well.\n\nOne alternative the panel does not separate: these heuristics all read fluency, and fluency improves with perplexity. A curve that rises with better next-token prediction is what you would see either way.\n\nThe dashed lines are an LSTM language model trained the same way. They reach lower and move around more, and the sentiment curve drops from 0.42 to 0.30 before recovering.\n\nThe paper offers this as support for [[transformer-inductive-bias]] — that attention over a wide context, restricted by [[masked-self-attention]], is a more structured memory for [[long-range-dependencies-gpt1]] than a recurrent state. It is one [[lstm-gpt1]] configuration against one transformer, single runs, with variance judged by eye off a plot. The paper writes *suggesting*, and that is the right strength for it.", "childId": null, "number": "9.3", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "three-removals", "title": "Three Removals, Eight Datasets", "body": "[[table-5]] is four recipes down the side and eight datasets across the top. Those eight are the [[glue-benchmark]] tasks.\n\nRACE and the [[story-cloze-test]] are not among them. The two datasets carrying the paper's largest margins are therefore absent from every row of its [[ablation-studies]].\n\nThe last column averages the eight numbers, unweighted. Those numbers are Matthews correlation, accuracy, F1 and Pearson correlation, so the average adds a correlation point to an accuracy point as if they were the same unit.\n\nThe full system scores 74.7. Removing pre-training gives 59.9, and $74.7 - 59.9 = 14.8$, with every column down ([[ablation-no-pretraining]]). One column dominates: CoLA falls from 45.4 to 18.9, and that 26.5-point drop divided across eight datasets contributes 3.3 of the 14.8 on its own.\n\nThe architecture swap gives 69.1, so $74.7 - 69.1 = 5.6$ ([[ablation-lstm-substitution]]). The substituted model is a single-layer LSTM of 2048 units, against twelve blocks of [[hidden-state-dimension-768]]. Depth, width and architecture all change together, so the 5.6 is not attributable to recurrence alone. The LSTM takes one column, [[mrpc]], at 83.2 against 82.3.\n\nThe third row is the one that does not behave. Fine-tuning with the supervised loss alone scores 75.0, three tenths above the full model, and takes the best cell in five of the eight columns ([[ablation-no-auxiliary-objective]]).\n\n[[auxiliary-lm-objective]] earns its keep on exactly three: [[qqp]], [[multinli|MNLI]] and QNLI. Those are the larger sets, which is the trend the paper states and the most it claims.\n\nThe recipe keeps a component that its own table scores slightly against on average, with [[auxiliary-objective-weight]] fixed at 0.5 and never swept.", "childId": "n-which-parts-do-the-work--three-removals", "number": "9.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "numbers-that-disagree", "title": "The Numbers That Do Not Line Up", "body": "[[rte]] is the clearest loss. The model reaches 56.0 against 61.7 from a multi-task biLSTM in [[table-2]], 5.7 points short, on 2,490 training examples. The paper suggests multi-task training would help and reports no such run. RTE is also one of the eight ablation columns, so the smallest set in the evaluation carries an eighth of every average in Table 5.\n\nThe GLUE figure moves between sections. [[table-4]]'s last column reads 68.9 to 72.8, and $72.8 - 68.9 = 3.9$. The introduction's headline for the same benchmark is 5.5. The paper does not reconcile the two, and the GLUE column folds in inference datasets that Table 4 does not show.\n\nSeveral wins are small enough that the missing variance matters. SNLI gains 0.6 in Table 2. [[sts-b]] gains 1 point in Table 4. Every number on both sides is a single reported run against a single published best, with no repeats and no spread given.\n\n[[state-of-the-art-9-of-12]] counts wins across [[evaluation-task-families]] without weighting them, so a 0.6 and the 8.9 in [[table-3]] each contribute one. The three that are not wins are RTE, SST-2 and [[mrpc]]. The gains are stated as [[absolute-improvement]] throughout, which keeps the arithmetic checkable.\n\nThe conclusion adds a claim the experiments do not carry. It says the model acquires significant [[world-knowledge]] from predicting long stretches of text. Every task in the evaluation rewards reading the passage in front of the model, and nothing in the design separates knowledge brought to a passage from comprehension of it.", "childId": null, "number": "9.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}], "number": "9", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-the-mismatch--two-questions": {"id": "n-the-mismatch--two-questions", "parentId": "n-the-mismatch", "parentChapterId": "two-questions", "depth": 2, "title": "What the Two Open Questions Were Made Of", "intro": "The parent named the two obstacles and the machinery each involved. This level opens them up: what each candidate objective actually optimizes, what kind of evidence \"each outperforms the others on different tasks\" is, what each transfer mechanism costs in parameters or tuning, and why the two questions were hard to separate from each other.", "chapters": [{"id": "what-each-objective-optimizes", "title": "What Each Objective Actually Optimizes", "body": "The first question ([[choice-of-pretraining-objective]]) gets one sentence and three citations. It does not say what any of the three optimizes. Here is what each one asks a model to produce.\n\nNext-token prediction is the [[language-modeling-objective]]. Take a run of text, and at every position ask the model for a distribution over the vocabulary. The loss is the log-probability it assigns to the token that actually came next, summed over positions — [[maximum-likelihood-training]] and nothing more. Any text at all is training data for it.\n\nTranslation asks for a whole sentence in a second language given a sentence in the first. The part that gets reused afterwards is the encoder's hidden states, since the decoder half has no job outside translation.\n\nThe paper does not point this out, but that objective needs sentence-aligned pairs, and those pairs are annotated data. So the three candidates do not sit on the same side of [[labeled-data-scarcity]]. Two run on raw text; one runs on a parallel corpus somebody built.\n\nDiscourse coherence asks whether a group of sentences belongs together in the order given. The supervision typically comes free from the document: sentences in their original order are positives, shuffled or substituted ones are negatives. Its usual output is one vector per sentence, which places it near [[phrase-and-sentence-embeddings]].\n\nThat difference in output matters more than the introduction's single sentence suggests. [[word-embedding-transfer]] hands the next model a lookup table. A sentence encoder hands it a vector. A language model hands over every weight in the network — which is what makes [[unsupervised-pretraining]] a choice of starting point rather than a choice of features, and what keeps all of this inside [[semi-supervised-learning-for-nlp]].", "childId": null, "number": "1.2.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 8]}}, {"id": "scatter-not-ranking", "title": "A Scatter, and What Would Resolve It", "body": "Read the claim exactly: each *method* outperforms the others on different tasks. Not each objective. That distinction carries the whole difficulty.\n\nA method is an objective, plus an architecture, plus a corpus, plus a way of moving the result into the target task, plus a choice of which datasets to report. Three groups built three such bundles. When one wins on sentiment and another wins on entailment, the objective is one of five things that differ.\n\nNothing in that comparison isolates it. And the paper does not fix the problem: it never trains a translation-objective or coherence-objective model of its own, so it never runs the head-to-head the sentence describes as unresolved.\n\nWhat it runs instead is a comparison against none. [[ablation-no-pretraining]] in [[table-5]] trains the same transformer directly on the supervised tasks and loses 14.8 points on average. [[layers-transferred]] in [[fig-2]] carries a growing number of pre-trained layers into fine-tuning and finds each one adds. A [[token-level-perplexity]] of 18.4 says the objective was fit well, and [[zero-shot-behaviors]] says the fitted model already performs some of the tasks.\n\nEvery one of those measures pre-training against no pre-training. None measures language modelling against translation. The choice is defended as useful, not as best, which is a weaker claim than the question asked for.\n\nThe footnote is the honest part. It points at the [[glue-benchmark]] leaderboard rather than at a paper. A leaderboard is a number that changes, so citing one as evidence about which objective transfers says the ordering was still moving. That board scores the same [[natural-language-understanding]] tasks the paper later reports on ([[evaluation-task-families]], [[baseline-comparisons]]).", "childId": null, "number": "1.2.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 4, 5, 6, 7, 8]}}, {"id": "machinery-and-cost", "title": "Three Kinds of Machinery, Three Kinds of Cost", "body": "[[how-to-transfer-representations]] gets a list of three, each with its own citation. Resolve the citations and the three become concrete.\n\nTask-specific architecture changes first. The transferred representation goes in at the bottom, and above it sits a network shaped around one task: an attention layer between premise and hypothesis for entailment, a pooling scheme for classification, and so on. [[task-specific-architectures]] means these get designed, tuned and trained from scratch, once per task. Neither the design work nor the weights carry to the next task.\n\nIntricate learning schemes second. The citation the introduction attaches here is the same work the related-work section describes as fine-tuning a pre-trained LSTM language model on a staged schedule ([[ulmfit]], inside [[lm-pretraining-then-finetuning-predecessors]] alongside [[semi-supervised-sequence-learning]]).\n\nThe cost there is not parameters. It is schedule: which layers unfreeze in which epoch, a separate learning rate per layer, a shaped rate curve. Those numbers have to be found per task.\n\nExtra unsupervised loss terms third. [[auxiliary-training-objectives]] adds a second loss to the supervised one and optimizes the sum, so raw text keeps shaping the weights while the labels do. The cost is one weight to tune and the compute of a second head.\n\nNow the honest part. The paper does not drop the third mechanism — it keeps it. Fine-tuning here optimizes [[auxiliary-lm-objective]], with [[auxiliary-objective-weight]] set to 0.5, and the paper's own [[ablation-no-auxiliary-objective]] reports the benefit is uneven: larger datasets gain from the term, smaller ones do not.\n\nSo the complaint is not that these mechanisms fail. It is that three were in use at once, each traced to a different paper, and nobody had removed them one at a time. The ablation table later in this paper is what doing so looks like.", "childId": "n-the-mismatch--two-questions--machinery-and-cost", "number": "1.2.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "frozen-features", "title": "Frozen Features, and the Metric the Paper Picks", "body": "A fourth option sits slightly apart from those three, and the paper puts it in the related-work section rather than the introduction.\n\n[[feature-based-transfer]]: freeze the pre-trained model, run the input through it, take the hidden states out, and hand them to a separate task model as extra input vectors alongside that model's own embeddings. The best-known instance is [[elmo-deep-contextualized-word-representations]], where the states come from a pre-trained bidirectional language model.\n\nNote what does not happen. No gradient from the task loss reaches the pre-trained weights. They are a fixed function from tokens to vectors, and everything that learns the task is new.\n\nThat is where [[per-task-parameter-cost]] comes from. The paper's phrase is that such approaches involve a substantial amount of new parameters for each separate target task. It is choosing a metric: count the freshly initialized parameters a new task requires. On that metric its own side reads [[minimal-extra-parameters]] — one [[linear-output-layer-wy]], plus embeddings for the [[delimiter-token]]s that [[task-specific-input-transformations]] introduces through its [[traversal-style-approach]].\n\nThe metric is not neutral. A frozen model has advantages the count does not see. Its states can be computed once and cached across every epoch. No gradients flow through the deep stack. One copy of the pre-trained weights serves all tasks at the same time.\n\nFine-tuning gives up all three. It needs a full backward pass through every layer, and it ends with a separate copy of the entire model per task.\n\nThe paper does not weigh those costs against each other. It picks the parameter count, on which its own approach wins, and moves on.", "childId": null, "number": "1.2.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}], "pages": [1, 2, 3, 4, 5, 6, 7]}}, {"id": "why-they-compound", "title": "Why the Two Questions Compound", "body": "The paragraph ends with a diagnosis: these two uncertainties are why effective semi-supervised approaches for language had been hard to build. The question is why two open problems should compound rather than simply add.\n\nThey compound because the objective constrains the transfer. A translation model's usable half is an encoder, so its output arrives as features and a task network has to be built to consume them. A sentence encoder hands over one vector per sentence, and anything the task needs below that level must come from elsewhere.\n\nA language model is the case where the whole stack comes across. That is the one setting in which [[transfer-learning]] can mean keeping every weight and continuing to train it.\n\nThe citations show the tangle directly. The work cited for the language modelling objective is also cited for task-specific architecture changes. The work cited for translation is also cited as a source of auxiliary features. Nobody was varying one factor at a time, because each published system was a single point rather than a row in a grid.\n\nThat shape explains what the rest of the paper does. It fixes one objective and one transfer style — [[generative-pretraining]] followed by fine-tuning, together the [[two-stage-training-procedure]] — and then holds the architecture constant across every task, which is what [[task-agnostic-model]] means here.\n\nIts argument against recurrent predecessors ([[lstm-short-range-limitation]]) and its count of [[state-of-the-art-9-of-12]] are both attempts to make one point in that grid carry the case. Neither closes the comparison the introduction says is open. They argue that this pairing works, not that it is the right one.", "childId": null, "number": "1.2.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "1.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-which-family-this-joins--closest-line": {"id": "n-which-family-this-joins--closest-line", "parentId": "n-which-family-this-joins", "parentChapterId": "closest-line", "depth": 2, "title": "Nearly the Same Recipe", "intro": "The parent gave you the shape of the argument: same recipe, two claimed differences, one of them barely measured. This level opens each piece up — what the two earlier systems actually trained, what the short-range sentence is asserting step by step, and how much weight each experiment can carry once you look at what it varied.", "chapters": [{"id": "what-they-did", "title": "What the Two Predecessors Actually Trained", "body": "[[semi-supervised-sequence-learning]] is the earlier of the two works named under [[lm-pretraining-then-finetuning-predecessors]], and its pre-training stage came in two forms.\n\nOne was the [[language-modeling-objective]]: read unlabelled text and predict the next token. The other was a sequence autoencoder: read a sequence into a recurrent state, then train the network to emit that same sequence back out. Either way the pre-trained weights were those of an [[lstm-gpt1]], and either way the second stage was [[supervised-fine-tuning|supervised fine-tuning]] of the whole network for [[text-classification]].\n\n[[ulmfit]] kept only the language modelling half. It pre-trained an LSTM language model, then fine-tuned it for classification on a schedule that was staged rather than uniform — different layers brought in at different points, with the learning rate shaped to match.\n\nThat staging is worth holding onto, because this paper cites the same work twice for two different reasons.\n\nIn the related work section it appears as the closest line. In the introduction it appears in the list of things that make [[how-to-transfer-representations]] an open question, under the heading of intricate learning schemes.\n\nSo the paper is not only claiming a different architecture. It is also claiming that its own second stage is plainer than ULMFiT's: [[three-epochs-fine-tuning]] for most datasets, and [[minimal-extra-parameters]] on top of the pre-trained stack.\n\nThat difference is never argued in the related work section. It is stated as a property of [[two-stage-training-procedure]] elsewhere, and left there. Only [[unsupervised-pretraining]] as a category, and the range claim, are put forward here as the separation.", "childId": null, "number": "2.5.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "inside-the-sentence", "title": "One Sentence, and the Chain Inside It", "body": "[[lstm-short-range-limitation]] is a single clause: the predecessors' use of LSTMs restricts their prediction ability to a short range. Unpacked, it is two steps, and only the second is about transfer.\n\nThe first step is about what a recurrent network can learn at all. Everything it knows about the prefix lives in one fixed-size state, rewritten at every token. A dependency reaching back four hundred tokens has to survive four hundred overwrites of that state to affect the prediction.\n\nThe second step is the transfer consequence. If pre-training never taught the model to condition on such a dependency, the pre-trained weights hold nothing about it to carry into the target task. Whatever linguistic information the phase does capture, the reach of the transferred model is capped by the reach of the pre-trained one.\n\nThe paper's alternative is stated as a property of [[multi-layer-transformer-decoder]]. [[masked-self-attention]] lets every position take a direct weighted read of every earlier position, with no compression through time in between, and [[context-window-512-tokens]] fixes how far back that reach extends.\n\nThe corpus is chosen so the window has something to reach across. [[bookscorpus]] supplies [[long-range-contiguous-text]] — sentences and paragraphs in their original order — where the [[one-billion-word-benchmark]] used by [[elmo-deep-contextualized-word-representations]] is shuffled at the sentence level.\n\nWhat is never supplied is a number. The paper does not say what range an LSTM reaches, nor what range its own model reaches, nor how [[long-range-dependencies-gpt1]] such as [[coreference]] across sentences fare under either. The sentence ends with a forward pointer to the experiments.", "childId": null, "number": "2.5.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-one-swap", "title": "The One Controlled Swap, and What It Varied", "body": "Of the three rows in [[ablation-studies]], reported in [[table-5]], one speaks to the range claim. [[ablation-lstm-substitution]] holds the framework fixed — same input transformations, same fine-tuning procedure, same objective — and replaces the transformer with a single-layer 2048-unit LSTM. The average score falls by 5.6 points.\n\nRead that configuration against [[model-specification]]. The transformer is [[twelve-layer-depth]] with [[hidden-state-dimension-768]] states. The LSTM is one layer, of 2048 units.\n\nSo the swap changes two things at once: recurrence for attention, and depth twelve for depth one. The paper's own layer analysis says depth carries value, which means part of the 5.6 may be depth rather than range.\n\nThe exception is [[mrpc]], the [[semantic-similarity]] dataset built from news sentence pairs, and the only dataset where the LSTM comes out ahead. The paper reports the exception in one clause and does not account for it. The pairs there are short, which is where a limit on reach should cost least — but the paper does not say that, and neither does the table.\n\nFor scale, the same table reports [[ablation-no-pretraining]] at 14.8 points. Architecture is worth roughly a third of what stage one is worth, on the paper's own averaging, while [[ablation-no-auxiliary-objective]] moves the average by far less than either.\n\nAll of which leaves 5.6 as a scalar summarising a set of dataset scores. Nothing in it is indexed by distance, so nothing in it separates a range effect from any other advantage the transformer might have.", "childId": null, "number": "2.5.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 4, 5, 6, 7, 8]}}, {"id": "layers-and-variance", "title": "Two Diagnostics That Point Sideways", "body": "[[layers-transferred]] is the left panel of [[fig-2]]. Dev accuracy on [[multinli]] and [[race-dataset]] is plotted against how many pre-trained blocks are carried into fine-tuning. Transferring the embeddings alone already helps, and each further block adds more, reaching up to 9% for full transfer on MultiNLI.\n\nThe conclusion drawn is that every layer holds function worth carrying. That is a claim about how much of the stack transfers.\n\nIt is not a claim about how far back a prediction reaches. A curve rising with depth would look the same whether the extra layers bought range, abstraction, or capacity.\n\nThe right panel tracks [[zero-shot-behaviors]]: four heuristics, three of them built on [[average-token-log-probability-scoring]], run against the generative model across pre-training checkpoints with no fine-tuning at all. The scores rise steadily and stay stable.\n\n[[transformer-inductive-bias]] is the hypothesis attached to that panel — that attention gives a more structured memory than a recurrent state, and that this is what assists transfer. The evidence offered for it is one observation: the LSTM shows higher variance in its zero-shot scores.\n\nHigher variance across checkpoints is instability. It is not reach.\n\nThe paper's own verb is suggesting, twice in that paragraph, and the hedge is fair. Put together, the range claim rests on an averaged score gap, a depth curve, a variance observation, and a design argument about a 512-token window over contiguous book text. Each is consistent with the claim. None of them measures it.", "childId": null, "number": "2.5.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}, {"id": "breadth-by-inspection", "title": "The Difference You Can Check by Inspection", "body": "The second claimed difference asks nothing of the reader beyond looking at [[table-1]]. [[evaluation-task-families]] covers four families and twelve datasets, where the predecessors reported [[text-classification]].\n\nWalk the list. Five datasets are [[natural-language-inference]], from [[snli]] at roughly 550k training examples down to [[rte]] at 2490. Two are [[question-answering-and-commonsense-reasoning]], including the [[story-cloze-test]], where a multi-sentence story has to be finished with the right one of two endings. Three are [[semantic-similarity]], among them [[qqp]] and [[sts-b]] at about 5.7k examples. Two are single-sentence classification, one of which is [[sst-2]].\n\nSo ten of the twelve sit outside the task type the earlier work reported on. Only the last two are the same kind of problem.\n\nThat is a fact about which datasets were run, not an inference from a score gap. It survives whatever you conclude about range.\n\nAnd it is carried by a different part of the paper. Breadth comes from [[task-agnostic-model]] plus the input transformations that fold ordered pairs and document-question-answer triples into one token sequence. Nothing in that argument depends on choosing attention over recurrence.\n\nThe headline that follows — [[state-of-the-art-9-of-12]] — is likewise a count, not a mechanism.\n\nWhich leaves the two claimed differences resting on very different footings. One is asserted, pointed forward, and then supported indirectly. The other is simply exhibited.", "childId": null, "number": "2.5.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "2.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-predicting-the-next-token--stack-dimensions": {"id": "n-predicting-the-next-token--stack-dimensions", "parentId": "n-predicting-the-next-token", "parentChapterId": "stack-dimensions", "depth": 2, "title": "The Numbers the Stack Was Built With", "intro": "The parent listed the dimensions. This level takes them one at a time and asks what each one actually controls inside a block, what it costs in weights or activations, and what the paper offers as a reason for it — which, for most of them, is nothing.", "chapters": [{"id": "one-width-everywhere", "title": "The Width That Nothing Is Allowed to Change", "body": "Of the numbers in [[model-specification]], 768 is the least free. It is not a per-layer setting that happens to be held constant. Three separate places in [[multi-layer-transformer-decoder]] pin it to the same value at once.\n\nThe first is the input. [[input-representation-h0]] adds token embeddings and position embeddings together, so both tables must produce vectors of the same width, and that width becomes the width of everything downstream.\n\nThe second is the residual stream. Each block adds its sublayer outputs back into the state it received, so whatever a block computes internally, it must hand back something of the same shape it was given.\n\nThe third is the output. [[output-softmax-tied-embeddings]] scores the vocabulary by multiplying the top state by the transpose of the embedding table. That product only makes sense if a top-layer state is the same length as one row of [[token-embedding-matrix]].\n\nSo [[hidden-state-dimension-768]] is one decision made once, not twelve.\n\nIt is also where a large block of weights sits outside the stack. [[byte-pair-encoding-gpt1]] with [[bpe-merges-40000]] gives a vocabulary of roughly forty thousand entries. Forty thousand rows of 768 numbers is 30.7M weights. [[learned-position-embeddings]] add one row per slot in the [[context-window-512-tokens]], so 512 by 768, about 0.4M more.\n\nTying means that table is read twice per forward pass — once to look up, once transposed to score — and receives gradient from both.", "childId": null, "number": "4.4.1", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "heads-that-cost-nothing", "title": "Twelve Heads, and What They Do Not Cost", "body": "Head count is the one dimension here that is free in parameters.\n\nA block's attention uses four square projections — query, key, value, and the output projection that recombines. Each is 768 by 768, whatever the head count. [[twelve-attention-heads]] does not add a thirteenth matrix; it slices the three input projections into twelve strips of 768 by 64 and lets each strip run its own attention. The recombining matrix then stitches the twelve 64-dimensional results back into 768. Four times 589,824 is about 2.4M weights, and that figure is the same for one head or for twelve.\n\nWhat the count does change is how many distinct attention patterns a block can hold. One head must fold all its evidence about the past into a single softmax over positions. Twelve can keep twelve, which matters for the [[long-range-dependencies-gpt1]] the paper is after, where one head might track the nearest few tokens while another reaches back hundreds.\n\nThe 64-dimensional subspace also sets the scale inside the softmax: dot products are divided by $\\sqrt{64}$, which is 8.\n\nThe real cost is activations. Under [[masked-self-attention]], each head builds a triangular 512 by 512 score matrix; twelve heads is about 3.1M scores per sequence per block, and [[pretraining-schedule]] runs 64 sequences at a time.\n\nOn the choice itself, the paper says only that it largely follows the original [[transformer-gpt1]] work. [[eq-decoder-stack]] treats the block as given, and [[decoder-only-stack]] inherits its interior unchanged. No head-count comparison is reported.", "childId": null, "number": "4.4.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "fourfold-and-the-bend", "title": "The Sublayer That Holds Two Thirds of the Weights", "body": "The second sublayer is where most of a block's parameters live, and where none of its communication happens.\n\n\"Position-wise\" in [[position-wise-feedforward-3072]] means the same 768 to 3072 to 768 map runs at every position independently, with nothing passing sideways between them. That splits the block cleanly: attention moves information between tokens, and this sublayer does the per-token computation on what arrived.\n\nCount it. $768 \\times 3072$ is 2,359,296, and there are two such matrices, up and back down. About 4.7M, against attention's 2.4M. Two thirds of each block.\n\nBetween the two matrices sits [[gelu]], written $x\\,\\Phi(x)$, where $\\Phi$ is the standard normal cumulative distribution. Work two inputs through it. At $x = 2$, $\\Phi$ is about 0.977, so the input passes through nearly untouched. At $x = -2$, $\\Phi$ is about 0.023, so the output is about $-0.046$ — close to zero, but not zero, and still carrying gradient.\n\nThat is the difference from a hard cut at zero. The curve also dips slightly below zero for mildly negative inputs before flattening, so it is not monotone.\n\nThe paper states the choice with a citation and no comparison. No ReLU control run appears anywhere in it.\n\nOne more thing acts on this sublayer's output. Under [[regularization-setup]], [[residual-embedding-attention-dropout]] applies [[dropout-gpt1]] at rate 0.1 to residual branches, so what a block computes is thinned before it is added back. [[fig-1]] draws the two sublayers in sequence.", "childId": null, "number": "4.4.3", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "init-and-layernorm", "title": "One Standard Deviation for Every Matrix", "body": "[[weight-initialization]] draws every weight from $\\mathcal{N}(0, 0.02)$. The thing to notice is that this is one number applied to matrices with very different fan-in.\n\nCompare it against the usual scaling. For a projection reading 768 inputs, $1/\\sqrt{768}$ is about 0.036, so 0.02 is a little over half of what a fan-in rule would ask. For the feed-forward matrix reading 3072 inputs, $1/\\sqrt{3072}$ is about 0.018, and 0.02 is almost exactly it.\n\nSo the same draw is roughly fan-in-scaled for the widest matrix in the block and deliberately small for everything else.\n\nThe paper's stated reason for getting away with this is [[layer-normalization-gpt1]]. Normalization rescales each position's activations to zero mean and unit variance before applying a learned gain and bias, so the size of what reaches the next matrix is largely reset regardless of how the weights were drawn. The word the paper uses is \"sufficient.\"\n\nThat is an assertion, not a result. No initialization sweep is reported, no run that diverged under an alternative, no comparison of any kind.\n\nThe prose also does not say where normalization sits within a block, only that it is used extensively throughout the model; the block diagram shows one after each sublayer.\n\nThose learned gains surface again in [[pre-training-optimization]]. The [[decoupled-weight-decay]] term applies $w = 0.01$ to all non-bias and non-gain weights, which exempts them. Together with [[adam-optimizer-gpt1]] and the [[linear-warmup]] over 2000 updates, this is the whole of what keeps early training stable, and none of it is ablated.", "childId": null, "number": "4.4.4", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "depth-as-dial", "title": "The Only Number the Paper Turns", "body": "Every dimension so far arrives as a stated setting with nothing behind it. [[twelve-layer-depth]] is different, because [[layers-transferred]] makes it a variable.\n\nThe left panel of [[fig-2]] plots dev accuracy on [[multinli]] and [[race-dataset]] against how many of the twelve pre-trained blocks are carried into fine-tuning. The leftmost point transfers the embedding table alone, which is [[word-embedding-transfer]], and which the paper calls the standard result. From there, accuracy climbs with each block added, reaching up to 9% for full transfer on MultiNLI.\n\nRead what that licenses. The curve is still rising at twelve, and the paper reports no point past it and no run at any other depth.\n\nSo the sweep says no transferred layer was dead weight. It does not say twelve was the right depth, and it does not show the gain flattening out.\n\nThere is a price attached to the 9%. At roughly 7.1M weights per block, carrying all twelve moves about 85M parameters into the target task, on top of the embedding table.\n\nOne nearby number is easy to misread as the same experiment. In [[table-5]], [[ablation-no-pretraining]] costs 14.8 points — but that is the same twelve-layer stack trained on the task from scratch, not the zero-layer end of this curve.\n\nThe evidence here is two datasets, dev accuracy, single runs, no error bars.", "childId": null, "number": "4.4.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "4.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-the-corpus-and-the-training-run--shape-of-the-stack": {"id": "n-the-corpus-and-the-training-run--shape-of-the-stack", "parentId": "n-the-corpus-and-the-training-run", "parentChapterId": "shape-of-the-stack", "depth": 2, "title": "How the Dimensions Fit Together", "intro": "One block, followed from the vector that enters it to the vector that leaves. Then the arithmetic behind the smaller choices the specification states in a sentence each: what each one costs, what it leaves undefined, and how much the paper actually tested.", "chapters": [{"id": "inside-one-block", "title": "One Block, Followed Through", "body": "A single position enters a block carrying one [[hidden-state-dimension-768|768-number]] vector. [[input-representation-h0|At layer zero]] that vector is a token embedding plus a position embedding. Above layer zero it is whatever the block below produced.\n\nThe attention sublayer first makes three versions of it. The query, key and value projections each multiply the vector by a $768 \\times 768$ matrix, so all three come out at full width.\n\nThen the split. Those 768 numbers are cut into [[twelve-attention-heads|twelve]] contiguous slices of 64. Head $h$ takes slice $h$ of the query, slice $h$ of the key and slice $h$ of the value, and never sees the other eleven.\n\nNothing is duplicated by this. Twelve heads of width 64 cost exactly the arithmetic of one head of width 768. What changes is that the comparison between two tokens becomes twelve separate 64-dimensional dot products rather than one 768-dimensional one — twelve narrow views instead of one wide one.\n\nThe head width also fixes the score scale. Attention divides each dot product by $\\sqrt{d_k}$, and $d_k = 64$ makes that divisor exactly 8.\n\nEach head's scores then pass the [[masked-self-attention|causal mask]] before the softmax, so positions after the current one get zero weight. There is no encoder output to attend to instead — [[decoder-only-stack|that half is gone]].\n\nThe twelve 64-dimensional results are concatenated back to 768 and sent through the fourth $768 \\times 768$ matrix.\n\nThe second sublayer mixes nothing. [[position-wise-feedforward-3072|The feed-forward network]] runs on each position on its own: up to 3072, activation, back down to 768.\n\nBoth sublayers sit on residual branches with [[layer-normalization-gpt1|layer normalization]]. This is the block [[fig-1|Figure 1 draws]] once, stacked twelve times, and written out in [[eq-decoder-stack|Equation 2]] — the [[transformer-gpt1|transformer]] block with the encoder attention removed.", "childId": "n-the-corpus-and-the-training-run--shape-of-the-stack--inside-one-block", "number": "5.3.1", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "where-the-count-lands", "title": "Where the Count Actually Lands", "body": "The total is worth splitting three ways, because the three parts behave differently.\n\nInside a block the two sublayers are not equal. Attention's four projections come to $4 \\times 589{,}824$. The feed-forward pair comes to $2 \\times 2{,}359{,}296$, which is that same quantity twice over. So exactly two thirds of a block's weights sit in the position-wise map and one third in attention.\n\nMost of the per-block capacity is the transformation applied after mixing, not the mixing.\n\nThe embedding table is the other large piece. [[bpe-merges-40000|40,000 merges]] is not itself a row count: the vocabulary is the base symbols, plus the merged symbols, plus the tokens added later for fine-tuning, and the paper never states the total. Round to 40,000 rows and the table is $40{,}000 \\times 768 = 30{,}720{,}000$ parameters.\n\nThat table is used at both ends. [[token-embedding-matrix|$W_e$]] maps tokens in at the bottom, and [[output-softmax-tied-embeddings|its transpose scores the vocabulary]] at the top. There is no separate output matrix, so those rows take gradient from the input lookup and from the final softmax together.\n\nThen there is a cost no parameter count shows. Each head builds a score matrix over the [[context-window-512-tokens|512-token window]]: $512 \\times 512 = 262{,}144$ numbers. Twelve heads across [[twelve-layer-depth|twelve layers]] make $37{,}748{,}736$ of them for one sequence, and a minibatch holds 64 sequences — about 2.4 billion attention weights alive per step.\n\nIn arithmetic it is smaller than that sounds. Per token per block, the four projections are 2.36M multiply-accumulates, the feed-forward 4.72M, and the attend-and-average over 512 positions about 0.79M. At this window the quadratic term is roughly a tenth of the work. The window costs memory more than it costs compute, and none of this appears in [[model-specification|the specification]].", "childId": null, "number": "5.3.2", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [3, 4, 5, 7, 8]}}, {"id": "positions-as-a-table", "title": "A Table Instead of a Function", "body": "[[learned-position-embeddings|The switch to a learned table]] gets one sentence in the paper and no reason attached to it.\n\nThe two options are different kinds of object. A sinusoid is a function of the slot index and the channel: hand it any integer and it returns a vector. Slot 900 has an encoding whether or not any training sequence ever reached slot 900.\n\nA table is a parameter. $W_p$ has 512 rows because the model reads 512 slots. Row 513 is not wrong or degraded. It does not exist.\n\nThe window has stopped being a training decision and become a shape.\n\nIn parameters it is cheap: $512 \\times 768 = 393{,}216$, under half a percent of the stack.\n\nThe interesting difference is in training traffic, since a learned row only knows what gradient reached it. [[pretraining-schedule|Every pre-training minibatch]] is 64 contiguous sequences of exactly 512 tokens. Every one of the 512 rows therefore appears once in every sequence, at every update. The last row is trained as hard as the first.\n\nStage two does not hold that property. [[task-specific-input-transformations|Task inputs are rewritten]] into a single sequence starting at slot one, bracketed by [[start-and-end-tokens|start and end tokens]] and split by a [[delimiter-token|delimiter]]. Many of those sequences stop well short of 512 slots, and fine-tuning runs for [[three-epochs-fine-tuning|three passes]] over a small dataset.\n\nSo the high-index rows enter each task carrying only what pre-training put there, and receive little further gradient.\n\nThe paper measures none of this. It reports no comparison of learned against sinusoidal embeddings, and no evidence that the substitution changed any result.", "childId": null, "number": "5.3.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [1, 2, 3, 4, 5]}}, {"id": "the-smooth-gate", "title": "A Gate That Slides", "body": "[[gelu|GELU]] and ReLU differ in exactly one factor. ReLU multiplies $x$ by the indicator $\\mathbb{1}[x>0]$, a gate that is either 0 or 1. GELU multiplies $x$ by $\\Phi(x)$, a gate that slides continuously between them.\n\nPut two numbers through it. At $x = 2$, $\\Phi(2) = 0.977$ and the output is $1.95$, where ReLU would give $2$. At $x = -2$, $\\Phi(-2) = 0.023$ and the output is $-0.046$, where ReLU would give exactly $0$.\n\nTwo things follow from that.\n\nFirst, there is no flat half-line. ReLU's derivative is identically zero for every negative input, so a unit driven negative receives no gradient at all. GELU's derivative is $\\Phi(x) + x\\phi(x)$, which shrinks as $x$ falls but is never zero across a stretch.\n\nSecond, the function is not monotone. That derivative crosses zero near $x = -0.75$, where GELU bottoms out around $-0.17$ and then climbs back toward zero. Slightly more negative inputs can produce less negative outputs.\n\nAll of this happens inside the feed-forward sublayer, between its two matrices.\n\nThe evidence behind the choice is thin, and the paper does not pretend otherwise. It names GELU with a citation and says nothing more. It is not among [[ablation-studies|the three removals]] the paper does run — [[ablation-no-pretraining|no pre-training]], [[ablation-lstm-substitution|an LSTM in place of the transformer]], and [[ablation-no-auxiliary-objective|no auxiliary loss]] — reported in [[table-5|Table 5]]. Nothing here says what the same stack with ReLU would have scored.", "childId": null, "number": "5.3.4", "sources": {"sections": [{"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [4, 5, 7, 8]}}, {"id": "why-small-init-held", "title": "Why 0.02 Was Enough", "body": "The claim attached to [[weight-initialization|$\\mathcal{N}(0, 0.02)$]] is that layernorm made it sufficient. It reads better once you see what would otherwise have gone wrong.\n\nTake a $768 \\times 768$ projection whose input components have unit variance. Draw the weights at standard deviation $\\sigma$ and the outputs come out at $\\sigma\\sqrt{768}$, which is $\\sigma \\times 27.7$.\n\nFor that to land at 1, $\\sigma$ would have to be $1/\\sqrt{768} = 0.036$. The rule usually paired with rectified activations asks for $\\sqrt{2/768} = 0.051$. At $0.02$ the output standard deviation is $0.554$ instead.\n\nThat is a shrink of nearly half at every matrix. There are two matrix stages per block and twelve blocks in [[multi-layer-transformer-decoder|the stack]]. Compounded, $0.554^{24}$ is about $7 \\times 10^{-7}$ — the signal would reach the top essentially gone, and the gradient would come back the same way.\n\nNormalization removes the compounding. Each normalized point rescales its vector to zero mean and unit variance across the 768 channels, so the shrink is undone before the next stage and absolute scale never accumulates.\n\nWhat the small draw then controls is not activation scale. It is how large each sublayer's contribution is against the residual stream it is added to, and at step zero that is small — further attenuated by [[residual-embedding-attention-dropout|dropout on the residual branches]].\n\nOne related detail sits in the same paragraph of the paper: [[decoupled-weight-decay|the modified weight decay]] skips all bias and gain weights, leaving layernorm's learned scales free.\n\nThe same 0.02 covers every matrix, with no per-layer adjustment — which is what makes it simple. And \"sufficient\" is a report that the run worked, not a comparison. No initialization experiment appears in [[pre-training-optimization|the training setup]] or the analysis.", "childId": null, "number": "5.3.5", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}], "number": "5.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, "n-from-language-model-to-classifier--why-the-old-loss-stays-on": {"id": "n-from-language-model-to-classifier--why-the-old-loss-stays-on", "parentId": "n-from-language-model-to-classifier", "parentChapterId": "why-the-old-loss-stays-on", "depth": 2, "title": "The Second Loss, Term by Term", "intro": "The parent settled what the auxiliary term is and where the paper puts it. This level does the arithmetic: which text the loss actually reads, what the tied head saves and what it costs to run, what $\\lambda = 0.5$ does and does not pin down, how thin the evidence for the two claimed effects is, and what the ablation row comes to when you do the subtraction yourself.", "chapters": [{"id": "what-the-loss-reads", "title": "Which Text the Loss Reads", "body": "$\\mathcal{C}$ — the [[labeled-dataset-c]] — does not hold plain sentences by the time either loss touches it. Its inputs have already been through [[task-specific-input-transformations]].\n\nSo the sequence the auxiliary term scores is the transformed one, and that sequence contains tokens no book contains. Every input is bracketed by [[start-and-end-tokens]]. The parts inside are separated by the [[delimiter-token]] `$`.\n\n[[eq-lm-objective]] asks the model to predict each token from the tokens before it, and these markers sit in the stream like any other token. The paper does not say whether the positions holding them are scored or skipped.\n\nHow many sequences an example produces also varies by task. [[entailment-input-transformation]] makes one sequence from a premise and a hypothesis. [[similarity-input-transformation]] makes two, one for each ordering of the pair. [[qa-and-commonsense-input-transformation]] makes one per candidate answer, so a four-way multiple-choice question yields four.\n\nWhatever the label loss reads, the auxiliary term reads exactly the same sequences.\n\nWhat it never reads is the label. $y$ is not in the token stream at all; it is reachable only through [[linear-output-layer-wy]]. So the gradient from the auxiliary term flows into the embeddings and into every transformer block, and never into $W_y$.\n\nThere is a shift in the text itself as well. Pre-training scored [[long-range-contiguous-text]] in windows of [[context-window-512-tokens]]. A premise, a `$` and a hypothesis is a much shorter object with a marker in the middle.\n\nThe same objective is now being maximized on text of a different shape, and the paper does not comment on that.", "childId": null, "number": "6.3.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "free-in-parameters", "title": "Free in Parameters, Not in Compute", "body": "\"No new parameters\" is worth putting a number on.\n\nThe vocabulary comes from [[byte-pair-encoding-gpt1]] built with [[bpe-merges-40000]], so it holds on the order of 40,000 subword units. Each state in the stack is [[hidden-state-dimension-768]] wide. A projection from a 768-dimensional state to 40,000 scores is therefore a matrix of about 30.7 million entries.\n\n[[output-softmax-tied-embeddings]] means that matrix is never stored. The head is the transpose of [[token-embedding-matrix]], which the input side needs anyway.\n\nFor scale: each of the [[twelve-layer-depth]] blocks holds roughly 7 million weights, so twelve of them come to around 85 million. An untied output projection would have added about a third of the stack again, carried through pre-training and into every fine-tuning run.\n\nThat is what the count in [[minimal-extra-parameters]] — one matrix $W_y$, plus embeddings for delimiters — quietly rests on. It is also the same measure the paper uses against [[per-task-parameter-cost]] elsewhere.\n\nParameters are not the only cost. $W_y$ is applied once per sequence, at [[final-token-activation]]. The tied head is applied at every position, and each application is those 30.7 million multiply-adds followed by a softmax over 40,000 rows.\n\nA pass through all twelve blocks at one position is around 85 million multiply-adds, before counting attention. So scoring every position with the language modelling head adds roughly a third to the forward work of a fine-tuning step.\n\nUnder [[three-epochs-fine-tuning]] at [[fine-tuning-lr-and-batch]] that is a bounded amount of extra compute. The paper reports no timing for either configuration.", "childId": null, "number": "6.3.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "what-lambda-balances", "title": "What $\\lambda = 0.5$ Balances", "body": "Both terms in [[eq-combined-objective]] are written as sums, and they sum over different things.\n\n[[supervised-objective-l2]], as written in [[eq-supervised-objective]], contributes one log-probability per labelled example: the log-probability of that example's correct label. [[language-modeling-objective]], applied to the same example, contributes one log-probability per token.\n\nTake a premise-hypothesis pair forty tokens long. The label side of the sum has one term in it. The auxiliary side has forty. Scaling by [[auxiliary-objective-weight]] at $0.5$ leaves twenty against one.\n\nSo $0.5$ does not, on its own, mean the two objectives are weighted evenly. Where the ratio actually lands depends on whether an implementation sums or averages each term, and on how long the task's sequences are. The paper writes sums, and does not say which its code does.\n\nOne consequence is that a single $\\lambda$ means different things across the twelve datasets. A [[race-dataset]] example is a passage, a question and a candidate answer. A [[cola]] example is one sentence. At the same $\\lambda$, the auxiliary term carries far more of the gradient in the first case than in the second.\n\n$\\lambda$ is reported once, in the closing line of [[fine-tuning-hyperparameters]], in the same list as the learning rate, the batch size and the [[classifier-dropout]]. One value covers every task. No search over it is reported, and no sensitivity is measured.\n\nThat matters more here than it would for a well-behaved knob. The ablation ahead reports the term's effect changing sign from dataset to dataset, which makes a per-task $\\lambda$ the obvious response — and it is not attempted.", "childId": null, "number": "6.3.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "two-claims", "title": "Two Claims, Unequally Evidenced", "body": "The paper's case for keeping the term is one sentence: including language modelling as an auxiliary objective helped by improving generalization of the supervised model, and by accelerating convergence. Two references follow, cited as prior work that saw the same.\n\nThe two claims are not evidenced the same way, so take them apart.\n\nGeneralization is testable inside this paper. Train with the term, train without it, compare held-out scores. That experiment exists — it is [[ablation-no-auxiliary-objective]], one of the three in [[ablation-studies]] — and the next chapter reads it.\n\nConvergence has nothing measuring it. No fine-tuning learning curve appears anywhere in the paper. [[fig-2]] holds the only training-progress plots, and both concern stage one: the left panel is [[layers-transferred]], the right tracks [[zero-shot-behaviors]] across pre-training updates.\n\nNeither says how many fine-tuning steps a run took with the term compared to without. The claim is stated and left there.\n\nNo mechanism is offered for either effect. The paper does not say whether the term acts as a regularizer, keeps the tied head calibrated on text of the new shape, or does something else. [[pretraining-as-regularization]] is raised in the related work, but about stage one, not about this.\n\nThe cited corroboration also sits at a slant. The clearer of the two references, named under [[auxiliary-training-objectives]], added a language modelling loss to sequence labelling — predicting a tag at every token, not one label from the last position.\n\nAnd the paper's own reading of that branch is that [[generative-pretraining]] already learns several of the linguistic aspects such an objective would supply. That is an argument for the term mattering less here than it did there.", "childId": null, "number": "6.3.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 7, 8]}}, {"id": "the-ablation-row", "title": "Doing the Subtraction Yourself", "body": "[[table-5]] carries a row labelled \"Transformer w/o aux LM\". It is the same recipe with $\\lambda$ set to zero.\n\nStart with what it does not cover. The table reports eight datasets, not twelve. [[snli]], [[scitail]], RACE and the [[story-cloze-test]] are absent — so the term's effect on the two benchmarks carrying the paper's largest reported margins is never measured at all.\n\nNow the eight. Keeping the term costs 2.5 points on CoLA (45.4 against 47.9), 0.7 on [[sst-2]] (91.3 against 92.0), 2.6 on [[mrpc]] (82.3 against 84.9) and 1.2 on [[sts-b]] (82.0 against 83.2).\n\nIt gains 0.5 on [[qqp]] (70.3 against 69.8), 0.7 on [[multinli]] (81.8 against 81.1), 1.2 on [[qnli]] (88.1 against 86.9) and 1.6 on [[rte]] (56.0 against 54.4).\n\nThe losses total 7.0 points. The gains total 4.0. Net $-3.0$ across eight datasets is $-0.375$ each, which rounds to the gap between the two reported averages, 74.7 and 75.0.\n\nThat average is unweighted, and the caption says so. It adds one Matthews correlation, four accuracies, two F1 scores and one Pearson correlation as though they shared a unit. CoLA's 2.5-point Matthews swing counts exactly as much as QQP's 0.5-point F1 swing.\n\nThen the size reading. RTE is a dataset the paper itself calls one of the smaller ones, at 2490 examples, and it shows the largest single gain from keeping the term.\n\nSTS-B, at roughly 5.7k examples, is hurt by it and fits the trend. Those two are the only ones of the eight whose sizes the paper prints.", "childId": null, "number": "6.3.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}], "number": "6.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-one-sequence-per-task--the-four-shapes": {"id": "n-one-sequence-per-task--the-four-shapes", "parentId": "n-one-sequence-per-task", "parentChapterId": "the-four-shapes", "depth": 2, "title": "Four Shapes, and What Each Costs to Run", "intro": "The parent priced the four templates. This level takes each apart at the level of the mechanism: what the markers actually add in the cases that look free, why the similarity merge is addition rather than something else, what the softmax over candidates is normalizing, and where the running bill lands against a window the paper never budgets for.", "chapters": [{"id": "markers-only", "title": "The Two Templates That Only Add Markers", "body": "Calling the classification case untransformed is nearly right, and the exception is worth having. The paper says all transformations include adding randomly initialized start and end tokens, $\\langle s\\rangle$ and $\\langle e\\rangle$ ([[start-and-end-tokens]]).\n\nSo a single sentence going into [[text-classification]] is still rewritten. Two positions are bracketed onto it, and both carry embeddings that did not exist during pre-training.\n\nThose embeddings are learned during fine-tuning. They belong to the small set of freshly initialized parameters that a new task brings with it ([[minimal-extra-parameters]]).\n\nEntailment adds one more symbol. The [[delimiter-token]] `$` goes between the premise and the hypothesis ([[entailment-input-transformation]]), so the sequence has five parts: start, premise, delimiter, hypothesis, end. One forward pass, over a sequence of length $|p| + |h| + 3$.\n\nThe order in that sequence is not a choice anyone made. [[natural-language-inference]] hands over a directed pair: the premise is given, and the hypothesis is the thing being judged against it.\n\nThat direction interacts with the stack in a way the paper does not comment on. Under [[masked-self-attention]] each position attends only to itself and to earlier positions.\n\nHypothesis tokens can therefore attend back into the premise. Premise tokens cannot see the hypothesis at all.\n\nThe premise is read once, without knowing what will be asked of it. Only the hypothesis is read in the light of the other sentence.\n\n[[fig-1]] draws these two panels as nearly the same picture: one text block for classification, two blocks and a delimiter for entailment, each feeding one transformer and one linear head. That visual sameness is the [[traversal-style-approach]] working on its easy cases, where [[structured-inputs]] already carry a reading order and only need writing down in it.", "childId": null, "number": "7.3.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "symmetry-by-addition", "title": "Buying Symmetry with a Second Pass", "body": "The repair fits in one sentence of the paper: build both orderings, process each independently, add the two representations element-wise, feed the sum to the linear layer ([[similarity-input-transformation]]).\n\nWalk the shapes. Each pass produces $h_l^m$, the top block's activation at the last position ([[final-token-activation]]), which is a vector of 768 numbers in the trained model ([[model-specification]]).\n\nTwo passes give two such vectors. Adding them gives one vector of 768 numbers, which is exactly the input [[linear-output-layer-wy]] already expected ([[eq-task-head]]).\n\nSo the head is not told it is being fed a sum. Its shape is identical to the entailment case.\n\nAddition is doing one specific job here. Write the stack as $f$ and the two sentences as $a$ and $b$. The quantity $f([a;b]) + f([b;a])$ is unchanged when you relabel which sentence was called first, because addition commutes.\n\nConcatenating the two vectors would also use both orderings. But it would keep a slot meaning \"the pass where $a$ came first\", widening the head's input to 1536 and putting the arbitrary choice straight back in. Averaging would serve as well as addition, differing by a factor of two that $W_y$ can absorb. The paper names addition and does not compare the alternatives.\n\nBe precise about what became symmetric. Each summand is still produced by an order-sensitive traversal; only the aggregate is invariant. That is sufficient, because the prediction is a function of the aggregate alone.\n\nThe price is two forward and two backward passes per example, paid on [[mrpc]], [[qqp]] and [[sts-b]] ([[semantic-similarity]]) across all three fine-tuning epochs ([[fine-tuning-hyperparameters]]). No ablation isolates the symmetric sum, so what it contributes to those three scores is not measured.", "childId": null, "number": "7.3.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "one-pass-per-candidate", "title": "When the Number of Answers Is Not Known in Advance", "body": "Question answering breaks the pattern somewhere else. Entailment had a fixed number of parts; here the part count is a property of the individual example.\n\nThe template is $[z; q; \\$; a_k]$, built once per candidate ([[qa-and-commonsense-input-transformation]]). Read the punctuation closely. There is one delimiter, and it sits between the question and the answer.\n\nThe passage and the question are run together with no marker at their join. The prose agrees — concatenate the document context and question with each possible answer, delimiter in between — and the multiple-choice panel of the figure draws a single Delim box.\n\nWhy not keep one sequence and give the head one output column per option? Because the option count moves. The [[story-cloze-test]] offers two endings ([[question-answering-and-commonsense-reasoning]]). [[race-dataset]] is built from middle and high school exam passages, and the paper never prints how many choices those questions carry.\n\nA matrix with a column per option would fix that number when the model is built. Running the same [[decoder-only-stack]] $K$ times instead moves the count out of the architecture and into a loop. Handling variable structure inside the network is what [[task-specific-architectures]] would do, and that is the thing being declined.\n\nThe $K$ scores are then normalized by a softmax across sequences. The label space is assembled at run time from whatever candidates the example supplied.\n\nThe head's shape is not stated. The figure draws a Linear box after each candidate's pass, and for a distribution over $K$ options to come out, each box must emit one number, which makes $W_y$ a $768 \\times 1$ matrix.\n\nWhether one such matrix is shared across candidates is left unsaid. A separate matrix per slot would make a candidate's score depend on its position in the list, which is the dependence this design works elsewhere to remove.\n\nThe supervised loss ([[eq-supervised-objective]]) is the log-probability of the correct candidate, so the $K$ passes touch each other only through the shared normalizer. [[table-3]] reports what comes out.", "childId": null, "number": "7.3.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "bill-and-ceiling", "title": "The Bill, and the One Limit Nobody Prices", "body": "Add the passes up per training example. Classification, one. Entailment, one. Similarity, two. Multiple choice, $K$.\n\nThis is a multiplier on fine-tuning compute and on activation memory. It is not a multiplier on parameters: the same weights run every time, which is the whole point of [[task-specific-input-transformations]] and of the [[task-agnostic-model]] claim ([[table-1]]).\n\nIt is also a multiplier on the cheaper of the two stages. Pre-training runs 100 epochs over minibatches of 64 sequences; fine-tuning runs three epochs at batch size 32. Doubling or quadrupling the short stage is a small addition to the total, though the paper never states the comparison itself.\n\nNow the limit. The stack reads 512 tokens ([[context-window-512-tokens]]), a number set during pre-training, where the objective conditions each token on a window of that size ([[language-modeling-objective]]). Position information comes from a trained matrix with one vector per slot ([[learned-position-embeddings]]), so there are no vectors for positions beyond the last one pre-training used.\n\nA comprehension sequence has to fit a whole passage, a question, an answer and the markers inside that. Tokenization pushes the other way: byte-pair encoding with 40,000 merges ([[byte-pair-encoding-gpt1]], part of the [[text-preprocessing-pipeline]]) splits rare words into several units, so the token count runs above the word count.\n\nThe paper does not say whether long passages are truncated, or from which end.\n\nThe silence sits oddly next to the argument being made. RACE is chosen partly for having more reasoning-type questions than [[cnn-and-squad-contrast]], and is described as a fitting test for a model trained on [[long-range-dependencies-gpt1]]. Long range is being claimed as the strength, while the mechanism that would bound it goes unmentioned.\n\nThis is a gap in the reporting, not a demonstrated fault. The RACE numbers were obtained somehow; the paper just does not say how the input was made to fit.", "childId": null, "number": "7.3.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "7.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-the-scoreboard--the-margins": {"id": "n-the-scoreboard--the-margins", "parentId": "n-the-scoreboard", "parentChapterId": "the-margins", "depth": 2, "title": "The Numbers Behind the Margins", "intro": "The parent laid the figures out. This level says what each dataset is actually asking a system to do, what kind of system held the number being subtracted from, and where a blended figure like RACE's 59.0 comes from arithmetically.", "chapters": [{"id": "nli-what-is-asked", "title": "What Entailment Asks, and How It Is Fed In", "body": "All five columns of [[table-2]] score the same task. A system reads two sentences, a premise and a hypothesis, and assigns one of three labels: the premise entails the hypothesis, contradicts it, or leaves it undecided. That is [[natural-language-inference]], which the paper also calls recognizing textual entailment.\n\nSection 4.2 names what makes it hard, and the list is worth reading slowly.\n\nLexical entailment: knowing that one word licenses another, so that a cat on a mat entails an animal on a mat. [[coreference]]: two expressions referring to the same entity, so that whether a pronoun points at the premise's subject or its object can flip the label. Lexical and syntactic ambiguity: a word with two senses, or a phrase that could attach in two places.\n\nNone of that is built into the network. Whatever the model has of it, it has from predicting next tokens on books.\n\nThe feed is identical across all five datasets. Premise tokens and hypothesis tokens are concatenated with a `$` [[delimiter-token]] between them — the [[entailment-input-transformation]] — and the sequence is bracketed by [[start-and-end-tokens]]. The [[final-token-activation]] from the top block goes through [[linear-output-layer-wy]] and softmaxes into three label scores.\n\nSo nothing is reshaped per column. There is no per-dataset [[task-specific-architectures|architecture]] tuned against that benchmark's quirks.\n\nThat matters for reading the spread. A gain of 5.8 points on one column and 0.6 on another came out of the same weights and the same [[three-epochs-fine-tuning|three epochs of fine-tuning]]. Whatever explains the difference sits in the datasets, and in who held the previous number.", "childId": null, "number": "8.2.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "five-sources", "title": "Five Sources, Five Different Ceilings", "body": "Where the sentences come from differs by column, and the paper picks the five for exactly that spread.\n\n[[snli]] pairs are written over image captions, so its premises describe scenes. [[multinli]] mixes transcribed speech, popular fiction and government reports. [[qnli]] is built over Wikipedia articles. [[scitail]] is derived from science exam questions. [[rte]] is drawn from news.\n\nMultiNLI's two reported columns follow from that mix. The matched development set is drawn from genres that also appear in its training data. The mismatched set is drawn from genres held out of training. Mismatched is the lower score for nearly every system in the table, which is why 82.1 and 81.4 sit apart rather than on top of each other.\n\nSize differs as much as source. SNLI is the largest dataset in the whole evaluation at roughly 550k training pairs. RTE is the smallest at 2,490.\n\nNow the other side of each subtraction. SNLI's 89.3 came from five-model ensembles, one of them ESIM — a biLSTM built for inference — with [[elmo-deep-contextualized-word-representations|ELMo]] features added as inputs. That column has absorbed a lot of task-specific work.\n\nQNLI is the opposite case. Of the [[baseline-comparisons]] in the table, only the two multi-task models taken from the [[glue-benchmark]] paper report a QNLI number at all; the rest of the column is dashes. Its 82.3 comes from a general multi-task system, not from something built and re-tuned for QNLI across several papers.\n\nSo the two figures are not measuring the same contest. 0.6 is taken off a column many groups have pushed on. 5.8 is taken off a column almost nobody had entered.", "childId": "n-the-scoreboard--the-margins--five-sources", "number": "8.2.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "why-race", "title": "Why RACE, and What Its Two Splits Say", "body": "[[race-dataset|RACE]] is picked with a stated reason, and the reason is part of the evidence.\n\nIt is reading comprehension assembled from English exam passages, middle school and high school, each with multiple-choice questions written to test whether a student understood the passage. It is the larger half of the [[question-answering-and-commonsense-reasoning]] family.\n\nThe argument for choosing it runs through [[cnn-and-squad-contrast|CNN and SQuAD]]. On those, the answer is something located in the passage — a span, or an entity filling a blank. RACE, the paper says, has been shown to contain more reasoning-type questions than either, which makes it \"the perfect evaluation for our model which is trained to handle long-range contexts\".\n\nRead that plainly. The benchmark is selected because it suits the property being claimed, and the claim about its question mix is cited to other work rather than measured here.\n\nEach candidate answer is scored on its own. Document, question and that one answer are concatenated into a single sequence, and the resulting scores are normalized across candidates by a softmax — the [[qa-and-commonsense-input-transformation]]. Passage plus question plus answer is a long input, which is where [[bookscorpus]] and its [[long-range-contiguous-text]] are meant to pay off.\n\nThe split arithmetic is checkable. The model's two splits are 62.9 and 57.4, whose midpoint is 60.15, yet the combined figure in [[table-3]] is 59.0 — below that midpoint, nearer the high-school number.\n\nSolving $62.9 - 5.5w = 59.0$ gives $w \\approx 0.71$. About seven in ten RACE test questions are high-school ones.\n\nRun the same sum on the previous best row, where 60.2 and 50.3 combine to 53.3, and $w \\approx 0.70$. The two rows agree, which is a small check that the combined column is a weighted blend and nothing stranger.", "childId": null, "number": "8.2.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "story-cloze", "title": "Story Cloze, and the Reading Laid Over It", "body": "[[story-cloze-test|Story Cloze]] hands over a short multi-sentence story and two candidate endings, and asks which one actually finishes it.\n\nTwo options means chance is 50. The live range on that column is not 0 to 100 but 50 to 100. A system at 77.6 has covered a little over half the distance from guessing to perfect; 86.5 covers about three quarters of it.\n\nThe input format is the one RACE gets. Each ending is appended to the story to make its own sequence, both sequences are scored, and the two scores are normalized against each other. [[supervised-fine-tuning]] on the labelled endings trains the single linear layer sitting on top.\n\nThe previous 77.6 is a single system, the Hidden Coherence Model, not an ensemble.\n\nThe paper reads 77.6 against 86.5, together with RACE, as showing the model handles [[long-range-dependencies-gpt1|long-range context]] well. There is a mechanism behind that reading: attention over the whole context is argued to give a more [[transformer-inductive-bias|structured memory]] than a recurrent state carried forward, and the paper elsewhere points at an [[lstm-short-range-limitation|LSTM's shorter effective range]].\n\nBut note what the two numbers do not do. Neither column varies story length, or context length, or anything else that would isolate range as the cause.\n\nA model that had simply absorbed more [[world-knowledge]] about how situations usually end would move that number in the same direction by the same amount.\n\nThe interpretation is laid over the result. It is consistent with the result. It is not separated out by it.", "childId": null, "number": "8.2.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "margins-as-errors", "title": "The Same Margins as Error Reduction", "body": "Every margin so far is a subtraction in accuracy points, which is what the paper means by [[absolute-improvement]]. That treatment gives a point gained at 89 the same weight as a point gained at 53.\n\nHere are the same rows read a second way: what share of the previous system's errors disappeared. This re-expression is not in the paper.\n\nSNLI. The old 89.3 leaves $100 - 89.3 = 10.7$ points of error, and 89.9 leaves 10.1. The gain removes $0.6 / 10.7 \\approx 5.6\\%$ of them.\n\nMultiNLI matched: $1.5 / 19.4 \\approx 7.7\\%$. Mismatched: $1.3 / 19.9 \\approx 6.5\\%$.\n\nSciTail: $5.0 / 16.7 \\approx 30\\%$. QNLI: $5.8 / 17.7 \\approx 33\\%$. Story Cloze: $8.9 / 22.4 \\approx 40\\%$.\n\nRACE overall: $5.7 / 46.7 \\approx 12\\%$, because that column starts with nearly half its questions wrong.\n\nThe RACE splits move closer together under this reading. High school clears $7.1 / 49.7 \\approx 14\\%$ of its errors, middle school $2.7 / 39.8 \\approx 7\\%$ — still twice as much, but not the 2.6-fold gap the raw points suggest.\n\nThis second reading is not neutral either. Near a ceiling, some of the remaining errors are label noise rather than failures a better model could fix, so a small relative gain up there may be worth more than it looks.\n\nNeither reading settles which win is largest. What the paper banks instead is a count: [[state-of-the-art-9-of-12]] across the [[evaluation-task-families]], one [[task-agnostic-model]] behind every entry, and the count treats all nine alike.\n\nNothing in these two tables says why the wins happened. That argument is made separately, by [[layers-transferred]] in [[fig-2]] and by [[ablation-no-pretraining]].", "childId": null, "number": "8.2.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}], "number": "8.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-which-parts-do-the-work--three-removals": {"id": "n-which-parts-do-the-work--three-removals", "parentId": "n-which-parts-do-the-work", "parentChapterId": "three-removals", "depth": 2, "title": "Three Removals, Eight Datasets", "intro": "The level above gave the three headline deltas and the shape of the grid. This one puts every cell on the page, does the additions the table only prints the results of, and asks what each row can and cannot license.", "chapters": [{"id": "what-the-average-adds-up", "title": "What the Average Column Is Adding Up", "body": "Start with the reference row of [[table-5]], left to right: 45.4, 91.3, 82.3, 82.0, 70.3, 81.8, 88.1, 56.0.\n\nAdd them and you get 597.2. Divide by eight and you get 74.65, which the table prints as 74.7.\n\nThat is the whole operation. Nothing is rescaled first, and no dataset is weighted by how many training examples it has.\n\nThe eight columns do not share a zero. Matthews correlation on [[cola]] sits at 0 for a classifier that guesses, so its usable range runs from 0 to 100. Accuracy on [[sst-2]] sits near 50 for a coin flip on a binary label, and near 33 on three-way [[multinli]]. F1 on the positive class rewards a model that simply answers yes when most pairs carry the positive label, so the floor for [[mrpc]] sits high rather than at zero.\n\nFour different floors, averaged as if they were one scale.\n\nThe practical effect is not that the average is meaningless. It is that the gaps between rows are set mostly by the columns with the most room to move, and those are the ones whose metric bottoms out at zero.\n\nOne more thing about the grid itself. Each of the three lower rows removes exactly one component from the top row, and no row removes two. There is no run with an [[lstm-gpt1]] and no pre-training, and none with neither pre-training nor the auxiliary loss.\n\nSo the table reports three separate effects measured against one reference, and nothing in it measures how they interact.\n\nA last caution on the number. These eight are the [[glue-benchmark]] tasks, but 74.7 is not the 72.8 GLUE score reported in [[table-4]]. They are different quantities and should not be read against each other.", "childId": null, "number": "9.4.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}, {"id": "where-the-collapse-sits", "title": "Where the 14.8 Actually Comes From", "body": "The [[ablation-no-pretraining]] row reads 18.9, 84.0, 79.4, 30.9, 65.5, 75.7, 71.2, 53.8. That sums to 479.4, and $479.4 / 8 = 59.925$, printed as 59.9.\n\nThe headline 14.8 is the difference of two rounded numbers. Unrounded it is $74.65 - 59.925 = 14.725$.\n\nNow take the drops column by column. CoLA falls 26.5. SST-2 falls 7.3. [[mrpc]] falls 2.9. STS-B falls from 82.0 to 30.9, which is 51.1. [[qqp]] falls 4.8, [[multinli|MNLI]] 6.1, [[qnli]] 16.9, and RTE 2.2.\n\nThose eight drops sum to 117.8, and $117.8 / 8 = 14.7$, which is the gap.\n\nSTS-B alone contributes $51.1 / 8 = 6.4$ of it. CoLA contributes 3.3 and QNLI 2.1. Three columns therefore account for 11.8 of the 14.7.\n\nThe remaining five columns together contribute 2.9. Five of the eight datasets move less, in total, than STS-B moves on its own.\n\nWhy STS-B in particular. It is the smallest training set in the evaluation at roughly 5.7k pairs, its target is a continuous similarity score, and its metric is Pearson correlation, whose chance value is 0. Fine-tuning is [[three-epochs-fine-tuning]] at [[fine-tuning-lr-and-batch]], so from a random initialization that is a few hundred updates on a regression target.\n\nAt the other end, RTE moves 2.2 points on 2490 training examples, with both values close to where a majority-class predictor would sit.\n\nThe paper's sentence is that the lack of [[generative-pretraining]] hurts across all the tasks. Every column is down, so the claim holds exactly as written.\n\nThe spread runs from 2.2 to 51.1, so \"across the board\" describes the direction and not the size. The average is largely two columns of [[labeled-data-scarcity]] showing up at once.", "childId": null, "number": "9.4.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "lstm-changes-more-than-one-thing", "title": "The LSTM Row Changes More Than One Thing", "body": "The [[ablation-lstm-substitution]] row reads 30.3, 90.5, 83.2, 71.8, 68.1, 73.7, 81.1, 54.6. That is 553.3, and $553.3 / 8 = 69.16$, printed 69.1.\n\nThe per-column gaps against the full model are 15.1 on CoLA, 0.8 on SST-2, minus 0.9 on MRPC, 10.2 on STS-B, 2.2 on [[qqp]], 8.1 on [[multinli|MNLI]], 7.0 on QNLI and 1.4 on RTE.\n\nCoLA and STS-B again supply 3.2 of the 5.6. The same two columns that dominate the pre-training row dominate this one.\n\nNow the substituted model. It is one recurrent layer of 2048 units. The [[multi-layer-transformer-decoder]] it replaces is [[twelve-layer-depth]] of blocks at [[hidden-state-dimension-768]], each carrying a [[position-wise-feedforward-3072]] inner layer, as fixed by the [[model-specification]].\n\nDepth goes from twelve to one. Width per position goes from 768 to 2048. The mechanism for mixing information across positions changes from attention to a gated recurrent state.\n\nThree changes, one number.\n\nThere is also a missing measurement. The paper reports its transformer's [[token-level-perplexity]] of 18.4 on [[bookscorpus]], and reports nothing equivalent for the LSTM.\n\nSo we cannot tell whether the LSTM transferred worse from a comparable language model, or was simply a worse language model before fine-tuning began.\n\nThe row also keeps the auxiliary loss switched on, and no LSTM row exists without it.\n\nThe [[mrpc]] exception is worth stating precisely. The LSTM's 83.2 beats the full model's 82.3, and it is the only cell in the table where that happens. It does not take the column, because 84.9 elsewhere in the table is higher.\n\nThe architecture argument leans on a second, separate observation in [[fig-2]], where the LSTM's zero-shot scores swing more from checkpoint to checkpoint. The paper offers that as [[transformer-inductive-bias]], and it is a different kind of evidence than the 5.6.", "childId": null, "number": "9.4.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-row-that-argues-back", "title": "The Row That Scores Against the Recipe", "body": "The [[ablation-no-auxiliary-objective]] row reads 47.9, 92.0, 84.9, 83.2, 69.8, 81.1, 86.9, 54.4. That is 600.2, and $600.2 / 8 = 75.025$, printed 75.0.\n\nSplit the eight columns by which side wins. Dropping the loss gains 2.5 on CoLA, 0.7 on SST-2, 2.6 on [[mrpc]] and 1.2 on STS-B, for 7.0 points in total.\n\nKeeping it gains 0.5 on [[qqp]], 0.7 on [[multinli|MNLI]], 1.2 on QNLI and 1.6 on [[rte]], for 4.0 points in total.\n\nThat is four columns each way. The three tenths on the average come from the size of the margins rather than from winning more columns: $(7.0 - 4.0)/8 = 0.375$.\n\nThe paper reads the split by dataset size, and for three of the four columns the reading works. QQP and MNLI have hundreds of thousands of training pairs, QNLI has around a hundred thousand, and all three favour keeping [[auxiliary-lm-objective]].\n\nRTE does not fit. It has 2490 examples, the smallest count among the eight, and it favours keeping the loss by the largest margin of the four.\n\nThe paper writes that the trend suggests larger datasets benefit. With four columns on that side and one of them a counterexample, the hedge is doing real work.\n\nThe other missing measurement is the weight itself. [[eq-combined-objective]] scales the language modelling term by $\\lambda$ against [[supervised-objective-l2]], and [[fine-tuning-hyperparameters]] fixes [[auxiliary-objective-weight]] at 0.5.\n\nThe table contains $\\lambda = 0.5$ and $\\lambda = 0$. Two points, no curve, and no run at 0.25 or 1.0.\n\nThe ordering matters too. Every number in [[table-2]] and [[table-3]], across the full [[evaluation-task-families]], was produced at $\\lambda = 0.5$.\n\nSo this row reports on a setting already committed to, rather than choosing one.", "childId": "n-which-parts-do-the-work--three-removals--the-row-that-argues-back", "number": "9.4.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "9.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-the-mismatch--two-questions--machinery-and-cost": {"id": "n-the-mismatch--two-questions--machinery-and-cost", "parentId": "n-the-mismatch--two-questions", "parentChapterId": "machinery-and-cost", "depth": 3, "title": "Three Kinds of Machinery, Three Kinds of Cost", "intro": "The parent named three fine-tuning-side mechanisms and priced them in a phrase each. This level takes them apart: what the per-task network is actually made of, what a staged schedule costs when you count runs instead of weights, what the second loss costs once you notice the head it reuses — and then the one number the paper puts on the only one of the three it keeps.", "chapters": [{"id": "the-network-you-build-once", "title": "The Network You Build Once Per Task", "body": "Start with what the alternative is physically made of.\n\nYou hold a pre-trained representation. For entailment you put it at the bottom of a stack. Above it you place a module that reads two sequences at once: an attention layer that lets every hypothesis token look at every premise token, then a pooling step that collapses the resulting matrix to a vector, then a classifier on that vector. For single-sentence classification you skip the cross-attention and keep a pooling scheme. That upper module is what the paper calls [[task-specific-architectures]].\n\nIt costs twice.\n\nFirst in design. Someone decides that entailment wants cross-attention and that classification wants max-pooling rather than mean-pooling, and those decisions are made per task by hand.\n\nSecond in weights. The module is initialized fresh and trained on the task's labels alone. It never sees raw text. Section 3.3 states the consequence plainly: such an approach \"re-introduces a significant amount of task-specific customization and does not use [[transfer-learning]] for these additional architectural components.\"\n\nSo transfer stops at the seam between the pre-trained part and the hand-built part. The paper's way of counting that is [[per-task-parameter-cost]] — how many freshly initialized parameters a new task needs.\n\nThe replacement absorbs the same difference somewhere else. [[task-specific-input-transformations]] takes [[structured-inputs]] and, by the [[traversal-style-approach]], writes their parts into one ordered token sequence: [[start-and-end-tokens]] bracket it, a [[delimiter-token]] marks where one part stops. [[fig-1]] draws all four shapes side by side.\n\nWhat remains to be added on top is then [[linear-output-layer-wy]] plus embeddings for the delimiters — the whole of [[minimal-extra-parameters]], and the basis of the [[task-agnostic-model]] claim.", "childId": null, "number": "1.2.3.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "schedule-not-parameters", "title": "Schedule, Not Parameters", "body": "The second mechanism costs nothing you can count in a parameter table.\n\n[[ulmfit]] sits inside [[lm-pretraining-then-finetuning-predecessors]], the line the related-work section calls closest to this paper's own, alongside [[semi-supervised-sequence-learning]]. Its fine-tuning is staged. Layers are unfrozen in a chosen order across epochs. Each layer gets its own learning rate. The rate over training follows a shaped curve rather than a plain decay.\n\nEvery one of those is a number, and every number has to be found on the task you are fine-tuning. The cost is measured in runs, not in weights.\n\nSet that against what this paper actually did. [[fine-tuning-hyperparameters]] says: reuse the pre-training settings unless stated otherwise. [[pre-training-optimization]] peaked at $2.5\\times10^{-4}$; [[fine-tuning-lr-and-batch]] uses $6.25\\times10^{-5}$, which is that peak divided by four, with batch size 32. [[three-epochs-fine-tuning]] reports three passes sufficed for most datasets. [[classifier-dropout]] adds dropout at 0.1 on the added head.\n\n[[fine-tuning-lr-schedule]] warms the rate up over the first 0.2% of updates, then decays it linearly to zero. Walk that. A 100,000-example set at batch 32 gives 3,125 updates an epoch, so 9,375 across three epochs, so warmup covers roughly nineteen of them. It is a brief ramp off zero, not a stage.\n\nAnd no layer is ever frozen. All twelve blocks update from the first step.\n\nTwo hedges are in the paper's own wording: \"unless specified\" and \"for most tasks.\" Some datasets got other settings, and which ones is not reported.\n\nNote also that the paper's stated objection to this same family in related work is [[lstm-short-range-limitation]] — an argument about architecture, not about schedule.", "childId": null, "number": "1.2.3.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [1, 2, 3, 4, 5]}}, {"id": "what-a-second-loss-costs", "title": "What a Second Loss Actually Costs Here", "body": "The third mechanism is the branch of [[semi-supervised-learning-for-nlp]] the related-work section files under [[auxiliary-training-objectives]]: instead of using unlabelled data to pick a starting point, add an unsupervised term to the supervised loss and optimize the sum.\n\nThis paper's instance is [[auxiliary-lm-objective]], written out in [[eq-combined-objective]] as\n\n$$L_3(\\mathcal{C}) = L_2(\\mathcal{C}) + \\lambda\\, L_1(\\mathcal{C}).$$\n\nRead the argument, not just the symbols. Both terms take $\\mathcal{C}$, the labelled task set. The language modelling loss during [[supervised-fine-tuning]] is computed on the task's own inputs, scored simply as text — not on the pre-training corpus. So nothing new has to be loaded.\n\nThe two terms score the same example at different granularities. [[supervised-objective-l2]] contributes one log-probability per example, for its label. [[language-modeling-objective]] contributes one per token of that example.\n\nNow the price. A second loss usually implies a second output head. Here it does not, because the language modelling head is the tied embedding matrix $W_e^{\\top}$ from [[output-softmax-tied-embeddings]], which is still sitting there from stage one. Parameter cost: zero.\n\nWhat remains is compute — a softmax over the 40,000-merge subword vocabulary at every position, and its backward pass — and one number, [[auxiliary-objective-weight]], set to 0.5. That value is stated in the setup, not derived, and no sweep over it is reported.\n\nThe paper gives two reasons for including the term: better generalization of the supervised model, and faster convergence. Both are reported as things they found, with no mechanism offered, and with prior work cited as having seen the same.", "childId": null, "number": "1.2.3.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "the-one-measurement", "title": "The One Measurement, and What It Covers", "body": "[[ablation-no-auxiliary-objective]] is the row in [[table-5]] that tests the mechanism this paper kept. Fine-tune without the language modelling term, hold everything else fixed.\n\nThe average score goes up by 0.3.\n\nSit with the direction. The one mechanism of the three that survives into the recipe is the one whose removal costs nothing on the aggregate number the paper itself reports.\n\nIt earns its place unevenly. The term helps on [[qqp]] and on the [[natural-language-inference]] sets, and the paper reads the pattern as larger datasets benefiting while smaller ones do not.\n\nTwo limits on how far that reading carries. Size is not a controlled variable here; it is a trend read off a handful of columns whose training sets run from roughly 550k examples on [[snli]] down to 2,490 on [[rte]]. And RTE is both an NLI set and the smallest of them, so the paper's two summaries — helps on NLI, helps on large data — do not pick out quite the same columns. Separately, $\\lambda$ stayed at 0.5 throughout, so the comparison is 0.5 against 0, not a curve.\n\nPut the magnitude next to its neighbours in the same table. [[ablation-no-pretraining]] costs 14.8 points. [[ablation-lstm-substitution]] costs 5.6. This one gains 0.3 the other way. Inside [[ablation-studies]] it places a distant third.\n\nOne last thing the table does not do. It removes parts of this paper's own recipe. Against the per-task network and the staged schedule the paper offers a design argument and a scoreboard — not an ablation row.", "childId": null, "number": "1.2.3.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "1.2.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-the-corpus-and-the-training-run--shape-of-the-stack--inside-one-block": {"id": "n-the-corpus-and-the-training-run--shape-of-the-stack--inside-one-block", "parentId": "n-the-corpus-and-the-training-run--shape-of-the-stack", "parentChapterId": "inside-one-block", "depth": 3, "title": "Two Sublayers, One at a Time", "intro": "The parent walked a vector through the block from the outside. This level goes inside the two sublayers separately: what one 64-wide head actually computes and why its divisor is 8, what the mask does arithmetically and why the training objective requires it, where the residual branches and the normalization sit around each sublayer, and what it costs that the feed-forward network applies the same map at every position.", "chapters": [{"id": "inside-one-head", "title": "Inside One Head", "body": "Take head seven, at position $i$, in the middle of some block.\n\nIts query is not the full vector. It is slice seven: sixty-four of the [[hidden-state-dimension-768|768]] numbers the query projection produced. The key it compares against, at some earlier position $j$, is slice seven of that position's key vector — the same sixty-four coordinates, never any of the others.\n\nThe score is their dot product. Sixty-four products, summed into one scalar.\n\nDo that for every ordered pair and you have a grid of scalars, one per pair, for each of the [[twelve-attention-heads|twelve heads]] in each of the twelve blocks. With a [[context-window-512-tokens|512-token window]] that is $512 \\times 512$ entries per head.\n\nNow the divisor. Suppose the query and key entries are roughly independent, near zero mean, near unit scale. A sum of sixty-four such products has variance about sixty-four, so a typical score sits around $\\pm 8$ — and scores of that size push the softmax towards putting nearly all its weight on one position, where its gradient is close to flat. Dividing by $\\sqrt{d_k} = \\sqrt{64} = 8$ pulls the scores back to order one.\n\nSo the divisor tracks head width, not model width. Six heads of 128 would have divided by about 11.3 instead.\n\nAfter the softmax, the weights multiply the value slices — again sixty-four numbers each — and the head emits sixty-four numbers.\n\nThe paper does not derive any of this. Its [[model-specification|setup paragraph]] gives the head count and the state size in one sentence, and says the [[multi-layer-transformer-decoder|decoder]] largely follows the original [[transformer-gpt1|transformer]] for the rest.", "childId": null, "number": "5.3.1.1", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "minus-infinity", "title": "What the Mask Is Actually Doing", "body": "The mask is addition, not deletion.\n\nBefore the softmax, every score at a pair where $j > i$ has $-\\infty$ added to it — in practice a large negative constant. The softmax exponentiates, $e^{-\\infty} = 0$, and those positions come out at exactly zero weight.\n\nThe ordering matters. Because the masking happens before normalization, the surviving weights are renormalized over the visible prefix alone and still sum to one. Zeroing weights after a softmax would instead leave each row summing to less than one, by an amount that depends on how far along the sequence the row sits.\n\nWhy pay for this at all? Because of how the [[language-modeling-objective|training loss]] is collected. [[eq-lm-objective|Equation 1]] sums a log-probability over every token in the corpus, and one forward pass over a 512-token sequence produces all 512 of those terms at once — 512 predictions, 512 loss terms, one pass.\n\nThat density is only sound if each position is blind to its own target. Position $i$ is asked to predict token $i+1$. Unmasked, it could attend to position $i+1$ and read the answer out of that position's value vector, and the loss would fall to nothing while the model learned nothing.\n\nSo the score grid is triangular, and roughly half the scores computed are discarded. Position 1 attends to one token; position 512 attends to 512.\n\nThere is also nothing else for a head to attend to. The [[decoder-only-stack|encoder half is gone]], and with it the block's third sublayer. Reaching back across [[long-range-dependencies-gpt1|long distances]] happens inside this one triangle or not at all.", "childId": null, "number": "5.3.1.2", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "branch-and-norm", "title": "Where the Normalization Sits", "body": "Neither sublayer replaces the vector. Each one computes a correction, and the correction is added back.\n\nSo a position's 768 numbers pass through the block along a straight path, with the attention result added at one point and the feed-forward result added at another. [[layer-normalization-gpt1|Layer normalization]] is applied around each of those two additions — though the paper never writes the block out. It says only that layernorm is used extensively throughout the model, and [[eq-decoder-stack|Equation 2]] compresses the whole thing into the word `transformer_block`.\n\nWorth noticing what layer normalization normalizes over. It takes one position's 768 numbers, subtracts their mean, divides by their standard deviation, then applies a learned gain and a learned bias — 768 of each.\n\nWhich means it mixes nothing across positions either. Attention remains the only place in the block where one token's numbers touch another's.\n\n[[dropout-gpt1|Dropout]] sits here too. The paper applies it at rate 0.1 on the [[residual-embedding-attention-dropout|residual branches and inside attention]]: the sublayer's contribution can be dropped, while the path carrying the input forward is left alone. A block with its branch fully dropped passes its input along unchanged.\n\nThe paper claims one concrete payoff for having layernorm everywhere. It says that presence is why a plain [[weight-initialization|$\\mathcal{N}(0, 0.02)$ initialization]] was sufficient across all [[twelve-layer-depth|twelve blocks]] — an assertion made in the setup paragraph, with no ablation behind it.", "childId": null, "number": "5.3.1.3", "sources": {"sections": [{"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [3, 4, 5, 7, 8]}}, {"id": "same-map-everywhere", "title": "One Map, Applied 512 Times", "body": "The second sublayer has no index of position anywhere in it.\n\n[[position-wise-feedforward-3072|It is two matrices]]: one taking 768 numbers up to 3072, one bringing 3072 back down to 768, with an [[gelu|activation]] between them. The same two matrices are used at position 1, at position 300 and at position 512.\n\nSo the sublayer does not see a sequence. It sees a batch of vectors and applies one function to each. Sequence length is irrelevant to it: doubling the context doubles the work and changes nothing else.\n\nWhat that buys is a clean division of labour. Combining information across tokens happens in attention and only there. Turning a single token's current representation into something else — a nonlinear map through 3072 intermediate features, four times the width it started at — happens here and only here.\n\nWhat it costs is that this sublayer cannot notice an arrangement. If a feature depends on two tokens standing in a particular relation, attention has to have already merged them into one vector before the feed-forward network can act on it.\n\nPosition never enters as an argument because it entered once as data. [[input-representation-h0|At layer zero]] a position embedding was added to the token embedding, so where a token sits is already part of the numbers being transformed.\n\nThe paper gives 3072 as a number in the setup and does not argue for it, nor for the 4:1 ratio it implies. Both arrive with the architecture, alongside the [[token-embedding-matrix|embedding matrix]] and the [[learned-position-embeddings|position table]] that feed it.", "childId": null, "number": "5.3.1.4", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [3, 4, 5]}}, {"id": "twelve-rounds", "title": "Twelve Rounds of the Same Two Steps", "body": "Put the two sublayers back together and the block reads as a pair of alternating moves: gather from the past, then transform in place.\n\nRun that twelve times and each round works on the output of the last. A token's vector after block four is not a token any more. It is whatever four rounds of gathering and transforming made of the prefix ending at that position. [[fig-1|Figure 1]] draws the pair once and marks it $\\times 12$.\n\nThe paper does offer evidence that the rounds are not redundant. [[layers-transferred|Its layer-transfer analysis]] carries a varying number of pre-trained blocks into fine-tuning and reports that each added layer helps, up to 9% on MultiNLI for full transfer, which it reads as each layer holding functionality the target tasks can use. [[fig-2|Figure 2]] plots those curves.\n\nThat is a claim about the stack as a whole, not about either sublayer on its own. No experiment here isolates attention from the feed-forward network, varies the head count, or moves the 3072.\n\nThe closest thing to an architectural control is [[ablation-lstm-substitution|swapping the whole stack]] for a single-layer 2048-unit LSTM, which [[table-5|Table 5]] scores 5.6 average points worse. The paper's reading of that gap is offered as a hypothesis rather than a result: attention gives the model a [[transformer-inductive-bias|more structured memory]] than a recurrent state does.\n\nEverything a target task will eventually see comes out of the top block, and [[final-token-activation|only at the last position]]. Twelve rounds have to have put it there.", "childId": null, "number": "5.3.1.5", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 7, 8]}}], "number": "5.3.1", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, "n-the-scoreboard--the-margins--five-sources": {"id": "n-the-scoreboard--the-margins--five-sources", "parentId": "n-the-scoreboard--the-margins", "parentChapterId": "five-sources", "depth": 3, "title": "Five Sources, Five Different Ceilings", "intro": "The parent named each dataset's source and left it there. This level takes them one at a time: what a caption, a government report or an exam question makes easy or hard, who actually held each column in Table 2, and how much of that column's margin is explained by the baseline rather than by the model.", "chapters": [{"id": "captions-and-a-crowded-column", "title": "Captions: Where Ensembling Is Worth More Than the Margin", "body": "The paper gives [[snli]] one word of description: image captions. Follow what that word implies.\n\nA caption is written to describe a picture. So the premise is one sentence, usually present tense, usually about objects and actions someone can see.\n\nNothing in it refers back to an earlier sentence, because there is no earlier sentence. That takes [[coreference]] almost entirely out of this column — one of the four phenomena the paper names when it says [[natural-language-inference]] is hard.\n\nWhat is left is mostly lexical entailment. Does *person* follow from *man*, does *sleeping* rule out *running*. A caption corpus exercises that heavily and the rest of the list lightly.\n\nNow the column itself in [[table-2]]. Two rows tie for the underlined previous best at 89.3: ESIM with [[elmo-deep-contextualized-word-representations|ELMo]] features as a five-model ensemble, and CAFE as a five-model ensemble.\n\nCAFE also appears further down as a single model, scoring 88.5.\n\nSubtract those two CAFE rows. Ensembling five separately trained copies of the same [[task-specific-architectures|task-built architecture]] buys 0.8 points on this column.\n\nThe paper's SNLI margin is 0.6.\n\nSo the [[absolute-improvement]] claimed here is smaller than what one baseline gained from ensembling alone. The single model at 89.9 is still ahead of both 89.3 rows, and the paper is entitled to the subtraction it makes.\n\nBut a like-for-like comparison — one model against one model — is 89.9 against CAFE's 88.5, a gap of 1.4. The paper never reports it that way, because its rule for [[baseline-comparisons]] is to take the best published number whatever produced it. On this column that rule works against the paper's own number, and on other columns it will work for it.", "childId": null, "number": "8.2.2.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-genre-mix-and-the-held-out-half", "title": "Three Genres, and What the Matched Gap Actually Measures", "body": "[[multinli]]'s three named genres each stress something different.\n\nTranscribed speech is disfluent. It has restarts, filler and sentences that never finish, so a system trained on clean text meets input it has not seen shaped that way.\n\nPopular fiction is where cross-sentence reference finally appears: pronouns, characters named once and referred to afterwards. This is the source in the whole set that genuinely tests [[long-range-dependencies-gpt1|long-range reference]].\n\nGovernment reports go the other way. Long formal clauses, nested qualifiers, and the syntactic ambiguity the paper lists as a difficulty.\n\nThe matched and mismatched development sets are the same task over different halves of that genre pool. So the difference between the two columns is meant to read as a transfer cost.\n\nWalk it down the rows. CAFE's five-model ensemble loses 1.2 points crossing over, 80.2 to 79.0. The Stochastic Answer Network ensemble loses 0.5, 80.6 to 80.1. This paper's model loses 0.7, 82.1 to 81.4.\n\nThen look at the two [[glue-benchmark]] multi-task rows. GenSen goes 71.4 to 71.3, and the multi-task [[lstm-gpt1|biLSTM]] with attention goes 72.2 to 72.1. Each loses 0.1.\n\nThose are the smallest gaps in the column and they belong to the weakest systems, roughly ten points below everything else. A model that is not fitting the matched genres closely has little genre-specific fit to lose.\n\nSo the matched-minus-mismatched difference is not a clean measure of genre transfer. It is confounded with how well the system does at all.\n\nMultiNLI is also the one NLI dataset doing double duty in this paper. Its development accuracy is what [[layers-transferred]] plots in the left panel of [[fig-2]], the sweep that reports up to 9 percent for transferring the full stack rather than the embeddings alone. That makes it the dataset the paper uses to argue about the [[task-agnostic-model]], not just to score it.", "childId": null, "number": "8.2.2.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 5, 6, 7, 8]}}, {"id": "the-two-thin-columns", "title": "Science Exams and Wikipedia: The Emptiest Columns Give the Biggest Numbers", "body": "[[scitail]] comes from science exam questions. That source is declarative and technical: statements about processes, with a vocabulary of terms that appear rarely in general text and almost no pronouns.\n\nWhether stage one prepared the model for that vocabulary is not something the paper checks. [[bookscorpus]] is described only as over 7,000 unpublished books across genres, with no breakdown by subject, so how much science text the pre-trained weights ever saw is unknown.\n\nThe SciTail column holds exactly one baseline number: CAFE as a single model, 83.3. Not an ensemble — the previous best on this dataset was set by one run of one task-built system.\n\nThat same CAFE row scores 88.5 on SNLI. The architecture is 5.2 points lower on SciTail than on captions, which suggests the source is harder for it, or simply that fewer people had tuned against it.\n\nThe paper's 88.3 minus 83.3 gives the 5.0 the text quotes.\n\n[[qnli]] is built over Wikipedia articles, and the paper says nothing more about its construction. Encyclopedia prose is well-formed and factual, which removes the disfluency problem, but its sentences carry dense entity reference.\n\nIts column has two numbers. GenSen at 82.3 and the multi-task biLSTM with attention at 82.1 — 0.2 apart, both taken from the same GLUE paper, both systems spreading capacity across many tasks at once.\n\nThere is a way to measure how strong that ceiling is. GenSen, the row that sets it, scores 71.4 on matched MultiNLI, about nine points below the dedicated NLI systems in the same table.\n\nSo QNLI's previous best was held by a system that is off the pace on the one column where it can be compared directly. The 5.8 is real arithmetic, and it is also the thinnest contest in the table — worth holding in mind against the headline [[state-of-the-art-9-of-12]].", "childId": null, "number": "8.2.2.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 4, 5, 6, 7, 8]}}, {"id": "news-and-2490-examples", "title": "News, 2,490 Examples, and What Three Epochs Buys", "body": "[[rte]] is drawn from news articles, which is the source in this set with the most cross-sentence reference and the densest named entities. On source alone it is the column closest to the phenomena the paper says make the task hard.\n\nIt is also the one the paper loses.\n\nStart with the size ratio. SNLI's roughly 550,000 training pairs against RTE's 2,490 is a factor of about 220.\n\nNow put that through the recipe. [[fine-tuning-hyperparameters]] fixes batch size 32, and [[three-epochs-fine-tuning|three epochs]] is reported as sufficient for most datasets.\n\nOn RTE, 2,490 examples at 32 per batch is about 78 updates per epoch. Three epochs is therefore roughly 230 gradient steps.\n\nOn SNLI the same settings give about 17,200 updates per epoch, so around 51,600 steps.\n\nThat is the concrete shape of the problem. The [[supervised-fine-tuning]] stage has two orders of magnitude less signal to work with on RTE than on SNLI, at the same learning rate of 6.25e-5 and the same [[classifier-dropout]].\n\nThe result is 56.0. Both GLUE multi-task rows sit above it: 61.7 takes the bold, and GenSen's 59.2 also clears it. The model is third of three here, not second — the table's only column where it is beaten twice.\n\nThe shortfall against the best is 61.7 minus 56.0, which is 5.7. That is almost exactly the size of the QNLI gain, 5.8, and it is measured against the same family of multi-task systems.\n\nThe paper's account is that RTE is small, and that multi-task training would likely help given how the model does on the larger NLI sets. It states plainly that it has not tried this.\n\nSo the explanation is a hypothesis about [[labeled-data-scarcity]] under the [[two-stage-training-procedure]], offered without a run behind it.", "childId": null, "number": "8.2.2.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "what-the-set-covers", "title": "The Phenomenon List Against the Five Sources", "body": "Line up the paper's own list of what makes inference hard — lexical entailment, coreference, lexical ambiguity, syntactic ambiguity — against where the sentences come from.\n\nLexical entailment is everywhere. Every one of the five requires deciding whether one word or phrase follows from another.\n\nCoreference across sentences is thin. Captions have none by construction, exam statements have little, encyclopedia sentences some. It is really only fiction and transcribed speech inside MultiNLI, and news in RTE, that put it in front of the model.\n\nSyntactic ambiguity concentrates in the same two places: government reports and news prose.\n\nNow read the margins back against that. The two largest gains, 5.0 and 5.8, come from the columns whose sources exercise the least cross-sentence reference and whose baseline rows are thinnest. The two sources carrying the most of it return 1.5 and 1.3 on MultiNLI, and a 5.7-point loss on RTE.\n\nThat is a reading, not a finding, and the paper does not make it.\n\nWhat the paper does claim from these five columns is an ability to reason over multiple sentences and to handle aspects of linguistic ambiguity. The support is aggregate accuracy on five datasets chosen for diverse sources. No error analysis by phenomenon is reported anywhere, so the list of four difficulties motivates the task and is never used to break down the result.\n\nThe diversity argument carries the weight instead: if one model leads on sources this different without being redesigned for any of them, that is the case for [[evaluation-task-families|breadth over depth]].\n\nDirect evidence for cross-sentence reasoning sits elsewhere in the paper — in the reading-comprehension results the next chapters take up, and in the [[long-range-contiguous-text]] argument for the corpus. The parallel scoreboard outside inference is [[table-4]].", "childId": null, "number": "8.2.2.5", "sources": {"sections": [{"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [4, 5, 6, 7, 8]}}], "number": "8.2.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "n-which-parts-do-the-work--three-removals--the-row-that-argues-back": {"id": "n-which-parts-do-the-work--three-removals--the-row-that-argues-back", "parentId": "n-which-parts-do-the-work--three-removals", "parentChapterId": "the-row-that-argues-back", "depth": 3, "title": "Four Columns Each Way, and a Weight Never Swept", "intro": "The parent gave the split and the arithmetic. This level goes into the cells themselves — what each column actually measures, which of the paper's two readings of the split survives contact with the numbers, what the weight $\\lambda$ is doing mechanically at each setting, and which published numbers were produced by which of the two rows.", "chapters": [{"id": "two-rows-eight-metrics", "title": "Two Rows, Eight Metrics", "body": "The comparison needs both rows. The full model reads 45.4, 91.3, 82.3, 82.0, 70.3, 81.8, 88.1, 56.0, and averages 74.7. Set the [[ablation-no-auxiliary-objective]] row underneath it in [[table-5]] and every cell subtracts directly.\n\nBut the eight columns are not measured in one unit. The column headers mark the metric for each: [[cola]] is scored by Matthews correlation, [[mrpc]] and [[qqp]] by F1, [[sts-b]] by Pearson correlation, and [[sst-2]], [[multinli]], [[qnli]] and [[rte]] by accuracy.\n\nSo the 7.0 on one side and the 4.0 on the other are sums across a correlation coefficient, two F1 scores, a second correlation coefficient and four accuracies.\n\nThat is what the average column already does, and it is how the paper reports gains everywhere else as [[absolute-improvement]]. It is still worth saying plainly. A point of Matthews correlation on CoLA and a point of accuracy on RTE are not the same quantity, and the three tenths rests on adding them as if they were.\n\nNow look at where the margins actually sit. Two of the eight pairs cancel exactly: 0.7 on SST-2 against 0.7 on MNLI, and 1.2 on STS-B against 1.2 on QNLI. Those four columns contribute nothing to the gap.\n\nWhat is left is 2.5 on CoLA and 2.6 on MRPC against 0.5 on QQP and 1.6 on RTE. That is $5.1 - 2.1 = 3.0$, the whole difference.\n\nThe result turns on four cells, and the two largest single moves in the table both favour dropping the loss.", "childId": null, "number": "9.4.4.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 5, 6, 7, 8]}}, {"id": "family-or-size", "title": "By Family, or By Size", "body": "Section 5 says two things about this split, and they are not the same claim.\n\nThe first is by task family: the auxiliary objective helps on the NLI tasks and [[qqp]]. Three of Table 5's columns — [[multinli|MNLI]], QNLI and RTE — are [[natural-language-inference]] datasets, and QQP is named separately. That reading covers all four winning columns with no exception.\n\nThe second is the one the section leaves the reader with: the trend suggests larger datasets benefit and smaller ones do not. This is where RTE stops fitting, at 2490 training examples and the largest margin on its side.\n\nThere is a further gap. The paper never prints training-set sizes for these eight columns. [[table-1]] lists the twelve datasets by family and name, not by count.\n\nThree sizes appear anywhere in the paper: RTE at 2490, [[sts-b]] at roughly 5.7k, and [[snli]] at roughly 550k. The size axis the trend is read along is asserted rather than shown.\n\nAnd the ablation covers eight of the twelve datasets in [[evaluation-task-families]]. SNLI is not a column. Neither are [[scitail]], [[race-dataset]] or [[story-cloze-test]].\n\nSo the largest dataset the paper does size is absent from the table where size is invoked.\n\nThe hedge in \"suggests\" is the paper's own word, and it does not claim more than that. Read strictly, [[ablation-studies]] reports a family split cleanly and a size trend loosely.", "childId": null, "number": "9.4.4.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "two-points-no-curve", "title": "One Weight, Two Settings", "body": "What the removed term actually computes is worth unpacking before asking about its weight.\n\n[[eq-combined-objective]] is $L_3(C) = L_2(C) + \\lambda L_1(C)$. Both terms take $C$, the [[labeled-dataset-c]]. So [[auxiliary-lm-objective]] is not the pre-training loss over [[bookscorpus]] carried forward. It is next-token prediction run over the target task's own labelled inputs.\n\nThose inputs are the sequences produced by [[task-specific-input-transformations]], markers and [[delimiter-token]] included. On an entailment task the model is predicting the next token of a premise-delimiter-hypothesis string.\n\nThat gives the amount of auxiliary signal a size: it scales with $|C|$. On RTE the term sees 2490 transformed pairs, and [[fine-tuning-hyperparameters]] runs only [[three-epochs-fine-tuning]] over them. On [[qqp]] it sees hundreds of thousands.\n\nThat is a mechanism the size trend could have been built on. The paper does not offer it, or any other.\n\n[[auxiliary-objective-weight]] is one global constant, 0.5, across all twelve datasets. Nothing in the setup lets $\\lambda$ vary by task, and the same [[fine-tuning-lr-and-batch]] settings are shared alongside it.\n\nThe ablation moves that one constant to 0. Two points, and they are the endpoints.\n\nFrom two endpoints you cannot tell whether the average is monotone in $\\lambda$ or dips between them. You also cannot tell whether the columns that lose at 0.5 would recover at 0.25 while the columns that win keep winning.\n\nA quantity whose effect changes sign across columns is exactly the case where the size of the weight might matter per column, and that is the measurement not taken.", "childId": null, "number": "9.4.4.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "already-committed", "title": "A Diagnostic on a Setting Already Spent", "body": "The ordering is what makes this row different from the other two removals.\n\nEvery number in [[table-2]], [[table-3]] and [[table-4]] was produced at $\\lambda = 0.5$. The scoreboard was fixed before the ablation asked whether 0.5 was the right value.\n\nOn four of the eight columns, that means the published figure is the lower of the two the paper measured.\n\n[[cola]] is reported at 45.4 against a previous best of 35.0, and the section calls it an especially big jump. The row without the loss reads 47.9. SST-2 is reported at 91.3 and described as competitive with the state of the art rather than beating it; the other row reads 92.0. [[mrpc]] is 82.3 against 84.9. STS-B is reported as a 1 point absolute gain at 82.0, where the other row reads 83.2.\n\nThe paper does not go back and re-report any of these. The [[state-of-the-art-9-of-12]] count and the 72.8 on the [[glue-benchmark]] both stand on the $\\lambda = 0.5$ run.\n\nThere is a defensible reason for that, though the paper does not state it. Picking the better of two settings per column would break the [[task-agnostic-model]] claim the whole [[two-stage-training-procedure]] is built to make: one recipe, unchanged, applied everywhere.\n\nLeaving the headline numbers alone keeps that claim intact and makes four of them conservative — by accident of ordering, not by design.\n\nWhat the row cannot be is a justification of 0.5. It measures a setting that had already been spent.", "childId": null, "number": "9.4.4.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 5, 6, 7, 8]}}], "number": "9.4.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}}, "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "insights": {"title": "Reading Across the Paper", "intro": "The tour walks the paper front to back, section by section, the way it was written. This read does something else: it puts relationships side by side and reports what only shows up when they sit together — a setting in section 4.1 that turns out to be forced by an equation in section 3.1, a claim in the conclusion whose nearest evidence measures something else, a design choice the ablation table says should have been made per dataset. Nothing here contradicts the tour. It is the same paper, cut along its dependencies instead of its page order.", "chapters": [{"id": "scarce-labels-and-the-smallest-dataset", "title": "The paper argues from scarce labels, then loses on the smallest labelled set it tries", "body": "The case for the whole recipe is an asymmetry: raw text is abundant, and labelled data for any one task is not. The worst result in the paper is on [[rte]], the smallest labelled dataset in its inference family, at 2490 training examples.\n\n[[table-2]] puts one fine-tuned model against systems built for each dataset. It reports gains of 1.5 points on MNLI, 5 on SciTail, 5.8 on QNLI and 0.6 on [[snli]]. On RTE it reaches 56% accuracy where a multi-task biLSTM reports 61.7%. The paper reads that as a small-data effect, says the model would likely benefit from multi-task training, and then says it has not run that experiment. SNLI, at roughly 550k training examples, is the largest set in the same family and produces the smallest of the four wins.\n\nThe cleanest test of the size reading is [[sts-b]]. It holds roughly 5.7k training examples, which puts it in the same small band as RTE's 2490. It gains a point over the previous best. Two datasets of similar size, opposite verdicts, and size is offered as the explanation for one of them only.\n\nThe unevenness repeats in text classification. [[cola]] rises to 45.4 from a previous best of 35.0, which the paper reads as evidence of linguistic bias picked up during pre-training. [[sst-2]] reaches 91.3% and matches rather than beats what was already published. [[table-4]] carries both, together with [[semantic-similarity]], where two of three datasets are wins and [[mrpc]] is not claimed.\n\nThe headline is new best results on 9 of 12. That count appears in no single table. It is a sum of wins across Tables 2, 3 and 4, with [[table-1]] fixing the denominator at twelve. All three misses sit in those tables rather than being left out, which is what makes [[state-of-the-art-9-of-12]] auditable at all. The one summary figure spanning several datasets, a [[glue-benchmark]] score of 72.8 against 68.9, is an average, and an average can be carried by a single large win such as CoLA.\n\nSo the premise the design was built backwards from — that [[labeled-data-scarcity]] is what needs solving — is where [[two-stage-training-procedure]] has its one clear failure.", "edgeIds": ["e001", "e047", "e048", "e049", "e050", "e054", "e055", "e056", "e057", "e114", "e115", "e116", "e117"], "number": "1", "childId": null, "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "one-lambda-for-a-conditional-effect", "title": "The auxiliary loss helps large datasets and hurts small ones, and gets a single weight for all twelve", "body": "Stage two optimizes two losses at once, and the paper's own ablation says the second should not be switched on everywhere. Equation 5 fixes the combination as $L_3(C) = L_2(C) + \\lambda L_1(C)$ with $\\lambda = 0.5$ for every dataset, while [[table-5]] reports that removing $L_1$ helps on some datasets and hurts on others.\n\nStart from the parts. [[supervised-objective-l2]] is written out in [[eq-supervised-objective]] as the summed log-probability of the correct label over the labelled data — ordinary supervised training, stated plainly so that something can be added to it. What gets added by [[eq-combined-objective]] is the pre-training loss, recomputed on the task's own inputs. That addition costs no parameters, because the language modelling head is nothing but $W_e^T$, the transposed embedding table, which is still sitting there from stage one. A model with a separately trained output projection would have had to carry one along on purpose; [[output-softmax-tied-embeddings]] means this one does not.\n\nNow the tension. The two terms pull on the same weights, so gradient capacity is divided between predicting the label and predicting the next token, and $\\lambda$ is where the split is set. [[auxiliary-objective-weight]] is reported as 0.5 with no sweep, so it is a stated setting rather than a tuned finding. Against that, [[ablation-no-auxiliary-objective]] finds the sign of the effect changing with the dataset: the inference tasks and [[qqp]] benefit from keeping the term, smaller sets do not, and the paper words the trend as larger datasets benefiting. One constant is therefore being applied across cases where the paper's own evidence says the right value differs.\n\nThere is a second thing the paper states but does not join up. Its related-work section splits [[semi-supervised-learning-for-nlp]] into two branches: [[unsupervised-pretraining]], where unlabelled data only chooses where the weights start, and [[auxiliary-training-objectives]], where an unsupervised term is added to the supervised loss. The recipe sits in the first branch and borrows the second. And when it borrows, it says pre-training has already learned the linguistic aspects the auxiliary objective would otherwise supply. That sentence is an argument for [[auxiliary-lm-objective]] being redundant once stage one is large enough — which is close to the ablation's own trend, read from the other end. The paper never puts the two remarks next to each other.", "edgeIds": ["e018", "e035", "e041", "e042", "e043", "e067", "e079", "e080", "e108", "e109", "e110", "e111", "e119"], "number": "2", "childId": null, "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "settings-whose-mechanisms-live-elsewhere", "title": "A large part of the model is settings for mechanisms defined in other papers", "body": "Read the model specification as a list and it looks like a design. Read it as a set of dependencies and most of it is a value chosen for a slot that some other paper cut, with this paper supplying the number and one sentence of justification.\n\nThe stack itself is the clearest case. [[multi-layer-transformer-decoder]] is not a new architecture; it is the block of prior work, stacked twelve deep. [[decoder-only-stack]] is one cut of that design: drop the encoder half, keep a single stack attending to its own past, because a language modelling objective has no separate source to encode. [[eq-decoder-stack]] is where you can check that — three lines with no encoder and no cross-attention anywhere in them, and [[transformer-gpt1]] supplying everything inside each block.\n\nThe open slots then get filled with numbers. [[position-wise-feedforward-3072]] widens each 768-dimensional vector fourfold and projects it back. [[twelve-attention-heads]] do not each receive their own state; they divide it, so 768 over 12 leaves each head a 64-dimensional subspace, which ties [[hidden-state-dimension-768]] and the head count together as one dial with two labels. Dropout at rate 0.1 is placed at three points — residual branches, embeddings, attention — the mechanism assumed known, the placements specified.\n\nThree more are substitutions with the mechanism defined in a citation. [[learned-position-embeddings]] replace the original transformer's fixed sinusoids with a trained table; no comparison between the two is reported. [[byte-pair-encoding-gpt1]] decides what a token is, at 40,000 merges, with the merge algorithm defined in [53] — which also means the rows of $W_e$ are subword pieces, and since the output reuses $W_e^T$, the distribution the model predicts is over those same pieces. [[decoupled-weight-decay]] is used at $w = 0.01$ specifically because plain L2 inside the loss gets rescaled by Adam's per-parameter step; the variant is from [37], and the regularizer is picked because of the optimizer rather than independently. [[gelu]] replaces ReLU, defined in [18].\n\nOne borrowed piece even justifies another. [[weight-initialization]] draws every weight from $\\mathcal{N}(0, 0.02)$, and the stated reason it suffices is that [[layer-normalization-gpt1]] is used throughout, rescaling activations at each position so the initialization never has to keep magnitudes in range itself.", "edgeIds": ["e004", "e006", "e007", "e012", "e014", "e015", "e030", "e037", "e038", "e069", "e075", "e076", "e091", "e092", "e093", "e122"], "number": "3", "childId": null, "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "one-decision-three-appearances", "title": "The mask, the 512-token window and the choice of books are one decision made three times", "body": "These three look independent. The mask is architecture, 512 is a hyperparameter, BooksCorpus is data, and they appear in different sections. Follow the dependencies and they are one commitment restated at three levels.\n\nStart at [[eq-lm-objective]]. It defines [[language-modeling-objective]] as the summed log-probability the network assigns each token given the $k$ tokens before it, leaving $k$ as a free symbol. That conditioning is what [[masked-self-attention]] exists to realize: each position may attend to itself and earlier positions, never later ones. Without the mask a position could attend to the token it is being asked to predict, and the objective would be solved by copying. With it, one forward pass over a sequence produces one honest prediction at every position at once.\n\nNow $k$ gets a value. [[context-window-512-tokens]] fixes it at 512 contiguous tokens. That number is not only a setting in the loss — it is a row count. Because position information comes from a trained table rather than sinusoids, [[learned-position-embeddings]] has one row per slot, so 512 is a size in the parameter file and not something that can be raised at test time.\n\nA 512-token window is only worth paying for if the tokens inside it are related to each other. That is what selects the corpus. [[bookscorpus]] is over 7,000 unpublished books, and its stated selling point is [[long-range-contiguous-text]] — sentences left in their original order, so a window usually spans several paragraphs of one story. The paper names [[one-billion-word-benchmark]] as roughly the same size and rejects it because sentence-level shuffling destroys that structure. On a shuffled corpus, the same 512 slots would mostly hold unrelated neighbours, and the mask would be enforcing a conditioning that had nothing to condition on.\n\nWhat all three are for is [[long-range-dependencies-gpt1]], and the paper gives two concrete cases: [[coreference]], where a pronoun and the name it stands for can sit sentences apart, and [[race-dataset]], where a question points at a detail far back in a passage.\n\nThe same chain doubles as the architecture argument. [[lstm-short-range-limitation]] is the paper's stated reason for not using a recurrent network: pre-trained LSTMs keep their predictive ability local, capping what they can hand over. Every prediction seeing up to 512 preceding tokens is the concrete counterpoint to that claim.", "edgeIds": ["e003", "e005", "e008", "e009", "e010", "e036", "e071", "e072", "e073", "e074", "e089", "e090", "e103", "e106", "e107"], "number": "4", "childId": null, "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-comparisons-not-run", "title": "The two things the paper argues hardest for are the two it never varies", "body": "[[ablation-studies]] runs three controlled removals: drop the auxiliary loss, swap the transformer for an LSTM, skip pre-training. Neither of the two choices the paper spends the most prose defending — the corpus and the pre-training objective — is varied in any of them.\n\nThe objective first. The introduction sets out [[choice-of-pretraining-objective]] as an open question and names three candidates being tried in the field — language modelling, machine translation, discourse coherence — each ahead of the others on different tasks. The paper commits to next-token prediction and reports what happens. It does not claim the choice is best, and it runs no second objective to compare against, so the question it opened stays open. Nothing about the estimator is unusual either: [[language-modeling-objective]] is [[maximum-likelihood-training]] applied to text, so whatever stage one contributes comes from the data and the architecture rather than from the loss being special.\n\nThe corpus next. [[long-range-contiguous-text]] is argued for against the sentence-shuffled alternative, and the evidence offered is downstream. [[table-3]] reports the paper's two largest margins, 8.9 points on the Story Cloze Test and 5.7 overall on [[race-dataset]], and these are read as showing the model handles long context. [[cnn-and-squad-contrast]] appears only to argue that RACE has more reasoning-type questions than earlier reading comprehension sets. But no table separates long-range items from short-range ones, and no pre-training corpus was swapped and rerun. The corpus argument therefore rests on scores from a model trained on one corpus, which is one inferential step weaker than the claim it carries.\n\nTwo more places where the measurement sits beside the claim rather than under it. [[token-level-perplexity]] of 18.4 is offered as evidence that stage one worked; it is the pre-training loss restated per token, so it reports fit to BooksCorpus and nothing about transfer. [[world-knowledge]] appears in the conclusion as \"significant world knowledge\" acquired from pre-training, and the nearest evidence is the zero-shot panel plus the downstream tables, neither of which measures facts about the world.\n\nAnd [[domain-mismatch-tolerance]] — the assumption that the unlabelled corpus need not match the target domain — is stated in the introduction and then relied on throughout, with fiction books pre-training a model evaluated on science exams, news paraphrase and Quora question pairs. It is never tested directly.", "edgeIds": ["e011", "e013", "e051", "e052", "e053", "e062", "e063", "e068", "e096", "e126", "e128"], "number": "5", "childId": "i-the-comparisons-not-run", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "task-work-moved-into-the-input", "title": "The single-model claim is paid for in the input format, and one format needs a repair", "body": "[[task-agnostic-model]] is true of the architecture and not of the pipeline. The per-task work still exists; it has been moved out of the network and into a serialization step, and one of the four serializations then needs a fix for a defect the readout introduces.\n\nThe comparison the paper draws is with [[task-specific-architectures]], the prevailing practice of hand-designing a network around each task's structure, often stacked on transferred representations. Both approaches accept that tasks differ. They disagree about where the difference is absorbed. Here it is absorbed by [[task-specific-input-transformations]]: premise-hypothesis pairs and document-question-answer triplets are each rewritten as one ordered token sequence before the model sees anything. [[fig-1]] is the concrete content of that idea, with the repeated block on the left and four task shapes feeding the same stack on the right, and [[multi-layer-transformer-decoder]] is what actually fills the task-agnostic role for all twelve datasets.\n\nThe payoff is measured in [[per-task-parameter-cost]]. [[eq-task-head]] introduces exactly one matrix, $W_y$, applied to a single vector and softmaxed, which is why [[minimal-extra-parameters]] can be checked by counting rather than believed. Adding [[delimiter-token]] embeddings completes the list. The systems this single matrix is measured against are mostly task-built biLSTMs, sometimes with attention, ELMo features or ensembling.\n\nThat one-matrix head is only possible because the sequence has already been collapsed. [[final-token-activation]] is the final block's output at the last input position, and for that position to mean the same thing across examples, every transformed input is bracketed by [[start-and-end-tokens]].\n\n### The defect and its repair\n\nA left-to-right stack summarizing at the last token is order-sensitive by construction: whichever part comes second sits closer to the readout. [[entailment-input-transformation]] does not mind, because a premise and a hypothesis have an inherent direction, and one traversal with a delimiter between them is faithful. [[similarity-input-transformation]] does mind, because two sentences being compared have no natural order and a single traversal would impose one arbitrarily. The repair is to build both orderings, run each through the stack independently, and add the two final activations element-wise before the linear layer — at twice the compute per example. [[qa-and-commonsense-input-transformation]] handles variable structure the same way, building one sequence per candidate answer and normalizing scores across candidates, so [[traversal-style-approach]] absorbs a changing number of parts by running a fixed model several times.", "edgeIds": ["e016", "e017", "e019", "e020", "e021", "e039", "e040", "e044", "e045", "e046", "e070", "e077", "e078", "e081", "e082", "e083", "e084", "e097", "e098", "e100", "e127", "e130"], "number": "6", "childId": "i-task-work-moved-into-the-input", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "everything-is-carried-in-the-weights", "title": "Every setting in stage two is arranged around not disturbing the weights, and none of it is argued", "body": "What stage one hands over is a parameter vector and nothing else. [[unsupervised-pretraining]] is the branch of semi-supervised learning where unlabelled data chooses where the weights start, and here the language model's outputs are discarded entirely — only $\\Theta$ survives. Every number in the fine-tuning setup then reads as protection for that vector, though the paper reports them as settings and argues the point nowhere.\n\nThe two stages train the same weights against opposite targets. [[generative-pretraining]] maximizes the probability of the next token over unlabelled text; [[supervised-fine-tuning]] maximizes the probability of the correct label given the input. The second does not initialize a fresh network. It continues the exact parameters the first produced.\n\nNow read the settings. The peak learning rate falls from 2.5e-4 to 6.25e-5, four times smaller, with batches of 32 instead of 64 — [[fine-tuning-lr-and-batch]] against [[pre-training-optimization]]. Three passes over a task's training set replace 100 over BooksCorpus. [[three-epochs-fine-tuning]] would be an absurd budget from random initialization; the paper simply says the model fine-tunes quickly. The only regularizer stage two adds is [[classifier-dropout]] at 0.1, applied to the head — the newest and smallest part, and the part most able to overfit a small labelled set. Everything else is inherited. Small steps, few of them, one new thing regularized: an arrangement for adjusting weights that already encode something worth keeping.\n\nThe contrasts sharpen what \"carried in the weights\" means. [[feature-based-transfer]] freezes the pre-trained model and feeds its hidden states into a separate task network as extra inputs; [[elmo-deep-contextualized-word-representations]] is the best-known case, and its task model is trained from scratch. Here there is no second network and every pre-trained weight is updated. The price is visible in [[masked-self-attention]]: because each position must predict the next token, it may never see the right context, while ELMo's bidirectional language model can — one approach gives up the right context, the other gives up a single stack that can be fine-tuned as it stands.\n\n[[word-embedding-transfer]] is the same distinction at word level, moving one vector per word and nothing above it, and [[layers-transferred]] shows what stopping there costs: full transfer is worth up to 9% on MultiNLI over embeddings alone. And within [[lm-pretraining-then-finetuning-predecessors]], [[ulmfit]]'s staged schedule is grouped with the intricate learning schemes the introduction names as an obstacle. This one is three epochs at a single rate, warmup over 0.2% of updates, then linear decay.", "edgeIds": ["e002", "e023", "e024", "e064", "e065", "e066", "e094", "e095", "e099", "e101", "e102", "e118", "e120", "e121", "e125", "e129"], "number": "7", "childId": null, "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "ablations-rank-the-paper-s-own-claims", "title": "The paper's own ablations put the pre-training three times ahead of the transformer", "body": "The title leads with two things: generative pre-training, and the transformer that does it. [[table-5]] measures both, and they are not close. Removing pre-training costs 14.8% across the board; replacing the transformer costs 5.6 average points. Roughly a factor of three, in favour of the data.\n\n[[ablation-no-pretraining]] is one row. It trains the identical architecture directly on the supervised tasks, so the only thing it removes is [[generative-pretraining]], and performance drops on every task measured. That single number is the strongest direct evidence for [[two-stage-training-procedure]] anywhere in the paper — the whole recipe rests on it, and it is the largest of the three ablation effects.\n\n[[ablation-lstm-substitution]] is the other end. It swaps the twelve-block stack for a single-layer 2048-unit [[lstm-gpt1]] and holds everything else fixed: the same serialized inputs, the same last-token readout, the same two objectives. That control is only available because [[task-specific-input-transformations]] are architecture-independent — the transformations do not know what is between the input and the readout. Because nothing else moves, the 5.6-point drop can be attributed to the sequence model itself.\n\nTwo things follow that the average hides. First, [[multi-layer-transformer-decoder]] wins on eleven of the twelve datasets in that comparison and loses on one: [[mrpc]]. The architecture claim is an average with a counterexample, and the paper reports the counterexample rather than dropping it. Second, the ranking cuts against how the method is usually summarized. If the ablations are taken at face value, the recipe would survive a considerably worse architecture and would not survive losing stage one.\n\nWhat the third row of the same table shows is different in kind. Dropping the auxiliary language modelling loss does not degrade the model uniformly; it helps in some places and hurts in others. So of the three removals in [[ablation-studies]], two produce a single signed number and one produces a pattern that depends on the dataset. Only the first two can be read as a ranking at all.", "edgeIds": ["e022", "e031", "e032", "e033", "e034", "e104", "e105", "e112", "e113"], "number": "8", "childId": null, "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-explanation-is-a-scoring-rule", "title": "The account of why pre-training works reads the training loss back out", "body": "Section 5 is the paper's attempt to say why the recipe works rather than that it works, and its main device is a scoring rule. Three of the four zero-shot heuristics rank a candidate string by the mean log-probability the model assigns its tokens — which is the same quantity [[language-modeling-objective]] maximizes, averaged over one candidate instead of summed over a corpus.\n\nThat matters for how the curves should be read. A generative model does not emit labels, so getting task answers out of it without fine-tuning requires turning it into a scorer, and [[average-token-log-probability-scoring]] is that converter. [[cola-zero-shot-heuristic]] is the score plus a threshold. [[race-zero-shot-heuristic]] conditions on document and question and takes the highest-scoring answer. [[dprd-winograd-heuristic]] substitutes each possible referent for a definite pronoun and keeps whichever substitution leaves the remainder scoring higher, which is [[coreference]] posed as a comparison between two rewritten sentences. Only [[sst2-zero-shot-heuristic]] works differently, appending the token \"very\" and restricting the output distribution to \"positive\" and \"negative\" — available only because the model already produces a distribution over the whole vocabulary at every position.\n\nThe right panel of [[fig-2]] then shows these scores rising steadily across pre-training updates. The paper words the reading as a hypothesis, and it is right to. The heuristics read out exactly the quantity training is pushing on, so a rise is close to what optimizing $L_1$ means, and the curves are relative trends rather than absolute task scores. [[zero-shot-behaviors]] shows the ability growing; it does not show it competitive, and the section presents it as a weaker way of getting answers used as a diagnostic for [[supervised-fine-tuning]].\n\nThe left panel is a different kind of evidence. [[layers-transferred]] carries a variable number of pre-trained layers into fine-tuning and finds accuracy climbing with each one, up to 9% on [[multinli]] for full transfer. That is a measurement rather than a restatement — but it is a dial with twelve positions only because [[twelve-layer-depth]] made it one, and a shallower stack would leave less room for the effect to appear.\n\nThe weakest link in the section is [[transformer-inductive-bias]]. The claim that attention gives a more structured memory than [[lstm-gpt1]] rests on one observation: the LSTM's zero-shot performance varies more across pre-training. No variance figure is quoted. It is a qualitative reading of a plot, offered as a hypothesis, and the paper says so.", "edgeIds": ["e025", "e026", "e027", "e028", "e029", "e058", "e059", "e060", "e061", "e085", "e086", "e087", "e088", "e123", "e124"], "number": "9", "childId": null, "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "nodes": {"i-the-comparisons-not-run": {"id": "i-the-comparisons-not-run", "parentId": "insights-root", "parentChapterId": "the-comparisons-not-run", "depth": 1, "title": "Three removals, three different questions, one schedule tuned for the full model", "intro": "The parent said what the ablations do not vary. This level goes the other way and takes the three rows that were run, one at a time: what each holds fixed, what it changes, and how far the number it produces reaches. Two of the three answer narrower questions than their headline sizes suggest.", "chapters": [{"id": "the-shared-frame", "title": "Four rows, eight datasets, one mixed scale", "body": "[[table-5]] is four training recipes run over the same eight datasets. The top row is the full system. The three below it each change exactly one thing, so a column can be read straight down. The four averages are 74.7 for the full model, 59.9 with pre-training removed, 69.1 with the transformer replaced, and 75.0 with the auxiliary loss switched off.\n\nEight, not twelve. [[evaluation-task-families]] covers twelve datasets in [[table-1]], and the ablation table drops four of them: [[snli]], [[scitail]], [[race-dataset]] and [[story-cloze-test]]. The last two are where the paper's largest margins live. [[table-3]] reports 8.9 on Story Cloze and 5.7 on RACE, and those are the two numbers the abstract leads with. No row of [[ablation-studies]] says what pre-training or the architecture was worth on either of them.\n\nThe Avg. Score column is an unweighted mean of the eight cells in its row. The cells are not on one scale. [[cola]] is scored by Matthews correlation, [[sst-2]] and the NLI sets by accuracy, [[mrpc]] and [[qqp]] by F1, [[sts-b]] by Pearson correlation. Nothing is rescaled before averaging. So the 14.8 and the 5.6 that follow are 14.8 and 5.6 points on a scale assembled by adding four different metrics together and dividing by eight. They are comparable to each other, because they come from the same column. They are not percentage points of anything.", "edgeIds": ["e031", "e033", "e034", "e035", "e051"], "childId": null, "number": "5.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-pre-training-row", "title": "Removing pre-training changes the initialization and nothing else", "body": "The [[ablation-no-pretraining]] row keeps the same twelve-block decoder, the same serialized inputs, the same linear head, the same two losses. One thing moves: the starting weights. Instead of the parameters [[generative-pretraining]] produced, the run begins from the [[weight-initialization]] the paper uses everywhere, draws from $\\mathcal{N}(0, 0.02)$.\n\nThe average falls from 74.7 to 59.9. Every column drops. [[cola]] falls hardest, from 45.4 to 18.9, and the paper reads that as the linguistic bias coming from stage one rather than from the labels.\n\nWhat the row cannot tell you is what the same architecture would do if it were given a schedule of its own. Section 4.1 says the [[fine-tuning-hyperparameters]] reuse the pre-training settings unless stated, with [[fine-tuning-lr-and-batch]] at $6.25\\times10^{-5}$ and batch 32, a warmup over the first 0.2% of updates, and [[three-epochs-fine-tuning]]. Three epochs is a budget chosen because, in the paper's words, the model fine-tunes quickly — a property of the pre-trained start. Run it on [[rte]], which has 2,490 training examples, and three epochs at batch 32 is about 234 gradient updates. A network starting from random weights gets 234 updates on that task.\n\nSo the row measures a pre-trained start against a random start under a recipe built for the first. It is a lower bound on what [[two-stage-training-procedure]] buys inside this setup, and the paper does not claim otherwise. It is not a measurement of what the transformer can reach when trained directly.", "edgeIds": ["e031", "e033", "e113", "e024", "e112"], "childId": null, "number": "5.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-lstm-row", "title": "The LSTM swap moves depth, width and family together", "body": "[[ablation-lstm-substitution]] is the cleanest of the three in one respect. The swap is possible at all because everything around the sequence model is architecture-independent: [[task-specific-input-transformations]] turn every task into one token stream, the readout takes the last position's activation, and both losses are unchanged. Whatever changes in the scores is the sequence model.\n\nBut a lot of the sequence model changes at once. The paper's [[model-specification]] is [[twelve-layer-depth]] of blocks at [[hidden-state-dimension-768]] with [[position-wise-feedforward-3072]]. The replacement is one layer of 2048 units. Take the shapes the paper gives: a block's four attention projections are $4\\times768^2\\approx2.4$M parameters, its feed-forward pair is $768\\times3072$ twice, about 4.7M, so roughly 7M a block and about 85M across twelve. A single LSTM layer's four gates over a 2048-unit state are $4\\times2048^2$, about 17M, plus its input projections. No parameter counts are reported for either. Depth, width and architecture family all differ, and the 5.6 points cover all three differences together.\n\n[[mrpc]] is the exception, 83.2 for the [[lstm-gpt1]] against 82.3 for the full model. The paper reports it. The architecture claim is an average over eight datasets with one loss inside it, not a sweep.\n\nAnd the row does not test the argument the architecture was chosen for. [[lstm-short-range-limitation]] says pre-trained recurrent models keep their predictions local, with [[context-window-512-tokens]] as the answer. Eight end-to-end scores do not separate range from anything else. The nearest support for [[transformer-inductive-bias]] is a variance remark, worded as a hypothesis.", "edgeIds": ["e032", "e034", "e104", "e105", "e022", "e005", "e107"], "childId": null, "number": "5.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "the-auxiliary-row", "title": "The third removal gains, and cannot separate the term from its weight", "body": "[[ablation-no-auxiliary-objective]] does not cost anything on average. Fine-tuning with the supervised loss alone scores 75.0 against the full model's 74.7, three tenths of a point ahead, and takes the best cell in five of the eight columns. The paper keeps the term anyway and reports where it earns its place: [[qqp]], [[multinli]] and [[qnli]].\n\nWhat the row isolates is the second term of [[eq-combined-objective]] — the [[auxiliary-lm-objective]] computed on the labelled task's own text and added to [[supervised-objective-l2]]. What it cannot isolate is the term apart from its size. [[auxiliary-objective-weight]] is fixed at $\\lambda = 0.5$ for every dataset in the table, and no other value is run. So the row does not read \"the auxiliary loss is worth $-0.3$ on average\". It reads \"the auxiliary loss at $\\lambda = 0.5$ is worth $-0.3$ on average\". Whether a smaller weight would keep the gains on the three large datasets and remove the losses on [[sts-b]] and the rest is not addressed either way.\n\nThat makes it a different kind of experiment from the other two. Removing pre-training removes something with no dial; there is no partial pre-training in the table. Replacing the transformer removes something with no dial either. Removing the auxiliary loss sets one continuous knob to zero from a single other setting, and calls the difference the effect of the knob. The two losses are also competing for the same gradient during fine-tuning, so the removal is not a subtraction of capability.", "edgeIds": ["e035", "e108", "e109", "e110", "e111"], "childId": null, "number": "5.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "one-run-per-row", "title": "Every cell is one run, and only the largest number survives that", "body": "Each cell in [[table-5]] is a single number. No seeds, no repeats, no spread. Nothing in [[ablation-studies]] says how much a rerun would move.\n\nThe same section does rely on run-to-run spread elsewhere. In the right panel of [[fig-2]], the paper's reading of [[zero-shot-behaviors]] notes that the [[lstm-gpt1]] shows higher variance across pre-training updates than the transformer, and that observation carries most of the case for [[transformer-inductive-bias]]. No variance figure is quoted there either. So spread is invoked where it supports an argument and left unreported where it would qualify one.\n\nThat matters unevenly across the three removals. [[sts-b]] has roughly 5,700 training examples and [[rte]] has 2,490; at batch 32 and [[three-epochs-fine-tuning]], the RTE run is a few hundred updates. Cells that small move under a different seed. A $0.3$-point difference in an eight-way unweighted mean sits well inside the range a rerun could plausibly produce, and $0.3$ is the whole result of [[ablation-no-auxiliary-objective]] — the row a size-dependent trend is then read from.\n\nThe 5.6 is harder to explain away. The 14.8 of [[ablation-no-pretraining]] is not in reach of seed noise at all, and every column moves the same way, which is a consistency check the average alone does not give. The reliability of the three ablations tracks their size, and only the largest is clearly out of reach of the error bars the table does not carry.", "edgeIds": ["e035", "e061", "e124", "e028", "e109"], "childId": null, "number": "5.5", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "i-task-work-moved-into-the-input": {"id": "i-task-work-moved-into-the-input", "parentId": "insights-root", "parentChapterId": "task-work-moved-into-the-input", "depth": 1, "title": "Four Formats, One Readout", "intro": "The parent treated the four serializations as a set. Taken one at a time they are not four instances of one idea: one of them is not a transformation at all, one gets the readout's asymmetry for free, and two pay for it in forward passes rather than in parameters. This level walks each format, says what the last-token readout does to it, and ends on what the paper's cost accounting does not count.", "chapters": [{"id": "classification-no-transformation", "title": "The task that already fits", "body": "Section 3.3 opens by conceding that one of the four cases needs nothing. For [[text-classification]], the paper says, the model can be fine-tuned directly as described in the previous section. So of the four columns in [[fig-1]]'s right panel, only three are answers to the problem of [[structured-inputs]]; the first is the shape the pre-trained model already reads.\n\nWhat still happens to a classification example is the bracketing. The sentence is wrapped in [[start-and-end-tokens]] and handed over. No [[delimiter-token]] appears anywhere in the sequence, because there are no parts to separate.\n\nThe readout costs this case almost nothing, and the reason is worth spelling out. [[masked-self-attention]] lets a position attend to itself and everything before it, never to anything after. In a sequence of $m$ tokens, position $m$ is therefore the only position that has had all $m$ tokens in view. When [[eq-task-head]] reads [[final-token-activation]] at that last position, it is reading the one slot where the whole input has been seen. For a single sentence, the direction the stack summarizes in and the direction the sentence is written in are the same direction.\n\nThe two datasets are [[cola]] and [[sst-2]], and their results in [[table-4]] pull apart: 45.4 on CoLA against a previous best of 35.0, and 91.3% on SST-2, which the paper calls competitive rather than best. Both went through the identical, unmodified [[supervised-fine-tuning]] path. Whatever separates them, it is not the input format.", "edgeIds": ["e044", "e046", "e016", "e077", "e039"], "childId": null, "number": "6.1", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "entailment-one-delimiter", "title": "Entailment: one delimiter, one pass", "body": "[[entailment-input-transformation]] is the smallest real case of the [[traversal-style-approach]]: concatenate the premise tokens, then a `$`, then the hypothesis tokens. One sequence, one pass through the stack.\n\nThe parent said the order-sensitivity does not hurt here. The mechanism behind that is more specific than the readout. Under [[masked-self-attention]], every hypothesis token can attend back across the entire premise, while no premise token can attend forward to any hypothesis token. The comparison between the two sentences is therefore computed only in the second half of the sequence, in the hypothesis positions and the end token. Putting the hypothesis second is not a neutral choice about which vector ends up nearer the readout; it decides which sentence gets read in light of the other. For a task that asks whether the premise supports the hypothesis, that is the direction the question runs in.\n\nThe boundary itself is carried by one symbol. The [[delimiter-token]] is a randomly initialized embedding, trained during fine-tuning, and the model is never told anything else about where one sentence ended. Nothing in the architecture partitions the sequence.\n\nOne format then serves all five datasets of [[natural-language-inference]] without adjustment: [[snli]] at roughly 550k training examples, [[multinli]], [[qnli]], [[scitail]], and [[rte]] at 2490. [[table-2]] reports gains on four and a loss on the smallest. The serialization does not vary with dataset size, and the paper does not suggest it should.", "edgeIds": ["e082", "e127", "e016", "e019"], "childId": null, "number": "6.2", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "similarity-two-passes", "title": "Similarity: why the two vectors are added", "body": "The parent gave the repair. The detail worth pausing on is that [[similarity-input-transformation]] adds the two [[final-token-activation]] vectors rather than concatenating them.\n\nWalk what each option would do to the head. Each pass returns one 768-dimensional vector, since the states are [[hidden-state-dimension-768]] throughout. Concatenating the two would give a 1536-dimensional input, so [[linear-output-layer-wy]] would need twice as many rows, and — more to the point — those two halves would be free to be weighted differently. The asymmetry the repair was meant to remove would come back inside the head. Element-wise addition is commutative, so swapping the two sentences leaves the summed vector bit-for-bit unchanged, and $W_y$ stays a single 768-row matrix. The invariance is exact, and it is bought at the readout rather than trained for.\n\nIt is also only at the readout. The two passes are independent; neither ordering's forward computation sees the other. The single channel between them is the sum. Anything that would require holding both readings at once is not representable here, and the price of even this much is two forward passes per example, at training time and at test time, which [[fig-1]] draws as two stacks.\n\nAmong the three [[semantic-similarity]] datasets, [[table-4]] claims a 1 point gain on [[sts-b]] and 4.2% on [[qqp]], and claims nothing on [[mrpc]]. MRPC is also the single dataset where [[ablation-lstm-substitution]] beats the transformer. The paper reports both facts and connects neither to the doubled-pass format.", "edgeIds": ["e021", "e045", "e083", "e127", "e017"], "childId": null, "number": "6.3", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "multiple-choice-per-candidate", "title": "Multiple choice: one pass per candidate", "body": "[[qa-and-commonsense-input-transformation]] writes each sequence as $[z; q; \\$; a_k]$ — document, question, delimiter, one candidate answer. Read that notation literally and only one [[delimiter-token]] appears in it. The answer is marked off; the join between document and question is not.\n\nThe normalization changes shape here too. In classification, softmax runs across the columns of [[linear-output-layer-wy]] for a single sequence. Here it runs across sequences: each candidate's pass produces its own score, and [[eq-task-head]] is applied once per candidate before the scores are compared. Same matrix, same last-token vector, a different axis to normalize over. This is how [[structured-inputs]] with a variable number of parts get handled without touching the model — the [[traversal-style-approach]] absorbs the variation by running the fixed stack several times.\n\nThe cost is that the document is re-encoded from scratch for every candidate. On [[race-dataset]], passages are middle- and high-school exam texts and the input is capped by the [[context-window-512-tokens]], so for a four-option question the great majority of four full forward passes is the same document processed four times over. [[story-cloze-test]] has two options and so costs two.\n\n[[table-3]] reports the paper's largest margins on exactly these two datasets of [[question-answering-and-commonsense-reasoning]]: 8.9% on Story Cloze and 5.7% overall on RACE. The format that repeats the most computation is the one the biggest gains come from, and the paper does not read anything into that.", "edgeIds": ["e084", "e082", "e040", "e044"], "childId": null, "number": "6.4", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "what-the-count-leaves-out", "title": "What the parameter count does not count", "body": "[[per-task-parameter-cost]] is the axis the paper chooses for its comparison with [[task-specific-architectures]], and on that axis the four formats are nearly identical. Each adds [[linear-output-layer-wy]]: 768 rows, and as many columns as the task has labels — or a single column, for the multiple-choice case that softmaxes across sequences. [[minimal-extra-parameters]] then lists one further item, embeddings for the delimiter tokens.\n\nThe bookkeeping has a small gap. Section 3.2 names $W_y$ and delimiter embeddings as the only extra parameters; Section 3.3 says every transformation adds randomly initialized [[start-and-end-tokens]]. Those are embeddings as well, so the true addition is three vocabulary rows rather than one. Three rows of 768 numbers against twelve blocks of a 768-dimensional stack does not change the argument, but the stated list is short by two.\n\nThe larger omission is the other axis. Counting parameters, the four formats cost the same. Counting forward passes per example, they are one, one, two, and one per candidate. The [[traversal-style-approach]] pays for structure in compute, and no figure in the paper reports that. When the head is measured against [[baseline-comparisons]] — task-built biLSTMs, sometimes with attention or ELMo features, sometimes ensembled — the comparison being drawn is parameters added per task, not work done per example. That is the sense in which [[task-agnostic-model]] is cheap.", "edgeIds": ["e020", "e040", "e081", "e100", "e130", "e097", "e098", "e019"], "childId": null, "number": "6.5", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}], "number": "6", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}}, "unusedNote": "All 130 edges are assigned to exactly one chapter, and every [load-bearing] edge appears. That is not the same as every edge doing equal work, so here is the honest breakdown.\n\nEdges that drive an argument and are named or quantified in the prose: roughly two thirds of the set — the ablation numbers (e031-e034, e104, e105, e112, e113), the scoreboard and its misses (e047-e057, e114-e117), the mask/window/corpus chain (e003, e008-e010, e071-e074, e103), the auxiliary-objective tension (e035, e042, e043, e080, e108-e111), the serialization chapter's transformations (e016-e021, e082-e084, e127), and the diagnostics (e025-e029, e058-e061, e085-e088).\n\nEdges present as supporting detail rather than as the point of a paragraph: e006, e038, e075, e076 (the tied-embedding and layer-zero definitions appear inside the borrowed-mechanisms chapter as one clause each); e030, e091, e092, e093 (the head/width/dropout settings are listed to make the \"filled slots\" case, not examined individually); e077, e078, e079, e041 (equation-defines-symbol edges, which mostly confirm that a claim is checkable rather than adding an insight); e013 and e096 (both restate that a quantity is ordinary, which one sentence covers).\n\nEdges I could have given more room and did not: e005 and e106-e107, the LSTM short-range argument, appear at the end of the chain chapter but deserve a fuller reckoning against the ablation result in the ablation chapter, where the same architecture claim is measured; splitting them across two chapters weakens both slightly. e102, the left-to-right versus bidirectional trade-off, is a genuine two-sided tension compressed into two sentences.\n\nThe relationship type I deliberately did not organize around is instance-of: 33 of the 130 edges are \"this setting is a case of that general thing\", and taken as a group they are a filing system. They are distributed across chapters as the concrete values that make each argument checkable.\n\nNo use was made of the edge-theme groupings as chapter boundaries. Every chapter here cuts across at least two of them.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "summary": {"title": "Learn the language first, and spend the labels on the task", "lede": "The paper starts from an imbalance in what data exists. For any one language understanding task, the labelled examples were written by people and there are not many of them, while the raw text nobody labelled is effectively unlimited. Its answer is to train one network twice — first to predict the next token across 7,000 books, then, starting from those same weights, on each task's labelled data — and to change nothing else per task beyond one matrix and a way of writing the input as a single sequence. Measured on twelve datasets, that recipe beats systems built for each of them individually on nine. What follows is the argument in order, from why the labels run out to what the paper's own numbers leave unsettled.", "beats": [{"id": "the-labels-are-what-runs-out", "heading": "Labelled data is made by hand, so there is never much of it", "body": "A labelled example for a language task is written by a person. Someone reads a premise and a hypothesis and records whether the second follows from the first. Someone else judges whether a sentence is grammatical, or scores a pair of sentences for similarity.\n\nThat is slow work and it is paid work, so the sets stay small. Several of the datasets this paper measures on have a few thousand training examples.\n\nRaw text has no such ceiling. There is far more of it than anyone will ever annotate.\n\nThe paper gathers a spread of tasks under one heading — entailment, question answering, [[semantic-similarity]], document classification — and calls the set [[natural-language-understanding]]. Each comes with its own dataset and its own idea of a correct answer.\n\nThe standard treatment trains a network to predict the label directly from the input, which is [[generative-vs-discriminative-training|discriminative training]]. Follow what that requires. The network starts from random weights, so the labelled examples have to pay for everything it learns: not only the task, but how words go together, what a negation does, and what the words refer to.\n\nThat is the mismatch the paper opens on ([[labeled-data-scarcity]]). The scarce resource is being spent on the part that is not scarce.\n\nThe alternative is to learn the language from unlabelled text first, and spend the labels on the task alone. The paper is not the first to want that. Its claim is about what it takes to make it work across tasks that do not look alike.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "two-questions-and-the-branch-this-joins", "heading": "Two things were unsettled: which objective to pre-train on, and how to carry it over", "body": "Using unlabelled text to help a supervised task was already ordinary practice. So the related work section has one job: name the family, cut it into branches, and say which branch this is.\n\nThe family is [[semi-supervised-learning-for-nlp]] — a large unlabelled corpus alongside a small labelled one. Its best-known members train one vector per word on raw text and hand that table to a task model ([[word-embedding-transfer]]). The paper grants that this works, and notes it carries word-level information only. Later work moved up to [[phrase-and-sentence-embeddings]], one vector for a longer span.\n\nCut the family a second way, by what the unlabelled data is allowed to change. One branch adds a second unsupervised loss beside the supervised one ([[auxiliary-training-objectives]]), so the objective itself changes. The other leaves the objective alone and uses unlabelled text only to decide where optimization starts ([[unsupervised-pretraining]]). A cited result there argues the starting point does more than ease optimization: it also generalizes better ([[pretraining-as-regularization]]).\n\nThis paper sits in the second branch, and splits it once more.\n\n[[feature-based-transfer]] freezes the pre-trained model and feeds its hidden states into a separate task network as extra inputs; [[elmo-deep-contextualized-word-representations|ELMo]] is the example named. The objection is [[per-task-parameter-cost]]. The task network is designed and initialized fresh for every task, so each one pays for a substantial set of new parameters.\n\nThe line the paper calls closest to its own carries the weights themselves forward instead ([[lm-pretraining-then-finetuning-predecessors]]). [[semi-supervised-sequence-learning]] did that with a recurrent network and [[ulmfit]] with a staged fine-tuning schedule, both for [[text-classification|classification]]. The disagreement there is not about the recipe but about the architecture and the reach: the paper argues a recurrent pre-trained model keeps its predictions local ([[lstm-short-range-limitation]]), and it evaluates on far more than classification.\n\nTwo questions are left standing, and the paper names them both. Which unsupervised objective produces representations that transfer ([[choice-of-pretraining-objective]]), and how to move a representation into a target task once you have one ([[how-to-transfer-representations]]).", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "one-set-of-weights-trained-twice", "heading": "One set of weights is trained twice, and nothing is frozen in between", "body": "The recipe in outline. Stage one, [[generative-pretraining]]: fit a language model to a large unlabelled corpus, and keep the weights rather than any text it produces. Stage two, [[supervised-fine-tuning]]: take those exact weights as the initialization and go on training them on a task's labelled examples. Together that is the [[two-stage-training-procedure]].\n\nThat is all [[transfer-learning|the transfer]] amounts to here. No layer is held fixed. The pre-trained model is not consulted from outside as a feature extractor — it becomes the task model.\n\nTwo consequences follow, and the paper leans on both.\n\nFirst, the thing being fine-tuned is the same stack every time. That is what it means by a [[task-agnostic-model]], and the comparison it wants is against [[task-specific-architectures]]: networks designed around one task's structure, which is what most of the published baselines are.\n\nSecond, the pre-training text need not resemble the task text. The paper states that the target tasks are not required to be in the same domain as the unlabelled corpus ([[domain-mismatch-tolerance]]). Books are the pre-training text, and the evaluation includes science exams, news, image captions and Wikipedia.\n\nThat second one is an assumption stated, not a result shown. No matched-domain corpus is run as a control.\n\nThe architecture is the transformer of prior work, not a new design. What remains to specify is what stage one optimizes, what network it optimizes, and what stage two does with the result.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 7, 8]}}, {"id": "the-whole-signal-is-the-next-token", "heading": "Stage one trains on one quantity: the probability the model gives each token, given the ones before it", "body": "Stage one has no labels, so the training signal has to come out of the text itself. The paper takes the oldest one available: given the tokens so far, predict the one that comes next.\n\nOver an unlabelled corpus of tokens $\\mathcal{U}$, maximize\n\n$$L_1(\\mathcal{U}) = \\sum_i \\log P(u_i \\mid u_{i-k},\\dots,u_{i-1};\\Theta)$$\n\nRead it position by position. At each $i$ the network sees the $k$ tokens before it and produces a distribution over the vocabulary. The number added into the sum is the log-probability it gave to the token that actually appeared. Nothing else is scored.\n\nThat single sum is the whole of stage one ([[language-modeling-objective]]). Every parameter the model has is set by pushing it up.\n\nThe network is a [[multi-layer-transformer-decoder]]: the transformer block of prior work with the encoder half removed, leaving one stack that reads only its own past ([[decoder-only-stack]]).\n\nThe removal is load-bearing rather than a tidying-up. The objective scores every position at once, and a position must not be able to see the token it is being asked to predict. [[masked-self-attention]] enforces that — each position attends to itself and to earlier positions, never to later ones. Without the mask the loss would be trivial to drive down, and driving it down would teach nothing.\n\nThe network itself is three lines. Embed the context tokens and add a position vector to each, giving $h_0 = UW_e + W_p$ ([[input-representation-h0]]). $W_e$ is the [[token-embedding-matrix]], and $W_p$ is a trained table with one vector per slot ([[learned-position-embeddings]]) rather than the fixed sinusoids of the original transformer. Push $h_0$ through $n$ identical blocks. Multiply the top layer by $W_e^{\\mathsf{T}}$ and softmax ([[output-softmax-tied-embeddings]]), so the matrix that turns tokens into vectors also turns vectors back into scores over tokens.", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}], "pages": [1, 2, 3, 4, 5]}}, {"id": "books-because-the-sentences-stay-in-order", "heading": "The corpus was chosen for the length of its contiguous text, not for its size", "body": "The objective says what to maximize. It does not say over what text.\n\nThe corpus is [[bookscorpus]]: over 7,000 unpublished books across genres. The stated reason for choosing it is not the amount of text. It is that a book keeps its sentences in their original order, paragraph after paragraph ([[long-range-contiguous-text]]).\n\nThe comparison the paper draws makes the point. The [[one-billion-word-benchmark|1B Word Benchmark]] holds roughly as much text, and is the corpus ELMo used, but it is shuffled sentence by sentence. Shuffling leaves the word statistics intact and destroys everything above the sentence.\n\nWhether that matters depends on how much text the model may look at once. The context window $k$ is fixed at 512 tokens ([[context-window-512-tokens]]).\n\n512 tokens is several paragraphs. So a prediction can condition on material from well before the sentence it sits in, which is where the [[long-range-dependencies-gpt1|far-apart relations]] the paper wants learned would have to come from.\n\nA window that wide only earns its cost if the text inside it is continuous. On shuffled data the far end of the window is a different sentence about something else, and there is nothing there to condition on.\n\nThis is a bet, and it is argued rather than measured. No model is trained on the shuffled corpus here for comparison. Where the corpus choice pays off, if it does, is in which task families the model gains most on later.", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 8]}}, {"id": "what-was-actually-trained", "heading": "The model is twelve blocks deep, and the depth is what makes one later experiment possible", "body": "Text becomes tokens in three steps ([[text-preprocessing-pipeline]]): clean the raw text, tokenize it, then cut the tokens into subword units with [[byte-pair-encoding-gpt1|byte-pair encoding]]. BPE starts from characters and repeatedly merges the most frequent adjacent pair. The count of merges is the single knob, set to [[bpe-merges-40000|40,000]] — enough that common words survive whole while rare ones break into pieces that were seen elsewhere.\n\nThe trained model is 12 blocks deep, with [[hidden-state-dimension-768|768-dimensional]] states, [[twelve-attention-heads|12 attention heads]] and a [[position-wise-feedforward-3072|3072-dimensional]] inner feed-forward layer ([[model-specification]]). The numbers are related to one another: 768 split across 12 heads leaves each head a 64-dimensional subspace, and 3072 is four times 768. [[gelu|GELU]] stands in for ReLU as the activation.\n\n[[twelve-layer-depth|The depth of 12]] is worth marking here, because it is what makes one of the later diagnostics possible. With twelve blocks you can transfer zero through twelve of them and watch what each one adds.\n\nThe run uses [[adam-optimizer-gpt1|Adam]] at a peak learning rate of 2.5e-4, [[linear-warmup|raised from zero over the first 2000 updates]] and then [[cosine-annealing|annealed back to zero on a cosine curve]], for [[pretraining-schedule|100 passes]] over minibatches of 64 sequences ([[pre-training-optimization]]). Dropout in three places and a [[decoupled-weight-decay|modified weight decay]] do the regularizing ([[regularization-setup]]).\n\nOne number comes out of stage one: [[token-level-perplexity|18.4]] token-level perplexity on the corpus. It says the model fit the books. It says nothing yet about any task, and the paper does not argue from it.", "sources": {"sections": [{"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [3, 4, 5, 7, 8]}}, {"id": "one-matrix-on-the-last-token", "heading": "Stage two adds one matrix, and keeps the language modelling loss running beside the task loss", "body": "Stage two has to turn a next-token predictor into a label predictor, and it has to do it the same way for every task.\n\nThe labelled data is [[labeled-dataset-c|$\\mathcal{C}$]]: each instance is a token sequence $x_1,\\dots,x_m$ paired with one label $y$.\n\nRun the sequence through the pre-trained stack. Take the final block's activation at the last token ([[final-token-activation]]) — one vector, which has attended over everything before it. Multiply it by one added matrix $W_y$ ([[linear-output-layer-wy]]) and softmax.\n\nThat is the entire task-specific classifier. The loss on top of it is ordinary supervised likelihood: sum $\\log P(y \\mid x_1,\\dots,x_m)$ over the labelled set ([[supervised-objective-l2|$L_2$]]).\n\nThe paper does not stop there. It keeps the language modelling loss running during fine-tuning, computed on the labelled task data, and adds it in ([[auxiliary-lm-objective]]):\n\n$$L_3(\\mathcal{C}) = L_2(\\mathcal{C}) + \\lambda\\, L_1(\\mathcal{C})$$\n\nwith [[auxiliary-objective-weight|$\\lambda = 0.5$]]. The stated reasons are better generalization and faster convergence.\n\nNotice what has happened there. The auxiliary-objective branch, set aside earlier as a rival way of using unlabelled data, is used here on top of pre-training instead of in place of it. Its own removal, later, does not come back uniform.\n\nFine-tuning is short. Most tasks use a learning rate of 6.25e-5, about four times smaller than the pre-training peak, at batch size 32 ([[fine-tuning-lr-and-batch]]), warmed up over the first 0.2% of updates and then [[fine-tuning-lr-schedule|decayed linearly to zero]]. [[three-epochs-fine-tuning|Three passes]] over a task's training set sufficed for most datasets, with [[classifier-dropout|dropout 0.1]] on the added head and everything else inherited from stage one ([[fine-tuning-hyperparameters]]).", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 3, 4, 5, 7, 8]}}, {"id": "every-task-is-written-as-one-sequence", "heading": "Tasks that are not one sequence of tokens get rewritten until they are", "body": "A decoder reads one ordered run of tokens. Several of these tasks do not hand over one run of tokens. Entailment gives an ordered pair of sentences; reading comprehension gives a document, a question and a list of candidate answers ([[structured-inputs]]).\n\nThere are two places to absorb that difference. Prior work absorbs it in the architecture, building a module shaped like the task and stacking it on the transferred representation. The paper's objection is that this puts the per-task design straight back in, and that the added module starts from random weights, so it gets nothing from pre-training.\n\nSo the difference is absorbed in the input instead ([[task-specific-input-transformations]]). Each structured input is walked into a single sequence ([[traversal-style-approach]]), bracketed by a randomly initialized start and end token ([[start-and-end-tokens]]) and split by a `$` [[delimiter-token|delimiter]].\n\nEntailment becomes premise, delimiter, hypothesis, read as one sequence ([[entailment-input-transformation]]).\n\nSimilarity has no natural order between its two sentences. So both orderings are built and run through the stack separately, and the two final activations are added element-wise before the linear layer ([[similarity-input-transformation]]).\n\nQuestion answering builds one sequence per candidate answer — document, question, delimiter, that answer. Each is scored on its own, and the scores are softmaxed across the candidates ([[qa-and-commonsense-input-transformation]]).\n\nThis is what keeps the parameter count small. The only weights a new task adds are $W_y$ and embeddings for the delimiter tokens ([[minimal-extra-parameters]]), which is the paper's direct answer to the per-task cost it charged against [[feature-based-transfer|feature-based transfer]].\n\nIt is also what makes the evaluation menu possible: [[evaluation-task-families|four families of tasks across twelve datasets]], several of them drawn from the [[glue-benchmark|GLUE]] bundle.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}], "pages": [1, 2, 3, 4, 5, 6, 7]}}, {"id": "nine-of-twelve", "heading": "One fine-tuned model beats task-built systems on nine of the twelve datasets", "body": "Gains are reported as [[absolute-improvement|differences in percentage points]] against the previous best published number, not as relative error reduction. On the other side are mostly biLSTMs built for the individual task, some with attention, some using ELMo features, some ensembles ([[baseline-comparisons]]).\n\n[[natural-language-inference]] asks for a judgement on a premise and a hypothesis: entailment, contradiction or neutral. Across five datasets the fine-tuned model leads on four — 1.5 points on [[multinli|MultiNLI]], 5 on [[scitail|SciTail]], 5.8 on [[qnli|QNLI]] and 0.6 on [[snli|SNLI]], the largest set at roughly 550,000 training pairs.\n\nIt loses the fifth. [[rte|RTE]] has 2,490 training examples, and the model reaches 56% against 61.7% from a multi-task biLSTM. The paper's reading is that its own approach would probably also benefit from multi-task training, and it says it has not tried that.\n\n[[question-answering-and-commonsense-reasoning|Reading and commonsense reasoning]] give the widest margins. On [[race-dataset|RACE]], exam passages with questions written for middle- and high-school students, the gain is 5.7 points overall. On the [[story-cloze-test|Story Cloze Test]], choosing the right ending to a short story from two options, it is 8.9. Both reward conditioning on a long passage, which is what the corpus and the 512-token window were chosen for.\n\n[[semantic-similarity]] and classification fill out the rest. [[qqp|Quora Question Pairs]] gains 4.2 points over a single-task biLSTM with attention and ELMo. [[sts-b|STS-B]], the smallest set in the evaluation at about 5,700 examples, gains 1. On [[cola|CoLA]], expert judgements of whether a sentence is grammatical, the score is 45.4 against a previous best of 35.0, the widest gap on the board. On [[sst-2|SST-2]] sentiment the model reaches 91.3%, which the paper calls competitive rather than best. The overall GLUE score is 72.8 against a previous 68.9.\n\nCounted up: new best published results on [[state-of-the-art-9-of-12|nine of the twelve datasets]], over training sets spanning two orders of magnitude in size.", "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, {"id": "which-parts-do-the-work", "heading": "Every transferred layer helps, and some of the tasks already work with no fine-tuning at all", "body": "The scoreboard says the recipe works. It does not say which part of it works. The analysis asks three times.\n\nThe first varies how much of the stack is carried over ([[layers-transferred]]). Fine-tune with the embeddings alone transferred, then with one block, then two, and so on up to all twelve, and plot development accuracy. It climbs with each added layer, reaching up to 9 points on MultiNLI at full transfer, and nothing saturates early. The reading offered is that every layer holds something a target task can use, so moving the embeddings alone leaves most of the value behind.\n\nThe second asks what the pre-trained model can already do with no fine-tuning at all ([[zero-shot-behaviors]]). A generative model does not emit labels, so each task has to be turned into a scoring problem. Three of the four heuristics use the same device: the mean log-probability the model assigns a candidate string ([[average-token-log-probability-scoring]]). Threshold that score for grammatical acceptability ([[cola-zero-shot-heuristic]]); pick the highest-scoring answer given the document and the question ([[race-zero-shot-heuristic]]); or substitute each candidate referent for the pronoun and keep the reading that scores better ([[dprd-winograd-heuristic]]). Sentiment is done differently — append the token *very*, restrict the output to *positive* and *negative*, and take the higher ([[sst2-zero-shot-heuristic]]).\n\nTracked across pre-training, all four rise steadily and stay stable. The paper reads that as the language modelling objective picking up task-relevant behaviour on its way to better next-token prediction, rather than that behaviour appearing only when supervision arrives.\n\nThe same heuristics run against an LSTM give noisier scores. That is offered in support of [[transformer-inductive-bias|the transformer's more structured attentional memory helping transfer]] — a hypothesis resting on one comparison.", "sources": {"sections": [{"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [1, 2, 7, 8]}}, {"id": "the-three-removals", "heading": "Taking the pieces out one at a time: pre-training costs the most, and the auxiliary loss is not uniform", "body": "The third diagnostic removes one piece at a time and re-runs the recipe without it ([[ablation-studies]]).\n\nTraining the same transformer straight on the labelled tasks, with no pre-training, costs 14.8 average points and hurts on every task measured ([[ablation-no-pretraining]]). That is the strongest single number in the paper. It is also the one carrying the central claim: the gains come from stage one, not from the architecture arriving in good shape.\n\nSwapping the transformer for a single-layer 2048-unit LSTM, holding the rest of the recipe fixed, costs 5.6 average points ([[ablation-lstm-substitution]]). The LSTM wins on exactly one dataset, [[mrpc|MRPC]]. That is the paper's own measurement of what the architecture choice buys on top of what pre-training buys.\n\nThe third removal is the awkward one. Dropping the auxiliary language modelling loss during fine-tuning does not simply degrade the model ([[ablation-no-auxiliary-objective]]). It helps on some datasets and hurts on others, and the paper reads the pattern as the larger sets benefiting from the extra loss and the smaller ones not.\n\nThat reading is drawn from twelve points, with no repeated runs behind any of them. The loss stays in the recipe on the strength of it.", "sources": {"sections": [{"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}], "pages": [5, 6, 7, 8]}}, {"id": "what-it-settled-and-what-it-did-not", "heading": "What the paper settles, and what its own numbers do not", "body": "What holds up: pre-training a twelve-block decoder on unlabelled books and then fine-tuning those same weights beats systems built for each task on nine of twelve datasets, and the no-pre-training result says most of that comes from stage one. Depth keeps paying across all twelve layers on the two datasets swept. The recipe is the same for every task, and the extra parameters a new task costs are one matrix and a few token embeddings.\n\nThe gaps are visible in the paper's own numbers.\n\nRTE, the smallest inference set, is a loss, and the explanation offered for it — that multi-task training would help — is not tested here.\n\nThe auxiliary loss is part of the recipe, but its removal shows it helping only on the larger sets, a trend read off twelve datasets with no repeated runs.\n\nEvery reported number is a single run against a published best, with no variance on either side. A gain of 0.6 points and a gain of 8.9 points are therefore being read the same way, and only one of them can bear it.\n\nThe GLUE figure does not sit still. The results section compares 72.8 against 68.9, a difference of 3.9, while the introduction's headline number for GLUE is 5.5.\n\nThe corpus argument is made and not run. Books are chosen for their long stretches of contiguous text, and a shuffled corpus of about the same size is named as the alternative, but no model is trained on it here, so the comparison stays an argument.\n\nAnd the conclusion reaches past what was measured, saying the model acquires significant [[world-knowledge|world knowledge]] from predicting text. Nothing in the evaluation separates world knowledge from the reading ability these tasks also reward.", "sources": {"sections": [{"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [8]}}], "sources": {"sections": [{"id": "abstract", "title": "Abstract", "start": 1, "end": 1}, {"id": "1", "title": "Introduction", "start": 1, "end": 2}, {"id": "2", "title": "Related Work", "start": 2, "end": 3}, {"id": "3", "title": "Framework", "start": 3, "end": 3}, {"id": "3.1", "title": "Unsupervised pre-training", "start": 3, "end": 3}, {"id": "3.2", "title": "Supervised fine-tuning", "start": 3, "end": 4}, {"id": "3.3", "title": "Task-specific input transformations", "start": 4, "end": 4}, {"id": "4.1", "title": "Setup", "start": 4, "end": 5}, {"id": "4.2", "title": "Supervised fine-tuning", "start": 5, "end": 7}, {"id": "5", "title": "Analysis", "start": 7, "end": 8}, {"id": "6", "title": "Conclusion", "start": 8, "end": 8}], "pages": [1, 2, 3, 4, 5, 6, 7, 8]}}, "reading": [], "refs": {"paperId": "gpt-1", "accessed": [{"paperId": "1801.10198", "citationKey": "[34]", "whyNeeded": "Section 3.1 says only that it uses a multi-layer Transformer decoder, a variant of the original transformer, citing this. The decoder-only variant — which sublayers were dropped and how the single stack is arranged — is defined there and is the architecture every result in this paper is produced by.", "concepts": ["transformer-decoder-t-d", "transduction-as-single-sequence-lm", "long-input-scaling-comparison", "memory-compressed-attention", "local-attention-blocks-lmlml"]}, {"paperId": "1711.05101", "citationKey": "[37]", "whyNeeded": "The paper says only 'a modified version of L2 regularization proposed in [37], with w = 0.01'. What the modification is, and why decoupling it from Adam's adaptive denominator changes the effective penalty, is entirely in that paper and is needed to reproduce the pre-training run.", "concepts": ["l2-regularization-vs-weight-decay", "adaptive-preconditioner-dilutes-l2", "decoupled-weight-decay-update", "normalized-weight-decay"]}, {"paperId": "1606.08415", "citationKey": "[18]", "whyNeeded": "GELU is named without a formula and used at the 3072-dimensional point of every feed-forward sublayer. Its definition, the tanh approximation usually implemented, and the stochastic-regularizer motivation all live there.", "concepts": ["gelu-definition", "gelu-as-expected-stochastic-regularizer", "gelu-tanh-approximation", "gelu-vs-relu-and-elu"]}, {"paperId": "1509.06664", "citationKey": "[52]", "whyNeeded": "Sections 1 and 3.3 say the input transformations are derived from a traversal-style approach and cite this without defining it. The whole minimal-architecture-change claim rests on what that serialization actually is.", "concepts": ["conditional-encoding", "premise-hypothesis-delimiter", "cell-state-conditioning-handoff", "shared-parameter-single-reader", "last-output-vector-classifier", "independent-encoding-baseline-contrast"]}, {"paperId": "1508.07909", "citationKey": "[53]", "whyNeeded": "GPT-1 uses a bytepair encoding vocabulary with 40,000 merges, and its reported token-level perplexity of 18.4 is measured in those units.", "concepts": ["bpe-merge-algorithm", "bpe-segmentation-at-test-time", "bpe-vocabulary-size", "joint-bpe-shared-vocabulary", "vocabulary-vs-sequence-length-tradeoff"]}, {"paperId": "1706.03762", "citationKey": "[62]", "whyNeeded": "GPT-1 is this architecture minus the encoder, with masked attention and learned rather than sinusoidal positions.", "concepts": ["transformer", "sequence-transduction", "machine-translation", "language-modeling", "encoder-decoder-architecture", "auto-regressive-generation", "recurrent-neural-network", "lstm", "gated-recurrent-unit", "sequential-computation-bottleneck", "factorization-tricks", "conditional-computation", "attention-mechanism", "queries-keys-values", "compatibility-function", "scaled-dot-product-attention", "dk-dv-dimensions", "sqrt-dk-scaling", "dot-product-attention", "additive-attention", "multi-head-attention", "attention-head", "num-heads-h", "attention-projection-matrices", "attention-averaging-resolution-cost", "attention-interpretability", "self-attention", "encoder-self-attention", "masked-decoder-self-attention", "causal-masking", "restricted-self-attention", "encoder-decoder-attention", "encoder-stack", "decoder-stack", "sub-layer", "residual-connection", "layer-normalization", "n-layers", "d-model", "position-wise-feed-forward-network", "d-ff", "relu", "softmax", "token-embeddings", "embedding-softmax-weight-sharing", "sqrt-dmodel-embedding-multiplier", "positional-encoding", "sinusoidal-positional-encoding", "relative-position-linearity", "learned-positional-embedding", "convolutional-sequence-models", "extended-neural-gpu", "bytenet", "convs2s", "dilated-convolutions", "separable-convolutions", "end-to-end-memory-networks", "layer-comparison-desiderata", "complexity-per-layer", "minimum-sequential-operations", "maximum-path-length", "long-range-dependencies", "byte-pair-encoding", "word-piece-encoding", "bleu", "perplexity", "model-ensembling", "tensor2tensor", "transformer-training-recipe", "wmt-2014-en-de", "wmt-2014-en-fr", "length-based-batching", "training-hardware-and-schedule", "base-vs-big-transformer", "adam-optimizer", "transformer-adam-settings", "learning-rate-warmup-schedule", "warmup-steps-4000", "regularization", "dropout", "residual-dropout", "attention-dropout", "label-smoothing", "beam-search", "length-penalty", "inference-length-limit", "checkpoint-averaging", "training-flops-estimate", "transformer-ablations", "attention-heads-ablation", "key-size-ablation", "size-and-dropout-ablation", "constituency-parsing", "penn-treebank-wsj", "semi-supervised-parsing", "recurrent-neural-network-grammar", "berkeley-parser"]}, {"paperId": "1607.06450", "citationKey": "[2]", "whyNeeded": "GPT-1 justifies its N(0, 0.02) initialization by the fact that layernorm is used extensively throughout the model.", "concepts": ["layer-normalization-statistics", "gain-and-bias-parameters", "layer-norm-vs-batch-norm", "per-timestep-normalization", "normalization-invariance-properties"]}]}, "regions": [{"id": "p-abstract-01", "kind": "heading", "sectionId": "abstract", "page": 1, "rect": [0.46366, 0.30626, 0.53635, 0.32135], "text": "Abstract"}, {"id": "p-abstract-02", "kind": "paragraph", "sectionId": "abstract", "page": 1, "rect": [0.23508, 0.33885, 0.76778, 0.55813], "text": "Natural language understanding comprises a wide range of diverse tasks such\nas textual entailment, question answering, semantic similarity assessment, and\ndocument classification. Although large unlabeled text corpora are abundant,\nlabeled data for learning these specific tasks is scarce, making it challenging for\ndiscriminatively trained models to perform adequately. We demonstrate that large\ngains on these tasks can be realized by generative pre-training of a language model\non a diverse corpus of unlabeled text, followed by discriminative fine-tuning on each\nspecific task. In contrast to previous approaches, we make use of task-aware input\ntransformations during fine-tuning to achieve effective transfer while requiring\nminimal changes to the model architecture. We demonstrate the effectiveness of\nour approach on a wide range of benchmarks for natural language understanding.\nOur general task-agnostic model outperforms discriminatively trained models that\nuse architectures specifically crafted for each task, significantly improving upon the\nstate of the art in 9 out of the 12 tasks studied. For instance, we achieve absolute\nimprovements of 8.9% on commonsense reasoning (Stories Cloze Test), 5.7% on\nquestion answering (RACE), and 1.5% on textual entailment (MultiNLI)."}, {"id": "p-1-01", "kind": "heading", "sectionId": "1", "page": 1, "rect": [0.17647, 0.58771, 0.31179, 0.60281], "text": "1\nIntroduction"}, {"id": "p-1-02", "kind": "paragraph", "sectionId": "1", "page": 1, "rect": [0.17597, 0.61963, 0.82638, 0.74246], "text": "The ability to learn effectively from raw text is crucial to alleviating the dependence on supervised\nlearning in natural language processing (NLP). Most deep learning methods require substantial\namounts of manually labeled data, which restricts their applicability in many domains that suffer\nfrom a dearth of annotated resources [61]. In these situations, models that can leverage linguistic\ninformation from unlabeled data provide a valuable alternative to gathering more annotation, which\ncan be time-consuming and expensive. Further, even in cases where considerable supervision\nis available, learning good representations in an unsupervised fashion can provide a significant\nperformance boost. The most compelling evidence for this so far has been the extensive use of pre-\ntrained word embeddings [10, 39, 42] to improve performance on a range of NLP tasks [8, 11, 26, 45]."}, {"id": "p-1-03", "kind": "paragraph", "sectionId": "1", "page": 1, "rect": [0.17647, 0.75053, 0.82354, 0.87334], "text": "Leveraging more than word-level information from unlabeled text, however, is challenging for two\nmain reasons. First, it is unclear what type of optimization objectives are most effective at learning\ntext representations that are useful for transfer. Recent research has looked at various objectives\nsuch as language modeling [44], machine translation [38], and discourse coherence [22], with each\nmethod outperforming the others on different tasks.1 Second, there is no consensus on the most\neffective way to transfer these learned representations to the target task. Existing techniques involve\na combination of making task-specific changes to the model architecture [43, 44], using intricate\nlearning schemes [21] and adding auxiliary learning objectives [50]. These uncertainties have made\nit difficult to develop effective semi-supervised learning approaches for language processing."}, {"id": "p-1-04", "kind": "paragraph", "sectionId": "1", "page": 1, "rect": [0.19715, 0.88595, 0.436, 0.89921], "text": "1https://gluebenchmark.com/leaderboard"}, {"id": "p-1-05", "kind": "paragraph", "sectionId": "1", "page": 1, "rect": [0.17647, 0.9256, 0.33609, 0.93692], "text": "Preprint. Work in progress."}, {"id": "p-1-06", "kind": "paragraph", "sectionId": "1", "page": 2, "rect": [0.17593, 0.09385, 0.82354, 0.20295], "text": "In this paper, we explore a semi-supervised approach for language understanding tasks using a\ncombination of unsupervised pre-training and supervised fine-tuning. Our goal is to learn a universal\nrepresentation that transfers with little adaptation to a wide range of tasks. We assume access to\na large corpus of unlabeled text and several datasets with manually annotated training examples\n(target tasks). Our setup does not require these target tasks to be in the same domain as the unlabeled\ncorpus. We employ a two-stage training procedure. First, we use a language modeling objective on\nthe unlabeled data to learn the initial parameters of a neural network model. Subsequently, we adapt\nthese parameters to a target task using the corresponding supervised objective."}, {"id": "p-1-07", "kind": "paragraph", "sectionId": "1", "page": 2, "rect": [0.17588, 0.21094, 0.82638, 0.32006], "text": "For our model architecture, we use the Transformer [62], which has been shown to perform strongly on\nvarious tasks such as machine translation [62], document generation [34], and syntactic parsing [29].\nThis model choice provides us with a more structured memory for handling long-term dependencies in\ntext, compared to alternatives like recurrent networks, resulting in robust transfer performance across\ndiverse tasks. During transfer, we utilize task-specific input adaptations derived from traversal-style\napproaches [52], which process structured text input as a single contiguous sequence of tokens. As\nwe demonstrate in our experiments, these adaptations enable us to fine-tune effectively with minimal\nchanges to the architecture of the pre-trained model."}, {"id": "p-1-08", "kind": "paragraph", "sectionId": "1", "page": 2, "rect": [0.17571, 0.32827, 0.82557, 0.45094], "text": "We evaluate our approach on four types of language understanding tasks – natural language inference,\nquestion answering, semantic similarity, and text classification. Our general task-agnostic model\noutperforms discriminatively trained models that employ architectures specifically crafted for each\ntask, significantly improving upon the state of the art in 9 out of the 12 tasks studied. For instance,\nwe achieve absolute improvements of 8.9% on commonsense reasoning (Stories Cloze Test) [40],\n5.7% on question answering (RACE) [30], 1.5% on textual entailment (MultiNLI) [66] and 5.5% on\nthe recently introduced GLUE multi-task benchmark [64]. We also analyzed zero-shot behaviors\nof the pre-trained model on four different settings and demonstrate that it acquires useful linguistic\nknowledge for downstream tasks."}, {"id": "p-2-01", "kind": "heading", "sectionId": "2", "page": 2, "rect": [0.17647, 0.47555, 0.32204, 0.49064], "text": "2\nRelated Work"}, {"id": "p-2-02", "kind": "paragraph", "sectionId": "2", "page": 2, "rect": [0.17588, 0.50869, 0.82556, 0.6178], "text": "Semi-supervised learning for NLP\nOur work broadly falls under the category of semi-supervised\nlearning for natural language. This paradigm has attracted significant interest, with applications to\ntasks like sequence labeling [24, 33, 57] or text classification [41, 70]. The earliest approaches used\nunlabeled data to compute word-level or phrase-level statistics, which were then used as features in a\nsupervised model [33]. Over the last few years, researchers have demonstrated the benefits of using\nword embeddings [11, 39, 42], which are trained on unlabeled corpora, to improve performance on a\nvariety of tasks [8, 11, 26, 45]. These approaches, however, mainly transfer word-level information,\nwhereas we aim to capture higher-level semantics."}, {"id": "p-2-03", "kind": "paragraph", "sectionId": "2", "page": 2, "rect": [0.17647, 0.62582, 0.82556, 0.67981], "text": "Recent approaches have investigated learning and utilizing more than word-level semantics from\nunlabeled data. Phrase-level or sentence-level embeddings, which can be trained using an unlabeled\ncorpus, have been used to encode text into suitable vector representations for various target tasks [28,\n32, 1, 36, 22, 12, 56, 31]."}, {"id": "p-2-04", "kind": "paragraph", "sectionId": "2", "page": 2, "rect": [0.17588, 0.69968, 0.82354, 0.79502], "text": "Unsupervised pre-training\nUnsupervised pre-training is a special case of semi-supervised learning\nwhere the goal is to find a good initialization point instead of modifying the supervised learning\nobjective. Early works explored the use of the technique in image classification [20, 49, 63] and\nregression tasks [3]. Subsequent research [15] demonstrated that pre-training acts as a regularization\nscheme, enabling better generalization in deep neural networks. In recent work, the method has\nbeen used to help train deep neural networks on various tasks like image classification [69], speech\nrecognition [68], entity disambiguation [17] and machine translation [48]."}, {"id": "p-2-05", "kind": "paragraph", "sectionId": "2", "page": 2, "rect": [0.17597, 0.80305, 0.82624, 0.91216], "text": "The closest line of work to ours involves pre-training a neural network using a language modeling\nobjective and then fine-tuning it on a target task with supervision. Dai et al. [13] and Howard and\nRuder [21] follow this method to improve text classification. However, although the pre-training\nphase helps capture some linguistic information, their usage of LSTM models restricts their prediction\nability to a short range. In contrast, our choice of transformer networks allows us to capture longer-\nrange linguistic structure, as demonstrated in our experiments. Further, we also demonstrate the\neffectiveness of our model on a wider range of tasks including natural language inference, paraphrase\ndetection and story completion. Other approaches [43, 44, 38] use hidden representations from a"}, {"id": "p-2-06", "kind": "paragraph", "sectionId": "2", "page": 3, "rect": [0.17647, 0.09392, 0.82354, 0.13408], "text": "pre-trained language or machine translation model as auxiliary features while training a supervised\nmodel on the target task. This involves a substantial amount of new parameters for each separate\ntarget task, whereas we require minimal changes to our model architecture during transfer."}, {"id": "p-2-07", "kind": "paragraph", "sectionId": "2", "page": 3, "rect": [0.17647, 0.14954, 0.82353, 0.24488], "text": "Auxiliary training objectives\nAdding auxiliary unsupervised training objectives is an alternative\nform of semi-supervised learning. Early work by Collobert and Weston [10] used a wide variety of\nauxiliary NLP tasks such as POS tagging, chunking, named entity recognition, and language modeling\nto improve semantic role labeling. More recently, Rei [50] added an auxiliary language modeling\nobjective to their target task objective and demonstrated performance gains on sequence labeling\ntasks. Our experiments also use an auxiliary objective, but as we show, unsupervised pre-training\nalready learns several linguistic aspects relevant to target tasks."}, {"id": "p-3-01", "kind": "heading", "sectionId": "3", "page": 3, "rect": [0.17647, 0.26508, 0.30431, 0.28017], "text": "3\nFramework"}, {"id": "p-3-02", "kind": "paragraph", "sectionId": "3", "page": 3, "rect": [0.17647, 0.29518, 0.82353, 0.33541], "text": "Our training procedure consists of two stages. The first stage is learning a high-capacity language\nmodel on a large corpus of text. This is followed by a fine-tuning stage, where we adapt the model to\na discriminative task with labeled data."}, {"id": "p-3.1-01", "kind": "heading", "sectionId": "3.1", "page": 3, "rect": [0.17647, 0.35257, 0.39669, 0.36515], "text": "3.1\nUnsupervised pre-training"}, {"id": "p-3.1-02", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.17647, 0.37745, 0.82353, 0.40426], "text": "Given an unsupervised corpus of tokens U = {u1, . . . , un}, we use a standard language modeling\nobjective to maximize the following likelihood:"}, {"id": "p-3.1-03", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.36063, 0.40878, 0.44871, 0.42532], "text": "L1(U) =\nX"}, {"id": "p-3.1-04", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.43464, 0.41152, 0.82353, 0.43828], "text": "i\nlog P(ui|ui−k, . . . , ui−1; Θ)\n(1)"}, {"id": "p-3.1-05", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.17588, 0.44088, 0.82352, 0.46752], "text": "where k is the size of the context window, and the conditional probability P is modeled using a neural\nnetwork with parameters Θ. These parameters are trained using stochastic gradient descent [51]."}, {"id": "p-3.1-06", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.17647, 0.47547, 0.82353, 0.5623], "text": "In our experiments, we use a multi-layer Transformer decoder [34] for the language model, which is\na variant of the transformer [62]. This model applies a multi-headed self-attention operation over the\ninput context tokens followed by position-wise feedforward layers to produce an output distribution\nover target tokens:\nh0 = UWe + Wp\nhl = transformer_block(hl−1)∀i ∈[1, n]"}, {"id": "p-3.1-07", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.34296, 0.54993, 0.82353, 0.5839], "text": "P(u) = softmax(hnW T\ne )\n(2)"}, {"id": "p-3.1-08", "kind": "paragraph", "sectionId": "3.1", "page": 3, "rect": [0.17588, 0.58465, 0.82353, 0.61318], "text": "where U = (u−k, . . . , u−1) is the context vector of tokens, n is the number of layers, We is the token\nembedding matrix, and Wp is the position embedding matrix."}, {"id": "p-3.2-01", "kind": "heading", "sectionId": "3.2", "page": 3, "rect": [0.17647, 0.62846, 0.36988, 0.64103], "text": "3.2\nSupervised fine-tuning"}, {"id": "p-3.2-02", "kind": "paragraph", "sectionId": "3.2", "page": 3, "rect": [0.17588, 0.65384, 0.82557, 0.74312], "text": "After training the model with the objective in Eq. 1, we adapt the parameters to the supervised target\ntask. We assume a labeled dataset C, where each instance consists of a sequence of input tokens,\nx1, . . . , xm, along with a label y. The inputs are passed through our pre-trained model to obtain\nthe final transformer block’s activation hm\nl , which is then fed into an added linear output layer with\nparameters Wy to predict y:\nP(y|x1, . . . , xm) = softmax(hm\nl Wy).\n(3)"}, {"id": "p-3.2-03", "kind": "paragraph", "sectionId": "3.2", "page": 3, "rect": [0.17597, 0.75152, 0.5048, 0.76409], "text": "This gives us the following objective to maximize:"}, {"id": "p-3.2-04", "kind": "paragraph", "sectionId": "3.2", "page": 3, "rect": [0.38271, 0.76861, 0.47096, 0.78516], "text": "L2(C) =\nX"}, {"id": "p-3.2-05", "kind": "paragraph", "sectionId": "3.2", "page": 3, "rect": [0.44497, 0.76927, 0.82353, 0.79889], "text": "(x,y)\nlog P(y|x1, . . . , xm).\n(4)"}, {"id": "p-3.2-06", "kind": "paragraph", "sectionId": "3.2", "page": 3, "rect": [0.17571, 0.81068, 0.8238, 0.91213], "text": "We additionally found that including language modeling as an auxiliary objective to the fine-tuning\nhelped learning by (a) improving generalization of the supervised model, and (b) accelerating\nconvergence. This is in line with prior work [50, 43], who also observed improved performance with\nsuch an auxiliary objective. Specifically, we optimize the following objective (with weight λ):\nL3(C) = L2(C) + λ ∗L1(C)\n(5)\nOverall, the only extra parameters we require during fine-tuning are Wy, and embeddings for delimiter\ntokens (described below in Section 3.3)."}, {"id": "fig-1", "kind": "item", "sectionId": null, "page": 4, "rect": [0.16667, 0.08333, 0.83333, 0.34533]}, {"id": "p-3.3-01", "kind": "heading", "sectionId": "3.3", "page": 4, "rect": [0.17647, 0.36733, 0.459, 0.37991], "text": "3.3\nTask-specific input transformations"}, {"id": "p-3.3-02", "kind": "paragraph", "sectionId": "3.3", "page": 4, "rect": [0.17588, 0.39348, 0.82638, 0.55767], "text": "For some tasks, like text classification, we can directly fine-tune our model as described above.\nCertain other tasks, like question answering or textual entailment, have structured inputs such as\nordered sentence pairs, or triplets of document, question, and answers. Since our pre-trained model\nwas trained on contiguous sequences of text, we require some modifications to apply it to these tasks.\nPrevious work proposed learning task specific architectures on top of transferred representations [44].\nSuch an approach re-introduces a significant amount of task-specific customization and does not\nuse transfer learning for these additional architectural components. Instead, we use a traversal-style\napproach [52], where we convert structured inputs into an ordered sequence that our pre-trained\nmodel can process. These input transformations allow us to avoid making extensive changes to the\narchitecture across tasks. We provide a brief description of these input transformations below and\nFigure 1 provides a visual illustration. All transformations include adding randomly initialized start\nand end tokens (⟨s⟩, ⟨e⟩)."}, {"id": "p-3.3-03", "kind": "paragraph", "sectionId": "3.3", "page": 4, "rect": [0.17647, 0.57626, 0.82353, 0.6029], "text": "Textual entailment\nFor entailment tasks, we concatenate the premise p and hypothesis h token\nsequences, with a delimiter token ($) in between."}, {"id": "p-3.3-04", "kind": "paragraph", "sectionId": "3.3", "page": 4, "rect": [0.17588, 0.62167, 0.82638, 0.67568], "text": "Similarity\nFor similarity tasks, there is no inherent ordering of the two sentences being compared.\nTo reflect this, we modify the input sequence to contain both possible sentence orderings (with a\ndelimiter in between) and process each independently to produce two sequence representations hm\nl\nwhich are added element-wise before being fed into the linear output layer."}, {"id": "p-3.3-05", "kind": "paragraph", "sectionId": "3.3", "page": 4, "rect": [0.17647, 0.69444, 0.82394, 0.76223], "text": "Question Answering and Commonsense Reasoning\nFor these tasks, we are given a context\ndocument z, a question q, and a set of possible answers {ak}. We concatenate the document context\nand question with each possible answer, adding a delimiter token in between to get [z; q; $; ak]. Each\nof these sequences are processed independently with our model and then normalized via a softmax\nlayer to produce an output distribution over possible answers."}, {"id": "p-4-01", "kind": "heading", "sectionId": "4", "page": 4, "rect": [0.17647, 0.78573, 0.31212, 0.80083], "text": "4\nExperiments"}, {"id": "p-4.1-01", "kind": "heading", "sectionId": "4.1", "page": 4, "rect": [0.17647, 0.81821, 0.2529, 0.83079], "text": "4.1\nSetup"}, {"id": "p-4.1-02", "kind": "paragraph", "sectionId": "4.1", "page": 4, "rect": [0.17571, 0.84434, 0.82637, 0.91213], "text": "Unsupervised pre-training\nWe use the BooksCorpus dataset [71] for training the language model.\nIt contains over 7,000 unique unpublished books from a variety of genres including Adventure,\nFantasy, and Romance. Crucially, it contains long stretches of contiguous text, which allows the\ngenerative model to learn to condition on long-range information. An alternative dataset, the 1B\nWord Benchmark, which is used by a similar approach, ELMo [44], is approximately the same size"}, {"id": "table-1", "kind": "item", "sectionId": null, "page": 5, "rect": [0.16993, 0.08359, 0.83007, 0.19407]}, {"id": "p-4.1-03", "kind": "paragraph", "sectionId": "4.1", "page": 5, "rect": [0.17606, 0.21452, 0.82353, 0.24089], "text": "but is shuffled at a sentence level - destroying long-range structure. Our language model achieves a\nvery low token level perplexity of 18.4 on this corpus."}, {"id": "p-4.1-04", "kind": "paragraph", "sectionId": "4.1", "page": 5, "rect": [0.17525, 0.25753, 0.82638, 0.44929], "text": "Model specifications\nOur model largely follows the original transformer work [62]. We trained a\n12-layer decoder-only transformer with masked self-attention heads (768 dimensional states and 12\nattention heads). For the position-wise feed-forward networks, we used 3072 dimensional inner states.\nWe used the Adam optimization scheme [27] with a max learning rate of 2.5e-4. The learning rate\nwas increased linearly from zero over the first 2000 updates and annealed to 0 using a cosine schedule.\nWe train for 100 epochs on minibatches of 64 randomly sampled, contiguous sequences of 512 tokens.\nSince layernorm [2] is used extensively throughout the model, a simple weight initialization of\nN(0, 0.02) was sufficient. We used a bytepair encoding (BPE) vocabulary with 40,000 merges [53]\nand residual, embedding, and attention dropouts with a rate of 0.1 for regularization. We also\nemployed a modified version of L2 regularization proposed in [37], with w = 0.01 on all non bias or\ngain weights. For the activation function, we used the Gaussian Error Linear Unit (GELU) [18]. We\nused learned position embeddings instead of the sinusoidal version proposed in the original work.\nWe use the ftfy library2 to clean the raw text in BooksCorpus, standardize some punctuation and\nwhitespace, and use the spaCy tokenizer.3"}, {"id": "p-4.1-05", "kind": "paragraph", "sectionId": "4.1", "page": 5, "rect": [0.17588, 0.46592, 0.82353, 0.53371], "text": "Fine-tuning details\nUnless specified, we reuse the hyperparameter settings from unsupervised\npre-training. We add dropout to the classifier with a rate of 0.1. For most tasks, we use a learning rate\nof 6.25e-5 and a batchsize of 32. Our model finetunes quickly and 3 epochs of training was sufficient\nfor most cases. We use a linear learning rate decay schedule with warmup over 0.2% of training. λ\nwas set to 0.5."}, {"id": "p-4.2-01", "kind": "heading", "sectionId": "4.2", "page": 5, "rect": [0.17647, 0.55205, 0.36988, 0.56463], "text": "4.2\nSupervised fine-tuning"}, {"id": "p-4.2-02", "kind": "paragraph", "sectionId": "4.2", "page": 5, "rect": [0.17571, 0.57735, 0.82557, 0.63134], "text": "We perform experiments on a variety of supervised tasks including natural language inference,\nquestion answering, semantic similarity, and text classification. Some of these tasks are available\nas part of the recently released GLUE multi-task benchmark [64], which we make use of. Figure 1\nprovides an overview of all the tasks and datasets."}, {"id": "p-4.2-03", "kind": "paragraph", "sectionId": "4.2", "page": 5, "rect": [0.17647, 0.64798, 0.82623, 0.75709], "text": "Natural Language Inference\nThe task of natural language inference (NLI), also known as recog-\nnizing textual entailment, involves reading a pair of sentences and judging the relationship between\nthem from one of entailment, contradiction or neutral. Although there has been a lot of\nrecent interest [58, 35, 44], the task remains challenging due to the presence of a wide variety of\nphenomena like lexical entailment, coreference, and lexical and syntactic ambiguity. We evaluate\non five datasets with diverse sources, including image captions (SNLI), transcribed speech, popular\nfiction, and government reports (MNLI), Wikipedia articles (QNLI), science exams (SciTail) or news\narticles (RTE)."}, {"id": "p-4.2-04", "kind": "paragraph", "sectionId": "4.2", "page": 5, "rect": [0.17597, 0.76519, 0.82637, 0.87418], "text": "Table 2 details various results on the different NLI tasks for our model and previous state-of-the-art\napproaches. Our method significantly outperforms the baselines on four of the five datasets, achieving\nabsolute improvements of upto 1.5% on MNLI, 5% on SciTail, 5.8% on QNLI and 0.6% on SNLI\nover the previous best results. This demonstrates our model’s ability to better reason over multiple\nsentences, and handle aspects of linguistic ambiguity. On RTE, one of the smaller datasets we\nevaluate on (2490 examples), we achieve an accuracy of 56%, which is below the 61.7% reported by a\nmulti-task biLSTM model. Given the strong performance of our approach on larger NLI datasets, it is\nlikely our model will benefit from multi-task training as well but we have not explored this currently."}, {"id": "p-4.2-05", "kind": "paragraph", "sectionId": "4.2", "page": 5, "rect": [0.19715, 0.88486, 0.49512, 0.91211], "text": "2https://ftfy.readthedocs.io/en/latest/\n3https://spacy.io/"}, {"id": "table-2", "kind": "item", "sectionId": null, "page": 6, "rect": [0.16585, 0.08371, 0.83333, 0.30467]}, {"id": "table-3", "kind": "item", "sectionId": null, "page": 6, "rect": [0.16585, 0.3125, 0.83333, 0.50316]}, {"id": "p-4.2-06", "kind": "paragraph", "sectionId": "4.2", "page": 6, "rect": [0.17597, 0.53219, 0.82637, 0.65508], "text": "Question answering and commonsense reasoning\nAnother task that requires aspects of single\nand multi-sentence reasoning is question answering. We use the recently released RACE dataset [30],\nconsisting of English passages with associated questions from middle and high school exams. This\ncorpus has been shown to contain more reasoning type questions that other datasets like CNN [19] or\nSQuaD [47], providing the perfect evaluation for our model which is trained to handle long-range\ncontexts. In addition, we evaluate on the Story Cloze Test [40], which involves selecting the correct\nending to multi-sentence stories from two options. On these tasks, our model again outperforms the\nprevious best results by significant margins - up to 8.9% on Story Cloze, and 5.7% overall on RACE.\nThis demonstrates the ability of our model to handle long-range contexts effectively."}, {"id": "p-4.2-07", "kind": "paragraph", "sectionId": "4.2", "page": 6, "rect": [0.17571, 0.67449, 0.82638, 0.7836], "text": "Semantic Similarity\nSemantic similarity (or paraphrase detection) tasks involve predicting whether\ntwo sentences are semantically equivalent or not. The challenges lie in recognizing rephrasing of\nconcepts, understanding negation, and handling syntactic ambiguity. We use three datasets for this\ntask – the Microsoft Paraphrase corpus (MRPC) [14] (collected from news sources), the Quora\nQuestion Pairs (QQP) dataset [9], and the Semantic Textual Similarity benchmark (STS-B) [6].\nWe obtain state-of-the-art results on two of the three semantic similarity tasks (Table 4) with a 1\npoint absolute gain on STS-B. The performance delta on QQP is significant, with a 4.2% absolute\nimprovement over Single-task BiLSTM + ELMo + Attn."}, {"id": "p-4.2-08", "kind": "paragraph", "sectionId": "4.2", "page": 6, "rect": [0.17597, 0.80302, 0.82557, 0.91213], "text": "Classification\nFinally, we also evaluate on two different text classification tasks. The Corpus\nof Linguistic Acceptability (CoLA) [65] contains expert judgements on whether a sentence is\ngrammatical or not, and tests the innate linguistic bias of trained models. The Stanford Sentiment\nTreebank (SST-2) [54], on the other hand, is a standard binary classification task. Our model obtains\nan score of 45.4 on CoLA, which is an especially big jump over the previous best result of 35.0,\nshowcasing the innate linguistic bias learned by our model. The model also achieves 91.3% accuracy\non SST-2, which is competitive with the state-of-the-art results. We also achieve an overall score of\n72.8 on the GLUE benchmark, which is significantly better than the previous best of 68.9."}, {"id": "table-4", "kind": "item", "sectionId": null, "page": 7, "rect": [0.16585, 0.08371, 0.83578, 0.32677]}, {"id": "p-4.2-09", "kind": "paragraph", "sectionId": "4.2", "page": 7, "rect": [0.17647, 0.35411, 0.82597, 0.4081], "text": "Overall, our approach achieves new state-of-the-art results in 9 out of the 12 datasets we evaluate\non, outperforming ensembles in many cases. Our results also indicate that our approach works well\nacross datasets of different sizes, from smaller datasets such as STS-B (≈5.7k training examples) –\nto the largest one – SNLI (≈550k training examples)."}, {"id": "p-5-01", "kind": "heading", "sectionId": "5", "page": 7, "rect": [0.17647, 0.43087, 0.27633, 0.44596], "text": "5\nAnalysis"}, {"id": "p-5-02", "kind": "paragraph", "sectionId": "5", "page": 7, "rect": [0.17571, 0.4629, 0.82637, 0.54447], "text": "Impact of number of layers transferred\nWe observed the impact of transferring a variable number\nof layers from unsupervised pre-training to the supervised target task. Figure 2(left) illustrates the\nperformance of our approach on MultiNLI and RACE as a function of the number of layers transferred.\nWe observe the standard result that transferring embeddings improves performance and that each\ntransformer layer provides further benefits up to 9% for full transfer on MultiNLI. This indicates that\neach layer in the pre-trained model contains useful functionality for solving target tasks."}, {"id": "fig-2", "kind": "item", "sectionId": null, "page": 7, "rect": [0.16667, 0.55581, 0.83333, 0.84558]}, {"id": "p-5-03", "kind": "paragraph", "sectionId": "5", "page": 7, "rect": [0.17647, 0.87189, 0.82623, 0.9121], "text": "Zero-shot Behaviors\nWe’d like to better understand why language model pre-training of transform-\ners is effective. A hypothesis is that the underlying generative model learns to perform many of the\ntasks we evaluate on in order to improve its language modeling capability and that the more structured"}, {"id": "table-5", "kind": "item", "sectionId": null, "page": 8, "rect": [0.16585, 0.08359, 0.83333, 0.22816]}, {"id": "p-5-04", "kind": "paragraph", "sectionId": "5", "page": 8, "rect": [0.17647, 0.25602, 0.82411, 0.35124], "text": "attentional memory of the transformer assists in transfer compared to LSTMs. We designed a series\nof heuristic solutions that use the underlying generative model to perform tasks without supervised\nfinetuning. We visualize the effectiveness of these heuristic solutions over the course of generative\npre-training in Fig 2(right). We observe the performance of these heuristics is stable and steadily\nincreases over training suggesting that generative pretraining supports the learning of a wide variety\nof task relevant functionality. We also observe the LSTM exhibits higher variance in its zero-shot\nperformance suggesting that the inductive bias of the Transformer architecture assists in transfer."}, {"id": "p-5-05", "kind": "paragraph", "sectionId": "5", "page": 8, "rect": [0.17588, 0.35926, 0.82637, 0.48212], "text": "For CoLA (linguistic acceptability), examples are scored as the average token log-probability the\ngenerative model assigns and predictions are made by thresholding. For SST-2 (sentiment analysis),\nwe append the token very to each example and restrict the language model’s output distribution to only\nthe words positive and negative and guess the token it assigns higher probability to as the prediction.\nFor RACE (question answering), we pick the answer the generative model assigns the highest average\ntoken log-probability when conditioned on the document and question. For DPRD [46] (winograd\nschemas), we replace the definite pronoun with the two possible referrents and predict the resolution\nthat the generative model assigns higher average token log-probability to the rest of the sequence\nafter the substitution."}, {"id": "p-5-06", "kind": "paragraph", "sectionId": "5", "page": 8, "rect": [0.17597, 0.49994, 0.82409, 0.6366], "text": "Ablation studies\nWe perform three different ablation studies (Table 5). First, we examine the\nperformance of our method without the auxiliary LM objective during fine-tuning. We observe that\nthe auxiliary objective helps on the NLI tasks and QQP. Overall, the trend suggests that larger datasets\nbenefit from the auxiliary objective but smaller datasets do not. Second, we analyze the effect of the\nTransformer by comparing it with a single layer 2048 unit LSTM using the same framework. We\nobserve a 5.6 average score drop when using the LSTM instead of the Transformer. The LSTM only\noutperforms the Transformer on one dataset – MRPC. Finally, we also compare with our transformer\narchitecture directly trained on supervised target tasks, without pre-training. We observe that the lack\nof pre-training hurts performance across all the tasks, resulting in a 14.8% decrease compared to our\nfull model."}, {"id": "p-6-01", "kind": "heading", "sectionId": "6", "page": 8, "rect": [0.17647, 0.65916, 0.29913, 0.67425], "text": "6\nConclusion"}, {"id": "p-6-02", "kind": "paragraph", "sectionId": "6", "page": 8, "rect": [0.17571, 0.69109, 0.82556, 0.85528], "text": "We introduced a framework for achieving strong natural language understanding with a single\ntask-agnostic model through generative pre-training and discriminative fine-tuning. By pre-training\non a diverse corpus with long stretches of contiguous text our model acquires significant world\nknowledge and ability to process long-range dependencies which are then successfully transferred to\nsolving discriminative tasks such as question answering, semantic similarity assessment, entailment\ndetermination, and text classification, improving the state of the art on 9 of the 12 datasets we\nstudy. Using unsupervised (pre-)training to boost performance on discriminative tasks has long\nbeen an important goal of Machine Learning research. Our work suggests that achieving significant\nperformance gains is indeed possible, and offers hints as to what models (Transformers) and data sets\n(text with long range dependencies) work best with this approach. We hope that this will help enable\nnew research into unsupervised learning, for both natural language understanding and other domains,\nfurther improving our understanding of how and when unsupervised learning works."}], "pdfPages": 12, "readerKind": "pdf", "sections": [{"id": "front", "title": "Title & authors"}, {"id": "abstract", "title": "Abstract"}, {"id": "1", "title": "Introduction"}, {"id": "2", "title": "Related Work"}, {"id": "3", "title": "Framework"}, {"id": "3.1", "title": "Unsupervised pre-training"}, {"id": "3.2", "title": "Supervised fine-tuning"}, {"id": "3.3", "title": "Task-specific input transformations"}, {"id": "4", "title": "Experiments"}, {"id": "4.1", "title": "Setup"}, {"id": "4.2", "title": "Supervised fine-tuning"}, {"id": "5", "title": "Analysis"}, {"id": "6", "title": "Conclusion"}, {"id": "references", "title": "References"}]};
